import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateThumbnail = async (prompt: string, style: string, base64Image?: string) => {
  const ai = getAI();
  const fullPrompt = `Create a professional YouTube thumbnail in ${style} style. Description: ${prompt}. Ensure high contrast, bold text, and expressive faces if applicable. Premium quality.`;

  const contents: any = {
    parts: [{ text: fullPrompt }]
  };

  if (base64Image) {
    contents.parts.push({
      inlineData: {
        data: base64Image.split(',')[1],
        mimeType: 'image/png'
      }
    });
  }

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents,
    config: {
      imageConfig: {
        aspectRatio: "16:9",
      }
    }
  });

  const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  if (imagePart?.inlineData) {
    return `data:image/png;base64,${imagePart.inlineData.data}`;
  }
  throw new Error("No image generated");
};

export const analyzeChannel = async (channelUrl: string) => {
  const ai = getAI();
  const prompt = `Analyze this YouTube channel URL for thumbnail optimization and CTR: ${channelUrl}. Provide feedback on Style Improvement, CTR-Optimization, and 3 specific suggestions for new designs. Return in JSON format.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          styleFeedback: { type: Type.STRING },
          ctrOptimization: { type: Type.STRING },
          suggestions: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["styleFeedback", "ctrOptimization", "suggestions"]
      }
    }
  });

  return JSON.parse(response.text);
};

export const remakeThumbnail = async (base64Image: string, prompt: string) => {
  const ai = getAI();
  const fullPrompt = `Analyze the layout and structure of the provided thumbnail image. Create a new version of it with the following variations: ${prompt}. Keep the same successful structure but update colors, branding, and text according to the description.`;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Image.split(',')[1],
            mimeType: 'image/png'
          }
        },
        { text: fullPrompt }
      ]
    },
    config: {
      imageConfig: {
        aspectRatio: "16:9"
      }
    }
  });

  const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  if (imagePart?.inlineData) {
    return `data:image/png;base64,${imagePart.inlineData.data}`;
  }
  throw new Error("No remake generated");
};

