import React from 'react';
import { Tab, ThumbnailStyle, Design } from '../types';
import { Wand2, LineChart, Copy, Grid, Upload, Sparkles, Loader2, Download, Trash2, History } from 'lucide-react';
import { generateThumbnail, analyzeChannel, remakeThumbnail } from '../services/geminiService';

export const Studio: React.FC = () => {
  const [activeTab, setActiveTab] = React.useState<Tab>('generate');
  const [prompt, setPrompt] = React.useState('');
  const [style, setStyle] = React.useState<ThumbnailStyle>(ThumbnailStyle.CLEAN);
  const [channelUrl, setChannelUrl] = React.useState('');
  const [loading, setLoading] = React.useState(false);
  const [previewImage, setPreviewImage] = React.useState<string | null>(null);
  const [designs, setDesigns] = React.useState<Design[]>([]);
  const [analysis, setAnalysis] = React.useState<any>(null);
  const [referenceImage, setReferenceImage] = React.useState<string | null>(null);

  const handleGenerate = async () => {
    if (!prompt) return;
    setLoading(true);
    try {
      const result = await generateThumbnail(prompt, style);
      setPreviewImage(result);
      setDesigns([{
        id: Date.now().toString(),
        imageUrl: result,
        prompt: prompt,
        createdAt: new Date().toLocaleDateString()
      }, ...designs]);
    } catch (err) {
      alert("Failed to generate: " + err);
    } finally {
      setLoading(false);
    }
  };

  const handleAnalyze = async () => {
    if (!channelUrl) return;
    setLoading(true);
    try {
      const result = await analyzeChannel(channelUrl);
      setAnalysis(result);
    } catch (err) {
      alert("Analysis failed: " + err);
    } finally {
      setLoading(false);
    }
  };

  const handleRemake = async () => {
    if (!referenceImage || !prompt) return;
    setLoading(true);
    try {
      const result = await remakeThumbnail(referenceImage, prompt);
      setPreviewImage(result);
      setDesigns([{
        id: Date.now().toString(),
        imageUrl: result,
        prompt: `Remake: ${prompt}`,
        createdAt: new Date().toLocaleDateString()
      }, ...designs]);
    } catch (err) {
      alert("Remake failed: " + err);
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'reference' | 'input') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (target === 'reference') setReferenceImage(reader.result as string);
        else setPreviewImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="pt-24 min-h-screen bg-[#030712] p-4 lg:p-8">
      <div className="max-w-7xl mx-auto">
        {/* Tabs */}
        <div className="flex overflow-x-auto pb-4 gap-2 mb-8 no-scrollbar">
          {[
            { id: 'generate', label: 'Generate Thumbnail', icon: Wand2 },
            { id: 'feedback', label: 'Channel Feedback', icon: LineChart },
            { id: 'remake', label: 'Remake Thumbnail', icon: Copy },
            { id: 'designs', label: 'My Designs', icon: Grid },
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as Tab)}
              className={`flex items-center gap-2 px-6 py-3 rounded-xl font-semibold transition-all shrink-0 ${
                activeTab === tab.id ? 'bg-blue-600 text-white' : 'bg-white/5 text-gray-400 hover:bg-white/10'
              }`}
            >
              <tab.icon className="w-5 h-5" />
              {tab.label}
            </button>
          ))}
        </div>

        <div className="grid lg:grid-cols-12 gap-8">
          {/* Left Panel - Input */}
          <div className="lg:col-span-5 space-y-6">
            <div className="glass rounded-3xl p-6 lg:p-8 space-y-6">
              {activeTab === 'generate' && (
                <>
                  <div>
                    <label className="block text-sm font-medium text-gray-400 mb-2 uppercase tracking-widest">Your Idea</label>
                    <textarea 
                      placeholder="Describe your thumbnail (e.g., 'A robot reading a futuristic book in space with bright neon lights')"
                      className="w-full h-32 bg-white/5 border border-white/10 rounded-2xl p-4 focus:outline-none focus:border-blue-500 transition-colors resize-none"
                      value={prompt}
                      onChange={(e) => setPrompt(e.target.value)}
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-400 mb-3 uppercase tracking-widest">Thumbnail Style</label>
                    <div className="grid grid-cols-2 gap-3">
                      {Object.values(ThumbnailStyle).map((s) => (
                        <button
                          key={s}
                          onClick={() => setStyle(s)}
                          className={`py-3 px-4 rounded-xl border text-sm font-bold transition-all ${
                            style === s ? 'border-blue-500 bg-blue-500/10 text-blue-400' : 'border-white/10 bg-white/5 hover:bg-white/10'
                          }`}
                        >
                          {s}
                        </button>
                      ))}
                    </div>
                  </div>
                  <button 
                    onClick={handleGenerate}
                    disabled={loading || !prompt}
                    className="w-full py-4 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-2xl font-bold text-lg shadow-xl shadow-blue-500/20 flex items-center justify-center gap-2 transition-all"
                  >
                    {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <><Sparkles className="w-5 h-5" /> Generate</>}
                  </button>
                </>
              )}

              {activeTab === 'feedback' && (
                <>
                  <div>
                    <label className="block text-sm font-medium text-gray-400 mb-2 uppercase tracking-widest">Channel URL</label>
                    <input 
                      type="url"
                      placeholder="https://youtube.com/@yourchannel"
                      className="w-full bg-white/5 border border-white/10 rounded-2xl p-4 focus:outline-none focus:border-blue-500 transition-colors"
                      value={channelUrl}
                      onChange={(e) => setChannelUrl(e.target.value)}
                    />
                  </div>
                  <button 
                    onClick={handleAnalyze}
                    disabled={loading || !channelUrl}
                    className="w-full py-4 bg-purple-600 hover:bg-purple-500 disabled:opacity-50 text-white rounded-2xl font-bold text-lg flex items-center justify-center gap-2 transition-all"
                  >
                    {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <><LineChart className="w-5 h-5" /> Analyze Channel</>}
                  </button>
                </>
              )}

              {activeTab === 'remake' && (
                <>
                  <div>
                    <label className="block text-sm font-medium text-gray-400 mb-2 uppercase tracking-widest">Reference Image</label>
                    <div className="relative group cursor-pointer border-2 border-dashed border-white/10 rounded-2xl aspect-video flex flex-center items-center justify-center overflow-hidden hover:border-blue-500 transition-colors">
                      {referenceImage ? (
                        <img src={referenceImage} className="w-full h-full object-cover" />
                      ) : (
                        <div className="text-center text-gray-500">
                          <Upload className="w-8 h-8 mx-auto mb-2" />
                          <p className="text-sm">Upload Thumbnail to Remake</p>
                        </div>
                      )}
                      <input type="file" onChange={(e) => handleFileUpload(e, 'reference')} className="absolute inset-0 opacity-0 cursor-pointer" />
                    </div>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-400 mb-2 uppercase tracking-widest">Custom Changes</label>
                    <textarea 
                      placeholder="What should be different? (e.g., 'Same composition but with red background and my face instead')"
                      className="w-full h-24 bg-white/5 border border-white/10 rounded-2xl p-4 focus:outline-none focus:border-blue-500 transition-colors resize-none"
                      value={prompt}
                      onChange={(e) => setPrompt(e.target.value)}
                    />
                  </div>
                  <button 
                    onClick={handleRemake}
                    disabled={loading || !referenceImage || !prompt}
                    className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white rounded-2xl font-bold text-lg flex items-center justify-center gap-2 transition-all"
                  >
                    {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <><Copy className="w-5 h-5" /> Remake Style</>}
                  </button>
                </>
              )}

              {activeTab === 'designs' && (
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <h3 className="text-lg font-bold">Your Design History</h3>
                    <button className="text-gray-500 hover:text-white"><History className="w-5 h-5" /></button>
                  </div>
                  <p className="text-sm text-gray-400">Manage and download your generated content here.</p>
                </div>
              )}
            </div>
          </div>

          {/* Right Panel - Preview */}
          <div className="lg:col-span-7">
            <div className="glass rounded-3xl p-4 lg:p-6 min-h-[500px] flex flex-col">
              <div className="flex items-center justify-between mb-6">
                <h3 className="text-lg font-bold uppercase tracking-widest text-gray-400">Live Preview</h3>
                <div className="flex gap-2">
