                      <div className="p-6 bg-purple-500/10 border border-purple-500/20 rounded-2xl">
                        <h4 className="font-bold text-purple-400 mb-2 flex items-center gap-2"><TrendingUp className="w-4 h-4" /> CTR Strategy</h4>
                        <p className="text-gray-300 leading-relaxed">{analysis.ctrOptimization}</p>
                      </div>
                      <div className="space-y-3">
                        <h4 className="font-bold text-gray-400 uppercase tracking-widest text-sm">New Design Suggestions</h4>
                        {analysis.suggestions.map((s: string, i: number) => (
                          <div key={i} className="flex gap-4 items-start p-4 bg-white/5 rounded-xl border border-white/5">
                            <span className="w-6 h-6 rounded-full bg-gray-800 text-xs flex items-center justify-center shrink-0">{i+1}</span>
                            <p className="text-gray-400 text-sm">{s}</p>
                          </div>
                        ))}
                      </div>
                    </div>
                  ) : previewImage ? (
                    <div className="group relative rounded-2xl overflow-hidden aspect-video border border-white/10">
                      <img src={previewImage} className="w-full h-full object-cover transition-transform group-hover:scale-105 duration-700" />
                      <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex items-end p-8">
                         <div className="w-full flex justify-between items-center">
                            <span className="text-xs font-bold uppercase tracking-widest bg-blue-600 px-3 py-1 rounded">1280x720 • HD</span>
                            <button className="bg-white text-black px-4 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-gray-200 transition-all">
                                <Download className="w-4 h-4" /> Download PNG
                            </button>
                         </div>
                      </div>
                    </div>
                  ) : (
                    <div className="flex-1 border-2 border-dashed border-white/5 rounded-2xl flex flex-col items-center justify-center text-gray-600">
                      <div className="w-20 h-20 rounded-3xl bg-white/5 flex items-center justify-center mb-4">
                        <Layout className="w-10 h-10" />
                      </div>
                      <p className="text-lg">No generation to show yet</p>
                      <p className="text-sm">Select an option and click generate</p>
                    </div>
                  )}
                </div>
              )}

              {activeTab === 'designs' && (
                <div className="grid grid-cols-2 gap-4">
                  {designs.length > 0 ? designs.map((d) => (
                    <div key={d.id} className="group relative rounded-xl overflow-hidden aspect-video border border-white/10">
                      <img src={d.imageUrl} className="w-full h-full object-cover" />
                      <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col justify-center items-center gap-2">
                        <button className="p-2 bg-white text-black rounded-lg hover:scale-110 transition-transform"><Download className="w-4 h-4" /></button>
                        <p className="text-[10px] text-white/50 px-2 text-center">{d.createdAt}</p>
