              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { User } from './types';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { Features } from './components/Features';
import { Pricing } from './components/Pricing';
import { Reviews } from './components/Reviews';
import { AuthModal } from './components/AuthModal';
import { Studio } from './components/Studio';

function App() {
  const [user, setUser] = React.useState<User | null>(null);
  const [currentView, setCurrentView] = React.useState<'home' | 'studio' | 'pricing'>('home');
  const [isAuthOpen, setIsAuthOpen] = React.useState(false);

  const handleLogin = (email: string) => {
    setUser({
      id: '1',
      email: email,
      name: email.split('@')[0],
      isLoggedIn: true
    });
    setIsAuthOpen(false);
    setCurrentView('studio');
  };

  const handleStartCreating = () => {
    if (user) {
      setCurrentView('studio');
    } else {
      setIsAuthOpen(true);
    }
  };

  const renderHome = () => (
    <div className="animate-in fade-in duration-700">
      <Hero 
        onStartCreating={handleStartCreating} 
        onViewPricing={() => setCurrentView('pricing')} 
      />
      <Features />
      <Reviews />
    </div>
  );

  const renderPricing = () => (
    <div className="pt-20 animate-in slide-in-from-bottom-4 duration-500">
      <Pricing />
    </div>
  );

  return (
    <div className="min-h-screen selection:bg-blue-500 selection:text-white">
      <Navbar 
        user={user} 
        onNavigate={setCurrentView} 
        onLoginClick={() => setIsAuthOpen(true)} 
      />

      <main>
        {currentView === 'home' && renderHome()}
        {currentView === 'studio' && <Studio />}
        {currentView === 'pricing' && renderPricing()}
      </main>

      <footer className="py-12 border-t border-white/5 bg-black">
        <div className="max-w-7xl mx-auto px-4 text-center">
            <div className="flex items-center justify-center gap-2 mb-4">
                <div className="bg-blue-600 p-1 rounded">
                    <Zap className="w-4 h-4 text-white fill-white" />
                </div>
                <span className="font-bold">ThumbCraft AI</span>
            </div>
            <p className="text-gray-500 text-sm">© 2024 ThumbCraft AI. All rights reserved.</p>
            <div className="mt-4 flex justify-center gap-6 text-sm text-gray-400">
                <a href="#" className="hover:text-white">Privacy</a>
                <a href="#" className="hover:text-white">Terms</a>
                <a href="#" className="hover:text-white">API</a>
            </div>
        </div>
      </footer>

      <AuthModal 
        isOpen={isAuthOpen} 
        onClose={() => setIsAuthOpen(false)} 
        onLogin={handleLogin} 
      />
    </div>
  );
}

