import { Zap, Layout, Play, TrendingUp, Sparkles } from 'lucide-react';

export default App;

import React from 'react';
import { Tab, ThumbnailStyle, Design } from '../types';
import { Wand2, LineChart, Copy, Grid, Upload, Sparkles, Loader2, Download, Trash2, History, CheckCircle2, AlertCircle } from 'lucide-react';
import { generateThumbnail, analyzeChannel, remakeThumbnail } from '../services/geminiService';

export const Studio: React.FC = () => {
  const [activeTab, setActiveTab] = React.useState<Tab>('generate');
  const [prompt, setPrompt] = React.useState('');
  const [style, setStyle] = React.useState<ThumbnailStyle>(ThumbnailStyle.CLEAN);
  const [channelUrl, setChannelUrl] = React.useState('');
  const [loading, setLoading] = React.useState(false);
  const [previewImage, setPreviewImage] = React.useState<string | null>(null);
  const [designs, setDesigns] = React.useState<Design[]>([]);
  const [analysis, setAnalysis] = React.useState<any>(null);
  const [referenceImage, setReferenceImage] = React.useState<string | null>(null);
  const [inputImage, setInputImage] = React.useState<string | null>(null);

  const handleGenerate = async () => {
    if (!prompt) return;
    setLoading(true);
    setPreviewImage(null);
    try {
      const result = await generateThumbnail(prompt, style, inputImage || undefined);
      setPreviewImage(result);
      setDesigns([{
        id: Date.now().toString(),
        imageUrl: result,
        prompt: prompt,
        createdAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      }, ...designs]);
    } catch (err) {
      console.error(err);
      alert("Failed to generate thumbnail. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleAnalyze = async () => {
    if (!channelUrl) return;
    setLoading(true);
    try {
      const result = await analyzeChannel(channelUrl);
      setAnalysis(result);
    } catch (err) {
      console.error(err);
      alert("Analysis failed. Ensure the URL is correct.");
    } finally {
      setLoading(false);
    }
  };

  const handleRemake = async () => {
    if (!referenceImage || !prompt) return;
    setLoading(true);
    setPreviewImage(null);
    try {
      const result = await remakeThumbnail(referenceImage, prompt);
      setPreviewImage(result);
      setDesigns([{
        id: Date.now().toString(),
        imageUrl: result,
        prompt: `Remake: ${prompt}`,
        createdAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      }, ...designs]);
    } catch (err) {
      console.error(err);
      alert("Remake failed. Please try a different reference.");
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'reference' | 'input') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (target === 'reference') setReferenceImage(reader.result as string);
        else setInputImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const downloadImage = (base64: string, filename: string) => {
    const link = document.createElement('a');
    link.href = base64;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="pt-24 min-h-screen bg-[#030712] p-4 lg:p-8 animate-in fade-in duration-500">
      <div className="max-w-7xl mx-auto">
        {/* Navigation Tabs */}
        <div className="flex overflow-x-auto pb-4 gap-2 mb-8 no-scrollbar">
          {[
            { id: 'generate', label: 'Generate', icon: Wand2 },
            { id: 'feedback', label: 'Channel Analyzer', icon: LineChart },
            { id: 'remake', label: 'Remake Feature', icon: Copy },
            { id: 'designs', label: 'My Designs', icon: Grid },
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as Tab)}
              className={`flex items-center gap-2 px-6 py-3 rounded-2xl font-semibold transition-all shrink-0 ${
                activeTab === tab.id 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20 scale-105' 
                  : 'bg-white/5 text-gray-400 hover:bg-white/10'
              }`}
            >
              <tab.icon className="w-5 h-5" />
              {tab.label}
            </button>
          ))}
        </div>

        <div className="grid lg:grid-cols-12 gap-8">
          {/* Left Panel - Control Center */}
          <div className="lg:col-span-5 space-y-6">
            <div className="glass rounded-[2rem] p-6 lg:p-8 space-y-6 border-white/5">
              {activeTab === 'generate' && (
                <div className="space-y-6 animate-in slide-in-from-left-4 duration-300">
                  <div>
                    <label className="block text-xs font-bold text-blue-500 mb-2 uppercase tracking-[0.2em]">Prompt</label>
                    <textarea 
                      placeholder="Describe your thumbnail (e.g., 'MrBeast style, person shocked pointing at a giant gold vault')"
                      className="w-full h-32 bg-black/40 border border-white/10 rounded-2xl p-4 focus:outline-none focus:border-blue-500 transition-all resize-none text-sm leading-relaxed"
                      value={prompt}
                      onChange={(e) => setPrompt(e.target.value)}
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-bold text-blue-500 mb-3 uppercase tracking-[0.2em]">Reference Image (Optional)</label>
                    <div className="relative group cursor-pointer border-2 border-dashed border-white/10 rounded-2xl aspect-video flex flex-center items-center justify-center overflow-hidden hover:border-blue-500/50 transition-colors bg-black/20">
                      {inputImage ? (
                        <div className="relative w-full h-full">
                          <img src={inputImage} className="w-full h-full object-cover" />
                          <button 
                            onClick={(e) => { e.stopPropagation(); setInputImage(null); }}
                            className="absolute top-2 right-2 p-1.5 bg-black/60 rounded-full hover:bg-red-500 transition-colors"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      ) : (
                        <div className="text-center text-gray-500 p-4">
                          <Upload className="w-8 h-8 mx-auto mb-2 opacity-20" />
                          <p className="text-xs">Drag or click to upload assets</p>
                        </div>
                      )}
                      {!inputImage && <input type="file" accept="image/*" onChange={(e) => handleFileUpload(e, 'input')} className="absolute inset-0 opacity-0 cursor-pointer" />}
                    </div>
                  </div>

                  <div>
                    <label className="block text-xs font-bold text-blue-500 mb-3 uppercase tracking-[0.2em]">Visual Style</label>
                    <div className="grid grid-cols-2 gap-2">
                      {Object.values(ThumbnailStyle).map((s) => (
                        <button
                          key={s}
                          onClick={() => setStyle(s)}
                          className={`py-3 px-4 rounded-xl border text-xs font-bold transition-all ${
                            style === s ? 'border-blue-500 bg-blue-500/10 text-blue-400' : 'border-white/10 bg-black/40 hover:bg-white/10 text-gray-400'
                          }`}
                        >
                          {s}
                        </button>
                      ))}
                    </div>
                  </div>

                  <button 
                    onClick={handleGenerate}
                    disabled={loading || !prompt}
                    className="w-full py-4 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-2xl font-bold text-lg shadow-xl shadow-blue-500/20 flex items-center justify-center gap-2 transition-all active:scale-[0.98]"
                  >
                    {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <><Sparkles className="w-5 h-5" /> Craft Thumbnail</>}
                  </button>
                </div>
              )}

              {activeTab === 'feedback' && (
                <div className="space-y-6 animate-in slide-in-from-left-4 duration-300">
                  <div className="bg-blue-500/5 p-4 rounded-2xl border border-blue-500/10">
                    <p className="text-sm text-blue-300/80 leading-relaxed">
                      Our AI will analyze your channel's branding, color palette, and current CTR performance to provide actionable improvements.
                    </p>
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-blue-500 mb-2 uppercase tracking-[0.2em]">Channel URL</label>
                    <input 
                      type="url"
                      placeholder="https://youtube.com/@MrBeast"
                      className="w-full bg-black/40 border border-white/10 rounded-2xl p-4 focus:outline-none focus:border-blue-500 transition-all"
                      value={channelUrl}
                      onChange={(e) => setChannelUrl(e.target.value)}
                    />
                  </div>
                  <button 
                    onClick={handleAnalyze}
                    disabled={loading || !channelUrl}
                    className="w-full py-4 bg-white text-black hover:bg-gray-200 disabled:opacity-50 text-white rounded-2xl font-bold text-lg flex items-center justify-center gap-2 transition-all active:scale-[0.98]"
                  >
                    {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <><LineChart className="w-5 h-5" /> Run Analysis</>}
                  </button>
                </div>
              )}

              {activeTab === 'remake' && (
                <div className="space-y-6 animate-in slide-in-from-left-4 duration-300">
                  <div>
                    <label className="block text-xs font-bold text-indigo-500 mb-2 uppercase tracking-[0.2em]">Target Style (Upload Screenshot)</label>
                    <div className="relative group cursor-pointer border-2 border-dashed border-white/10 rounded-2xl aspect-video flex flex-center items-center justify-center overflow-hidden hover:border-indigo-500/50 transition-colors bg-black/20">
                      {referenceImage ? (
                        <div className="relative w-full h-full">
                          <img src={referenceImage} className="w-full h-full object-cover" />
                          <button 
                            onClick={(e) => { e.stopPropagation(); setReferenceImage(null); }}
                            className="absolute top-2 right-2 p-1.5 bg-black/60 rounded-full hover:bg-red-500 transition-colors"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      ) : (
                        <div className="text-center text-gray-500 p-4">
                          <Upload className="w-8 h-8 mx-auto mb-2 opacity-20" />
                          <p className="text-xs">Upload viral thumbnail to clone</p>
                        </div>
                      )}
                      {!referenceImage && <input type="file" accept="image/*" onChange={(e) => handleFileUpload(e, 'reference')} className="absolute inset-0 opacity-0 cursor-pointer" />}
                    </div>
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-indigo-500 mb-2 uppercase tracking-[0.2em]">Adaptation Details</label>
                    <textarea 
                      placeholder="How should we change it? (e.g., 'Change background to dark blue and replace main character with a giant pizza')"
                      className="w-full h-24 bg-black/40 border border-white/10 rounded-2xl p-4 focus:outline-none focus:border-indigo-500 transition-all resize-none text-sm"
                      value={prompt}
                      onChange={(e) => setPrompt(e.target.value)}
                    />
                  </div>
                  <button 
                    onClick={handleRemake}
                    disabled={loading || !referenceImage || !prompt}
                    className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white rounded-2xl font-bold text-lg flex items-center justify-center gap-2 transition-all active:scale-[0.98]"
                  >
                    {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <><Copy className="w-5 h-5" /> Clone & Remake</>}
                  </button>
                </div>
              )}

              {activeTab === 'designs' && (
                <div className="space-y-4 animate-in slide-in-from-left-4 duration-300">
                  <div className="flex items-center justify-between">
                    <h3 className="text-lg font-bold">Workspace</h3>
                    <button className="text-gray-500 hover:text-white transition-colors"><History className="w-5 h-5" /></button>
                  </div>
                  <p className="text-xs text-gray-500 leading-relaxed uppercase tracking-widest font-bold">Recent History</p>
                  <div className="grid grid-cols-1 gap-3">
                    {designs.slice(0, 5).map(d => (
                      <div key={d.id} className="flex gap-4 p-3 bg-white/5 rounded-xl border border-white/5 items-center group">
                        <img src={d.imageUrl} className="w-16 h-10 rounded object-cover" />
                        <div className="flex-1 overflow-hidden">
                          <p className="text-xs font-bold truncate text-gray-300">{d.prompt}</p>
                          <p className="text-[10px] text-gray-600">{d.createdAt}</p>
                        </div>
                        <button 
                          onClick={() => downloadImage(d.imageUrl, `thumb-${d.id}.png`)}
                          className="p-1.5 hover:bg-white/10 rounded-lg text-gray-500 hover:text-white"
                        >
                          <Download className="w-4 h-4" />
                        </button>
                      </div>
                    ))}
                    {designs.length === 0 && <p className="text-sm text-gray-600 text-center py-8">No recent activity</p>}
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Right Panel - Result Preview Area */}
          <div className="lg:col-span-7">
            <div className="glass rounded-[2rem] p-4 lg:p-8 min-h-[600px] flex flex-col border-white/5 relative overflow-hidden">
              <div className="flex items-center justify-between mb-8">
                <div>
                  <h3 className="text-sm font-bold uppercase tracking-[0.2em] text-gray-500">Preview Engine</h3>
                  {loading && <div className="text-[10px] text-blue-500 animate-pulse font-bold mt-1">PROCESSING VIA CLOUD...</div>}
                </div>
                <div className="flex gap-2">
                  {previewImage && (
                    <button 
                      onClick={() => downloadImage(previewImage, 'thumbnail.png')}
                      className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 rounded-xl text-gray-300 transition-all text-sm font-bold border border-white/10"
                    >
                      <Download className="w-4 h-4" /> Download
                    </button>
                  )}
                </div>
              </div>

              <div className="flex-1 flex flex-col">
                {loading ? (
                  <div className="flex-1 flex flex-col items-center justify-center gap-6 animate-pulse">
                    <div className="relative">
                      <div className="absolute inset-0 bg-blue-500/20 blur-3xl rounded-full"></div>
                      <Loader2 className="w-16 h-16 text-blue-500 animate-spin relative z-10" />
                    </div>
                    <div className="text-center space-y-2">
                      <p className="text-xl font-bold text-white tracking-tight">Generating assets...</p>
                      <p className="text-sm text-gray-500">Our neural engine is rendering your vision.</p>
                    </div>
                  </div>
                ) : activeTab === 'feedback' && analysis ? (
                  <div className="space-y-6 animate-in zoom-in-95 duration-500 overflow-y-auto max-h-[700px] pr-2 custom-scroll">
                    <div className="p-8 bg-blue-500/5 border border-blue-500/10 rounded-[2rem] relative overflow-hidden">
                      <div className="absolute top-0 right-0 p-8 opacity-10"><LineChart className="w-24 h-24" /></div>
                      <h4 className="font-bold text-blue-400 mb-4 flex items-center gap-2 text-lg">
                        <Sparkles className="w-5 h-5" /> Style Report
                      </h4>
                      <p className="text-gray-300 leading-relaxed text-sm md:text-base">{analysis.styleFeedback}</p>
                    </div>

                    <div className="grid md:grid-cols-2 gap-4">
                      <div className="p-6 bg-emerald-500/5 border border-emerald-500/10 rounded-3xl">
                        <h4 className="font-bold text-emerald-400 mb-3 flex items-center gap-2 text-sm uppercase tracking-widest">
                          <CheckCircle2 className="w-4 h-4" /> Optimization
                        </h4>
                        <p className="text-gray-400 text-sm leading-relaxed">{analysis.ctrOptimization}</p>
                      </div>
                      <div className="p-6 bg-purple-500/5 border border-purple-500/10 rounded-3xl">
                        <h4 className="font-bold text-purple-400 mb-3 flex items-center gap-2 text-sm uppercase tracking-widest">
                          <AlertCircle className="w-4 h-4" /> Strategy
                        </h4>
                        <ul className="space-y-3">
                          {analysis.suggestions.slice(0, 3).map((s: string, i: number) => (
                            <li key={i} className="text-xs text-gray-400 flex gap-2">
                              <span className="text-purple-500 font-bold">•</span> {s}
                            </li>
                          ))}
                        </ul>
                      </div>
                    </div>
                  </div>
                ) : previewImage ? (
                  <div className="group relative rounded-3xl overflow-hidden aspect-video border border-white/10 shadow-2xl animate-in fade-in zoom-in-95 duration-500">
                    <img src={previewImage} className="w-full h-full object-cover" />
                    <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all flex items-end p-8">
                       <div className="w-full flex justify-between items-center">
                          <div className="space-y-1">
