import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateThumbnail = async (prompt: string, style: string, base64Image?: string) => {
  const ai = getAI();
  const fullPrompt = `Erstelle ein professionelles YouTube-Thumbnail im Stil '${style}'. Beschreibung: ${prompt}. Achte auf hohen Kontrast, fette Texte und ausdrucksstarke Gesichter, falls zutreffend. Premium-Qualität. Alle Texte im Bild sollten auf Deutsch sein, sofern nicht anders angegeben.`;

  const contents: any = {
    parts: [{ text: fullPrompt }]
  };

  if (base64Image) {
    contents.parts.push({
      inlineData: {
        data: base64Image.split(',')[1],
        mimeType: 'image/png'
      }
    });
  }

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents,
    config: {
      imageConfig: {
        aspectRatio: "16:9",
      }
    }
  });

  const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  if (imagePart?.inlineData) {
    return `data:image/png;base64,${imagePart.inlineData.data}`;
  }
  throw new Error("Kein Bild generiert");
};

export const analyzeChannel = async (channelUrl: string) => {
  const ai = getAI();
  const prompt = `Analysiere diesen YouTube-Kanal-URL für Thumbnail-Optimierung und CTR: ${channelUrl}. Gib Feedback zu Stilverbesserungen, CTR-Optimierung und nenne 3 spezifische Vorschläge für neue Designs. Deine Antwort MUSS auf DEUTSCH sein und im JSON-Format zurückgegeben werden.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          styleFeedback: { type: Type.STRING },
          ctrOptimization: { type: Type.STRING },
          suggestions: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["styleFeedback", "ctrOptimization", "suggestions"]
      }
    }
  });

  return JSON.parse(response.text);
};

export const remakeThumbnail = async (base64Image: string, prompt: string) => {
  const ai = getAI();
  const fullPrompt = `Analysiere das Layout und die Struktur des bereitgestellten Thumbnails. Erstelle eine neue Version davon mit folgenden Variationen: ${prompt}. Behalte die erfolgreiche Struktur bei, aber aktualisiere Farben, Branding und Texte gemäß der Beschreibung. Antworte mit einem neu generierten Bild.`;

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Image.split(',')[1],
            mimeType: 'image/png'
          }
        },
        { text: fullPrompt }
      ]
    },
    config: {
      imageConfig: {
        aspectRatio: "16:9"
      }
    }
  });

  const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  if (imagePart?.inlineData) {
    return `data:image/png;base64,${imagePart.inlineData.data}`;
  }
  throw new Error("Neuauflage fehlgeschlagen");
};

