              <h4 className="font-bold mb-6 text-sm uppercase tracking-widest text-gray-300">Unternehmen</h4>
              <ul className="space-y-4 text-gray-500 text-sm">
                <li><a href="#" className="hover:text-blue-500 transition-colors">Über uns</a></li>
                <li><a href="#" className="hover:text-blue-500 transition-colors">Karriere</a></li>
                <li><a href="#" className="hover:text-blue-500 transition-colors">Bedingungen</a></li>
                <li><a href="#" className="hover:text-blue-500 transition-colors">Datenschutz</a></li>
              </ul>
            </div>
          </div>
          <div className="pt-8 border-t border-white/5 flex flex-col md:flex-row justify-between items-center gap-4">
            <p className="text-gray-600 text-xs tracking-wide uppercase font-medium">© 2024 ThumbCraft AI. Alle Rechte vorbehalten.</p>
          </div>
        </div>
      </footer>

      <AuthModal 
        isOpen={isAuthOpen} 
        onClose={() => setIsAuthOpen(false)} 
        onLogin={handleLogin} 
      />
    </div>
  );
}

