import React from 'react';
import { Tab, ThumbnailStyle, Design } from '../types';
import { Wand2, LineChart, Copy, Grid, Upload, Sparkles, Loader2, Download, Trash2, History, CheckCircle2, AlertCircle, ChevronRight } from 'lucide-react';
import { generateThumbnail, analyzeChannel, remakeThumbnail } from '../services/geminiService';

export const Studio: React.FC = () => {
  const [activeTab, setActiveTab] = React.useState<Tab>('generate');
  const [prompt, setPrompt] = React.useState('');
  const [style, setStyle] = React.useState<ThumbnailStyle>(ThumbnailStyle.CLEAN);
  const [channelUrl, setChannelUrl] = React.useState('');
  const [loading, setLoading] = React.useState(false);
  const [previewImage, setPreviewImage] = React.useState<string | null>(null);
  const [designs, setDesigns] = React.useState<Design[]>([]);
  const [analysis, setAnalysis] = React.useState<any>(null);
  const [referenceImage, setReferenceImage] = React.useState<string | null>(null);
  const [inputImage, setInputImage] = React.useState<string | null>(null);

  const handleGenerate = async () => {
    if (!prompt) return;
    setLoading(true);
    setPreviewImage(null);
    try {
      const result = await generateThumbnail(prompt, style, inputImage || undefined);
      setPreviewImage(result);
      setDesigns([{
        id: Date.now().toString(),
        imageUrl: result,
        prompt: prompt,
        createdAt: new Date().toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' })
      }, ...designs]);
    } catch (err) {
      console.error(err);
      alert("Fehler bei der Thumbnail-Erstellung. Bitte erneut versuchen.");
    } finally {
      setLoading(false);
    }
  };

  const handleAnalyze = async () => {
    if (!channelUrl) return;
    setLoading(true);
    try {
      const result = await analyzeChannel(channelUrl);
      setAnalysis(result);
    } catch (err) {
      console.error(err);
      alert("Analyse fehlgeschlagen. Überprüfe die URL.");
    } finally {
      setLoading(false);
    }
  };

  const handleRemake = async () => {
    if (!referenceImage || !prompt) return;
    setLoading(true);
    setPreviewImage(null);
    try {
      const result = await remakeThumbnail(referenceImage, prompt);
      setPreviewImage(result);
      setDesigns([{
        id: Date.now().toString(),
        imageUrl: result,
        prompt: `Neuauflage: ${prompt}`,
        createdAt: new Date().toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' })
      }, ...designs]);
    } catch (err) {
      console.error(err);
      alert("Neuauflage fehlgeschlagen. Versuche eine andere Vorlage.");
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'reference' | 'input') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (target === 'reference') setReferenceImage(reader.result as string);
        else setInputImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const downloadImage = (base64: string, filename: string) => {
    const link = document.createElement('a');
    link.href = base64;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const navItems = [
    { id: 'generate', label: 'Erstellen', icon: Wand2, description: 'Neues Design entwerfen' },
    { id: 'feedback', label: 'Analyse', icon: LineChart, description: 'Kanal-Performance prüfen' },
    { id: 'remake', label: 'Neuauflage', icon: Copy, description: 'Stile klonen' },
    { id: 'designs', label: 'Bibliothek', icon: Grid, description: 'Deine Kreationen' },
  ];

  return (
    <div className="pt-24 min-h-screen bg-[#030712] p-4 lg:p-8 animate-in fade-in duration-500">
      <div className="max-w-7xl mx-auto flex flex-col lg:flex-row gap-8">

        {/* Linke Seitenleiste - Navigation */}
        <aside className="lg:w-64 flex-shrink-0">
          <div className="sticky top-24 space-y-2 flex lg:flex-col overflow-x-auto lg:overflow-visible pb-4 lg:pb-0 no-scrollbar gap-2 lg:gap-2">
            <p className="hidden lg:block text-[10px] font-bold text-gray-500 uppercase tracking-[0.2em] mb-4 ml-4">Studio Navigation</p>
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => setActiveTab(item.id as Tab)}
                className={`flex items-center gap-4 px-4 py-4 rounded-2xl font-semibold transition-all shrink-0 w-full text-left group border ${
                  activeTab === item.id 
                    ? 'bg-blue-600/10 border-blue-500/50 text-white shadow-lg shadow-blue-500/5' 
                    : 'bg-white/5 border-transparent text-gray-400 hover:bg-white/10 hover:text-gray-200'
                }`}
              >
                <div className={`p-2 rounded-xl transition-colors ${activeTab === item.id ? 'bg-blue-600 text-white' : 'bg-white/5 text-gray-500 group-hover:text-gray-300'}`}>
                  <item.icon className="w-5 h-5" />
                </div>
                <div className="hidden lg:block flex-1">
                  <p className="text-sm leading-none mb-1">{item.label}</p>
                  <p className="text-[10px] text-gray-500 font-normal truncate">{item.description}</p>
                </div>
                {activeTab === item.id && <ChevronRight className="hidden lg:block w-4 h-4 text-blue-500" />}
              </button>
            ))}
          </div>
        </aside>

        {/* Hauptinhalt - Steuerung und Vorschau */}
        <div className="flex-1 grid lg:grid-cols-12 gap-8">

          {/* Steuerungspanel */}
          <div className="lg:col-span-5 space-y-6">
            <div className="glass rounded-[2rem] p-6 lg:p-8 space-y-6 border-white/5 shadow-2xl">
              {activeTab === 'generate' && (
                <div className="space-y-6 animate-in slide-in-from-left-4 duration-300">
                  <div>
                    <label className="block text-xs font-bold text-blue-500 mb-2 uppercase tracking-[0.2em]">Beschreibung (Prompt)</label>
                    <textarea 
                      placeholder="Beschreibe dein Thumbnail (z.B. 'MrBeast Stil, Person zeigt geschockt auf einen Goldtresor')"
                      className="w-full h-32 bg-black/40 border border-white/10 rounded-2xl p-4 focus:outline-none focus:border-blue-500 transition-all resize-none text-sm leading-relaxed"
                      value={prompt}
                      onChange={(e) => setPrompt(e.target.value)}
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-bold text-blue-500 mb-3 uppercase tracking-[0.2em]">Referenzbild (Optional)</label>
                    <div className="relative group cursor-pointer border-2 border-dashed border-white/10 rounded-2xl aspect-video flex items-center justify-center overflow-hidden hover:border-blue-500/50 transition-colors bg-black/20">
                      {inputImage ? (
                        <div className="relative w-full h-full">
                          <img src={inputImage} className="w-full h-full object-cover" />
                          <button 
                            onClick={(e) => { e.stopPropagation(); setInputImage(null); }}
                            className="absolute top-2 right-2 p-1.5 bg-black/60 rounded-full hover:bg-red-500 transition-colors"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      ) : (
                        <div className="text-center text-gray-500 p-4">
                          <Upload className="w-8 h-8 mx-auto mb-2 opacity-20" />
                          <p className="text-xs">Assets hochladen oder hierher ziehen</p>
                        </div>
                      )}
                      {!inputImage && <input type="file" accept="image/*" onChange={(e) => handleFileUpload(e, 'input')} className="absolute inset-0 opacity-0 cursor-pointer" />}
                    </div>
                  </div>

                  <div>
                    <label className="block text-xs font-bold text-blue-500 mb-3 uppercase tracking-[0.2em]">Visueller Stil</label>
                    <div className="grid grid-cols-2 gap-2">
                      {Object.values(ThumbnailStyle).map((s) => (
                        <button
                          key={s}
                          onClick={() => setStyle(s)}
                          className={`py-3 px-4 rounded-xl border text-xs font-bold transition-all ${
                            style === s ? 'border-blue-500 bg-blue-500/10 text-blue-400' : 'border-white/10 bg-black/40 hover:bg-white/10 text-gray-400'
                          }`}
                        >
                          {s}
                        </button>
                      ))}
                    </div>
                  </div>

                  <button 
                    onClick={handleGenerate}
                    disabled={loading || !prompt}
                    className="w-full py-4 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-2xl font-bold text-lg shadow-xl shadow-blue-500/20 flex items-center justify-center gap-2 transition-all active:scale-[0.98]"
                  >
                    {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <><Sparkles className="w-5 h-5" /> Thumbnail erstellen</>}
                  </button>
                </div>
              )}

              {activeTab === 'feedback' && (
                <div className="space-y-6 animate-in slide-in-from-left-4 duration-300">
                  <div className="bg-blue-500/5 p-4 rounded-2xl border border-blue-500/10">
                    <p className="text-sm text-blue-300/80 leading-relaxed">
                      Unsere KI analysiert das Branding, die Farbpalette und die aktuelle CTR-Performance deines Kanals für konkrete Optimierungsvorschläge.
                    </p>
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-blue-500 mb-2 uppercase tracking-[0.2em]">YouTube Kanal-URL</label>
                    <input 
                      type="url"
                      placeholder="https://youtube.com/@DeinKanal"
                      className="w-full bg-black/40 border border-white/10 rounded-2xl p-4 focus:outline-none focus:border-blue-500 transition-all"
                      value={channelUrl}
                      onChange={(e) => setChannelUrl(e.target.value)}
                    />
                  </div>
                  <button 
                    onClick={handleAnalyze}
                    disabled={loading || !channelUrl}
                    className="w-full py-4 bg-white text-black hover:bg-gray-200 disabled:opacity-50 rounded-2xl font-bold text-lg flex items-center justify-center gap-2 transition-all active:scale-[0.98]"
                  >
                    {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <><LineChart className="w-5 h-5" /> Analyse starten</>}
                  </button>
                </div>
              )}

              {activeTab === 'remake' && (
                <div className="space-y-6 animate-in slide-in-from-left-4 duration-300">
                  <div>
                    <label className="block text-xs font-bold text-indigo-500 mb-2 uppercase tracking-[0.2em]">Stil-Vorlage (Screenshot hochladen)</label>
                    <div className="relative group cursor-pointer border-2 border-dashed border-white/10 rounded-2xl aspect-video flex items-center justify-center overflow-hidden hover:border-indigo-500/50 transition-colors bg-black/20">
                      {referenceImage ? (
                        <div className="relative w-full h-full">
                          <img src={referenceImage} className="w-full h-full object-cover" />
                          <button 
                            onClick={(e) => { e.stopPropagation(); setReferenceImage(null); }}
                            className="absolute top-2 right-2 p-1.5 bg-black/60 rounded-full hover:bg-red-500 transition-colors"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      ) : (
                        <div className="text-center text-gray-500 p-4">
                          <Upload className="w-8 h-8 mx-auto mb-2 opacity-20" />
                          <p className="text-xs">Thumbnail zum Klonen hochladen</p>
                        </div>
                      )}
                      {!referenceImage && <input type="file" accept="image/*" onChange={(e) => handleFileUpload(e, 'reference')} className="absolute inset-0 opacity-0 cursor-pointer" />}
                    </div>
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-indigo-500 mb-2 uppercase tracking-[0.2em]">Anpassungen</label>
                    <textarea 
                      placeholder="Was soll anders sein? (z.B. 'Hintergrund dunkelblau machen und Hauptcharakter durch eine Pizza ersetzen')"
                      className="w-full h-24 bg-black/40 border border-white/10 rounded-2xl p-4 focus:outline-none focus:border-indigo-500 transition-all resize-none text-sm"
                      value={prompt}
                      onChange={(e) => setPrompt(e.target.value)}
                    />
                  </div>
                  <button 
                    onClick={handleRemake}
                    disabled={loading || !referenceImage || !prompt}
                    className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white rounded-2xl font-bold text-lg flex items-center justify-center gap-2 transition-all active:scale-[0.98]"
                  >
                    {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <><Copy className="w-5 h-5" /> Stil klonen & anpassen</>}
                  </button>
                </div>
              )}

              {activeTab === 'designs' && (
                <div className="space-y-4 animate-in slide-in-from-left-4 duration-300">
                  <div className="flex items-center justify-between">
                    <h3 className="text-lg font-bold">Arbeitsbereich</h3>
                    <button className="text-gray-500 hover:text-white transition-colors"><History className="w-5 h-5" /></button>
                  </div>
                  <p className="text-xs text-gray-500 leading-relaxed uppercase tracking-widest font-bold">Letzte Designs</p>
                  <div className="grid grid-cols-1 gap-3">
                    {designs.slice(0, 5).map(d => (
                      <div key={d.id} className="flex gap-4 p-3 bg-white/5 rounded-xl border border-white/5 items-center group">
                        <img src={d.imageUrl} className="w-16 h-10 rounded object-cover" />
                        <div className="flex-1 overflow-hidden">
                          <p className="text-xs font-bold truncate text-gray-300">{d.prompt}</p>
                          <p className="text-[10px] text-gray-600">{d.createdAt}</p>
                        </div>
                        <button 
                          onClick={() => downloadImage(d.imageUrl, `thumb-${d.id}.png`)}
                          className="p-1.5 hover:bg-white/10 rounded-lg text-gray-500 hover:text-white"
                        >
                          <Download className="w-4 h-4" />
                        </button>
                      </div>
                    ))}
                    {designs.length === 0 && <p className="text-sm text-gray-600 text-center py-8">Noch keine Aktivitäten vorhanden</p>}
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Vorschaupanel */}
