    </nav>
  );
};

import React, { useState, useEffect } from 'react';
import { Tab, ThumbnailStyle, Design } from '../types';
import { Wand2, LineChart, Copy, Grid, Upload, Sparkles, Loader2, Download, Trash2, History, CheckCircle2, AlertCircle, ChevronRight } from 'lucide-react';
import { generateThumbnail, analyzeChannel, remakeThumbnail } from '../services/geminiService';

const LOADING_STEPS = [
  "Analysiere Prompt...",
  "Generiere Komposition...",
  "Optimiere Farbpalette...",
  "Berechne Kontrast...",
  "Rendere Details...",
  "Finalisiere Export..."
];

export const Studio: React.FC = () => {
  const [activeTab, setActiveTab] = React.useState<Tab>('generate');
  const [prompt, setPrompt] = React.useState('');
  const [style, setStyle] = React.useState<ThumbnailStyle>(ThumbnailStyle.CLEAN);
  const [channelUrl, setChannelUrl] = React.useState('');
  const [loading, setLoading] = React.useState(false);
  const [uploading, setUploading] = React.useState(false);
  const [progress, setProgress] = React.useState(0);
  const [currentStep, setCurrentStep] = React.useState(0);
  const [previewImage, setPreviewImage] = React.useState<string | null>(null);
  const [designs, setDesigns] = React.useState<Design[]>([]);
  const [analysis, setAnalysis] = React.useState<any>(null);
  const [referenceImage, setReferenceImage] = React.useState<string | null>(null);
  const [inputImage, setInputImage] = React.useState<string | null>(null);

  // Simulierter Fortschrittsbalken-Effekt
  useEffect(() => {
    let interval: any;
    if (loading) {
      setProgress(0);
      setCurrentStep(0);
      interval = setInterval(() => {
        setProgress((prev) => {
          if (prev < 90) return prev + Math.random() * 15;
          return prev + 0.2; // Verlangsamen am Ende
        });
        setCurrentStep((prev) => (prev < LOADING_STEPS.length - 1 ? prev + 1 : prev));
      }, 800);
    } else {
      setProgress(0);
      setCurrentStep(0);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const handleGenerate = async () => {
    if (!prompt) return;
    setLoading(true);
    setPreviewImage(null);
    try {
      const result = await generateThumbnail(prompt, style, inputImage || undefined);
      setProgress(100);
      setTimeout(() => {
        setPreviewImage(result);
        setDesigns([{
          id: Date.now().toString(),
          imageUrl: result,
          prompt: prompt,
          createdAt: new Date().toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' })
        }, ...designs]);
      }, 500);
    } catch (err) {
      console.error(err);
      alert("Fehler bei der Thumbnail-Erstellung. Bitte erneut versuchen.");
    } finally {
      setTimeout(() => setLoading(false), 600);
    }
  };

  const handleAnalyze = async () => {
    if (!channelUrl) return;
    setLoading(true);
    try {
      const result = await analyzeChannel(channelUrl);
      setAnalysis(result);
    } catch (err) {
      console.error(err);
      alert("Analyse fehlgeschlagen. Überprüfe die URL.");
    } finally {
      setLoading(false);
    }
  };

  const handleRemake = async () => {
    if (!referenceImage || !prompt) return;
    setLoading(true);
    setPreviewImage(null);
    try {
      const result = await remakeThumbnail(referenceImage, prompt);
      setProgress(100);
      setTimeout(() => {
        setPreviewImage(result);
        setDesigns([{
          id: Date.now().toString(),
          imageUrl: result,
          prompt: `Neuauflage: ${prompt}`,
          createdAt: new Date().toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' })
        }, ...designs]);
      }, 500);
    } catch (err) {
      console.error(err);
      alert("Neuauflage fehlgeschlagen. Versuche eine andere Vorlage.");
    } finally {
      setTimeout(() => setLoading(false), 600);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'reference' | 'input') => {
    const file = e.target.files?.[0];
    if (file) {
      setUploading(true);
      const reader = new FileReader();
      reader.onloadend = () => {
        setTimeout(() => {
          if (target === 'reference') setReferenceImage(reader.result as string);
          else setInputImage(reader.result as string);
          setUploading(false);
        }, 800); // Künstliche Verzögerung für besseres Feedback
      };
      reader.readAsDataURL(file);
    }
  };

  const downloadImage = (base64: string, filename: string) => {
    const link = document.createElement('a');
    link.href = base64;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const navItems = [
    { id: 'generate', label: 'Erstellen', icon: Wand2, description: 'Neues Design entwerfen' },
    { id: 'feedback', label: 'Analyse', icon: LineChart, description: 'Kanal-Performance prüfen' },
    { id: 'remake', label: 'Neuauflage', icon: Copy, description: 'Stile klonen' },
    { id: 'designs', label: 'Bibliothek', icon: Grid, description: 'Deine Kreationen' },
  ];

  return (
    <div className="pt-24 min-h-screen bg-[#030712] p-4 lg:p-8 animate-in fade-in duration-500">
      <div className="max-w-7xl mx-auto flex flex-col lg:flex-row gap-8">

        {/* Linke Seitenleiste - Navigation */}
        <aside className="lg:w-64 flex-shrink-0">
          <div className="sticky top-24 space-y-2 flex lg:flex-col overflow-x-auto lg:overflow-visible pb-4 lg:pb-0 no-scrollbar gap-2 lg:gap-2">
            <p className="hidden lg:block text-[10px] font-bold text-gray-500 uppercase tracking-[0.2em] mb-4 ml-4">Studio Navigation</p>
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => setActiveTab(item.id as Tab)}
                className={`flex items-center gap-4 px-4 py-4 rounded-2xl font-semibold transition-all shrink-0 w-full text-left group border ${
                  activeTab === item.id 
                    ? 'bg-blue-600/10 border-blue-500/50 text-white shadow-lg shadow-blue-500/5' 
                    : 'bg-white/5 border-transparent text-gray-400 hover:bg-white/10 hover:text-gray-200'
                }`}
              >
                <div className={`p-2 rounded-xl transition-colors ${activeTab === item.id ? 'bg-blue-600 text-white' : 'bg-white/5 text-gray-500 group-hover:text-gray-300'}`}>
                  <item.icon className="w-5 h-5" />
                </div>
                <div className="hidden lg:block flex-1">
                  <p className="text-sm leading-none mb-1">{item.label}</p>
                  <p className="text-[10px] text-gray-500 font-normal truncate">{item.description}</p>
                </div>
                {activeTab === item.id && <ChevronRight className="hidden lg:block w-4 h-4 text-blue-500" />}
              </button>
            ))}
          </div>
        </aside>

        {/* Hauptinhalt - Steuerung und Vorschau */}
        <div className="flex-1 grid lg:grid-cols-12 gap-8">

          {/* Steuerungspanel */}
          <div className="lg:col-span-5 space-y-6">
            <div className="glass rounded-[2rem] p-6 lg:p-8 space-y-6 border-white/5 shadow-2xl">
              {activeTab === 'generate' && (
                <div className="space-y-6 animate-in slide-in-from-left-4 duration-300">
                  <div>
                    <label className="block text-xs font-bold text-blue-500 mb-2 uppercase tracking-[0.2em]">Beschreibung (Prompt)</label>
                    <textarea 
                      placeholder="Beschreibe dein Thumbnail (z.B. 'MrBeast Stil, Person zeigt geschockt auf einen Goldtresor')"
                      className="w-full h-32 bg-black/40 border border-white/10 rounded-2xl p-4 focus:outline-none focus:border-blue-500 transition-all resize-none text-sm leading-relaxed"
                      value={prompt}
                      onChange={(e) => setPrompt(e.target.value)}
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-bold text-blue-500 mb-3 uppercase tracking-[0.2em]">Referenzbild (Optional)</label>
                    <div className="relative group cursor-pointer border-2 border-dashed border-white/10 rounded-2xl aspect-video flex items-center justify-center overflow-hidden hover:border-blue-500/50 transition-colors bg-black/20">
                      {uploading ? (
                         <div className="flex flex-col items-center gap-2 animate-pulse">
                            <Loader2 className="w-8 h-8 text-blue-500 animate-spin" />
                            <span className="text-xs text-blue-500 font-bold uppercase tracking-widest">Wird hochgeladen...</span>
                         </div>
                      ) : inputImage ? (
                        <div className="relative w-full h-full">
