import React from 'react';
import { User } from './types';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { Features } from './components/Features';
import { Pricing } from './components/Pricing';
import { Reviews } from './components/Reviews';
import { Studio } from './components/Studio';
import { AuthModal } from './components/AuthModal';
import { Examples } from './components/Examples';
import { Zap, ArrowLeft } from 'lucide-react';

type MainView = 'home' | 'studio' | 'pricing' | 'reviews' | 'examples';

function App() {
  const [user, setUser] = React.useState<User | null>(null);
  const [currentView, setCurrentView] = React.useState<MainView>('home');
  const [isAuthOpen, setIsAuthOpen] = React.useState(false);

  const handleLogin = (email: string) => {
    setUser({
      id: '1',
      email: email,
      name: email.split('@')[0],
      isLoggedIn: true
    });
    setIsAuthOpen(false);
    setCurrentView('studio');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleStartCreating = () => {
    if (user) {
      setCurrentView('studio');
    } else {
      setIsAuthOpen(true);
    }
  };

  const handleNavigate = (view: MainView) => {
    setCurrentView(view);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const BackButton = () => (
    <button 
      onClick={() => handleNavigate('home')}
      className="fixed top-24 left-4 lg:left-8 z-40 flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 border border-white/10 rounded-full text-sm font-bold transition-all group"
    >
      <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
      Zurück
    </button>
  );

  return (
    <div className="min-h-screen selection:bg-blue-500 selection:text-white bg-[#030712] text-gray-100">
      <Navbar 
        user={user} 
        onNavigate={handleNavigate} 
        onLoginClick={() => setIsAuthOpen(true)} 
      />

      <main>
        {currentView === 'home' && (
          <div className="animate-in fade-in duration-700">
            <Hero 
              onStartCreating={handleStartCreating} 
              onViewPricing={() => handleNavigate('pricing')} 
            />
            <Features />
            <Pricing />
            <Reviews />
          </div>
        )}

        {currentView === 'pricing' && (
          <div className="pt-20">
            <BackButton />
            <Pricing />
          </div>
        )}

        {currentView === 'reviews' && (
          <div className="pt-20">
            <BackButton />
            <Reviews />
          </div>
        )}

        {currentView === 'examples' && (
          <div className="pt-20">
            <BackButton />
            <Examples onNavigateToStudio={() => handleNavigate('studio')} />
          </div>
        )}

        {currentView === 'studio' && <Studio />}
      </main>

      <footer className="py-20 border-t border-white/5 bg-black mt-20">
        <div className="max-w-7xl mx-auto px-4">
          <div className="grid md:grid-cols-4 gap-12 mb-16">
            <div className="col-span-2">
              <div className="flex items-center gap-2 mb-6">
                  <div className="bg-blue-600 p-1.5 rounded-lg shadow-lg shadow-blue-600/20">
                      <Zap className="w-5 h-5 text-white fill-white" />
                  </div>
                  <span className="text-xl font-bold tracking-tight">Thumbify <span className="text-blue-500">AI</span></span>
              </div>
              <p className="text-gray-500 max-w-sm leading-relaxed">
                Wir unterstützen die nächste Generation von Creatoren mit KI-Tools auf Profi-Niveau. Steigere deine CTR und dominiere den Feed.
              </p>
            </div>
            <div>
              <h4 className="font-bold mb-6 text-sm uppercase tracking-widest text-gray-300">Produkt</h4>
              <ul className="space-y-4 text-gray-500 text-sm">
                <li><button onClick={() => handleNavigate('studio')} className="hover:text-blue-500 transition-colors">Studio</button></li>
                <li><button onClick={() => handleNavigate('pricing')} className="hover:text-blue-500 transition-colors">Preise</button></li>
                <li><button onClick={() => handleNavigate('reviews')} className="hover:text-blue-500 transition-colors">Bewertungen</button></li>
                <li><button onClick={() => handleNavigate('examples')} className="hover:text-blue-500 transition-colors">Beispiele</button></li>
              </ul>
            </div>
            <div>
              <h4 className="font-bold mb-6 text-sm uppercase tracking-widest text-gray-300">Unternehmen</h4>
              <ul className="space-y-4 text-gray-500 text-sm">
                <li><a href="#" className="hover:text-blue-500 transition-colors">Über uns</a></li>
                <li><a href="#" className="hover:text-blue-500 transition-colors">Karriere</a></li>
                <li><a href="#" className="hover:text-blue-500 transition-colors">Bedingungen</a></li>
                <li><a href="#" className="hover:text-blue-500 transition-colors">Datenschutz</a></li>
              </ul>
            </div>
          </div>
          <div className="pt-8 border-t border-white/5 flex flex-col md:flex-row justify-between items-center gap-4">
            <p className="text-gray-600 text-xs tracking-wide uppercase font-medium">© 2024 Thumbify AI. Alle Rechte vorbehalten.</p>
          </div>
        </div>
      </footer>

      <AuthModal 
        isOpen={isAuthOpen} 
        onClose={() => setIsAuthOpen(false)} 
        onLogin={handleLogin} 
      />
    </div>
  );
}

export default App;

