  const [referenceImage, setReferenceImage] = React.useState<string | null>(null);
  const [inputImage, setInputImage] = React.useState<string | null>(null);

  useEffect(() => {
    let interval: any;
    if (loading) {
      setProgress(0);
      setCurrentStep(0);
      interval = setInterval(() => {
        setProgress((prev) => {
          if (prev < 90) return prev + Math.random() * 15;
          return prev + 0.2; 
        });
        setCurrentStep((prev) => (prev < LOADING_STEPS.length - 1 ? prev + 1 : prev));
      }, 800);
    } else {
      setProgress(0);
      setCurrentStep(0);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const validateYouTubeUrl = (url: string) => {
    const pattern = /^(https?:\/\/)?(www\.)?youtube\.com\/(channel\/|user\/|c\/|@)[a-zA-Z0-9_-]+/;
    return pattern.test(url);
  };

  const handleGenerate = async () => {
    if (!prompt) return;
    setLoading(true);
    setPreviewImage(null);
    try {
      const result = await generateThumbnail(prompt, style, inputImage || undefined);
      setProgress(100);
      setTimeout(() => {
        setPreviewImage(result);
        setDesigns([{
          id: Date.now().toString(),
          imageUrl: result,
          prompt: prompt,
          createdAt: new Date().toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' })
        }, ...designs]);
      }, 500);
    } catch (err) {
      console.error(err);
      alert("Fehler bei der Thumbnail-Erstellung. Bitte erneut versuchen.");
    } finally {
      setTimeout(() => setLoading(false), 600);
    }
  };

  const handleAnalyze = async () => {
    if (!channelUrl) return;
    if (!validateYouTubeUrl(channelUrl)) {
      setUrlError("Bitte gib eine gültige YouTube-Kanal-URL ein (z.B. youtube.com/@name)");
      return;
    }
    setUrlError(null);
    setLoading(true);
    try {
      const result = await analyzeChannel(channelUrl);
      setAnalysis(result);
    } catch (err) {
      console.error(err);
      alert("Analyse fehlgeschlagen. Überprüfe die URL.");
    } finally {
      setLoading(false);
    }
  };

  const handleRemake = async () => {
    if (!referenceImage || !prompt) return;
    setLoading(true);
    setPreviewImage(null);
    try {
      const result = await remakeThumbnail(referenceImage, prompt);
      setProgress(100);
      setTimeout(() => {
        setPreviewImage(result);
        setDesigns([{
          id: Date.now().toString(),
          imageUrl: result,
          prompt: `Neuauflage: ${prompt}`,
          createdAt: new Date().toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' })
        }, ...designs]);
      }, 500);
    } catch (err) {
      console.error(err);
      alert("Neuauflage fehlgeschlagen. Versuche eine andere Vorlage.");
    } finally {
      setTimeout(() => setLoading(false), 600);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'reference' | 'input') => {
    const file = e.target.files?.[0];
    if (file) {
      setUploading(true);
      const reader = new FileReader();
      reader.onloadend = () => {
        setTimeout(() => {
          if (target === 'reference') setReferenceImage(reader.result as string);
          else setInputImage(reader.result as string);
          setUploading(false);
        }, 800);
      };
      reader.readAsDataURL(file);
    }
  };

  const downloadImage = (base64: string, filename: string) => {
    const link = document.createElement('a');
    link.href = base64;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const navItems = [
    { id: 'generate', label: 'Erstellen', icon: Wand2, description: 'Neues Design entwerfen' },
    { id: 'feedback', label: 'Analyse', icon: LineChart, description: 'Kanal-Performance prüfen' },
    { id: 'remake', label: 'Neuauflage', icon: Copy, description: 'Stile klonen' },
    { id: 'designs', label: 'Bibliothek', icon: Grid, description: 'Deine Kreationen' },
  ];

  return (
    <div className="pt-24 min-h-screen bg-sky-50 dark:bg-slate-950 transition-colors duration-500 p-4 lg:p-8 animate-in fade-in duration-500">
      <div className="max-w-7xl mx-auto flex flex-col lg:flex-row gap-8">

        {/* Linke Seitenleiste - Navigation */}
        <aside className="lg:w-64 flex-shrink-0">
          <div className="sticky top-24 space-y-2 flex lg:flex-col overflow-x-auto lg:overflow-visible pb-4 lg:pb-0 no-scrollbar gap-2 lg:gap-2">
            <p className="hidden lg:block text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em] mb-4 ml-4">Studio Navigation</p>
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => setActiveTab(item.id as Tab)}
                className={`flex items-center gap-4 px-4 py-4 rounded-2xl font-semibold transition-all shrink-0 w-full text-left group border ${
                  activeTab === item.id 
                    ? 'bg-blue-600/10 border-blue-500/50 text-blue-600 dark:text-blue-400 shadow-lg shadow-blue-500/5' 
                    : 'bg-white/60 dark:bg-slate-900/60 border-transparent text-slate-500 dark:text-slate-400 hover:bg-blue-50 dark:hover:bg-slate-800 hover:text-blue-600'
                }`}
              >
                <div className={`p-2 rounded-xl transition-colors ${activeTab === item.id ? 'bg-blue-600 text-white' : 'bg-slate-100 dark:bg-slate-800 text-slate-500 group-hover:text-blue-600'}`}>
                  <item.icon className="w-5 h-5" />
                </div>
                <div className="hidden lg:block flex-1">
                  <p className="text-sm leading-none mb-1">{item.label}</p>
                  <p className="text-[10px] text-slate-400 dark:text-slate-500 font-normal truncate">{item.description}</p>
                </div>
                {activeTab === item.id && <ChevronRight className="hidden lg:block w-4 h-4 text-blue-500" />}
              </button>
            ))}
          </div>
        </aside>

        {/* Hauptinhalt */}
        <div className="flex-1 grid lg:grid-cols-12 gap-8">

          {/* Steuerungspanel */}
          <div className="lg:col-span-5 space-y-6">
            <div className="glass dark:bg-slate-900/80 rounded-[2rem] p-6 lg:p-8 space-y-6 border-black/5 dark:border-white/5 shadow-2xl transition-colors">
              {activeTab === 'generate' && (
                <div className="space-y-6 animate-in slide-in-from-left-4 duration-300">
                  <div>
                    <label className="block text-xs font-bold text-blue-600 dark:text-blue-400 mb-2 uppercase tracking-[0.2em]">Beschreibung (Prompt)</label>
                    <textarea 
                      placeholder="Beschreibe dein Thumbnail (z.B. 'MrBeast Stil, Person zeigt geschockt auf einen Goldtresor')"
                      className="w-full h-32 bg-white/80 dark:bg-slate-800/80 border border-black/5 dark:border-white/10 rounded-2xl p-4 focus:outline-none focus:border-blue-500 transition-all resize-none text-sm leading-relaxed text-slate-800 dark:text-slate-100"
                      value={prompt}
                      onChange={(e) => setPrompt(e.target.value)}
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-bold text-blue-600 dark:text-blue-400 mb-3 uppercase tracking-[0.2em]">Referenzbild (Optional)</label>
                    <div className="relative group cursor-pointer border-2 border-dashed border-black/5 dark:border-white/10 rounded-2xl aspect-video flex items-center justify-center overflow-hidden hover:border-blue-500/50 transition-colors bg-white/40 dark:bg-slate-800/40">
                      {uploading ? (
                         <div className="flex flex-col items-center gap-2 animate-pulse">
                            <Loader2 className="w-8 h-8 text-blue-600 animate-spin" />
                            <span className="text-xs text-blue-600 font-bold uppercase tracking-widest">Wird hochgeladen...</span>
                         </div>
                      ) : inputImage ? (
                        <div className="relative w-full h-full">
                          <img src={inputImage} className="w-full h-full object-cover" />
                          <button 
                            onClick={(e) => { e.stopPropagation(); setInputImage(null); }}
                            className="absolute top-2 right-2 p-1.5 bg-black/60 rounded-full hover:bg-red-500 transition-colors text-white"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      ) : (
                        <div className="text-center text-slate-400 dark:text-slate-500 p-4">
                          <Upload className="w-8 h-8 mx-auto mb-2 opacity-40" />
                          <p className="text-xs">Assets hochladen oder hierher ziehen</p>
                        </div>
                      )}
                      {!inputImage && !uploading && <input type="file" accept="image/*" onChange={(e) => handleFileUpload(e, 'input')} className="absolute inset-0 opacity-0 cursor-pointer" />}
                    </div>
                  </div>

                  <div>
                    <label className="block text-xs font-bold text-blue-600 dark:text-blue-400 mb-3 uppercase tracking-[0.2em]">Visueller Stil</label>
                    <div className="grid grid-cols-2 gap-2">
                      {Object.values(ThumbnailStyle).map((s) => (
                        <button
                          key={s}
                          onClick={() => setStyle(s)}
                          className={`py-3 px-4 rounded-xl border text-xs font-bold transition-all ${
                            style === s ? 'border-blue-500 bg-blue-500/10 text-blue-600 dark:text-blue-400' : 'border-black/5 dark:border-white/5 bg-white/60 dark:bg-slate-800/60 hover:bg-blue-50 dark:hover:bg-slate-700 text-slate-500 dark:text-slate-400'
                          }`}
                        >
                          {s}
                        </button>
                      ))}
                    </div>
                  </div>

                  <button 
                    onClick={handleGenerate}
                    disabled={loading || !prompt}
                    className="w-full py-4 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-2xl font-bold text-lg shadow-xl shadow-blue-500/20 flex items-center justify-center gap-2 transition-all active:scale-[0.98]"
                  >
                    {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <><Sparkles className="w-5 h-5" /> Thumbnail erstellen</>}
                  </button>
                </div>
              )}

              {activeTab === 'feedback' && (
                <div className="space-y-6 animate-in slide-in-from-left-4 duration-300">
                  <div className="bg-blue-50 dark:bg-blue-900/20 p-4 rounded-2xl border border-blue-100 dark:border-blue-800">
                    <p className="text-sm text-blue-600 dark:text-blue-400 leading-relaxed font-medium">
                      Unsere KI analysiert das Branding und die aktuelle CTR-Performance deines Kanals für Optimierungsvorschläge.
                    </p>
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-blue-600 dark:text-blue-400 mb-2 uppercase tracking-[0.2em]">YouTube Kanal-URL</label>
                    <input 
                      type="url"
                      placeholder="https://youtube.com/@DeinKanal"
                      className={`w-full bg-white/80 dark:bg-slate-800/80 border rounded-2xl p-4 focus:outline-none transition-all text-slate-800 dark:text-slate-100 ${
                        urlError ? 'border-red-500' : 'border-black/5 dark:border-white/10 focus:border-blue-500'
                      }`}
                      value={channelUrl}
                      onChange={(e) => {
                        setChannelUrl(e.target.value);
                        if (urlError) setUrlError(null);
                      }}
                    />
                    {urlError && (
                      <p className="text-red-500 text-[10px] mt-2 font-bold uppercase tracking-wider">
                        <AlertCircle className="w-3 h-3 inline mr-1 -mt-0.5" />
                        {urlError}
                      </p>
                    )}
                  </div>
                  <button 
                    onClick={handleAnalyze}
                    disabled={loading || !channelUrl}
                    className="w-full py-4 bg-slate-900 dark:bg-slate-100 text-white dark:text-slate-900 hover:bg-slate-800 dark:hover:bg-white disabled:opacity-50 rounded-2xl font-bold text-lg flex items-center justify-center gap-2 transition-all"
                  >
                    {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <><LineChart className="w-5 h-5" /> Analyse starten</>}
                  </button>
                </div>
              )}

              {activeTab === 'remake' && (
                <div className="space-y-6 animate-in slide-in-from-left-4 duration-300">
                   <div>
                    <label className="block text-xs font-bold text-indigo-600 dark:text-indigo-400 mb-2 uppercase tracking-[0.2em]">Stil-Vorlage</label>
                    <div className="relative group cursor-pointer border-2 border-dashed border-black/5 dark:border-white/10 rounded-2xl aspect-video flex items-center justify-center overflow-hidden hover:border-indigo-500/50 transition-colors bg-white/40 dark:bg-slate-800/40">
                      {uploading ? (
                         <div className="flex flex-col items-center gap-2 animate-pulse">
                            <Loader2 className="w-8 h-8 text-indigo-600 animate-spin" />
                            <span className="text-xs text-indigo-600 font-bold uppercase tracking-widest">Wird hochgeladen...</span>
                         </div>
                      ) : referenceImage ? (
                        <div className="relative w-full h-full">
                          <img src={referenceImage} className="w-full h-full object-cover" />
                          <button 
                            onClick={(e) => { e.stopPropagation(); setReferenceImage(null); }}
                            className="absolute top-2 right-2 p-1.5 bg-black/60 rounded-full hover:bg-red-500 transition-colors text-white"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      ) : (
                        <div className="text-center text-slate-400 dark:text-slate-500 p-4">
                          <Upload className="w-8 h-8 mx-auto mb-2 opacity-40" />
                          <p className="text-xs">Stil zum Klonen hochladen</p>
                        </div>
                      )}
                      {!referenceImage && !uploading && <input type="file" accept="image/*" onChange={(e) => handleFileUpload(e, 'reference')} className="absolute inset-0 opacity-0 cursor-pointer" />}
                    </div>
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-indigo-600 dark:text-indigo-400 mb-2 uppercase tracking-[0.2em]">Anpassungen</label>
                    <textarea 
                      placeholder="Was soll anders sein?"
                      className="w-full h-24 bg-white/80 dark:bg-slate-800/80 border border-black/5 dark:border-white/10 rounded-2xl p-4 focus:outline-none focus:border-indigo-500 transition-all resize-none text-sm text-slate-800 dark:text-slate-100"
                      value={prompt}
                      onChange={(e) => setPrompt(e.target.value)}
                    />
                  </div>
                  <button 
                    onClick={handleRemake}
                    disabled={loading || !referenceImage || !prompt}
                    className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 text-white rounded-2xl font-bold text-lg flex items-center justify-center gap-2 transition-all"
                  >
                    {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <><Copy className="w-5 h-5" /> Stil klonen</>}
                  </button>
                </div>
              )}

              {activeTab === 'designs' && (
                <div className="space-y-4 animate-in slide-in-from-left-4 duration-300">
                  <div className="flex items-center justify-between">
                    <h3 className="text-lg font-bold text-slate-800 dark:text-slate-200">Arbeitsbereich</h3>
                    <button className="text-slate-400 hover:text-blue-600 transition-colors"><History className="w-5 h-5" /></button>
                  </div>
                  <div className="grid grid-cols-1 gap-3">
                    {designs.map(d => (
                      <div key={d.id} className="flex gap-4 p-3 bg-white/60 dark:bg-slate-800/60 rounded-xl border border-black/5 dark:border-white/5 items-center">
                        <img src={d.imageUrl} className="w-16 h-10 rounded object-cover shadow-sm" />
                        <div className="flex-1 overflow-hidden">
                          <p className="text-xs font-bold truncate text-slate-700 dark:text-slate-300">{d.prompt}</p>
                          <p className="text-[10px] text-slate-400">{d.createdAt}</p>
                        </div>
                        <button onClick={() => downloadImage(d.imageUrl, `thumbify-${d.id}.png`)} className="p-1.5 hover:bg-blue-50 dark:hover:bg-slate-700 rounded-lg text-slate-400 hover:text-blue-600">
                          <Download className="w-4 h-4" />
                        </button>
                      </div>
                    ))}
                    {designs.length === 0 && <p className="text-sm text-slate-400 text-center py-8">Noch keine Aktivitäten vorhanden</p>}
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Vorschaupanel */}
          <div className="lg:col-span-7">
            <div className="glass dark:bg-slate-900/80 rounded-[2rem] p-4 lg:p-8 min-h-[600px] flex flex-col border-black/5 dark:border-white/5 relative overflow-hidden shadow-2xl transition-colors duration-500">
              <div className="flex items-center justify-between mb-8">
                <div>
                  <h3 className="text-sm font-bold uppercase tracking-[0.2em] text-slate-400 dark:text-slate-500">Vorschau-Engine</h3>
                  {loading && <div className="text-[10px] text-blue-600 dark:text-blue-400 animate-pulse font-bold mt-1">Berechne Pixel...</div>}
                </div>
              </div>

              <div className="flex-1 flex flex-col">
                {loading ? (
                  <div className="flex-1 flex flex-col items-center justify-center gap-8 animate-in fade-in duration-500">
                    <div className="relative">
                      <div className="absolute inset-0 bg-blue-600/10 dark:bg-blue-400/10 blur-[100px] rounded-full animate-pulse"></div>
                      <Loader2 className="w-24 h-24 text-blue-600 dark:text-blue-400 animate-spin" />
                    </div>
                    <div className="text-center space-y-2">
                        <p className="text-xl font-bold text-slate-800 dark:text-white tracking-tight animate-pulse">
                          {LOADING_STEPS[currentStep % LOADING_STEPS.length]}
                        </p>
                    </div>
                  </div>
                ) : previewImage ? (
                  <div className="group relative rounded-3xl overflow-hidden aspect-video border border-black/10 dark:border-white/10 shadow-2xl animate-in fade-in zoom-in-95 duration-500">
                    <img src={previewImage} className="w-full h-full object-cover" />
                    <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all flex items-end p-8">
                       <button 
                         onClick={() => downloadImage(previewImage, 'thumbify-final.png')}
                         className="bg-white text-black px-6 py-3 rounded-2xl font-bold flex items-center gap-2 hover:bg-gray-100 transition-all shadow-xl active:scale-95"
                       >
                         <Download className="w-4 h-4" /> Download
                       </button>
                    </div>
                  </div>
                ) : (
                  <div className="flex-1 border-2 border-dashed border-black/5 dark:border-white/5 rounded-[2rem] flex flex-col items-center justify-center text-slate-400 bg-white/40 dark:bg-slate-800/40">
                    <div className="w-24 h-24 rounded-full bg-white/60 dark:bg-slate-800/60 flex items-center justify-center mb-6 border border-black/5 dark:border-white/5">
                      <Wand2 className="w-10 h-10 opacity-30 text-blue-600 dark:text-blue-400" />
                    </div>
                    <p className="text-lg font-bold text-slate-500 dark:text-slate-400">Bereit zum Start</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

