import React, { useState, useEffect } from 'react';
import { Tab, ThumbnailStyle, Design } from '../types';
import { 
  Wand2, LineChart, Copy, Grid, Upload, Sparkles, 
  Loader2, Download, Trash2, History, ChevronRight, 
  Info, Maximize2, Share2, Settings2, Plus, Zap
} from 'lucide-react';
import { generateThumbnail, analyzeChannel, remakeThumbnail } from '../services/geminiService';

const LOADING_STEPS = [
  "Analysiere Vision...",
  "Neurales Rendering...",
  "CTR-Optimierung...",
  "Finalisiere Pixel..."
];

const Tooltip: React.FC<{ text: string; children?: React.ReactNode }> = ({ children, text }) => (
  <div className="group relative flex flex-col items-center">
    {children}
    <div className="absolute bottom-full mb-3 flex flex-col items-center hidden group-hover:flex animate-in fade-in zoom-in-95 duration-200 z-[100] pointer-events-none">
      <span className="relative z-10 p-2 text-[10px] leading-none text-white whitespace-nowrap bg-slate-900 border border-white/10 backdrop-blur-md rounded-md font-bold uppercase tracking-wider">
        {text}
      </span>
      <div className="w-2 h-2 -mt-1 rotate-45 bg-slate-900 border-r border-b border-white/10"></div>
    </div>
  </div>
);

export const Studio: React.FC = () => {
  const [activeTab, setActiveTab] = React.useState<Tab>('generate');
  const [prompt, setPrompt] = React.useState('');
  const [style, setStyle] = React.useState<ThumbnailStyle>(ThumbnailStyle.CLEAN);
  const [channelUrl, setChannelUrl] = React.useState('');
  const [loading, setLoading] = React.useState(false);
  const [uploading, setUploading] = React.useState(false);
  const [currentStep, setCurrentStep] = React.useState(0);
  const [previewImage, setPreviewImage] = React.useState<string | null>(null);
  const [designs, setDesigns] = React.useState<Design[]>([]);
  const [analysis, setAnalysis] = React.useState<any>(null);
  const [referenceImage, setReferenceImage] = React.useState<string | null>(null);
  const [inputImage, setInputImage] = React.useState<string | null>(null);

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setCurrentStep((prev) => (prev < LOADING_STEPS.length - 1 ? prev + 1 : 0));
      }, 1500);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const handleGenerate = async () => {
    if (!prompt) return;
    setLoading(true);
    setPreviewImage(null);
    try {
      const result = await generateThumbnail(prompt, style, inputImage || undefined);
      setPreviewImage(result);
      setDesigns([{
        id: Date.now().toString(),
        imageUrl: result,
        prompt: prompt,
        createdAt: 'Jetzt'
      }, ...designs]);
    } catch (err) {
      alert("Fehler bei der Erstellung.");
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'reference' | 'input') => {
    const file = e.target.files?.[0];
    if (file) {
      setUploading(true);
      const reader = new FileReader();
      reader.onloadend = () => {
        if (target === 'reference') setReferenceImage(reader.result as string);
        else setInputImage(reader.result as string);
        setUploading(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const navItems = [
    { id: 'generate', icon: Wand2, label: 'Creator' },
    { id: 'feedback', icon: LineChart, label: 'Analytics' },
    { id: 'remake', icon: Copy, label: 'Cloner' },
    { id: 'designs', icon: Grid, label: 'Library' },
  ];

  return (
    <div className="flex h-screen bg-[#020617] text-slate-200 overflow-hidden">

      {/* 1. Neue Slim-Sidebar */}
      <aside className="w-20 flex flex-col items-center py-8 border-r border-white/5 bg-slate-950/50 backdrop-blur-xl z-20">
        <div className="mb-12">
           <Zap className="w-8 h-8 text-blue-500 fill-current animate-pulse" />
        </div>
        <div className="flex-1 flex flex-col gap-6">
          {navItems.map((item) => (
            <Tooltip key={item.id} text={item.label}>
              <button
                onClick={() => setActiveTab(item.id as Tab)}
                className={`p-4 rounded-2xl transition-all relative group ${
                  activeTab === item.id 
                    ? 'bg-blue-600 text-white shadow-[0_0_20px_rgba(37,99,235,0.4)]' 
                    : 'text-slate-500 hover:text-white hover:bg-white/5'
                }`}
              >
                <item.icon className="w-6 h-6" />
                {activeTab === item.id && (
                  <div className="absolute left-0 top-1/2 -translate-y-1/2 w-1 h-8 bg-blue-500 rounded-r-full" />
                )}
              </button>
            </Tooltip>
          ))}
        </div>
        <button className="p-4 text-slate-500 hover:text-white transition-colors">
          <Settings2 className="w-6 h-6" />
        </button>
      </aside>

      {/* 2. Haupt-Arbeitsbereich (Canvas) */}
      <main className="flex-1 flex flex-col relative bg-[radial-gradient(circle_at_center,_#0f172a_0%,_#020617_100%)]">

        {/* Top Bar im Workspace */}
        <header className="h-16 flex items-center justify-between px-8 border-b border-white/5 bg-slate-950/20 backdrop-blur-md">
          <div className="flex items-center gap-4">
            <h2 className="text-sm font-black uppercase tracking-[0.3em] text-slate-500">
              Workspace / <span className="text-white">{activeTab}</span>
            </h2>
            <div className="h-4 w-px bg-white/10" />
            <span className="text-[10px] font-bold bg-green-500/10 text-green-500 px-2 py-0.5 rounded-full border border-green-500/20">
              System Live
            </span>
          </div>
          <div className="flex items-center gap-3">
             <button className="p-2 text-slate-400 hover:text-white transition-colors"><Share2 className="w-5 h-5" /></button>
             <button className="p-2 text-slate-400 hover:text-white transition-colors"><Maximize2 className="w-5 h-5" /></button>
          </div>
        </header>

        {/* Workspace Canvas */}
        <div className="flex-1 flex items-center justify-center p-12">
          <div className="relative w-full max-w-4xl aspect-video rounded-[2.5rem] bg-slate-900/40 border border-white/5 shadow-2xl overflow-hidden group">

            {loading ? (
              <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-950/80 backdrop-blur-md z-30">
                 <div className="relative mb-8">
                    <div className="absolute inset-0 bg-blue-600/20 blur-3xl rounded-full" />
                    <Loader2 className="w-20 h-20 text-blue-500 animate-spin relative" />
                 </div>
                 <p className="text-2xl font-black tracking-tight text-white animate-pulse">
                   {LOADING_STEPS[currentStep]}
                 </p>
                 <div className="mt-8 w-48 h-1 bg-white/5 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-600 animate-progress" style={{ width: '60%' }} />
                 </div>
              </div>
            ) : previewImage ? (
              <div className="w-full h-full relative group animate-in zoom-in-95 duration-700">
                <img src={previewImage} className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all flex items-end justify-center pb-12">
                   <button 
                     onClick={() => {
                        const link = document.createElement('a');
                        link.href = previewImage;
                        link.download = 'thumbify-hq.png';
                        link.click();
                     }}
                     className="px-8 py-4 bg-white text-black rounded-2xl font-black text-lg shadow-2xl flex items-center gap-3 hover:scale-105 active:scale-95 transition-all"
                   >
                     <Download className="w-6 h-6" /> Export in 4K
                   </button>
                </div>
              </div>
            ) : (
              <div className="w-full h-full flex flex-col items-center justify-center opacity-40">
                <div className="w-24 h-24 rounded-full border border-dashed border-white/20 flex items-center justify-center mb-6">
                   <Sparkles className="w-10 h-10 text-blue-500" />
                </div>
                <p className="text-lg font-bold tracking-tight">Warte auf Eingabe...</p>
              </div>
            )}

            {/* Subtile Grid-Dots Overlay */}
            <div className="absolute inset-0 pointer-events-none opacity-20 bg-[radial-gradient(#ffffff_1px,transparent_1px)] [background-size:20px_20px]" />
          </div>
        </div>
      </main>

      {/* 3. Rechtes Control Panel */}
      <aside className="w-[400px] bg-slate-950 border-l border-white/5 flex flex-col z-20">
        <div className="p-8 flex-1 overflow-y-auto custom-scrollbar space-y-8">

          <div className="flex items-center justify-between">
            <h3 className="text-xl font-black tracking-tight text-white">Engine Settings</h3>
            <div className="p-2 bg-white/5 rounded-lg text-slate-500"><Settings2 className="w-4 h-4" /></div>
          </div>

          {activeTab === 'generate' && (
            <div className="space-y-8 animate-in slide-in-from-right-4">
              {/* Prompt Section */}
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500">Visual Prompt</label>
                <div className="relative">
                  <textarea 
                    value={prompt}
                    onChange={(e) => setPrompt(e.target.value)}
                    placeholder="Beschreibe deine Vision..."
                    className="w-full h-40 bg-white/5 border border-white/10 rounded-2xl p-5 text-sm focus:outline-none focus:border-blue-500 transition-all resize-none leading-relaxed"
                  />
                  <div className="absolute bottom-4 right-4 flex gap-2">
                     <button className="p-2 bg-slate-800 rounded-lg hover:bg-slate-700 transition-colors"><Sparkles className="w-4 h-4 text-blue-400" /></button>
                  </div>
                </div>
              </div>

              {/* Styles Section */}
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500">Render Style</label>
                <div className="grid grid-cols-2 gap-3">
                  {Object.values(ThumbnailStyle).map((s) => (
                    <button
                      key={s}
                      onClick={() => setStyle(s)}
                      className={`py-3 px-4 rounded-xl border text-[11px] font-black tracking-widest uppercase transition-all ${
                        style === s 
                          ? 'border-blue-500 bg-blue-500/10 text-white shadow-[0_0_15px_rgba(59,130,246,0.2)]' 
                          : 'border-white/5 bg-white/5 text-slate-500 hover:border-white/20'
                      }`}
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>

              {/* Reference Upload */}
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500">Reference Image</label>
                <div className="relative h-24 border-2 border-dashed border-white/10 rounded-2xl overflow-hidden hover:border-blue-500/40 transition-colors">
                  {inputImage ? (
                    <div className="w-full h-full relative">
                       <img src={inputImage} className="w-full h-full object-cover" />
                       <button onClick={() => setInputImage(null)} className="absolute top-2 right-2 p-1 bg-red-500 rounded-md"><Trash2 className="w-3 h-3 text-white" /></button>
                    </div>
                  ) : (
                    <div className="w-full h-full flex flex-col items-center justify-center text-slate-500">
                       <Upload className="w-5 h-5 mb-1" />
                       <span className="text-[10px] font-bold">Upload Asset</span>
                    </div>
                  )}
                  {!inputImage && <input type="file" onChange={(e) => handleFileUpload(e, 'input')} className="absolute inset-0 opacity-0 cursor-pointer" />}
                </div>
              </div>

              <button 
                onClick={handleGenerate}
                disabled={loading || !prompt}
                className="w-full py-5 bg-blue-600 hover:bg-blue-500 disabled:opacity-30 text-white rounded-[1.5rem] font-black text-lg flex items-center justify-center gap-3 shadow-2xl shadow-blue-900/20 active:scale-95 transition-all"
              >
                <Wand2 className="w-6 h-6" /> Generate Design
              </button>
            </div>
          )}

          {activeTab === 'designs' && (
            <div className="space-y-6 animate-in slide-in-from-right-4">
              <div className="flex items-center justify-between">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500">Recent Creations</label>
                <button className="text-[10px] font-black uppercase text-slate-500 hover:text-white">Clear All</button>
              </div>
              <div className="grid grid-cols-2 gap-4">
                {designs.map(d => (
                  <div key={d.id} className="group relative aspect-video rounded-xl overflow-hidden border border-white/5 cursor-pointer">
                    <img src={d.imageUrl} className="w-full h-full object-cover transition-transform group-hover:scale-110" />
