      <div className="w-2 h-2 -mt-1 rotate-45 bg-slate-900 border-r border-b border-white/10"></div>
    </div>
  </div>
);

export const Studio: React.FC = () => {
  const [activeTab, setActiveTab] = React.useState<Tab>('generate');
  const [prompt, setPrompt] = React.useState('');
  const [remakePrompt, setRemakePrompt] = React.useState('');
  const [style, setStyle] = React.useState<ThumbnailStyle>(ThumbnailStyle.CLEAN);
  const [channelUrl, setChannelUrl] = React.useState('');
  const [loading, setLoading] = React.useState(false);
  const [uploading, setUploading] = React.useState(false);
  const [currentStep, setCurrentStep] = React.useState(0);
  const [previewImage, setPreviewImage] = React.useState<string | null>(null);
  const [designs, setDesigns] = React.useState<Design[]>([]);
  const [analysis, setAnalysis] = React.useState<any>(null);
  const [referenceImage, setReferenceImage] = React.useState<string | null>(null);
  const [inputImage, setInputImage] = React.useState<string | null>(null);

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setCurrentStep((prev) => (prev < LOADING_STEPS.length - 1 ? prev + 1 : 0));
      }, 1500);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const handleGenerate = async () => {
    if (!prompt) return;
    setLoading(true);
    setPreviewImage(null);
    try {
      const result = await generateThumbnail(prompt, style, inputImage || undefined);
      setPreviewImage(result);
      setDesigns([{
        id: Date.now().toString(),
        imageUrl: result,
        prompt: prompt,
        createdAt: 'Jetzt'
      }, ...designs]);
    } catch (err) {
      alert("Fehler bei der Erstellung.");
    } finally {
      setLoading(false);
    }
  };

  const handleRemake = async () => {
    if (!remakePrompt || !referenceImage) return;
    setLoading(true);
    setPreviewImage(null);
    try {
      const result = await remakeThumbnail(referenceImage, remakePrompt);
      setPreviewImage(result);
      setDesigns([{
        id: Date.now().toString(),
        imageUrl: result,
        prompt: remakePrompt,
        createdAt: 'Jetzt'
      }, ...designs]);
    } catch (err) {
      alert("Fehler bei der Neuauflage.");
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'reference' | 'input') => {
    const file = e.target.files?.[0];
    if (file) {
      setUploading(true);
      const reader = new FileReader();
      reader.onloadend = () => {
        if (target === 'reference') setReferenceImage(reader.result as string);
        else setInputImage(reader.result as string);
        setUploading(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const navItems = [
    { id: 'generate', icon: Wand2, label: 'Creator' },
    { id: 'feedback', icon: LineChart, label: 'Analytics' },
    { id: 'remake', icon: Copy, label: 'Cloner' },
    { id: 'designs', icon: Grid, label: 'Library' },
  ];

  return (
    <div className="flex h-screen bg-[#020617] text-slate-200 overflow-hidden">

      {/* 1. Slim-Sidebar */}
