import React, { useState, useEffect } from 'react';
import { User } from './types';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { Features } from './components/Features';
import { Pricing } from './components/Pricing';
import { Reviews } from './components/Reviews';
import { Studio } from './components/Studio';
import { AuthModal } from './components/AuthModal';
import { Examples } from './components/Examples';
import { Zap, ArrowLeft, Sun, Moon } from 'lucide-react';
import { BACKGROUND_IMAGE } from './constants';

type MainView = 'home' | 'studio' | 'pricing' | 'reviews' | 'examples';

function App() {
  const [user, setUser] = React.useState<User | null>(null);
  const [currentView, setCurrentView] = React.useState<MainView>('home');
  const [isAuthOpen, setIsAuthOpen] = React.useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);

  // Synchronize theme with local storage and document class
  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'light') {
      setIsDarkMode(false);
    } else {
      setIsDarkMode(true);
    }
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const handleLogin = (email: string) => {
    setUser({
      id: '1',
      email: email,
      name: email.split('@')[0],
      isLoggedIn: true
    });
    setIsAuthOpen(false);
    setCurrentView('studio');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleStartCreating = () => {
    if (user) {
      setCurrentView('studio');
    } else {
      setIsAuthOpen(true);
    }
  };

  const handleNavigate = (view: MainView) => {
    setCurrentView(view);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const BackButton = () => (
    <button 
      onClick={() => handleNavigate('home')}
      className="fixed top-24 left-4 lg:left-8 z-40 flex items-center gap-2 px-4 py-2 bg-white/50 dark:bg-slate-800/50 hover:bg-white/80 dark:hover:bg-slate-800/80 border border-black/5 dark:border-white/10 rounded-full text-sm font-bold transition-all group shadow-sm text-slate-900 dark:text-slate-100"
    >
      <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
      Zurück
    </button>
  );

  return (
    <div className={`min-h-screen transition-colors duration-500 selection:bg-blue-500 selection:text-white ${isDarkMode ? 'bg-slate-950 text-slate-100' : 'bg-sky-50 text-slate-900'} relative`}>
      {/* Theme Toggle Button */}
      <button
        onClick={toggleTheme}
        className="fixed top-4 right-4 z-[60] p-3 rounded-full bg-white/80 dark:bg-slate-800/80 border border-black/5 dark:border-white/10 shadow-xl backdrop-blur-md transition-all active:scale-90 flex items-center justify-center hover:rotate-12"
      >
        {isDarkMode ? "☀️" : "🌙"}
      </button>

      {/* Globaler Hintergrund */}
      {currentView === 'home' && (
        <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden">
          <div 
            className={`absolute inset-0 bg-cover bg-center bg-fixed transform scale-110 blur-[6px] opacity-[0.08] transition-all duration-500 ${isDarkMode ? 'brightness-[1.5] contrast-150' : 'brightness-[0.85]'}`}
            style={{ 
              backgroundImage: `url(${BACKGROUND_IMAGE})`,
            }}
          />
          <div className={`absolute inset-0 transition-colors duration-500 ${isDarkMode ? 'bg-gradient-to-br from-slate-950/90 to-blue-900/20' : 'bg-gradient-to-br from-blue-50/20 to-sky-100/30'}`} />
        </div>
      )}

      <Navbar 
        user={user} 
        onNavigate={handleNavigate} 
        onLoginClick={() => setIsAuthOpen(true)} 
      />

      <main className="relative z-10">
        {currentView === 'home' && (
          <div className="animate-in fade-in duration-700">
            <Hero 
              onStartCreating={handleStartCreating} 
              onViewPricing={() => handleNavigate('pricing')} 
            />
            <Features />
            <Reviews />
            <Pricing />
          </div>
        )}

        {currentView === 'pricing' && (
          <div className="pt-20">
            <BackButton />
            <Pricing />
          </div>
        )}

        {currentView === 'reviews' && (
          <div className="pt-20">
            <BackButton />
            <Reviews />
          </div>
        )}

        {currentView === 'examples' && (
          <div className="pt-20">
            <BackButton />
            <Examples onNavigateToStudio={() => handleNavigate('studio')} />
          </div>
        )}

        {currentView === 'studio' && user && (
          <Studio user={user} />
        )}
      </main>

      {/* Footer */}
      <footer className="py-20 border-t border-black/5 dark:border-white/5 bg-white/50 dark:bg-slate-900/50 mt-20 relative z-10">
        <div className="max-w-7xl mx-auto px-4">
          <div className="grid md:grid-cols-4 gap-12 mb-16">
            <div className="col-span-2">
              <div className="flex items-center gap-2 mb-6">
                  <div className="bg-blue-600 p-1.5 rounded-lg shadow-lg shadow-blue-600/20">
                      <Zap className="w-5 h-5 text-white fill-white" />
                  </div>
                  <span className="text-xl font-bold tracking-tight dark:text-white">Thumbify <span className="text-blue-500">AI</span></span>
              </div>
              <p className="text-slate-500 dark:text-slate-400 max-w-sm leading-relaxed">
                Wir unterstützen die nächste Generation von Creatoren mit KI-Tools auf Profi-Niveau. Steigere deine CTR und dominiere den Feed.
              </p>
            </div>
            <div>
              <h4 className="font-bold mb-6 text-sm uppercase tracking-widest text-slate-800 dark:text-slate-200">Produkt</h4>
              <ul className="space-y-4 text-slate-500 dark:text-slate-400 text-sm">
                <li><button onClick={() => handleNavigate('studio')} className="hover:text-blue-600 transition-colors">Studio</button></li>
                <li><button onClick={() => handleNavigate('pricing')} className="hover:text-blue-600 transition-colors">Preise</button></li>
                <li><button onClick={() => handleNavigate('reviews')} className="hover:text-blue-600 transition-colors">Bewertungen</button></li>
                <li><button onClick={() => handleNavigate('examples')} className="hover:text-blue-600 transition-colors">Beispiele</button></li>
              </ul>
            </div>
            <div>
              <h4 className="font-bold mb-6 text-sm uppercase tracking-widest text-slate-800 dark:text-slate-200">Unternehmen</h4>
              <ul className="space-y-4 text-slate-500 dark:text-slate-400 text-sm">
                <li><a href="#" className="hover:text-blue-600 transition-colors">Über uns</a></li>
                <li><a href="#" className="hover:text-blue-600 transition-colors">Karriere</a></li>
                <li><a href="#" className="hover:text-blue-600 transition-colors">Bedingungen</a></li>
                <li><a href="#" className="hover:text-blue-600 transition-colors">Datenschutz</a></li>
              </ul>
            </div>
          </div>
          <div className="pt-8 border-t border-black/5 dark:border-white/5 flex flex-col md:flex-row justify-between items-center gap-4 text-slate-400 text-xs uppercase font-medium">
            <p>© 2024 Thumbify AI. Alle Rechte vorbehalten.</p>
          </div>
        </div>
      </footer>

      <AuthModal 
        isOpen={isAuthOpen} 
        onClose={() => setIsAuthOpen(false)} 
        onLogin={handleLogin} 
      />
    </div>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { Tab, ThumbnailStyle, Design, User } from '../types';
import { 
  Wand2, LineChart, Copy, Grid, Upload, Sparkles, 
  Loader2, Download, Trash2, History, ChevronRight, 
  Info, Maximize2, Share2, Settings2, Plus, Zap
} from 'lucide-react';
import { generateThumbnail, analyzeChannel, remakeThumbnail } from '../services/geminiService';

const LOADING_STEPS = [
  "Analysiere Vision...",
  "Neurales Rendering...",
  "CTR-Optimierung...",
  "Finalisiere Pixel..."
];

const Tooltip: React.FC<{ text: string; children?: React.ReactNode }> = ({ children, text }) => (
  <div className="group relative flex flex-col items-center">
    {children}
    <div className="absolute bottom-full mb-3 flex flex-col items-center hidden group-hover:flex animate-in fade-in zoom-in-95 duration-200 z-[100] pointer-events-none">
      <span className="relative z-10 p-2 text-[10px] leading-none text-white whitespace-nowrap bg-slate-900 border border-white/10 backdrop-blur-md rounded-md font-bold uppercase tracking-wider">
        {text}
      </span>
      <div className="w-2 h-2 -mt-1 rotate-45 bg-slate-900 border-r border-b border-white/10"></div>
    </div>
  </div>
);

interface StudioProps {
  user: User;
}

export const Studio: React.FC<StudioProps> = ({ user }) => {
  const [activeTab, setActiveTab] = React.useState<Tab>('generate');
  const [prompt, setPrompt] = React.useState('');
  const [remakePrompt, setRemakePrompt] = React.useState('');
  const [style, setStyle] = React.useState<ThumbnailStyle>(ThumbnailStyle.CLEAN);
  const [loading, setLoading] = React.useState(false);
  const [uploading, setUploading] = React.useState(false);
  const [currentStep, setCurrentStep] = React.useState(0);
  const [previewImage, setPreviewImage] = React.useState<string | null>(null);
  const [designs, setDesigns] = React.useState<Design[]>([]);
  const [referenceImage, setReferenceImage] = React.useState<string | null>(null);
  const [inputImage, setInputImage] = React.useState<string | null>(null);

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setCurrentStep((prev) => (prev < LOADING_STEPS.length - 1 ? prev + 1 : 0));
      }, 1500);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const handleGenerate = async () => {
    if (!prompt) return;
    setLoading(true);
    setPreviewImage(null);
    try {
      const result = await generateThumbnail(prompt, style, inputImage || undefined);
      setPreviewImage(result);
      setDesigns([{
        id: Date.now().toString(),
        imageUrl: result,
        prompt: prompt,
        createdAt: 'Jetzt'
      }, ...designs]);
    } catch (err) {
      alert("Fehler bei der Erstellung.");
    } finally {
      setLoading(false);
    }
  };

  const handleRemake = async () => {
    if (!remakePrompt || !referenceImage) return;
    setLoading(true);
    setPreviewImage(null);
    try {
      const result = await remakeThumbnail(referenceImage, remakePrompt);
      setPreviewImage(result);
      setDesigns([{
        id: Date.now().toString(),
        imageUrl: result,
        prompt: remakePrompt,
        createdAt: 'Jetzt'
      }, ...designs]);
    } catch (err) {
      alert("Fehler bei der Neuauflage.");
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'reference' | 'input') => {
    const file = e.target.files?.[0];
    if (file) {
      setUploading(true);
      const reader = new FileReader();
      reader.onloadend = () => {
        if (target === 'reference') setReferenceImage(reader.result as string);
        else setInputImage(reader.result as string);
        setUploading(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const navItems = [
    { id: 'generate', icon: Wand2, label: 'Creator' },
    { id: 'remake', icon: Copy, label: 'Cloner' },
    { id: 'designs', icon: Grid, label: 'Library' },
  ];

  return (
    <div className="flex h-screen bg-[#020617] text-slate-200 overflow-hidden pt-20">

      {/* 1. Sidebar */}
      <aside className="w-20 flex flex-col items-center py-8 border-r border-white/5 bg-slate-950/50 backdrop-blur-xl z-20">
        <div className="mb-12">
           <Zap className="w-8 h-8 text-blue-500 fill-current animate-pulse" />
        </div>
        <div className="flex-1 flex flex-col gap-6">
          {navItems.map((item) => (
            <Tooltip key={item.id} text={item.label}>
              <button
                onClick={() => setActiveTab(item.id as Tab)}
                className={`p-4 rounded-2xl transition-all relative group ${
                  activeTab === item.id 
                    ? 'bg-blue-600 text-white shadow-[0_0_20px_rgba(37,99,235,0.4)]' 
                    : 'text-slate-500 hover:text-white hover:bg-white/5'
                }`}
              >
                <item.icon className="w-6 h-6" />
                {activeTab === item.id && (
                  <div className="absolute left-0 top-1/2 -translate-y-1/2 w-1 h-8 bg-blue-500 rounded-r-full" />
                )}
              </button>
            </Tooltip>
          ))}
        </div>
        <button className="p-4 text-slate-500 hover:text-white transition-colors">
          <Settings2 className="w-6 h-6" />
        </button>
      </aside>

      {/* 2. Main Workspace */}
      <main className="flex-1 flex flex-col relative bg-[radial-gradient(circle_at_center,_#0f172a_0%,_#020617_100%)]">
        <header className="h-16 flex items-center justify-between px-8 border-b border-white/5 bg-slate-950/20 backdrop-blur-md">
          <div className="flex items-center gap-4">
            <h2 className="text-sm font-black uppercase tracking-[0.3em] text-slate-500">
              Workspace / <span className="text-white">{activeTab}</span>
            </h2>
            <div className="h-4 w-px bg-white/10" />
            <span className="text-[10px] font-bold bg-green-500/10 text-green-500 px-2 py-0.5 rounded-full border border-green-500/20">
              System Live
            </span>
          </div>
        </header>

        <div className="flex-1 flex items-center justify-center p-12 overflow-y-auto">
          <div className="relative w-full max-w-4xl aspect-video rounded-[2.5rem] bg-slate-900/40 border border-white/5 shadow-2xl overflow-hidden group">
            {loading ? (
              <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-950/80 backdrop-blur-md z-30">
                 <Loader2 className="w-20 h-20 text-blue-500 animate-spin mb-6" />
                 <p className="text-2xl font-black text-white animate-pulse">{LOADING_STEPS[currentStep]}</p>
              </div>
            ) : previewImage ? (
              <div className="w-full h-full relative group animate-in zoom-in-95 duration-700">
                <img src={previewImage} className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-all flex items-end justify-center pb-12">
                   <button 
                     onClick={() => {
                        const link = document.createElement('a');
                        link.href = previewImage;
                        link.download = 'thumbify-hq.png';
                        link.click();
                     }}
                     className="px-8 py-4 bg-white text-black rounded-2xl font-black text-lg shadow-2xl flex items-center gap-3 hover:scale-105 active:scale-95 transition-all"
                   >
                     <Download className="w-6 h-6" /> Export 4K
                   </button>
                </div>
              </div>
            ) : (
              <div className="w-full h-full flex flex-col items-center justify-center opacity-40">
                <div className="w-24 h-24 rounded-full border border-dashed border-white/20 flex items-center justify-center mb-6">
                   <Sparkles className="w-10 h-10 text-blue-500" />
                </div>
                <p className="text-lg font-bold">Warte auf Eingabe...</p>
              </div>
            )}
          </div>
        </div>
      </main>

      {/* 3. Control Panel */}
      <aside className="w-[400px] bg-slate-950 border-l border-white/5 flex flex-col z-20 overflow-y-auto custom-scrollbar">
        <div className="p-8 space-y-8">
          <div className="flex items-center justify-between">
            <h3 className="text-xl font-black tracking-tight text-white">Engine Settings</h3>
            <div className="p-2 bg-white/5 rounded-lg text-slate-500"><Settings2 className="w-4 h-4" /></div>
          </div>

          {activeTab === 'generate' && (
            <div className="space-y-8">
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500">Visual Prompt</label>
                <textarea 
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  placeholder="Beschreibe deine Vision..."
                  className="w-full h-40 bg-white/5 border border-white/10 rounded-2xl p-5 text-sm focus:outline-none focus:border-blue-500 transition-all resize-none"
                />
              </div>

              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500">Render Style</label>
                <div className="grid grid-cols-2 gap-3">
                  {Object.values(ThumbnailStyle).map((s) => (
                    <button
                      key={s}
                      onClick={() => setStyle(s)}
                      className={`py-3 rounded-xl border text-[11px] font-black uppercase transition-all ${
                        style === s ? 'border-blue-500 bg-blue-500/10 text-white' : 'border-white/5 bg-white/5 text-slate-500'
                      }`}
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>

              <button 
                onClick={handleGenerate}
                disabled={loading || !prompt}
                className="w-full py-5 bg-blue-600 hover:bg-blue-500 disabled:opacity-30 text-white rounded-[1.5rem] font-black text-lg flex items-center justify-center gap-3 shadow-xl shadow-blue-900/20 active:scale-95 transition-all"
              >
                <Wand2 className="w-6 h-6" /> Generate Design
              </button>
            </div>
          )}

          {activeTab === 'remake' && (
            <div className="space-y-8">
              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500">Remake Variations</label>
                <textarea 
                  value={remakePrompt}
                  onChange={(e) => setRemakePrompt(e.target.value)}
                  placeholder="Welche Änderungen am Layout?"
                  className="w-full h-32 bg-white/5 border border-white/10 rounded-2xl p-5 text-sm focus:outline-none focus:border-blue-500"
                />
              </div>

              <div className="space-y-4">
                <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500">Reference Thumbnail</label>
                <div className="relative h-40 border-2 border-dashed border-white/10 rounded-2xl overflow-hidden bg-white/5">
                  {referenceImage ? (
                    <div className="w-full h-full relative">
                       <img src={referenceImage} className="w-full h-full object-cover" />
                       <button onClick={() => setReferenceImage(null)} className="absolute top-2 right-2 p-1 bg-red-500 rounded-md"><Trash2 className="w-3 h-3 text-white" /></button>
                    </div>
                  ) : (
                    <div className="w-full h-full flex flex-col items-center justify-center text-slate-500 text-center px-6">
                       <Upload className="w-8 h-8 mb-2" />
                       <span className="text-[10px] font-bold">Vorlagen-Bild hochladen</span>
                    </div>
                  )}
                  {!referenceImage && <input type="file" onChange={(e) => handleFileUpload(e, 'reference')} className="absolute inset-0 opacity-0 cursor-pointer" />}
                </div>
              </div>

              <button 
                onClick={handleRemake}
                disabled={loading || !remakePrompt || !referenceImage}
                className="w-full py-5 bg-purple-600 hover:bg-purple-500 disabled:opacity-30 text-white rounded-[1.5rem] font-black text-lg flex items-center justify-center gap-3 shadow-xl shadow-purple-900/20 active:scale-95 transition-all"
              >
                <Copy className="w-6 h-6" /> Clone starten
              </button>
            </div>
          )}

          {activeTab === 'designs' && (
            <div className="space-y-6">
              <label className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500">Library</label>
              <div className="grid grid-cols-2 gap-4">
                {designs.map(d => (
                  <div key={d.id} className="group relative aspect-video rounded-xl overflow-hidden border border-white/5 cursor-pointer">
                    <img src={d.imageUrl} className="w-full h-full object-cover transition-transform group-hover:scale-110" />
                    <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center gap-2">
                       <button onClick={() => setPreviewImage(d.imageUrl)} className="p-2 bg-white text-black rounded-lg"><Maximize2 className="w-4 h-4" /></button>
                       <button onClick={() => {
                          const link = document.createElement('a');
                          link.href = d.imageUrl;
                          link.download = `thumbify-${d.id}.png`;
                          link.click();
                       }} className="p-2 bg-white text-black rounded-lg"><Download className="w-4 h-4" /></button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="mt-auto p-8 border-t border-white/5 bg-slate-900/30">
          <div className="flex items-center gap-4">
             <div className="w-12 h-12 rounded-full bg-gradient-to-tr from-blue-600 to-purple-600 flex items-center justify-center font-black text-white text-xl">
                {user.name.charAt(0).toUpperCase()}
             </div>
             <div>
                <p className="text-sm font-black text-white leading-none mb-1">{user.name}</p>
                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Creator Account</p>
