import React, { useState, useEffect } from 'react';
import { User } from './types';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { Features } from './components/Features';
import { Pricing } from './components/Pricing';
import { Reviews } from './components/Reviews';
import { Studio } from './components/Studio';
import { AuthModal } from './components/AuthModal';
import { Examples } from './components/Examples';
import { Zap, ArrowLeft, Sun, Moon } from 'lucide-react';
import { BACKGROUND_IMAGE } from './constants';

type MainView = 'home' | 'studio' | 'pricing' | 'reviews' | 'examples';

function App() {
  const [user, setUser] = React.useState<User | null>(null);
  const [currentView, setCurrentView] = React.useState<MainView>('home');
  const [isAuthOpen, setIsAuthOpen] = React.useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);

  // Synchronize theme with local storage and document class
  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'light') {
      setIsDarkMode(false);
    } else {
      setIsDarkMode(true);
    }
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const handleLogin = (email: string) => {
    setUser({
      id: '1',
      email: email,
      name: email.split('@')[0],
      isLoggedIn: true
    });
    setIsAuthOpen(false);
    setCurrentView('studio');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleStartCreating = () => {
    if (user) {
      setCurrentView('studio');
    } else {
      setIsAuthOpen(true);
    }
  };

  const handleNavigate = (view: MainView) => {
    if (view === 'studio' && !user) {
      setIsAuthOpen(true);
      return;
    }
    setCurrentView(view);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const BackButton = () => (
    <button 
      onClick={() => handleNavigate('home')}
      className="fixed top-24 left-4 lg:left-8 z-40 flex items-center gap-2 px-4 py-2 bg-white/50 dark:bg-slate-800/50 hover:bg-white/80 dark:hover:bg-slate-800/80 border border-black/5 dark:border-white/10 rounded-full text-sm font-bold transition-all group shadow-sm text-slate-900 dark:text-slate-100"
    >
      <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
      Zurück
    </button>
  );

  return (
    <div className={`min-h-screen transition-colors duration-500 selection:bg-blue-500 selection:text-white ${isDarkMode ? 'bg-slate-950 text-slate-100' : 'bg-sky-50 text-slate-900'} relative`}>
      {/* Theme Toggle Button */}
      <button
        onClick={toggleTheme}
        className="fixed top-4 right-4 z-[60] p-3 rounded-full bg-white/80 dark:bg-slate-800/80 border border-black/5 dark:border-white/10 shadow-xl backdrop-blur-md transition-all active:scale-90 flex items-center justify-center hover:rotate-12"
      >
        {isDarkMode ? "☀️" : "🌙"}
      </button>

      {/* Globaler Hintergrund */}
      {currentView === 'home' && (
        <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden">
          <div 
            className={`absolute inset-0 bg-cover bg-center bg-fixed transform scale-110 blur-[6px] opacity-[0.08] transition-all duration-500 ${isDarkMode ? 'brightness-[1.5] contrast-150' : 'brightness-[0.85]'}`}
            style={{ 
              backgroundImage: `url(${BACKGROUND_IMAGE})`,
            }}
          />
          <div className={`absolute inset-0 transition-colors duration-500 ${isDarkMode ? 'bg-gradient-to-br from-slate-950/90 to-blue-900/20' : 'bg-gradient-to-br from-blue-50/20 to-sky-100/30'}`} />
        </div>
      )}

      <Navbar 
        user={user} 
        onNavigate={handleNavigate} 
        onLoginClick={() => setIsAuthOpen(true)} 
      />

      <main className="relative z-10">
        {currentView === 'home' && (
          <div className="animate-in fade-in duration-700">
            <Hero 
              onStartCreating={handleStartCreating} 
              onViewPricing={() => handleNavigate('pricing')} 
            />
            <Features />
            <Reviews />
            <Pricing />
          </div>
        )}

        {currentView === 'pricing' && (
          <div className="pt-20">
            <BackButton />
            <Pricing />
          </div>
        )}

        {currentView === 'reviews' && (
          <div className="pt-20">
            <BackButton />
            <Reviews />
          </div>
        )}

        {currentView === 'examples' && (
          <div className="pt-20">
            <BackButton />
            <Examples onNavigateToStudio={() => handleNavigate('studio')} />
          </div>
        )}

        {currentView === 'studio' && user && (
          <Studio user={user} />
        )}
      </main>

      {/* Footer */}
      <footer className="py-20 border-t border-black/5 dark:border-white/5 bg-white/50 dark:bg-slate-900/50 mt-20 relative z-10">
        <div className="max-w-7xl mx-auto px-4">
          <div className="grid md:grid-cols-4 gap-12 mb-16">
            <div className="col-span-2">
              <div className="flex items-center gap-2 mb-6">
                  <div className="bg-blue-600 p-1.5 rounded-lg shadow-lg shadow-blue-600/20">
                      <Zap className="w-5 h-5 text-white fill-white" />
                  </div>
                  <span className="text-xl font-bold tracking-tight dark:text-white">Thumbify <span className="text-blue-500">AI</span></span>
              </div>
              <p className="text-slate-500 dark:text-slate-400 max-w-sm leading-relaxed">
                Wir unterstützen die nächste Generation von Creatoren mit KI-Tools auf Profi-Niveau. Steigere deine CTR und dominiere den Feed.
              </p>
            </div>
            <div>
              <h4 className="font-bold mb-6 text-sm uppercase tracking-widest text-slate-800 dark:text-slate-200">Produkt</h4>
              <ul className="space-y-4 text-slate-500 dark:text-slate-400 text-sm">
                <li><button onClick={() => handleNavigate('studio')} className="hover:text-blue-600 transition-colors">Studio</button></li>
                <li><button onClick={() => handleNavigate('pricing')} className="hover:text-blue-600 transition-colors">Preise</button></li>
                <li><button onClick={() => handleNavigate('reviews')} className="hover:text-blue-600 transition-colors">Bewertungen</button></li>
                <li><button onClick={() => handleNavigate('examples')} className="hover:text-blue-600 transition-colors">Beispiele</button></li>
              </ul>
            </div>
            <div>
              <h4 className="font-bold mb-6 text-sm uppercase tracking-widest text-slate-800 dark:text-slate-200">Unternehmen</h4>
              <ul className="space-y-4 text-slate-500 dark:text-slate-400 text-sm">
                <li><a href="#" className="hover:text-blue-600 transition-colors">Über uns</a></li>
                <li><a href="#" className="hover:text-blue-600 transition-colors">Karriere</a></li>
                <li><a href="#" className="hover:text-blue-600 transition-colors">Bedingungen</a></li>
                <li><a href="#" className="hover:text-blue-600 transition-colors">Datenschutz</a></li>
              </ul>
            </div>
          </div>
          <div className="pt-8 border-t border-black/5 dark:border-white/5 flex flex-col md:flex-row justify-between items-center gap-4 text-slate-400 text-xs uppercase font-medium">
            <p>© 2024 Thumbify AI. Alle Rechte vorbehalten.</p>
          </div>
        </div>
      </footer>

      <AuthModal 
        isOpen={isAuthOpen} 
        onClose={() => setIsAuthOpen(false)} 
        onLogin={handleLogin} 
      />
    </div>
  );
}

export default App;

