    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setCurrentStep((prev) => (prev < LOADING_STEPS.length - 1 ? prev + 1 : 0));
      }, 1500);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setLoading(true);
    setPreviewImage(null);
    setAnalysis(null);
    try {
      const result = await generateThumbnail(prompt, style, inputImage || undefined);
      setPreviewImage(result);
      setDesigns([{
        id: Date.now().toString(),
        imageUrl: result,
        prompt: prompt,
        createdAt: 'Jetzt'
      }, ...designs]);
    } catch (err) {
      console.error(err);
      alert("Fehler bei der Erstellung.");
    } finally {
      setLoading(false);
    }
  };

