    { id: 'generate', icon: Wand2, label: 'KI Creator' },
    { id: 'remake', icon: Copy, label: 'Cloner' },
    { id: 'feedback', icon: LineChart, label: 'Audit' },
    { id: 'designs', icon: Grid, label: 'Galerie' },
