            {REVIEWS.slice(0, 5).map(review => (
              <img key={review.id} src={review.avatar} className="w-14 h-14 rounded-full border-4 border-white dark:border-slate-900 object-cover shadow-lg" alt="Nutzer" />
            ))}
          </div>
          <h2 className="text-3xl md:text-5xl font-black mb-4 tracking-tight text-slate-900 dark:text-white">Was unsere <span className="gradient-text">Creator</span> sagen</h2>
