  user: User;
}

export const Studio: React.FC<StudioProps> = ({ user }) => {
  const [activeTab, setActiveTab] = React.useState<Tab>('generate');
  const [prompt, setPrompt] = React.useState('');
  const [remakePrompt, setRemakePrompt] = React.useState('');
  const [channelUrl, setChannelUrl] = React.useState('');
  const [style, setStyle] = React.useState<ThumbnailStyle>(ThumbnailStyle.CLEAN);
  const [loading, setLoading] = React.useState(false);
  const [currentStep, setCurrentStep] = React.useState(0);
  const [previewImage, setPreviewImage] = React.useState<string | null>(null);
  const [analysis, setAnalysis] = React.useState<AnalysisResult | null>(null);
  const [designs, setDesigns] = React.useState<Design[]>([]);
  const [referenceImage, setReferenceImage] = React.useState<string | null>(null);
  const [inputImage, setInputImage] = React.useState<string | null>(null);

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setCurrentStep((prev) => (prev < LOADING_STEPS.length - 1 ? prev + 1 : 0));
      }, 1500);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    setLoading(true);
    setPreviewImage(null);
    setAnalysis(null);
    try {
      const result = await generateThumbnail(prompt, style, inputImage || undefined);
      setPreviewImage(result);
      setDesigns([{
        id: Date.now().toString(),
        imageUrl: result,
        prompt: prompt,
        createdAt: 'Jetzt'
      }, ...designs]);
    } catch (err) {
      console.error(err);
      alert("Fehler bei der Erstellung.");
    } finally {
      setLoading(false);
    }
  };

  const handleRemake = async () => {
    if (!remakePrompt.trim() || !referenceImage) return;
    setLoading(true);
    setPreviewImage(null);
    setAnalysis(null);
    try {
      const result = await remakeThumbnail(referenceImage, remakePrompt);
      setPreviewImage(result);
      setDesigns([{
        id: Date.now().toString(),
        imageUrl: result,
        prompt: remakePrompt,
        createdAt: 'Jetzt'
      }, ...designs]);
    } catch (err) {
      console.error(err);
      alert("Neuauflage fehlgeschlagen.");
    } finally {
      setLoading(false);
    }
  };

  const handleAnalyze = async () => {
    if (!channelUrl.trim()) return;
    setLoading(true);
    setPreviewImage(null);
    setAnalysis(null);
    try {
      const result = await analyzeChannel(channelUrl);
      setAnalysis(result);
    } catch (err) {
      console.error(err);
      alert("Analyse fehlgeschlagen.");
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'reference' | 'input') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (target === 'reference') setReferenceImage(reader.result as string);
        else setInputImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const appendKeyword = (keyword: string) => {
    setPrompt(prev => {
      const trimmed = prev.trim();
      if (!trimmed) return keyword;
      if (trimmed.endsWith(',')) return `${trimmed} ${keyword}`;
      return `${trimmed}, ${keyword}`;
    });
  };

