import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateThumbnail = async (prompt: string, style: string, base64Image?: string) => {
  const ai = getAI();
  const fullPrompt = `Erstelle ein professionelles YouTube-Thumbnail im Stil '${style}'. Beschreibung: ${prompt}. Achte auf extrem hohen Kontrast, fette Typografie und eine klare Bildhierarchie. Premium 4K Qualität.`;

  const contents: any = {
    parts: [{ text: fullPrompt }]
  };

  if (base64Image) {
    contents.parts.push({
      inlineData: {
        data: base64Image.split(',')[1],
        mimeType: 'image/png'
      }
    });
  }

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents,
    config: {
      imageConfig: {
        aspectRatio: "16:9",
      }
    }
  });

  const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  if (imagePart?.inlineData) {
    return `data:image/png;base64,${imagePart.inlineData.data}`;
  }
  throw new Error("Generierung fehlgeschlagen");
};

export const analyzeThumbnailImage = async (base64Image: string) => {
  const ai = getAI();
  const prompt = `Analysiere dieses YouTube-Thumbnail. Bewerte es auf einer Skala von 0-10 für CTR-Potenzial. Gib spezifische Verbesserungsvorschläge zu Komposition, Text lesbarkeit und Farben. Antworte in Deutsch und im JSON Format.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Image.split(',')[1], mimeType: 'image/png' } },
        { text: prompt }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          score: { type: Type.NUMBER },
          feedback: { type: Type.STRING },
          suggestions: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["score", "feedback", "suggestions"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const extractStyleFromImages = async (base64Images: string[]) => {
  const ai = getAI();
  const prompt = `Analysiere diese Thumbnails und extrahiere den gemeinsamen visuellen Stil (Farben, Fonts, Layout-Struktur). Beschreibe den Stil kurz und prägnant auf Deutsch. Gib die Antwort als JSON zurück.`;

  const contents: any = {
    parts: base64Images.map(img => ({
      inlineData: { data: img.split(',')[1], mimeType: 'image/png' }
    }))
  };
  contents.parts.push({ text: prompt });

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          summary: { type: Type.STRING },
          elements: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["summary", "elements"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

