import React, { useState } from 'react';
import { Copy, Upload, Loader2, Sparkles, CheckCircle, Trash2 } from 'lucide-react';
import { extractStyleFromImages, generateThumbnail } from '../services/geminiService';

export const StudioClone: React.FC = () => {
  const [images, setImages] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [styleSummary, setStyleSummary] = useState<{summary: string, elements: string[]} | null>(null);
  const [prompt, setPrompt] = useState('');
  const [result, setResult] = useState<string | null>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files) {
      Array.from(files).forEach(file => {
        const reader = new FileReader();
        reader.onloadend = () => setImages(prev => [...prev, reader.result as string].slice(0, 5));
        reader.readAsDataURL(file);
      });
    }
  };

  const handleExtract = async () => {
    if (images.length === 0) return;
    setLoading(true);
    try {
      const res = await extractStyleFromImages(images);
      setStyleSummary(res);
    } catch (err) {
      alert("Analyse fehlgeschlagen.");
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateInStyle = async () => {
    if (!prompt.trim() || !styleSummary) return;
    setLoading(true);
    try {
      const res = await generateThumbnail(`${prompt}. Beachte diesen Stil: ${styleSummary.summary}`, 'Custom');
      setResult(res);
    } catch (err) {
      alert("Generierung fehlgeschlagen.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="p-10 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl">
        <h2 className="text-3xl font-black mb-8 flex items-center gap-4">
          <Copy className="w-8 h-8 text-purple-500" />
          Style Cloner
        </h2>

        {!styleSummary ? (
          <div className="space-y-8">
            <p className="text-slate-500 dark:text-slate-400 font-medium">Lade bis zu 5 Thumbnails hoch, deren Stil wir analysieren sollen.</p>
            <div className="grid grid-cols-2 sm:grid-cols-5 gap-4">
              {images.map((img, i) => (
                <div key={i} className="relative aspect-video rounded-xl overflow-hidden border border-black/10">
                  <img src={img} className="w-full h-full object-cover" />
                  <button onClick={() => setImages(prev => prev.filter((_, idx) => idx !== i))} className="absolute top-1 right-1 p-1 bg-red-500 rounded text-white"><Trash2 className="w-3 h-3" /></button>
                </div>
              ))}
              {images.length < 5 && (
                <div className="relative aspect-video rounded-xl border-2 border-dashed border-black/10 dark:border-white/10 flex items-center justify-center group cursor-pointer hover:border-purple-500 transition-all">
                  <Upload className="w-6 h-6 text-slate-300 group-hover:text-purple-500" />
                  <input type="file" multiple onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                </div>
              )}
            </div>
            <button 
              onClick={handleExtract}
              disabled={loading || images.length === 0}
              className="w-full py-5 bg-purple-600 hover:bg-purple-700 text-white rounded-2xl font-black flex items-center justify-center gap-3 transition-all"
            >
              {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6" />}
              Kanal-Stil extrahieren
            </button>
          </div>
        ) : (
          <div className="space-y-10 animate-in fade-in duration-500">
            <div className="p-6 bg-purple-50 dark:bg-purple-900/20 rounded-3xl border border-purple-500/20">
              <h3 className="text-lg font-black text-purple-600 mb-4 flex items-center gap-2">
                <CheckCircle className="w-5 h-5" /> Stil-DNA gefunden
              </h3>
              <p className="text-slate-700 dark:text-slate-300 font-bold mb-6">{styleSummary.summary}</p>
              <div className="flex flex-wrap gap-2">
                {styleSummary.elements.map((el, i) => (
                  <span key={i} className="px-3 py-1 bg-white dark:bg-slate-800 rounded-full text-[10px] font-black uppercase text-slate-500 tracking-widest">{el}</span>
                ))}
              </div>
            </div>

            <div className="space-y-6">
              <label className="block text-xs font-black uppercase tracking-widest text-slate-500">Was soll das neue Thumbnail zeigen?</label>
              <textarea 
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="Neues Video-Thema beschreiben..."
                className="w-full h-32 bg-slate-50 dark:bg-slate-800 rounded-2xl p-4 focus:ring-2 focus:ring-purple-500 outline-none transition-all resize-none"
              />
              <button 
                onClick={handleGenerateInStyle}
                disabled={loading || !prompt}
                className="w-full py-5 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-black text-lg shadow-xl"
              >
                Im klonierten Stil generieren
              </button>
            </div>

            {result && (
              <div className="pt-8 border-t border-black/5 animate-in zoom-in-95">
                <div className="aspect-video rounded-3xl overflow-hidden shadow-2xl mb-4">
                  <img src={result} className="w-full h-full object-cover" />
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { LineChart, Upload, Loader2, Target, CheckCircle, AlertTriangle } from 'lucide-react';
import { analyzeThumbnailImage } from '../services/geminiService';

export const StudioAnalyze: React.FC = () => {
  const [image, setImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [analysis, setAnalysis] = useState<{score: number, feedback: string, suggestions: string[]} | null>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
        setAnalysis(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!image) return;
    setLoading(true);
    try {
      const res = await analyzeThumbnailImage(image);
      setAnalysis(res);
    } catch (err) {
      alert("Analyse fehlgeschlagen.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-5xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="grid md:grid-cols-2 gap-12">
        <div className="space-y-8">
          <div className="p-10 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl">
            <h2 className="text-2xl font-black mb-8 flex items-center gap-3">
              <Target className="w-7 h-7 text-emerald-500" />
              Thumbnail Audit
            </h2>
            <div className="relative aspect-video rounded-3xl border-2 border-dashed border-black/10 dark:border-white/10 flex flex-col items-center justify-center overflow-hidden group">
              {image ? (
                <img src={image} className="w-full h-full object-cover" />
              ) : (
                <>
                  <Upload className="w-10 h-10 text-slate-300 mb-4 group-hover:text-emerald-500 transition-colors" />
                  <p className="text-sm font-bold text-slate-400">Bild zum Analysieren ablegen</p>
                </>
              )}
              <input type="file" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
            </div>
            <button 
              onClick={handleAnalyze}
              disabled={loading || !image}
              className="w-full mt-8 py-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl font-black text-lg flex items-center justify-center gap-3 shadow-xl transition-all"
            >
              {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <LineChart className="w-6 h-6" />}
              CTR Score vorhersagen
            </button>
          </div>
        </div>

        <div className="flex flex-col justify-center">
          {analysis ? (
            <div className="space-y-8 animate-in slide-in-from-right-8 duration-500">
              <div className="p-10 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-500/10 blur-[60px] rounded-full" />
                <div className="relative z-10 flex items-center justify-between mb-8">
                  <div>
                    <h3 className="text-xs font-black uppercase tracking-widest text-slate-500 mb-1">Predictive Score</h3>
                    <p className="text-5xl font-black text-slate-900 dark:text-white">{analysis.score}<span className="text-2xl text-slate-400">/10</span></p>
                  </div>
                  <div className={`px-4 py-2 rounded-xl text-xs font-black uppercase ${analysis.score > 7 ? 'bg-emerald-500/10 text-emerald-500' : 'bg-amber-500/10 text-amber-500'}`}>
                    {analysis.score > 7 ? 'High Potential' : 'Needs Optimization'}
                  </div>
                </div>
                <p className="text-slate-600 dark:text-slate-400 font-medium leading-relaxed mb-10">{analysis.feedback}</p>
                <div className="space-y-4">
                  {analysis.suggestions.map((s, i) => (
                    <div key={i} className="flex items-start gap-4 p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl border border-black/5">
                      {analysis.score > 7 ? <CheckCircle className="w-5 h-5 text-emerald-500 shrink-0 mt-0.5" /> : <AlertTriangle className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />}
                      <span className="text-sm font-bold text-slate-700 dark:text-slate-300">{s}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ) : (
            <div className="text-center p-12 opacity-50">
              <div className="w-20 h-20 bg-slate-200 dark:bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-6">
                <LineChart className="w-10 h-10 text-slate-400" />
              </div>
              <h3 className="text-xl font-bold mb-2">Ergebnisse</h3>
              <p className="text-sm font-medium">Lade ein Bild hoch, um detaillierte Insights und CTR-Verbesserungen zu erhalten.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User } from './types';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { Features } from './components/Features';
import { Pricing } from './components/Pricing';
import { Reviews } from './components/Reviews';
import { AuthModal } from './components/AuthModal';
import { Examples } from './components/Examples';
import { StudioSelection } from './components/StudioSelection';
import { StudioGenerate } from './components/StudioGenerate';
import { StudioClone } from './components/StudioClone';
import { StudioAnalyze } from './components/StudioAnalyze';
import { Zap, ArrowLeft, Loader2, LayoutGrid } from 'lucide-react';
import { BACKGROUND_IMAGE } from './constants';

type MainView = 'home' | 'pricing' | 'reviews' | 'examples' | 'studio';
type StudioView = 'selection' | 'generate' | 'clone' | 'analyze';

function App() {
  const [user, setUser] = React.useState<User | null>(null);
  const [currentView, setCurrentView] = React.useState<MainView>('home');
  const [studioView, setStudioView] = React.useState<StudioView>('selection');
  const [isAuthOpen, setIsAuthOpen] = React.useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'light') setIsDarkMode(false);
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const handleLogin = (email: string) => {
    setUser({ id: '1', email: email, name: email.split('@')[0], isLoggedIn: true });
    setIsAuthOpen(false);
    handleNavigate('studio');
  };

  const handleNavigate = (view: MainView) => {
    if (view === 'studio' && !user) {
      setIsAuthOpen(true);
      return;
    }
    setCurrentView(view);
    if (view === 'studio') setStudioView('selection');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const BackButton = ({ toHome = true }) => (
    <button 
      onClick={() => toHome ? handleNavigate('home') : setStudioView('selection')}
      className="fixed top-24 left-4 lg:left-8 z-40 flex items-center gap-2 px-5 py-2.5 bg-white/80 dark:bg-slate-800/80 hover:bg-white dark:hover:bg-slate-800 border border-black/5 dark:border-white/10 rounded-full text-xs font-black uppercase tracking-widest transition-all group shadow-xl backdrop-blur-md text-slate-900 dark:text-slate-100"
    >
      <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
      {toHome ? 'Zurück' : 'Studio Home'}
    </button>
  );

  return (
    <div className={`min-h-screen transition-colors duration-500 selection:bg-blue-500 selection:text-white ${isDarkMode ? 'bg-slate-950 text-slate-100' : 'bg-sky-50 text-slate-900'} relative`}>

      <button
        onClick={toggleTheme}
        className="fixed top-4 right-4 z-[60] p-3 rounded-full bg-white/80 dark:bg-slate-800/80 border border-black/5 dark:border-white/10 shadow-xl backdrop-blur-md transition-all active:scale-90 flex items-center justify-center"
      >
        {isDarkMode ? "☀️" : "🌙"}
      </button>

      {currentView === 'home' && (
        <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden">
          <div 
            className={`absolute inset-0 bg-cover bg-center bg-fixed transform scale-110 blur-[6px] opacity-[0.08] transition-all duration-500 ${isDarkMode ? 'brightness-[1.5] contrast-150' : 'brightness-[0.85]'}`}
            style={{ backgroundImage: `url(${BACKGROUND_IMAGE})` }}
          />
          <div className={`absolute inset-0 transition-colors duration-500 ${isDarkMode ? 'bg-gradient-to-br from-slate-950/90 to-blue-900/20' : 'bg-gradient-to-br from-blue-50/20 to-sky-100/30'}`} />
        </div>
      )}

      <Navbar 
        user={user} 
        onNavigate={handleNavigate} 
        onLoginClick={() => setIsAuthOpen(true)} 
      />

      <main className="relative z-10">
        {currentView === 'home' && (
          <div className="animate-in fade-in duration-700">
            <Hero onStartCreating={() => handleNavigate('studio')} onViewPricing={() => handleNavigate('pricing')} />
            <Features />
            <Reviews />
            <Pricing />
          </div>
        )}

        {currentView === 'studio' && (
          <div className="pt-32 pb-20">
            {studioView === 'selection' ? (
              <>
                <BackButton toHome={true} />
                <StudioSelection onSelectMode={(mode) => setStudioView(mode as StudioView)} />
              </>
            ) : (
              <>
                <BackButton toHome={false} />
                <div className="px-4">
                  {studioView === 'generate' && <StudioGenerate />}
                  {studioView === 'clone' && <StudioClone />}
                  {studioView === 'analyze' && <StudioAnalyze />}
                </div>
              </>
            )}
          </div>
        )}

        {currentView === 'pricing' && <div className="pt-20"><BackButton /><Pricing /></div>}
        {currentView === 'reviews' && <div className="pt-20"><BackButton /><Reviews /></div>}
        {currentView === 'examples' && <div className="pt-20"><BackButton /><Examples onNavigateToStudio={() => handleNavigate('studio')} /></div>}
      </main>

      <footer className="py-20 border-t border-black/5 dark:border-white/5 bg-white/50 dark:bg-slate-900/50 mt-20 relative z-10">
        <div className="max-w-7xl mx-auto px-4 text-center">
          <div className="flex justify-center items-center gap-2 mb-6">
            <div className="bg-blue-600 p-1.5 rounded-lg shadow-lg">
              <Zap className="w-5 h-5 text-white fill-white" />
            </div>
            <span className="text-xl font-bold tracking-tight dark:text-white">Thumbify <span className="text-blue-500">AI</span></span>
          </div>
          <p className="text-slate-500 dark:text-slate-400 text-sm max-w-sm mx-auto mb-8">
            Das professionelle Toolset für YouTube Creator. Optimiere deine Klickraten mit künstlicher Intelligenz.
          </p>
          <div className="flex justify-center gap-8 text-slate-400 text-xs font-bold uppercase tracking-widest">
            <button onClick={() => handleNavigate('pricing')} className="hover:text-blue-500">Preise</button>
            <button onClick={() => handleNavigate('reviews')} className="hover:text-blue-500">Bewertungen</button>
            <button onClick={() => handleNavigate('examples')} className="hover:text-blue-500">Beispiele</button>
          </div>
        </div>
      </footer>

      <AuthModal isOpen={isAuthOpen} onClose={() => setIsAuthOpen(false)} onLogin={handleLogin} />
    </div>
  );
}

export default App;

