              <div className="p-10 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-500/10 blur-[60px] rounded-full" />
                <div className="relative z-10 flex items-center justify-between mb-8">
                  <div>
                    <h3 className="text-xs font-black uppercase tracking-widest text-slate-500 mb-1">Predictive Score</h3>
