import React from 'react';
import { X, Mail, Lock, AlertCircle } from 'lucide-react';

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  onLogin: (email: string) => void;
}

export const AuthModal: React.FC<AuthModalProps> = ({ isOpen, onClose, onLogin }) => {
  const [email, setEmail] = React.useState('');
  const [error, setError] = React.useState<string | null>(null);

  const validateEmail = (email: string) => {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email.toLowerCase());
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (!validateEmail(email)) {
      setError('Bitte gib eine gültige E-Mail-Adresse ein.');
      return;
    }

    onLogin(email);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={onClose}></div>

      <div className="relative w-full max-w-md bg-[#0f172a] border border-white/10 rounded-3xl p-8 shadow-2xl animate-in zoom-in-95 duration-200">
        <button onClick={onClose} className="absolute top-4 right-4 text-gray-400 hover:text-white">
          <X className="w-6 h-6" />
        </button>

        <div className="text-center mb-8">
          <h2 className="text-3xl font-bold mb-2">Willkommen zurück</h2>
          <p className="text-gray-400">Werde Teil von 4.500+ Creatoren auf Thumbify</p>
        </div>

        <button 
          onClick={() => onLogin('google-user@gmail.com')}
          className="w-full flex items-center justify-center gap-3 py-3 px-4 bg-white text-black rounded-xl font-bold mb-6 hover:bg-gray-200 transition-all"
        >
          <img src="https://www.google.com/favicon.ico" alt="Google" className="w-5 h-5" />
          Mit Google fortfahren
        </button>

        <div className="relative mb-6">
          <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-white/10"></div></div>
          <div className="relative flex justify-center text-sm uppercase"><span className="px-2 bg-[#0f172a] text-gray-500">Oder E-Mail Login</span></div>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="relative">
            <Mail className={`absolute left-3 top-3.5 w-5 h-5 ${error ? 'text-red-400' : 'text-gray-500'}`} />
            <input 
              type="text" 
              placeholder="E-Mail Adresse" 
              value={email}
              onChange={(e) => {
                setEmail(e.target.value);
                if (error) setError(null);
              }}
              className={`w-full bg-white/5 border rounded-xl py-3 pl-10 pr-4 focus:outline-none transition-colors ${
                error ? 'border-red-500 focus:border-red-500' : 'border-white/10 focus:border-blue-500'
              }`}
            />
            {error && (
              <div className="flex items-center gap-1.5 mt-2 text-red-400 text-xs font-bold animate-in fade-in slide-in-from-top-1">
                <AlertCircle className="w-3.5 h-3.5" />
                {error}
              </div>
            )}
          </div>
          <div className="relative">
            <Lock className="absolute left-3 top-3.5 w-5 h-5 text-gray-500" />
            <input 
              type="password" 
              placeholder="Passwort" 
              className="w-full bg-white/5 border border-white/10 rounded-xl py-3 pl-10 pr-4 focus:outline-none focus:border-blue-500 transition-colors"
              required
            />
          </div>

          <button 
            type="submit"
            className="w-full py-3 bg-blue-600 hover:bg-blue-500 rounded-xl font-bold transition-all shadow-lg shadow-blue-500/20"
          >
            Anmelden
          </button>
        </form>

        <p className="text-center text-sm text-gray-500 mt-6">
          Keine Kreditkarte zum Starten erforderlich. Mit der Anmeldung stimmst du unseren Bedingungen zu.
        </p>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Star, Quote, ChevronLeft, ChevronRight } from 'lucide-react';
