                  </div>

                  <div className="flex items-center gap-6 pt-10 border-t border-slate-100 dark:border-white/10">
                    <div className="relative">
                      <div className="absolute inset-0 bg-blue-500 blur-xl opacity-10 group-hover:opacity-30 transition-opacity rounded-full"></div>
                      <img src={review.avatar} className="relative w-16 h-16 rounded-full object-cover border-4 border-slate-50 dark:border-slate-800 shadow-sm" alt="Creator Profile" />
                    </div>
                    <div>
                      <p className="text-sm text-blue-600 dark:text-blue-400 font-bold uppercase tracking-wider">{review.role}</p>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* Indicators */}
          <div className="flex justify-center gap-3 mt-14">
            {REVIEWS.map((_, idx) => (
              <button
                key={idx}
                onClick={() => setActiveIndex(idx)}
                className={`h-2 rounded-full transition-all duration-300 ${
                  idx === activeIndex ? 'w-10 bg-blue-600 shadow-md shadow-blue-600/20' : 'w-3 bg-slate-200 dark:bg-slate-800 hover:bg-slate-300 dark:hover:bg-slate-700'
