import React, { useState } from 'react';
import { Copy, Upload, Loader2, Sparkles, CheckCircle, Trash2, Coins } from 'lucide-react';
import { extractStyleFromImages, generateThumbnail } from '../services/geminiService';

interface StudioCloneProps {
  useCredits: (amount: number) => boolean;
}

export const StudioClone: React.FC<StudioCloneProps> = ({ useCredits }) => {
  const [images, setImages] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [styleSummary, setStyleSummary] = useState<{summary: string, elements: string[]} | null>(null);
  const [prompt, setPrompt] = useState('');
  const [result, setResult] = useState<string | null>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files) {
      (Array.from(files) as File[]).forEach(file => {
        const reader = new FileReader();
        reader.onloadend = () => {
          if (typeof reader.result === 'string') {
            setImages(prev => [...prev, reader.result as string].slice(0, 5));
          }
        };
        reader.readAsDataURL(file);
      });
    }
  };

  const handleExtract = async () => {
    if (images.length === 0) return;

    // Extraktion kostet 5 Credits
    if (!useCredits(5)) return;

    setLoading(true);
    try {
      const res = await extractStyleFromImages(images);
      setStyleSummary(res);
    } catch (err) {
      alert("Analyse fehlgeschlagen.");
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateInStyle = async () => {
    if (!prompt.trim() || !styleSummary) return;

    // Generierung kostet weitere 10 Credits
    if (!useCredits(10)) return;

    setLoading(true);
    try {
      const res = await generateThumbnail(`${prompt}. Beachte diesen Stil: ${styleSummary.summary}`, 'Individuell');
      setResult(res);
    } catch (err) {
      alert("Generierung fehlgeschlagen.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="p-10 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl">
        <div className="flex justify-between items-center mb-8">
          <h2 className="text-3xl font-black flex items-center gap-4">
            <Copy className="w-8 h-8 text-purple-500" />
            Stil-Kloner
          </h2>
          <div className="flex items-center gap-1.5 text-[10px] font-black uppercase text-amber-500 tracking-widest bg-amber-500/10 px-3 py-1 rounded-full">
            <Coins className="w-3.5 h-3.5" />
            Analyse: 5 | Gen.: 10 Credits
          </div>
        </div>

        {!styleSummary ? (
          <div className="space-y-8">
            <p className="text-slate-500 dark:text-slate-400 font-medium">Lade bis zu 5 Thumbnails hoch, deren Stil wir analysieren sollen.</p>
            <div className="grid grid-cols-2 sm:grid-cols-5 gap-4">
              {images.map((img, i) => (
                <div key={i} className="relative aspect-video rounded-xl overflow-hidden border border-black/10">
                  <img src={img} className="w-full h-full object-cover" />
                  <button onClick={() => setImages(prev => prev.filter((_, idx) => idx !== i))} className="absolute top-1 right-1 p-1 bg-red-500 rounded text-white"><Trash2 className="w-3 h-3" /></button>
                </div>
              ))}
              {images.length < 5 && (
                <div className="relative aspect-video rounded-xl border-2 border-dashed border-black/10 dark:border-white/10 flex items-center justify-center group cursor-pointer hover:border-purple-500 transition-all">
                  <Upload className="w-6 h-6 text-slate-300 group-hover:text-purple-500" />
                  <input type="file" multiple onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                </div>
              )}
            </div>
            <button 
              onClick={handleExtract}
              disabled={loading || images.length === 0}
              className="w-full py-5 bg-purple-600 hover:bg-purple-700 text-white rounded-2xl font-black flex items-center justify-center gap-3 transition-all"
            >
              {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6" />}
              Kanal-Stil extrahieren
            </button>
          </div>
        ) : (
          <div className="space-y-10 animate-in fade-in duration-500">
            <div className="p-6 bg-purple-50 dark:bg-purple-900/20 rounded-3xl border border-purple-500/20">
              <h3 className="text-lg font-black text-purple-600 mb-4 flex items-center gap-2">
                <CheckCircle className="w-5 h-5" /> Stil-DNA gefunden
              </h3>
              <p className="text-slate-700 dark:text-slate-300 font-bold mb-6">{styleSummary.summary}</p>
              <div className="flex flex-wrap gap-2">
                {styleSummary.elements.map((el, i) => (
                  <span key={i} className="px-3 py-1 bg-white dark:bg-slate-800 rounded-full text-[10px] font-black uppercase text-slate-500 tracking-widest">{el}</span>
                ))}
              </div>
            </div>

            <div className="space-y-6">
              <label className="block text-xs font-black uppercase tracking-widest text-slate-500">Was soll das neue Thumbnail zeigen?</label>
              <textarea 
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="Neues Video-Thema beschreiben..."
                className="w-full h-32 bg-slate-50 dark:bg-slate-800 rounded-2xl p-4 focus:ring-2 focus:ring-purple-500 outline-none transition-all resize-none"
              />
              <button 
                onClick={handleGenerateInStyle}
                disabled={loading || !prompt}
                className="w-full py-5 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-black text-lg shadow-xl"
              >
                Im klonierten Stil generieren
              </button>
            </div>

            {result && (
              <div className="pt-8 border-t border-black/5 animate-in zoom-in-95">
                <div className="aspect-video rounded-3xl overflow-hidden shadow-2xl mb-4">
                  <img src={result} className="w-full h-full object-cover" />
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

