import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateThumbnail = async (prompt: string, style: string, base64Image?: string) => {
  const ai = getAI();

  const textKeywords = ['text', 'schrift', 'wort', 'title', 'titel', 'heading', 'überschrift', 'buchstaben', 'letters', 'words', 'quote', 'zitat', 'schreiben'];
  const textRequested = textKeywords.some(keyword => prompt.toLowerCase().includes(keyword));

  const textInstruction = textRequested 
    ? "Nutze fette, moderne und extrem gut lesbare Typografie für den geforderten Text. Der Text muss hervorstechen."
    : "Generiere das Bild absolut OHNE Text, OHNE Buchstaben und OHNE jegliche Schriftzeichen. Das Bild soll rein visuell sein und keine künstlichen Hieroglyphen oder Textelemente enthalten.";

  const fullPrompt = `Erstelle ein professionelles YouTube-Thumbnail im Stil '${style}'. 
Beschreibung: ${prompt}. 

WICHTIGE INSTRUKTION ZU TEXT:
${textInstruction}

ALLGEMEINE QUALITÄT:
Achte auf extrem hohen Kontrast, satte Farben und eine klare Bildhierarchie. Sorge für eine dramatische Beleuchtung und eine professionelle Komposition. Premium 4K Quality.`;

  const contents: any = {
    parts: [{ text: fullPrompt }]
  };

  if (base64Image) {
    contents.parts.push({
      inlineData: {
        data: base64Image.split(',')[1],
        mimeType: 'image/png'
      }
    });
  }

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents,
    config: {
      imageConfig: {
        aspectRatio: "16:9",
      }
    }
  });

  const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  if (imagePart?.inlineData) {
    return `data:image/png;base64,${imagePart.inlineData.data}`;
  }
  throw new Error("Generierung fehlgeschlagen");
};

export const analyzeThumbnailImage = async (base64Image: string) => {
  const ai = getAI();
  const prompt = `Analysiere dieses YouTube-Thumbnail. Bewerte es auf einer Skala von 0-10 für CTR-Potenzial. Gib spezifische Verbesserungsvorschläge zu Komposition, Text lesbarkeit und Farben. Antworte in Deutsch und im JSON Format.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Image.split(',')[1], mimeType: 'image/png' } },
        { text: prompt }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          score: { type: Type.NUMBER },
          feedback: { type: Type.STRING },
          suggestions: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["score", "feedback", "suggestions"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const analyzeYoutubeChannel = async (channelUrl: string) => {
  const ai = getAI();
  const prompt = `Führe ein professionelles YouTube Thumbnail Audit für den Kanal durch: ${channelUrl}. 
  Suche nach den neuesten Thumbnails dieses Kanals. 
  Analysiere:
  1. Den konsistenten visuellen Stil.
  2. Was gut funktioniert (Best Practices).
  3. Wo CTR verloren geht (Verbesserungspotenzial).
  4. Ein konkreter Aktionsplan für zukünftige Thumbnails.

  Antworte auf Deutsch und im JSON Format.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          channelName: { type: Type.STRING },
          identitySummary: { type: Type.STRING },
          strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
          weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
          actionPlan: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["channelName", "identitySummary", "strengths", "weaknesses", "actionPlan"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

