type StudioView = 'selection' | 'generate' | 'channel' | 'analyze';

const MouseGlow = () => {
  const [position, setPosition] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      setPosition({ x: e.clientX, y: e.clientY });
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return (
    <div 
      className="fixed inset-0 z-0 pointer-events-none transition-opacity duration-1000 opacity-30 dark:opacity-40"
      style={{
        background: `radial-gradient(600px circle at ${position.x}px ${position.y}px, rgba(59, 130, 246, 0.15), transparent 80%)`
      }}
    />
  );
};

function App() {
  const [user, setUser] = React.useState<User | null>(null);
  const [currentView, setCurrentView] = React.useState<MainView>('home');
  const [studioView, setStudioView] = React.useState<StudioView>('selection');
  const [isAuthOpen, setIsAuthOpen] = React.useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'light') setIsDarkMode(false);
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const handleLogin = (email: string) => {
    setUser({ 
      id: '1', 
      email: email, 
      name: email.split('@')[0], 
      credits: 100, 
      isLoggedIn: true 
    });
    setIsAuthOpen(false);
    handleNavigate('studio');
  };

  const useCredits = (amount: number): boolean => {
    if (!user || user.credits < amount) {
      alert(`Unzureichende Credits! Du benötigst ${amount} Credits für diese Aktion.`);
      setCurrentView('pricing');
      return false;
    }
    setUser({ ...user, credits: user.credits - amount });
    return true;
  };

  const handleNavigate = (view: MainView) => {
    if (view === 'studio' && !user) {
      setIsAuthOpen(true);
      return;
    }
    setCurrentView(view);
    if (view === 'studio') setStudioView('selection');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const BackButton = ({ toHome = true }) => (
    <button 
      onClick={() => toHome ? handleNavigate('home') : setStudioView('selection')}
      className="fixed top-24 left-4 lg:left-8 z-40 flex items-center gap-2 px-5 py-2.5 bg-white/80 dark:bg-slate-800/80 hover:bg-white dark:hover:bg-slate-800 border border-black/5 dark:border-white/10 rounded-full text-xs font-black uppercase tracking-widest transition-all group shadow-xl backdrop-blur-md text-slate-900 dark:text-slate-100"
    >
      <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
      {toHome ? 'Zurück' : 'Studio Übersicht'}
    </button>
  );

  return (
    <div className={`min-h-screen transition-colors duration-500 selection:bg-blue-500 selection:text-white ${isDarkMode ? 'bg-slate-950 text-slate-100' : 'bg-slate-50 text-slate-900'} relative`}>

      {currentView === 'home' && <MouseGlow />}

      <button
        onClick={toggleTheme}
        className="fixed top-4 right-4 z-[60] p-3 rounded-full bg-white/80 dark:bg-slate-800/80 border border-black/5 dark:border-white/10 shadow-xl backdrop-blur-md transition-all active:scale-90 flex items-center justify-center"
      >
        {isDarkMode ? "☀️" : "🌙"}
      </button>

      {currentView === 'home' && (
        <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden">
          <div 
            className={`absolute inset-0 bg-cover bg-center bg-fixed transform scale-110 blur-[6px] opacity-[0.06] transition-all duration-500 ${isDarkMode ? 'brightness-[1.2] contrast-150' : 'brightness-[0.8]'}`}
            style={{ backgroundImage: `url(${BACKGROUND_IMAGE})` }}
          />
          <div className={`absolute inset-0 transition-colors duration-500 ${isDarkMode ? 'bg-gradient-to-br from-slate-950/95 via-sky-950/20 to-slate-950/95' : 'bg-gradient-to-br from-sky-50/40 via-white/20 to-sky-50/40'}`} />
        </div>
      )}

      <Navbar 
        user={user} 
        onNavigate={handleNavigate} 
        onLoginClick={() => setIsAuthOpen(true)} 
      />

      <main className="relative z-10">
        {currentView === 'home' && (
          <div className="animate-in fade-in duration-700">
            <Hero onStartCreating={() => handleNavigate('studio')} onViewPricing={() => handleNavigate('pricing')} />

            <section className="py-24 border-y border-black/5 dark:border-white/5 bg-white/10 dark:bg-slate-900/10">
              <div className="max-w-7xl mx-auto px-4 grid md:grid-cols-2 gap-16 items-center">
                <div className="space-y-6">
                  <div className="inline-flex items-center gap-2 px-3 py-1 bg-amber-500/10 text-amber-600 dark:text-amber-400 rounded-full text-xs font-black uppercase tracking-widest">
                    <Coins className="w-4 h-4" /> Fairer Workflow
                  </div>
                  <h2 className="text-4xl font-black tracking-tight leading-tight">Keine Abos, nur <span className="text-blue-600">Leistung.</span></h2>
                  <p className="text-slate-500 dark:text-slate-400 font-medium text-lg leading-relaxed">
                    Bei Thumbify zahlst du nur für das, was du wirklich nutzt. Jede KI-Aktion verbraucht eine kleine Menge an Credits. Starte heute mit 100 kostenlosen Credits – ganz ohne Risiko.
                  </p>
                  <div className="space-y-4 pt-4">
                    {[
                      "100 Credits gratis zum Start",
                      "Volle Kontrolle über dein Budget",
                      "Keine versteckten Gebühren",
                      "Guthaben verfällt nie"
                    ].map((text, i) => (
                      <div key={i} className="flex items-center gap-3 font-bold text-slate-700 dark:text-slate-200">
                        <CheckCircle2 className="w-5 h-5 text-emerald-500" />
                        {text}
                      </div>
                    ))}
                  </div>
                </div>
                <div className="relative group">
                   <div className="absolute inset-0 bg-blue-600/10 blur-[100px] rounded-full group-hover:bg-blue-600/20 transition-all"></div>
                   <div className="relative p-10 bg-white dark:bg-slate-900/80 rounded-[3rem] border border-black/5 dark:border-white/10 shadow-2xl backdrop-blur-md">
                      <div className="grid grid-cols-2 gap-6 text-center">
                        <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-3xl border border-black/5">
                           <p className="text-3xl font-black mb-1">10</p>
                           <p className="text-[10px] font-black uppercase tracking-widest text-slate-500">Credits / Gen.</p>
                        </div>
                        <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-3xl border border-black/5">
                           <p className="text-3xl font-black mb-1">20</p>
                           <p className="text-[10px] font-black uppercase tracking-widest text-slate-500">Credits / Audit</p>
                        </div>
                        <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-3xl border border-black/5">
                           <p className="text-3xl font-black mb-1">5</p>
                           <p className="text-[10px] font-black uppercase tracking-widest text-slate-500">Credits / Image</p>
                        </div>
                        <div className="p-6 bg-blue-600 text-white rounded-3xl shadow-xl shadow-blue-600/20">
                           <p className="text-3xl font-black mb-1">100</p>
                           <p className="text-[10px] font-black uppercase tracking-widest opacity-80">Kostenloser Start</p>
                        </div>
                      </div>
                   </div>
                </div>
              </div>
            </section>

            <Features onNavigate={handleNavigate} />
            <Reviews />
            <Pricing onNavigate={handleNavigate} />
          </div>
        )}

        {currentView === 'studio' && (
          <div className="pt-32 pb-20">
            {studioView === 'selection' ? (
              <>
                <BackButton toHome={true} />
                <StudioSelection onSelectMode={(mode) => setStudioView(mode as StudioView)} />
              </>
            ) : (
              <>
                <BackButton toHome={false} />
                <div className="px-4">
                  {studioView === 'generate' && <StudioGenerate useCredits={useCredits} />}
                  {studioView === 'channel' && <StudioChannelAnalyze useCredits={useCredits} />}
                  {studioView === 'analyze' && <StudioAnalyze useCredits={useCredits} />}
                </div>
              </>
            )}
          </div>
        )}

        {currentView === 'pricing' && <div className="pt-20"><BackButton /><Pricing onNavigate={handleNavigate} /></div>}
        {currentView === 'reviews' && <div className="pt-20"><BackButton /><Reviews /></div>}
        {currentView === 'examples' && <div className="pt-20"><BackButton /><Examples onNavigateToStudio={() => handleNavigate('studio')} /></div>}
      </main>

      <footer className="py-20 border-t border-black/5 dark:border-white/5 bg-white/50 dark:bg-slate-900/50 mt-20 relative z-10">
        <div className="max-w-7xl mx-auto px-4 text-center">
          <div className="flex justify-center items-center gap-2 mb-6">
            <div className="bg-blue-600 p-1.5 rounded-lg shadow-lg">
              <Zap className="w-5 h-5 text-white fill-white" />
            </div>
            <span className="text-xl font-bold tracking-tight dark:text-white">Thumbify <span className="text-blue-500">AI</span></span>
          </div>
          <p className="text-slate-500 dark:text-slate-400 text-sm max-w-sm mx-auto mb-8">
            Das professionelle Toolset für YouTube Creator. Optimiere deine Klickraten mit künstlicher Intelligenz.
          </p>
          <div className="flex justify-center gap-8 text-slate-400 text-xs font-bold uppercase tracking-widest">
            <button onClick={() => handleNavigate('pricing')} className="hover:text-blue-500 transition-colors">Preise</button>
            <button onClick={() => handleNavigate('reviews')} className="hover:text-blue-500 transition-colors">Bewertungen</button>
            <button onClick={() => handleNavigate('examples')} className="hover:text-blue-500 transition-colors">Beispiele</button>
          </div>
        </div>
      </footer>

      <AuthModal isOpen={isAuthOpen} onClose={() => setIsAuthOpen(false)} onLogin={handleLogin} />
    </div>
  );
}

export default App;

