};

import React, { useState, useEffect } from 'react';
import { Youtube, Search, Loader2, Sparkles, CheckCircle, AlertTriangle, Coins, ArrowRight, ExternalLink, Zap, AlertCircle, RefreshCcw, FileText } from 'lucide-react';
import { analyzeYoutubeChannel } from '../services/geminiService';

interface StudioChannelAnalyzeProps {
  useCredits: (amount: number) => boolean;
}

export const StudioChannelAnalyze: React.FC<StudioChannelAnalyzeProps> = ({ useCredits }) => {
  const [url, setUrl] = useState('');
  const [urlError, setUrlError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [result, setResult] = useState<any | null>(null);

  useEffect(() => {
    let interval: any;
    if (loading) {
      setProgress(0);
      const steps = [
        { threshold: 15, text: "Google Search initialisieren..." },
        { threshold: 35, text: "Kanal-Daten werden geladen..." },
        { threshold: 55, text: "Thumbnails werden gescannt..." },
        { threshold: 75, text: "Visuelle Trends identifizieren..." },
        { threshold: 90, text: "Strategiebericht erstellen..." },
        { threshold: 98, text: "Finalisierung..." }
      ];

      interval = setInterval(() => {
        setProgress(prev => {
          const next = prev + Math.random() * 5;
          const currentStep = steps.find(s => next <= s.threshold) || steps[steps.length - 1];
          setStatusText(currentStep.text);
          return next >= 98 ? 98 : next;
        });
      }, 500);
    } else {
      setProgress(0);
      setStatusText('');
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const validateYoutubeUrl = (input: string) => {
    const youtubeRegex = /^(https?:\/\/)?(www\.)?(youtube\.com|youtu\.be)\/(channel\/|user\/|c\/|@)[a-zA-Z0-9_-]+(\/.*)?$/;
    if (!input.trim()) return "Bitte gib eine URL ein.";
    if (!youtubeRegex.test(input.trim())) return "Bitte gib eine gültige YouTube-Kanal-URL ein (z.B. youtube.com/@handle).";
    return null;
  };

  const handleAnalyze = async () => {
    const error = validateYoutubeUrl(url);
    if (error) {
      setUrlError(error);
      return;
    }
    setUrlError(null);
    if (!useCredits(20)) return;

    setLoading(true);
    setResult(null);
    try {
      const res = await analyzeYoutubeChannel(url);
      setResult(res);
      setProgress(100);
    } catch (err) {
      alert("Analyse fehlgeschlagen. Bitte prüfe die URL.");
    } finally {
      setTimeout(() => setLoading(false), 500);
    }
  };

  const handleExport = () => {
    alert("Audit-Bericht wird generiert... Dein PDF-Download startet in Kürze.");
  };

  const handleReset = () => {
    setResult(null);
    setUrl('');
    setProgress(0);
  };

  return (
    <div className="max-w-5xl mx-auto space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="p-10 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl">
        <div className="flex justify-between items-center mb-8">
          <h2 className="text-3xl font-black flex items-center gap-4">
            <Youtube className="w-10 h-10 text-red-600" />
            Kanal-Strategie Audit
          </h2>
          <div className="flex items-center gap-1.5 text-[10px] font-black uppercase text-amber-500 tracking-widest bg-amber-500/10 px-3 py-1 rounded-full">
            <Coins className="w-3.5 h-3.5" />
            Kostet 20 Credits
          </div>
        </div>

        <div className="space-y-6">
          <p className="text-slate-500 dark:text-slate-400 font-medium">
            Gib eine YouTube-Kanal-URL oder einen Handle ein. Unsere KI analysiert die neuesten Thumbnails und entwickelt eine Optimierungsstrategie.
          </p>

          <div className="space-y-2">
            <div className="relative group">
              <div className="absolute inset-y-0 left-0 pl-6 flex items-center pointer-events-none text-slate-400 group-focus-within:text-blue-500 transition-colors">
                <Search className="w-6 h-6" />
              </div>
              <input 
                type="text"
                value={url}
                onChange={(e) => {
                  setUrl(e.target.value);
                  if (urlError) setUrlError(null);
                }}
                placeholder="youtube.com/@KanalName oder Handle..."
                className={`w-full pl-16 pr-6 py-6 bg-slate-50 dark:bg-slate-800/50 border rounded-[2rem] text-lg font-bold focus:ring-4 outline-none transition-all ${
                  urlError 
                    ? 'border-red-500 focus:ring-red-500/10' 
                    : 'border-black/5 dark:border-white/5 focus:ring-blue-500/10'
                }`}
              />
            </div>
            {urlError && (
              <div className="flex items-center gap-2 px-6 text-red-500 text-sm font-bold animate-in fade-in slide-in-from-top-1">
                <AlertCircle className="w-4 h-4" />
                {urlError}
              </div>
            )}
          </div>

          {loading && (
            <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-300">
              <div className="flex justify-between items-end">
                <div className="flex items-center gap-2">
                  <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></div>
                  <span className="text-sm font-black uppercase tracking-widest text-blue-600 dark:text-blue-400">{statusText}</span>
                </div>
                <span className="text-sm font-black text-slate-400">{Math.round(progress)}%</span>
              </div>
              <div className="h-4 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden border border-black/5 dark:border-white/5 p-1">
                <div 
                  className="h-full bg-gradient-to-r from-blue-600 to-purple-600 rounded-full transition-all duration-700 ease-out shadow-[0_0_25px_rgba(147,51,234,0.4)]"
                  style={{ width: `${progress}%` }}
                ></div>
              </div>
            </div>
          )}

          <div className="flex gap-4">
             <button 
                onClick={handleAnalyze}
                disabled={loading || !url}
                className="flex-1 py-6 bg-slate-900 dark:bg-slate-100 text-white dark:text-slate-900 rounded-[2rem] font-black text-xl flex items-center justify-center gap-4 shadow-2xl transition-all active:scale-95 disabled:opacity-50"
              >
                {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6" />}
                Kanal tiefenanalysieren
              </button>
              {result && (
                <button 
                  onClick={handleReset}
                  className="px-8 py-6 bg-slate-100 dark:bg-slate-800 rounded-[2rem] font-black text-slate-500 hover:text-slate-900 dark:hover:text-white transition-all active:scale-95"
                >
                  <RefreshCcw className="w-6 h-6" />
                </button>
              )}
          </div>
        </div>
      </div>

      {result && (
        <div className="grid md:grid-cols-12 gap-8 animate-in slide-in-from-bottom-8 duration-700">
          <div className="md:col-span-12 p-10 bg-gradient-to-br from-purple-600 to-blue-700 rounded-[3rem] text-white shadow-xl">
             <div className="flex items-center gap-3 mb-6">
