             </div>
             <p className="text-xl font-medium leading-relaxed opacity-90">{result.identitySummary}</p>
          </div>

          <div className="md:col-span-6 space-y-8">
            <div className="p-8 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-black/5 dark:border-white/5 shadow-xl h-full">
              <h4 className="text-xl font-black mb-6 flex items-center gap-3 text-emerald-500">
                <CheckCircle className="w-6 h-6" /> CTR-Stärken
              </h4>
              <ul className="space-y-4">
                {result.strengths.map((s: string, i: number) => (
                  <li key={i} className="flex gap-4 items-start text-slate-600 dark:text-slate-400 font-medium">
