import { GoogleGenAI, Type } from "@google/genai";

// Always create a new instance right before use to ensure the latest API key is used
const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Analyzes the user's prompt to determine if text is requested and optimizes the scene description.
 */
const analyzePromptIntent = async (prompt: string) => {
  const ai = getAI();

  const analysisPrompt = `Analysiere den folgenden YouTube-Thumbnail-Prompt: "${prompt}"
Bestimme, ob der Nutzer expliziten Text im Bild wünscht (z.B. durch Anführungszeichen oder Wörter wie "Schrift", "Text", "Titel").
Extrahiere den gewünschten Text und erstelle eine optimierte visuelle Beschreibung für eine Bild-KI.

Antworte STRENG im JSON-Format:
{
  "wantsText": boolean,
  "extractedText": "der genaue Text oder null",
  "visualPrompt": "optimierte Beschreibung des Motivs ohne Text-Anweisungen"
}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: analysisPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            wantsText: { type: Type.BOOLEAN },
            extractedText: { type: Type.STRING, nullable: true },
            visualPrompt: { type: Type.STRING }
          },
          required: ["wantsText", "visualPrompt"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Intent analysis failed, falling back to keyword logic", e);
    return null;
  }
};

export const generateThumbnail = async (prompt: string, style: string, base64Image?: string) => {
  const ai = getAI();

  // Preliminary AI check to better distinguish intent
  const intent = await analyzePromptIntent(prompt);

  let textInstruction = "";
  let finalVisualPrompt = prompt;

  if (intent) {
    finalVisualPrompt = intent.visualPrompt;
    if (intent.wantsText) {
      textInstruction = `Nutze fette, moderne und extrem gut lesbare Typografie für den Text: "${intent.extractedText || 'TEXT'}". Der Text muss das zentrale, klickstarke Element sein.`;
    } else {
      textInstruction = `STRIKTE ANWEISUNG: Generiere ein Bild ABSOLUT OHNE JEGLICHEN TEXT. KEINE Buchstaben, KEINE Zahlen. Das Bild muss rein visuell sein.`;
    }
  } else {
    // Fallback Keyword Logic (Improved)
    const textKeywords = [
      'text', 'schrift', 'wort', 'title', 'titel', 'heading', 'überschrift', 
      'buchstaben', 'letters', 'words', 'quote', 'zitat', 'schreiben', 'aufschrift',
      'label', 'caption', 'typography', 'headline', 'banner', 'sign'
    ];
    const hasQuotes = /["'].*?["']/.test(prompt);
    const textRequested = textKeywords.some(keyword => prompt.toLowerCase().includes(keyword)) || hasQuotes;

    textInstruction = textRequested 
      ? "Integriere auffälligen, gut lesbaren Text basierend auf dem Motiv. Die Typografie muss modern und fett sein."
      : "STRIKTE ANWEISUNG: Generiere ein Bild ABSOLUT OHNE JEGLICHEN TEXT. KEINE Buchstaben oder Zahlen.";
  }

  const fullPrompt = `AUFGABE: Erstelle ein hochprofessionelles YouTube-Thumbnail.
STIL: ${style}. 
MOTIV: ${finalVisualPrompt}. 

STRATEGISCHE VORGABEN:
- Fokus auf starke visuelle Hierarchie und 'Rule of Thirds'.
- Dramatische Beleuchtung (Cinematic Lighting) und hoher Kontrast.
- Farben müssen gesättigt und 'eyecatching' sein für maximale CTR.

TEXT-REGEL:
${textInstruction}

TECHNISCHE QUALITÄT:
4K Auflösung, Ultra-Detail, Schärfentiefe, professionelles Color-Grading.`;

  const contents: any = {
    parts: [{ text: fullPrompt }]
  };

  if (base64Image) {
    contents.parts.push({
      inlineData: {
        data: base64Image.split(',')[1],
        mimeType: 'image/png'
      }
    });
  }

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents,
    config: {
      imageConfig: {
        aspectRatio: "16:9",
      }
    }
  });

  const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  if (imagePart?.inlineData) {
    return `data:image/png;base64,${imagePart.inlineData.data}`;
  }
  throw new Error("Generierung fehlgeschlagen - Kein Bild von der KI erhalten.");
};

export const analyzeThumbnailImage = async (base64Image: string) => {
  const ai = getAI();
  const prompt = `Analysiere dieses YouTube-Thumbnail. Bewerte es auf einer Skala von 0-10 für CTR-Potenzial. Gib spezifische Verbesserungsvorschläge zu Komposition, Text lesbarkeit und Farben. Antworte in Deutsch und im JSON Format.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Image.split(',')[1], mimeType: 'image/png' } },
        { text: prompt }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          score: { type: Type.NUMBER },
          feedback: { type: Type.STRING },
          suggestions: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["score", "feedback", "suggestions"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const analyzeYoutubeChannel = async (channelUrl: string) => {
  const ai = getAI();
  const prompt = `Führe ein professionelles YouTube Thumbnail Audit für den Kanal durch: ${channelUrl}. 
  Suche nach den neuesten Thumbnails dieses Kanals. 
  Analysiere den konsistenten visuellen Stil, Stärken, Schwächen und erstelle einen Aktionsplan.
  Antworte auf Deutsch und im JSON Format.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          channelName: { type: Type.STRING },
          identitySummary: { type: Type.STRING },
          strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
          weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
          actionPlan: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["channelName", "identitySummary", "strengths", "weaknesses", "actionPlan"]
      }
    }
  });

  const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
  const result = JSON.parse(response.text || '{}');

  return {
    ...result,
    sources: groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || chunk.web?.uri,
      url: chunk.web?.uri
    })).filter((s: any) => s.url) || []
  };
};

