import { GoogleGenAI, Type } from "@google/genai";

// Always create a new instance right before use to ensure the latest API key is used
const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Analyzes the user's prompt to determine if text is requested and optimizes the scene description.
 */
const analyzePromptIntent = async (prompt: string) => {
  const ai = getAI();

  const analysisPrompt = `Analysiere den folgenden YouTube-Thumbnail-Prompt: "${prompt}"
Bestimme, ob der Nutzer expliziten Text im Bild wünscht (z.B. durch Anführungszeichen oder Wörter wie "Schrift", "Text", "Titel").
Extrahiere den gewünschten Text und erstelle eine optimierte visuelle Beschreibung für eine Bild-KI.

Antworte STRENG im JSON-Format:
{
  "wantsText": boolean,
  "extractedText": "der genaue Text oder null",
  "visualPrompt": "optimierte Beschreibung des Motivs ohne Text-Anweisungen"
}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: analysisPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            wantsText: { type: Type.BOOLEAN },
            extractedText: { type: Type.STRING, nullable: true },
            visualPrompt: { type: Type.STRING }
          },
          required: ["wantsText", "visualPrompt"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Intent analysis failed, falling back to keyword logic", e);
    return null;
  }
};

export const remakeThumbnail = async (sourceBase64: string, adjustmentPrompt: string) => {
  const ai = getAI();

  // First, analyze the source image to extract its core style elements
  const analysisPrompt = `Analysiere dieses Thumbnail im Detail:
1. Was ist das Hauptmotiv?
2. Wie ist die Komposition (Regel der Drittel, Symmetrie, etc.)?
3. Was sind die dominanten Farben und Lichtstimmungen?
4. Welche Art von Text/Typografie wird verwendet?

Erstelle basierend auf dieser Analyse und der Nutzeranpassung "${adjustmentPrompt}" eine hochpräzise Beschreibung für ein Remake, das den exakten Stil beibehält, aber den Inhalt anpasst.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: sourceBase64.split(',')[1], mimeType: 'image/png' } },
        { text: analysisPrompt }
      ]
    }
  });

  const refinedPrompt = response.text;

  // Now generate the image using the refined instructions
  return generateThumbnail(refinedPrompt || adjustmentPrompt, 'Remake', sourceBase64);
};

export const generateThumbnail = async (prompt: string, style: string, base64Image?: string) => {
  const ai = getAI();

  // Preliminary AI check to better distinguish intent
  const intent = await analyzePromptIntent(prompt);

  let textInstruction = "";
  let finalVisualPrompt = prompt;

  if (intent) {
    finalVisualPrompt = intent.visualPrompt;
    if (intent.wantsText) {
      textInstruction = `Nutze fette, moderne und extrem gut lesbare Typografie für den Text: "${intent.extractedText || 'TEXT'}". Der Text muss das zentrale, klickstarke Element sein.`;
    } else {
      textInstruction = `STRIKTE ANWEISUNG: Generiere ein Bild ABSOLUT OHNE JEGLICHEN TEXT. KEINE Buchstaben, KEINE Zahlen. Das Bild muss rein visuell sein.`;
    }
  } else {
    // Fallback Keyword Logic (Improved)
    const textKeywords = [
      'text', 'schrift', 'wort', 'title', 'titel', 'heading', 'überschrift', 
      'buchstaben', 'letters', 'words', 'quote', 'zitat', 'schreiben', 'aufschrift',
      'label', 'caption', 'typography', 'headline', 'banner', 'sign'
    ];
    const hasQuotes = /["'].*?["']/.test(prompt);
    const textRequested = textKeywords.some(keyword => prompt.toLowerCase().includes(keyword)) || hasQuotes;

    textInstruction = textRequested 
      ? "Integriere auffälligen, gut lesbaren Text basierend auf dem Motiv. Die Typografie muss modern und fett sein."
      : "STRIKTE ANWEISUNG: Generiere ein Bild ABSOLUT OHNE JEGLICHEN TEXT. KEINE Buchstaben oder Zahlen.";
  }

  const fullPrompt = `AUFGABE: Erstelle ein hochprofessionelles YouTube-Thumbnail.
STIL: ${style}. 
MOTIV: ${finalVisualPrompt}. 

STRATEGISCHE VORGABEN:
- Fokus auf starke visuelle Hierarchie und 'Rule of Thirds'.
- Dramatische Beleuchtung (Cinematic Lighting) und hoher Kontrast.
- Farben müssen gesättigt und 'eyecatching' sein für maximale CTR.

TEXT-REGEL:
${textInstruction}

TECHNISCHE QUALITÄT:
4K Auflösung, Ultra-Detail, Schärfentiefe, professionelles Color-Grading.`;

  const contents: any = {
    parts: [{ text: fullPrompt }]
  };

  if (base64Image) {
    contents.parts.push({
      inlineData: {
        data: base64Image.split(',')[1],
        mimeType: 'image/png'
      }
    });
  }

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents,
    config: {
      imageConfig: {
        aspectRatio: "16:9",
      }
    }
  });

  const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  if (imagePart?.inlineData) {
    return `data:image/png;base64,${imagePart.inlineData.data}`;
  }
  throw new Error("Generierung fehlgeschlagen - Kein Bild von der KI erhalten.");
};

export const analyzeThumbnailImage = async (base64Image: string) => {
  const ai = getAI();
  const prompt = `Analysiere dieses YouTube-Thumbnail. Bewerte es auf einer Skala von 0-10 für CTR-Potenzial. Gib spezifische Verbesserungsvorschläge zu Komposition, Text lesbarkeit und Farben. Antworte in Deutsch und im JSON Format.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Image.split(',')[1], mimeType: 'image/png' } },
        { text: prompt }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          score: { type: Type.NUMBER },
          feedback: { type: Type.STRING },
          suggestions: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["score", "feedback", "suggestions"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const analyzeYoutubeChannel = async (channelUrl: string) => {
  const ai = getAI();
  const prompt = `Führe ein professionelles YouTube Thumbnail Audit für den Kanal durch: ${channelUrl}. 
  Suche nach den neuesten Thumbnails dieses Kanals. 
  Analysiere den konsistenten visuellen Stil, Stärken, Schwächen und erstelle einen Aktionsplan.
  Antworte auf Deutsch und im JSON Format.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          channelName: { type: Type.STRING },
          identitySummary: { type: Type.STRING },
          strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
          weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
          actionPlan: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["channelName", "identitySummary", "strengths", "weaknesses", "actionPlan"]
      }
    }
  });

  const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
  const result = JSON.parse(response.text || '{}');

  return {
    ...result,
    sources: groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || chunk.web?.uri,
      url: chunk.web?.uri
    })).filter((s: any) => s.url) || []
  };
};

import React, { useState, useEffect } from 'react';
import { Copy, Upload, Sparkles, Loader2, Download, Trash2, ArrowRight, Coins, Lightbulb, AlertCircle, Image as ImageIcon } from 'lucide-react';
import { remakeThumbnail } from '../services/geminiService';
import { User } from '../types';

interface StudioRemakeProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
}

export const StudioRemake: React.FC<StudioRemakeProps> = ({ useCredits, user }) => {
  const [sourceImage, setSourceImage] = useState<string | null>(null);
  const [adjustment, setAdjustment] = useState('');
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [result, setResult] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let interval: any;
    if (loading) {
      setProgress(0);
      const steps = [
        { threshold: 25, text: "Stil-Elemente werden extrahiert..." },
        { threshold: 50, text: "Komposition wird gematcht..." },
        { threshold: 80, text: "Anpassungen werden gerendert..." },
        { threshold: 95, text: "Finalisierung..." }
      ];

      interval = setInterval(() => {
        setProgress(prev => {
          const next = prev + Math.random() * 6;
          const currentStep = steps.find(s => next <= s.threshold) || steps[steps.length - 1];
          setStatusText(currentStep.text);
          return next >= 98 ? 98 : next;
        });
      }, 500);
    } else {
      setProgress(0);
      setStatusText('');
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setError(null);
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError("Bitte lade nur Bilddateien hoch.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => setSourceImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleRemake = async () => {
    if (!sourceImage) {
      setError("Bitte lade zuerst ein Referenzbild hoch.");
      return;
    }

    if (!user || user.credits < 15) {
      alert("Du benötigst 15 Credits für ein Remake.");
      return;
    }

    setLoading(true);
    setResult(null);
    try {
      const res = await remakeThumbnail(sourceImage, adjustment);
      useCredits(15);
      setResult(res);
      setProgress(100);
    } catch (err) {
      setError("Das Remake ist fehlgeschlagen. Bitte versuche es erneut.");
    } finally {
      setTimeout(() => setLoading(false), 500);
    }
  };

  return (
    <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="grid lg:grid-cols-2 gap-12">
        <div className="space-y-8">
          <div className="p-10 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-2xl font-black flex items-center gap-3">
                <Copy className="w-7 h-7 text-indigo-500" />
                Thumbnail-Remake
              </h2>
              <div className="flex items-center gap-1.5 text-[10px] font-black uppercase text-amber-500 tracking-widest bg-amber-500/10 px-3 py-1 rounded-full">
                <Coins className="w-3.5 h-3.5" />
                15 Credits
              </div>
            </div>

            <div className="space-y-8">
              {/* Reference Upload */}
              <div>
                <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-3">Referenz-Thumbnail</label>
                <div className={`relative h-56 border-2 border-dashed rounded-[2rem] flex flex-col items-center justify-center group overflow-hidden transition-all ${
                  sourceImage ? 'border-indigo-500/50' : 'border-black/10 dark:border-white/10 hover:border-indigo-500/30'
                }`}>
                  {sourceImage ? (
                    <>
                      <img src={sourceImage} className="w-full h-full object-cover opacity-60" />
                      <div className="absolute inset-0 flex items-center justify-center gap-3">
                         <button onClick={() => setSourceImage(null)} className="p-3 bg-red-500 text-white rounded-2xl shadow-xl hover:scale-110 transition-transform">
                           <Trash2 className="w-5 h-5" />
                         </button>
                         <div className="px-4 py-2 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-xl">Stil geladen</div>
                      </div>
                    </>
                  ) : (
                    <>
                      <div className="w-16 h-16 bg-slate-100 dark:bg-slate-800 rounded-3xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                        <Upload className="w-8 h-8 text-slate-400 group-hover:text-indigo-500" />
                      </div>
                      <span className="text-xs font-black uppercase tracking-widest text-slate-400">Bild hier ablegen</span>
                      <input type="file" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                    </>
                  )}
                </div>
              </div>

              {/* Adjustment Prompt */}
              <div>
                <div className="flex items-center justify-between mb-3">
                  <label className="text-xs font-black uppercase tracking-widest text-slate-500">Was soll geändert werden?</label>
                  <div className="flex items-center gap-1.5 text-[10px] font-bold text-indigo-500 bg-indigo-500/5 px-2 py-1 rounded-md">
                    <Sparkles className="w-3 h-3" /> Smart Adjustment
                  </div>
                </div>
                <textarea 
                  value={adjustment}
                  onChange={(e) => setAdjustment(e.target.value)}
                  placeholder="z.B. 'Ändere das Gesicht zu einem lachenden Gamer' oder 'Ersetze das iPhone durch eine PS5, behalte den Stil bei'..."
                  className="w-full h-32 bg-slate-50 dark:bg-slate-800/50 border border-black/5 dark:border-white/5 rounded-2xl p-4 focus:ring-4 focus:ring-indigo-500/10 outline-none transition-all resize-none font-medium"
                />
              </div>

              {error && (
                <div className="flex items-center gap-2 p-4 bg-red-500/10 text-red-500 rounded-2xl text-sm font-bold">
                   <AlertCircle className="w-5 h-5" />
                   {error}
                </div>
              )}

              {loading && (
                <div className="space-y-3 animate-in fade-in slide-in-from-top-2">
                  <div className="flex justify-between items-end">
                    <span className="text-xs font-black uppercase tracking-widest text-indigo-500">{statusText}</span>
                    <span className="text-xs font-black text-slate-400">{Math.round(progress)}%</span>
                  </div>
                  <div className="h-3 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden p-0.5 border border-black/5">
                    <div 
                      className="h-full bg-gradient-to-r from-indigo-600 to-blue-600 rounded-full transition-all duration-500 ease-out shadow-[0_0_15px_rgba(79,70,229,0.4)]"
                      style={{ width: `${progress}%` }}
                    ></div>
                  </div>
                </div>
              )}

              <button 
                onClick={handleRemake}
                disabled={loading || !sourceImage}
                className="w-full py-5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-black text-lg flex items-center justify-center gap-3 shadow-xl shadow-indigo-600/20 transition-all active:scale-95 disabled:opacity-50"
              >
                {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6" />}
                Remake starten
              </button>
            </div>
          </div>
        </div>

        <div className="flex flex-col justify-center">
          {result ? (
            <div className="space-y-6 animate-in zoom-in-95 duration-500">
              <div className="aspect-video rounded-[3rem] overflow-hidden shadow-2xl border-4 border-white dark:border-slate-800 group relative">
                <img src={result} className="w-full h-full object-cover" alt="Remake Ergebnis" />
                <div className="absolute top-4 left-4 px-4 py-2 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-xl shadow-lg">New Style Match</div>
              </div>
              <div className="flex gap-4">
                <button 
                  onClick={() => {
                    const link = document.createElement('a');
                    link.href = result;
                    link.download = 'remake-thumbnail.png';
                    link.click();
                  }}
                  className="flex-1 py-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl font-black flex items-center justify-center gap-3 shadow-xl transition-all active:scale-95"
                >
                  <Download className="w-6 h-6" /> 4K Download
                </button>
                <button 
                  onClick={() => setResult(null)}
                  className="px-8 py-5 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-2xl font-black hover:bg-slate-200 transition-all"
                >
                  Neu
                </button>
              </div>
            </div>
          ) : (
            <div className="aspect-video rounded-[3rem] bg-slate-100 dark:bg-slate-900/50 border-2 border-dashed border-black/10 dark:border-white/5 flex flex-col items-center justify-center text-center p-12">
              <div className="w-24 h-24 bg-indigo-500/10 rounded-[2.5rem] flex items-center justify-center mb-8">
                <ImageIcon className="w-12 h-12 text-indigo-500" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 dark:text-white mb-4">Bereit für dein Remake</h3>
              <p className="text-slate-500 dark:text-slate-400 font-medium max-w-sm leading-relaxed">
                Lade ein Referenzbild hoch und beschreibe deine Änderungen. Die KI wird den Stil perfekt adaptieren.
              </p>

              <div className="mt-12 flex items-center gap-6">
                 <div className="flex flex-col items-center gap-2">
                    <div className="w-10 h-10 rounded-xl bg-white dark:bg-slate-800 border border-black/5 shadow-sm flex items-center justify-center">
                       <Upload className="w-5 h-5 text-slate-400" />
                    </div>
                    <span className="text-[10px] font-black uppercase text-slate-400">1. Upload</span>
                 </div>
                 <ArrowRight className="w-4 h-4 text-slate-300" />
                 <div className="flex flex-col items-center gap-2">
                    <div className="w-10 h-10 rounded-xl bg-white dark:bg-slate-800 border border-black/5 shadow-sm flex items-center justify-center">
                       <Sparkles className="w-5 h-5 text-slate-400" />
                    </div>
                    <span className="text-[10px] font-black uppercase text-slate-400">2. Prompt</span>
                 </div>
                 <ArrowRight className="w-4 h-4 text-slate-300" />
                 <div className="flex flex-col items-center gap-2">
                    <div className="w-10 h-10 rounded-xl bg-indigo-600 shadow-lg shadow-indigo-600/20 flex items-center justify-center">
                       <Download className="w-5 h-5 text-white" />
                    </div>
                    <span className="text-[10px] font-black uppercase text-indigo-500">3. Result</span>
                 </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

