import React, { useState, useEffect, useRef } from 'react';
import { User } from './types';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { HowItWorks } from './components/HowItWorks';
import { Pricing } from './components/Pricing';
import { Reviews } from './components/Reviews';
import { AuthModal } from './components/AuthModal';
import { Examples } from './components/Examples';
import { StudioSelection } from './components/StudioSelection';
import { StudioGenerate } from './components/StudioGenerate';
import { StudioChannelAnalyze } from './components/StudioChannelAnalyze';
import { StudioAnalyze } from './components/StudioAnalyze';
import { StudioRemake } from './components/StudioRemake';
import { Zap, ArrowLeft, Coins, AlertCircle, ShoppingCart, X, CheckCircle, Lock } from 'lucide-react';
import { BACKGROUND_IMAGE, PricingPlan } from './constants';

type MainView = 'home' | 'pricing' | 'reviews' | 'examples' | 'studio';
type StudioView = 'selection' | 'generate' | 'channel' | 'analyze' | 'remake';

const MouseGlow = () => {
  const [position, setPosition] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      setPosition({ x: e.clientX, y: e.clientY });
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return (
    <div 
      className="fixed inset-0 z-0 pointer-events-none transition-opacity duration-1000 opacity-30 dark:opacity-40"
      style={{
        background: `radial-gradient(600px circle at ${position.x}px ${position.y}px, rgba(59, 130, 246, 0.15), transparent 80%)`
      }}
    />
  );
};

function App() {
  const [user, setUser] = React.useState<User | null>(null);
  const [currentView, setCurrentView] = React.useState<MainView>('home');
  const [studioView, setStudioView] = React.useState<StudioView>('selection');
  const [isAuthOpen, setIsAuthOpen] = React.useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [showLowCreditToast, setShowLowCreditToast] = useState(false);
  const [purchaseSuccess, setPurchaseSuccess] = useState<{ planName: string, amount: number } | null>(null);

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'light') setIsDarkMode(false);
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const handleLogin = (email: string) => {
    setUser({ 
      id: '1', 
      email: email, 
      name: email.split('@')[0], 
      credits: 30, // Starter Plan Initial Credits
      isLoggedIn: true,
      plan: 'Starter'
    });
    setIsAuthOpen(false);
    handleNavigate('studio');
  };

  const useCredits = (amount: number): boolean => {
    if (!user || user.credits < amount) {
      alert(`Unzureichende Credits! Du benötigst ${amount} Credits für diese Aktion.`);
      setCurrentView('pricing');
      return false;
    }
    const newBalance = user.credits - amount;
    setUser({ ...user, credits: newBalance });

    if (newBalance < 10) {
      setShowLowCreditToast(true);
    }
    return true;
  };

  const handlePurchase = (plan: PricingPlan) => {
    if (!user) {
      setIsAuthOpen(true);
      return;
    }

    const newCredits = user.credits + plan.credits;
    setUser({ ...user, credits: newCredits, plan: plan.name as any });
    setPurchaseSuccess({ planName: plan.name, amount: plan.credits });
    setShowLowCreditToast(false);

    setTimeout(() => setPurchaseSuccess(null), 5000);

    setCurrentView('studio');
    setStudioView('selection');
  };

  const handleNavigate = (view: MainView) => {
    if (view === 'studio' && !user) {
      setIsAuthOpen(true);
      return;
    }
    setCurrentView(view);
    if (view === 'studio') setStudioView('selection');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const checkPlanPermission = (mode: StudioView): boolean => {
    if (!user) return false;
    const plan = user.plan || 'Starter';

    if (mode === 'generate') return true; // Everyone can generate
    if (mode === 'analyze' || mode === 'channel') {
      return plan === 'Creator Pro' || plan === 'Production';
    }
    if (mode === 'remake') {
      return plan === 'Production';
    }
    return true;
  };

  const handleSelectStudioMode = (mode: StudioView) => {
    if (checkPlanPermission(mode)) {
      setStudioView(mode);
    } else {
      handleNavigate('pricing');
    }
  };

  const BackButton = ({ toHome = true }) => (
    <button 
      onClick={() => toHome ? handleNavigate('home') : setStudioView('selection')}
      className="fixed top-24 left-4 lg:left-8 z-40 flex items-center gap-2 px-5 py-2.5 bg-white/80 dark:bg-slate-800/80 hover:bg-white dark:hover:bg-slate-800 border border-black/5 dark:border-white/10 rounded-full text-xs font-black uppercase tracking-widest transition-all group shadow-xl backdrop-blur-md text-slate-900 dark:text-slate-100"
    >
      <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
      {toHome ? 'Zurück' : 'Studio Übersicht'}
    </button>
  );

  return (
    <div className={`min-h-screen transition-colors duration-500 selection:bg-blue-500 selection:text-white ${isDarkMode ? 'bg-slate-950 text-slate-100' : 'bg-slate-50 text-slate-900'} relative`}>

      {currentView === 'home' && <MouseGlow />}

      <button
        onClick={toggleTheme}
        className="fixed top-4 right-4 z-[60] p-3 rounded-full bg-white/80 dark:bg-slate-800/80 border border-black/5 dark:border-white/10 shadow-xl backdrop-blur-md transition-all active:scale-90 flex items-center justify-center"
      >
        {isDarkMode ? "☀️" : "🌙"}
      </button>

      {/* Purchase Success Toast */}
      {purchaseSuccess && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[110] w-full max-w-md px-4 animate-in slide-in-from-bottom-8 duration-500">
          <div className="bg-emerald-600 text-white rounded-3xl p-6 shadow-2xl flex items-center gap-6">
            <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center shrink-0">
              <CheckCircle className="w-6 h-6" />
            </div>
            <div className="flex-1 min-w-0">
              <h4 className="text-sm font-black uppercase tracking-wider mb-1">Kauf erfolgreich!</h4>
              <p className="text-xs font-medium opacity-90">Dein Plan <span className="font-black">{purchaseSuccess.planName}</span> wurde aktiviert. <span className="font-black">+{purchaseSuccess.amount} Credits</span> hinzugefügt.</p>
            </div>
            <button onClick={() => setPurchaseSuccess(null)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>
      )}

      {/* Credit Warning Toast */}
      {showLowCreditToast && user && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[100] w-full max-w-md px-4 animate-in slide-in-from-bottom-8 duration-500">
          <div className="bg-white dark:bg-slate-900 border-2 border-amber-500 rounded-3xl p-6 shadow-[0_20px_50px_rgba(245,158,11,0.3)] flex items-center gap-6">
            <div className="w-12 h-12 bg-amber-500/10 rounded-2xl flex items-center justify-center shrink-0">
              <AlertCircle className="w-6 h-6 text-amber-500" />
            </div>
            <div className="flex-1 min-w-0">
              <h4 className="text-sm font-black text-slate-900 dark:text-white uppercase tracking-wider mb-1">Guthaben fast leer!</h4>
              <p className="text-xs font-medium text-slate-500 dark:text-slate-400">Du hast nur noch <span className="text-amber-500 font-black">{user.credits} Credits</span>. Jetzt aufladen?</p>
            </div>
            <div className="flex flex-col gap-2">
              <button 
                onClick={() => { setShowLowCreditToast(false); handleNavigate('pricing'); }}
                className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-[10px] font-black uppercase rounded-xl flex items-center gap-2 shadow-lg shadow-blue-600/20 active:scale-95 transition-all"
              >
                <ShoppingCart className="w-3 h-3" /> Aufladen
              </button>
              <button onClick={() => setShowLowCreditToast(false)} className="text-[9px] font-black uppercase text-slate-400 hover:text-slate-600 text-center">Später</button>
            </div>
