              <div className="p-10 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-500/10 blur-[60px] rounded-full" />
                <div className="relative z-10 flex items-center justify-between mb-8">
                  <div>
                    <h3 className="text-xs font-black uppercase tracking-widest text-slate-500 mb-1">Vorhergesagter Score</h3>
                    <p className="text-5xl font-black text-slate-900 dark:text-white">{analysis.score}<span className="text-2xl text-slate-400">/10</span></p>
                  </div>
                  <div className={`px-4 py-2 rounded-xl text-xs font-black uppercase ${analysis.score > 7 ? 'bg-emerald-500/10 text-emerald-500' : 'bg-amber-500/10 text-amber-500'}`}>
                    {analysis.score > 7 ? 'Hohes Potenzial' : 'Optimierung nötig'}
                  </div>
                </div>
                <p className="text-slate-600 dark:text-slate-400 font-medium leading-relaxed mb-10">{analysis.feedback}</p>
                <div className="space-y-4 mb-10">
                  {analysis.suggestions.map((s, i) => (
                    <div key={i} className="flex items-start gap-4 p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl border border-black/5">
                      {analysis.score > 7 ? <CheckCircle className="w-5 h-5 text-emerald-500 shrink-0 mt-0.5" /> : <AlertTriangle className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />}
                      <span className="text-sm font-bold text-slate-700 dark:text-slate-300">{s}</span>
                    </div>
                  ))}
