import React, { useState, useEffect } from 'react';
import { Wand2, Upload, Sparkles, Loader2, Download, Trash2, Image as ImageIcon, Coins, Lightbulb, Plus, AlertCircle, ShoppingCart, Lock } from 'lucide-react';
import { generateThumbnail } from '../services/geminiService';
import { ThumbnailStyle, User } from '../types';

interface StudioGenerateProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
  onGoToPricing?: () => void;
}

const STYLE_SUGGESTIONS: Record<ThumbnailStyle, string[]> = {
  [ThumbnailStyle.CLEAN]: ["Professionelle Beleuchtung", "Weicher Hintergrund", "Hoher Kontrast", "Zentriertes Motiv", "Pastellfarben", "Minimalistisches Setup"],
  [ThumbnailStyle.BEAST]: ["Schockierter Gesichtsausdruck", "Intensive Emotionen", "Leuchtende Neonfarben", "Fette Umrandung", "Überrascht in Kamera blickend", "Action-Pose"],
  [ThumbnailStyle.MINIMAL]: ["Viel Negativraum", "Einzelnes Objekt im Fokus", "Flaches Design", "Elegante Ästhetik", "Monochromer Look", "Sanfter Schatten"],
  [ThumbnailStyle.GAMING]: ["RGB-Beleuchtung", "Partikeleffekte", "Dynamischer Blickwinkel", "Cyberpunk Vibe", "Gaming-Setup im Hintergrund", "Explosive Farben"]
};

export const StudioGenerate: React.FC<StudioGenerateProps> = ({ useCredits, user, onGoToPricing }) => {
  const [prompt, setPrompt] = useState('');
  const [style, setStyle] = useState<ThumbnailStyle>(ThumbnailStyle.CLEAN);
  const [image, setImage] = useState<string | null>(null);
  const [promptError, setPromptError] = useState<string | null>(null);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [result, setResult] = useState<string | null>(null);

  const isLowCredits = user && user.credits < 10;
  const isStarter = user?.plan === 'Starter';

  useEffect(() => {
    let interval: any;
    if (loading) {
      setProgress(0);
      const steps = [
        { threshold: 20, text: "KI initialisiert..." },
        { threshold: 45, text: "Motive werden komponiert..." },
        { threshold: 75, text: "Beleuchtung wird verfeinert..." },
        { threshold: 95, text: "Details werden gerendert..." }
      ];

      interval = setInterval(() => {
        setProgress(prev => {
          const next = prev + Math.random() * 8;
          const currentStep = steps.find(s => next <= s.threshold) || steps[steps.length - 1];
          setStatusText(currentStep.text);
          return next >= 98 ? 98 : next;
        });
      }, 400);
    } else {
      setProgress(0);
      setStatusText('');
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setUploadError(null);

    if (file) {
      const allowedTypes = ['image/png', 'image/jpeg', 'image/jpg'];
      if (!allowedTypes.includes(file.type)) {
        setUploadError("Ungültiges Format. Bitte lade nur PNG oder JPG Dateien hoch.");
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => setImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    setPromptError(null);

    if (!prompt.trim()) {
      setPromptError("Bitte beschreibe zuerst deine Vision für das Thumbnail.");
      return;
    }

    if (!user || user.credits < 10) {
      alert("Du benötigst mindestens 10 Credits, um ein Thumbnail zu generieren.");
      if (onGoToPricing) onGoToPricing();
      return;
    }

    setLoading(true);
    try {
      const res = await generateThumbnail(prompt, style, image || undefined);
      useCredits(10);
      setResult(res);
      setProgress(100);
      setStatusText("Fertig!");
    } catch (err) {
      alert("Fehler bei der Generierung.");
    } finally {
      setTimeout(() => setLoading(false), 500);
    }
  };

  const addSuggestion = (suggestion: string) => {
    setPromptError(null);
    setPrompt(prev => {
      const trimmed = prev.trim();
      if (!trimmed) return suggestion;
      if (trimmed.endsWith(',')) return `${trimmed} ${suggestion}`;
      return `${trimmed}, ${suggestion}`;
    });
  };

  return (
    <div className="max-w-6xl mx-auto grid lg:grid-cols-2 gap-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="space-y-8">

        {/* Starter Plan Info */}
        {isStarter && (
          <div className="p-6 bg-blue-600/5 border border-blue-600/20 rounded-[2rem] flex items-center justify-between gap-6 animate-in slide-in-from-top-4 duration-500">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 bg-blue-600/10 rounded-full flex items-center justify-center shrink-0">
                <Lock className="w-5 h-5 text-blue-600" />
              </div>
              <div>
                <h4 className="text-sm font-black text-blue-600 dark:text-blue-400 uppercase tracking-widest mb-1 leading-none">Starter Plan aktiv</h4>
                <p className="text-[10px] text-blue-500 font-bold opacity-80 uppercase tracking-wider">Bilder enthalten ein Wasserzeichen</p>
              </div>
            </div>
            <button 
              onClick={onGoToPricing}
              className="px-6 py-2.5 bg-blue-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-blue-600/20 active:scale-95 transition-all"
            >
              Pro holen
            </button>
          </div>
        )}

        <div className="p-8 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-black/5 dark:border-white/5 shadow-2xl">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-2xl font-black flex items-center gap-3">
              <Sparkles className="w-6 h-6 text-blue-500" />
              Konfiguration
            </h2>
            <div className="flex items-center gap-1.5 text-[10px] font-black uppercase text-amber-500 tracking-widest bg-amber-500/10 px-3 py-1 rounded-full">
              <Coins className="w-3.5 h-3.5" />
              10 Credits
            </div>
          </div>

          <div className="space-y-6">
            <div>
              <div className="flex items-center justify-between mb-3">
                <label className="text-xs font-black uppercase tracking-widest text-slate-500">Vision beschreiben</label>
                <div className="flex items-center gap-1.5 text-[10px] font-bold text-blue-500 bg-blue-500/5 px-2 py-1 rounded-md">
                   <Lightbulb className="w-3 h-3" /> Prompt Helper
                </div>
              </div>

              <div className="relative">
                <textarea 
                  value={prompt}
                  onChange={(e) => {
                    setPrompt(e.target.value);
                    if (promptError) setPromptError(null);
                  }}
                  placeholder="z.B. Ein schockierter Mann hält ein goldenes iPhone in der Hand..."
                  className={`w-full h-32 bg-slate-50 dark:bg-slate-800/50 border rounded-2xl p-4 focus:ring-2 outline-none transition-all resize-none mb-2 ${
                    promptError ? 'border-red-500 ring-2 ring-red-500/10' : 'border-black/5 dark:border-white/5 focus:ring-blue-500'
                  }`}
                />
                {promptError && (
                  <div className="flex items-center gap-1.5 text-red-500 text-[11px] font-bold animate-in fade-in slide-in-from-top-1 duration-200 mb-4">
                    <AlertCircle className="w-3.5 h-3.5" />
                    {promptError}
                  </div>
                )}
              </div>

              {/* Prompt Helper Chips */}
              <div className="space-y-2">
                <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Vorschläge für {style}</span>
                <div className="flex flex-wrap gap-2">
                  {STYLE_SUGGESTIONS[style].map((suggestion, i) => (
                    <button
                      key={i}
                      onClick={() => addSuggestion(suggestion)}
                      className="group flex items-center gap-1.5 px-3 py-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-blue-500 hover:text-white dark:hover:bg-blue-600 rounded-full text-[11px] font-bold transition-all border border-transparent"
                    >
                      <Plus className="w-3 h-3 opacity-50 group-hover:opacity-100" />
                      {suggestion}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            <div>
              <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-3">Stil auswählen</label>
              <div className="grid grid-cols-2 gap-3">
                {Object.values(ThumbnailStyle).map((s) => (
                  <button
                    key={s}
                    onClick={() => setStyle(s)}
                    className={`py-3 px-4 rounded-xl font-bold text-sm border transition-all ${
                      style === s 
                        ? 'bg-blue-600 border-blue-600 text-white shadow-lg' 
                        : 'bg-slate-50 dark:bg-slate-800/50 border-transparent text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'
                    }`}
                  >
                    {s}
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-3">Referenzbild (Optional)</label>
              <div className={`relative h-40 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center group overflow-hidden transition-colors ${
                uploadError ? 'border-red-500 bg-red-500/5' : 'border-black/10 dark:border-white/10'
              }`}>
                {image ? (
                  <>
                    <img src={image} className="w-full h-full object-cover opacity-50" />
                    <button onClick={() => { setImage(null); setUploadError(null); }} className="absolute p-2 bg-red-500 text-white rounded-lg shadow-xl hover:scale-110 transition-transform">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </>
                ) : (
                  <>
                    <Upload className={`w-8 h-8 mb-2 group-hover:text-blue-500 transition-colors ${uploadError ? 'text-red-400' : 'text-slate-300'}`} />
                    <span className={`text-[10px] font-black uppercase tracking-widest ${uploadError ? 'text-red-500' : 'text-slate-400'}`}>
                      Bild hochladen
                    </span>
                    <input type="file" accept="image/png, image/jpeg, image/jpg" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                  </>
                )}
              </div>
            </div>

            {loading && (
              <div className="space-y-3 animate-in fade-in slide-in-from-top-2 duration-300">
                <div className="flex justify-between items-end">
                  <span className="text-xs font-black uppercase tracking-widest text-blue-500">{statusText}</span>
                  <span className="text-xs font-black text-slate-400">{Math.round(progress)}%</span>
                </div>
                <div className="h-3 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden border border-black/5 dark:border-white/5">
                  <div 
                    className="h-full bg-blue-600 transition-all duration-500 ease-out shadow-[0_0_20px_rgba(37,99,235,0.4)]"
                    style={{ width: `${progress}%` }}
                  ></div>
                </div>
              </div>
            )}

            <button 
              onClick={handleGenerate}
              disabled={loading || !prompt.trim() || !!uploadError}
              className={`w-full py-5 rounded-2xl font-black text-lg flex items-center justify-center gap-3 shadow-xl transition-all active:scale-95 disabled:opacity-50 ${
                isLowCredits ? 'bg-amber-600 hover:bg-amber-700 shadow-amber-600/20' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-600/20'
              } text-white`}
            >
              {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Wand2 className="w-6 h-6" />}
              Thumbnail generieren
            </button>
          </div>
        </div>
      </div>

      <div className="flex flex-col justify-center">
        {result ? (
          <div className="space-y-6 animate-in zoom-in-95 duration-500">
            <div className="aspect-video rounded-[2.5rem] overflow-hidden shadow-2xl border-4 border-white dark:border-slate-800 relative">
              <img src={result} className="w-full h-full object-cover" alt="Generiertes Thumbnail" />
              {isStarter && (
                <div className="absolute bottom-4 right-4 bg-black/50 backdrop-blur-md px-4 py-2 rounded-xl border border-white/20 text-white/50 text-[10px] font-black uppercase tracking-widest pointer-events-none select-none">
                  Made with Thumbify AI
                </div>
              )}
            </div>
            <div className="flex gap-4">
              <button 
                onClick={() => {
                  const link = document.createElement('a');
                  link.href = result;
                  link.download = 'thumbnail.png';
                  link.click();
                }}
                className="flex-1 py-4 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-black flex items-center justify-center gap-2"
              >
                <Download className="w-5 h-5" /> In 4K speichern
              </button>
              <button onClick={() => setResult(null)} className="px-6 py-4 bg-slate-100 dark:bg-slate-800 rounded-xl font-black text-slate-500">Neu</button>
            </div>
          </div>
        ) : (
          <div className="aspect-video rounded-[3rem] bg-slate-100 dark:bg-slate-900/50 border-2 border-dashed border-black/5 dark:border-white/5 flex flex-col items-center justify-center text-center p-12">
