        <div className="space-y-8">

          {/* Starter Plan Info */}
          {isStarter && (
            <div className="p-6 bg-indigo-600/5 border border-indigo-600/20 rounded-[2rem] flex items-center justify-between gap-6 animate-in slide-in-from-top-4 duration-500">
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 bg-indigo-600/10 rounded-full flex items-center justify-center shrink-0">
                  <Lock className="w-5 h-5 text-indigo-600" />
                </div>
                <div>
                  <h4 className="text-sm font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest mb-1 leading-none">Starter Plan</h4>
                  <p className="text-[10px] text-indigo-500 font-bold opacity-80 uppercase tracking-wider">Ergebnisse enthalten ein Wasserzeichen</p>
                </div>
              </div>
            </div>
          )}

          <div className="p-10 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-2xl font-black flex items-center gap-3">
                <Copy className="w-7 h-7 text-indigo-500" />
