              </div>
            </div>

            <div className="space-y-8">
              {/* Reference Upload */}
              <div>
                <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-3">Referenz-Thumbnail</label>
                <div className={`relative h-56 border-2 border-dashed rounded-[2rem] flex flex-col items-center justify-center group overflow-hidden transition-all ${
                  sourceImage ? 'border-indigo-500/50' : 'border-black/10 dark:border-white/10 hover:border-indigo-500/30'
                }`}>
                  {sourceImage ? (
                    <>
                      <img src={sourceImage} className="w-full h-full object-cover opacity-60" />
                      <div className="absolute inset-0 flex items-center justify-center gap-3">
                         <button onClick={() => setSourceImage(null)} className="p-3 bg-red-500 text-white rounded-2xl shadow-xl hover:scale-110 transition-transform">
                           <Trash2 className="w-5 h-5" />
                         </button>
                         <div className="px-4 py-2 bg-indigo-600 text-white text-[10px] font-black uppercase rounded-xl">Stil geladen</div>
                      </div>
                    </>
                  ) : (
                    <>
                      <div className="w-16 h-16 bg-slate-100 dark:bg-slate-800 rounded-3xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                        <Upload className="w-8 h-8 text-slate-400 group-hover:text-indigo-500" />
