        <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-6">
          {(Object.keys(WORKFLOW_DATA) as ToolMode[]).map((mode) => {
            const data = WORKFLOW_DATA[mode];
            const colorClass = data.color === 'blue' ? 'text-blue-600' : data.color === 'purple' ? 'text-purple-600' : data.color === 'indigo' ? 'text-indigo-600' : 'text-emerald-600';
            const bgClass = data.color === 'blue' ? 'bg-blue-600' : data.color === 'purple' ? 'bg-purple-600' : data.color === 'indigo' ? 'bg-indigo-600' : 'bg-emerald-600';
            const lightBgClass = data.color === 'blue' ? 'bg-blue-50 dark:bg-blue-900/20' : data.color === 'purple' ? 'bg-purple-50 dark:bg-purple-900/20' : data.color === 'indigo' ? 'bg-indigo-50 dark:bg-indigo-900/20' : 'bg-emerald-50 dark:bg-emerald-900/20';

            return (
              <div key={mode} className="group relative bg-white dark:bg-slate-900/40 rounded-[3rem] border border-black/5 dark:border-white/5 p-8 shadow-sm hover:shadow-2xl transition-all duration-500 hover:-translate-y-2 flex flex-col h-full">

                {/* Header */}
                <div className="flex justify-between items-start mb-10">
                  <div className={`p-5 rounded-2xl ${lightBgClass} ${colorClass}`}>
                    {data.icon}
                  </div>
                  <span className={`text-[10px] font-black uppercase tracking-widest px-3 py-1.5 rounded-full ${lightBgClass} ${colorClass} border border-black/5`}>
                    {data.tag}
                  </span>
                </div>

                <h4 className="text-xl font-black text-slate-900 dark:text-white mb-4 tracking-tight">
                  {data.title}
                </h4>

                {/* Steps Timeline */}
                <div className="space-y-6 mb-10 flex-1">
                  {data.steps.map((step, idx) => (
                    <div key={idx} className="flex gap-4 relative group/step">
                      {idx < 2 && (
                        <div className="absolute left-3.5 top-8 w-0.5 h-6 bg-slate-100 dark:bg-slate-800" />
                      )}
                      <div className={`w-7 h-7 rounded-full ${lightBgClass} ${colorClass} flex items-center justify-center shrink-0 border border-black/5`}>
                        {step.icon}
                      </div>
                      <div>
                        <h5 className="text-[11px] font-black text-slate-800 dark:text-slate-200 uppercase tracking-wide leading-none mb-1">
                          {idx + 1}. {step.title}
                        </h5>
                        <p className="text-[10px] text-slate-500 dark:text-slate-400 font-medium leading-relaxed">
                          {step.description}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>

                {/* CTA */}
                <button 
                  onClick={() => onStartTool && onStartTool(mode)}
                  className={`w-full py-3.5 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all active:scale-95 ${bgClass} text-white shadow-xl shadow-current/10`}
                >
                  Tool öffnen
                  <ChevronRight className="w-3.5 h-3.5" />
                </button>
              </div>
            );
          })}
        </div>
      </div>

      {/* Background Decor */}
      <div className="absolute top-1/2 left-0 w-96 h-96 bg-blue-500/5 blur-[120px] rounded-full -translate-y-1/2 -translate-x-1/2 pointer-events-none" />
      <div className="absolute bottom-1/2 right-0 w-96 h-96 bg-purple-500/5 blur-[120px] rounded-full translate-y-1/2 translate-x-1/2 pointer-events-none" />
    </section>
