                  <div className={`p-2 rounded-xl flex items-center gap-1.5 text-[10px] font-black uppercase ${!hasCredits && hasPlan ? 'bg-red-500/10 text-red-500' : 'bg-amber-500/10 text-amber-600 dark:text-amber-400'}`}>
