                      {mode.icon}
                    </div>
                  </div>

                  <h3 className="text-xl font-black mb-3">
                    {mode.title}
                  </h3>

                  <p className="text-sm text-slate-500 dark:text-slate-400 font-medium leading-relaxed mb-6">
