              <h4 className="text-sm font-black uppercase tracking-wider mb-1">Kauf erfolgreich!</h4>
              <p className="text-xs font-medium opacity-90">Dein Plan <span className="font-black">{purchaseSuccess.planName}</span> wurde aktiviert. <span className="font-black">+{purchaseSuccess.amount} Credits</span> hinzugefügt.</p>
            </div>
            <button onClick={() => setPurchaseSuccess(null)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>
      )}

      {/* Credit Warning Toast */}
      {showLowCreditToast && user && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[100] w-full max-w-md px-4 animate-in slide-in-from-bottom-8 duration-500">
