      {currentView === 'home' && (
        <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden">
          <div 
            className={`absolute inset-0 bg-cover bg-center bg-fixed transform scale-110 blur-[6px] opacity-[0.06] transition-all duration-500 ${isDarkMode ? 'brightness-[1.3] contrast-[1.2]' : 'brightness-[0.8]'}`}
