      }}
    />
  );
};

const ExtremeGlow = () => (
  <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden select-none">
    {/* Large Soft Teal/Green Orbs - High Visibility but Premium */}
    <div className="absolute top-[-15%] left-[-10%] w-[90%] h-[90%] bg-teal-500/35 dark:bg-teal-500/45 blur-[220px] rounded-full animate-mesh"></div>
    <div className="absolute bottom-[-15%] right-[-10%] w-[100%] h-[100%] bg-emerald-600/25 dark:bg-emerald-600/35 blur-[280px] rounded-full animate-mesh" style={{ animationDelay: '-8s' }}></div>

    {/* Strategic Neon Glows behind key areas */}
    <div className="absolute top-[20%] left-1/2 -translate-x-1/2 w-[70%] h-[40%] bg-teal-400/20 dark:bg-teal-400/30 blur-[200px] rounded-[100%] animate-pulse-glow"></div>

