        {currentView === 'studio' && (
          <div className="pt-32 pb-20">
            {studioView === 'selection' ? (
              <>
                <BackButton toHome={true} />
                <StudioSelection user={user} onSelectMode={handleSelectStudioMode} />
              </>
            ) : (
              <>
                <BackButton toHome={false} />
                <div className="px-4">
                  {studioView === 'generate' && <StudioGenerate useCredits={useCredits} user={user} onGoToPricing={() => handleNavigate('pricing')} />}
                  {studioView === 'remake' && <StudioRemake useCredits={useCredits} user={user} />}
                  {studioView === 'channel' && <StudioChannelAnalyze useCredits={useCredits} user={user} />}
                  {studioView === 'analyze' && <StudioAnalyze useCredits={useCredits} user={user} />}
                </div>
              </>
            )}
          </div>
        )}

        {currentView === 'pricing' && <div className="pt-20"><BackButton /><Pricing onPurchase={handlePurchase} /></div>}
        {currentView === 'reviews' && <div className="pt-20"><BackButton /><Reviews /></div>}
        {currentView === 'examples' && <div className="pt-20"><BackButton /><Examples onNavigateToStudio={() => handleNavigate('studio')} /></div>}
      </main>

      <AuthModal isOpen={isAuthOpen} onClose={() => setIsAuthOpen(false)} onLogin={handleLogin} />
    </div>
  );
}

