import React, { useState } from 'react';
import { X, Mail, Lock, AlertCircle, LogIn, UserPlus, Loader2, CheckCircle2, ChevronRight } from 'lucide-react';

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  onLogin: (email: string) => void;
}

type GoogleLoginStep = 'initial' | 'connecting' | 'select_account' | 'finalizing' | 'success';

export const AuthModal: React.FC<AuthModalProps> = ({ isOpen, onClose, onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Google Login Simulation States
  const [googleStep, setGoogleStep] = useState<GoogleLoginStep>('initial');

  const validateEmail = (email: string) => {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email.toLowerCase());
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (!validateEmail(email)) {
      setError('Bitte gib eine gültige E-Mail-Adresse ein.');
      return;
    }

    if (password.length < 6) {
      setError('Das Passwort muss mindestens 6 Zeichen lang sein.');
      return;
    }

    onLogin(email);
  };

  const handleGoogleSimulation = () => {
    setGoogleStep('connecting');

    // Simulate connection delay
    setTimeout(() => {
