                      </div>
                      <ChevronRight className="w-4 h-4 text-slate-300 group-hover:translate-x-1 transition-transform" />
                    </button>
                  ))}
                  <button 
                    onClick={() => selectAccount('new-user@gmail.com')}
                    className="w-full p-4 border border-dashed border-black/10 dark:border-white/10 rounded-2xl text-xs font-black text-slate-400 hover:text-teal-600 hover:border-teal-500/30 transition-all"
                  >
                    Anderes Konto verwenden
                  </button>
                </div>
              </div>
            )}

            {(googleStep === 'finalizing' || googleStep === 'success') && (
              <div className="text-center space-y-6">
                <div className="relative flex items-center justify-center">
                   {googleStep === 'success' && (
                     <div className="absolute inset-0 bg-teal-500/20 blur-3xl animate-pulse rounded-full"></div>
                   )}
                   <div className={`relative w-24 h-24 rounded-3xl flex items-center justify-center transition-all duration-500 ${googleStep === 'success' ? 'bg-teal-600 scale-110' : 'bg-white dark:bg-slate-800'}`}>
                     {googleStep === 'finalizing' ? (
                        <Loader2 className="w-10 h-10 text-teal-600 animate-spin" />
                     ) : (
                        <CheckCircle2 className="w-12 h-12 text-white animate-in zoom-in-50" />
                     )}
