import React, { useState, useEffect } from 'react';
import { User } from './types';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { HowItWorks } from './components/HowItWorks';
import { Pricing } from './components/Pricing';
import { Reviews } from './components/Reviews';
import { AuthModal } from './components/AuthModal';
import { Examples } from './components/Examples';
import { StudioSelection } from './components/StudioSelection';
import { StudioGenerate } from './components/StudioGenerate';
import { StudioChannelAnalyze } from './components/StudioChannelAnalyze';
import { StudioAnalyze } from './components/StudioAnalyze';
import { StudioRemake } from './components/StudioRemake';
import { Zap, ArrowLeft, Coins, AlertCircle, ShoppingCart, X, CheckCircle, Sun, Moon } from 'lucide-react';
import { BACKGROUND_IMAGE, PricingPlan } from './constants';

type MainView = 'home' | 'pricing' | 'reviews' | 'examples' | 'studio';
type StudioView = 'selection' | 'generate' | 'channel' | 'analyze' | 'remake';

const MouseGlow = () => {
  const [position, setPosition] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      setPosition({ x: e.clientX, y: e.clientY });
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return (
    <div 
      className="fixed inset-0 z-0 pointer-events-none transition-opacity duration-1000 opacity-90 dark:opacity-100"
      style={{
        background: `radial-gradient(1500px circle at ${position.x}px ${position.y}px, rgba(45, 212, 191, 0.22), rgba(16, 185, 129, 0.08) 45%, transparent 85%)`
      }}
    />
  );
};

const ExtremeGlow = () => (
  <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden select-none">
    <div className="absolute top-[-25%] left-[-15%] w-[110%] h-[110%] bg-teal-500/45 dark:bg-teal-500/55 blur-[250px] rounded-full animate-mesh opacity-80"></div>
    <div className="absolute bottom-[-25%] right-[-15%] w-[120%] h-[120%] bg-emerald-600/35 dark:bg-emerald-600/45 blur-[320px] rounded-full animate-mesh opacity-80" style={{ animationDelay: '-8s' }}></div>
    <div className="absolute top-[15%] left-1/2 -translate-x-1/2 w-[85%] h-[50%] bg-teal-400/25 dark:bg-teal-400/35 blur-[220px] rounded-[100%] animate-pulse-glow"></div>
    <div className="absolute top-[35%] right-[10%] w-[55%] h-[55%] bg-cyan-400/20 dark:bg-cyan-400/30 blur-[200px] rounded-full animate-pulse-glow" style={{ animationDelay: '4s' }}></div>
    <div className="absolute bottom-[20%] left-[10%] w-[50%] h-[50%] bg-emerald-300/15 dark:bg-emerald-300/25 blur-[180px] rounded-full animate-pulse-glow" style={{ animationDelay: '2s' }}></div>
    <div className="absolute inset-0 bg-gradient-to-b from-[#020617]/0 via-[#020617]/10 to-[#020617]/40 dark:via-transparent dark:to-slate-950/60"></div>
  </div>
);

function App() {
  const [user, setUser] = React.useState<User | null>(null);
  const [currentView, setCurrentView] = React.useState<MainView>('home');
  const [studioView, setStudioView] = React.useState<StudioView>('selection');
  const [isAuthOpen, setIsAuthOpen] = React.useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [showLowCreditToast, setShowLowCreditToast] = useState(false);
  const [purchaseSuccess, setPurchaseSuccess] = useState<{ planName: string, amount: number } | null>(null);

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'light') setIsDarkMode(false);
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const handleLogin = (email: string) => {
    setUser({ 
      id: '1', 
      email: email, 
      name: email.split('@')[0], 
      credits: 30, 
      isLoggedIn: true,
      plan: 'Starter'
    });
    setIsAuthOpen(false);
    handleNavigate('studio');
  };

  const useCredits = (amount: number): boolean => {
    if (!user || user.credits < amount) {
      alert(`Unzureichende Credits! Du benötigst ${amount} Credits für diese Aktion.`);
      setCurrentView('pricing');
      return false;
    }
    const newBalance = user.credits - amount;
    setUser({ ...user, credits: newBalance });

    if (newBalance < 10) {
      setShowLowCreditToast(true);
    }
    return true;
  };

  const handlePurchase = (plan: PricingPlan) => {
    if (!user) {
      setIsAuthOpen(true);
      return;
    }

    const newCredits = user.credits + plan.credits;
    setUser({ ...user, credits: newCredits, plan: plan.name as any });
    setPurchaseSuccess({ planName: plan.name, amount: plan.credits });
    setShowLowCreditToast(false);

    setTimeout(() => setPurchaseSuccess(null), 5000);

    setCurrentView('studio');
    setStudioView('selection');
  };

  const handleNavigate = (view: MainView) => {
    if (view === 'studio' && !user) {
      setIsAuthOpen(true);
      return;
    }
    setCurrentView(view);
    if (view === 'studio') setStudioView('selection');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const checkPlanPermission = (mode: StudioView): boolean => {
    if (!user) return false;
    const plan = user.plan || 'Starter';

    if (mode === 'generate' || mode === 'remake') return true;
    if (mode === 'analyze' || mode === 'channel') {
      return plan === 'Creator Pro' || plan === 'Production';
    }
    return true;
  };

  const getToolCost = (mode: StudioView): number => {
    switch(mode) {
      case 'generate': return 10;
      case 'remake': return 20;
      case 'channel': return 100;
      case 'analyze': return 50;
      default: return 0;
    }
  };

  const handleSelectStudioMode = (mode: StudioView) => {
    if (!user) {
      setIsAuthOpen(true);
      return;
    }

    if (!checkPlanPermission(mode)) {
      alert("Dieses Tool ist in deinem aktuellen Plan nicht enthalten.");
      handleNavigate('pricing');
      return;
    }

    const cost = getToolCost(mode);
    if (user.credits < cost) {
      alert(`Du hast nicht genug Credits (${cost} benötigt). Bitte lade dein Konto auf.`);
      handleNavigate('pricing');
      return;
    }

    setStudioView(mode);
  };

  const BackButton = ({ toHome = true }) => (
    <button 
      onClick={() => toHome ? handleNavigate('home') : setStudioView('selection')}
      className="fixed top-24 left-4 lg:left-8 z-40 flex items-center gap-2 px-5 py-2.5 bg-white/80 dark:bg-slate-800/80 hover:bg-white dark:hover:bg-slate-800 border border-black/5 dark:border-white/10 rounded-full text-xs font-black uppercase tracking-widest transition-all group shadow-xl backdrop-blur-md text-slate-900 dark:text-slate-100"
    >
      <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
      {toHome ? 'Zurück' : 'Studio Übersicht'}
    </button>
  );

  return (
    <div className={`min-h-screen transition-colors duration-500 selection:bg-teal-500 selection:text-white ${isDarkMode ? 'bg-[#020617] text-slate-100' : 'bg-slate-50 text-slate-900'} relative`}>

      {currentView === 'home' && (
        <>
          <ExtremeGlow />
          <MouseGlow />
          <div className="mesh-gradient opacity-90"></div>
        </>
      )}

      {/* Theme Toggle Button - Modern "Small Sun" Switch */}
      <div className="fixed top-4 right-4 z-[70] flex items-center gap-3">
        <button
          onClick={toggleTheme}
          className="relative p-2.5 rounded-2xl bg-white/80 dark:bg-slate-800/80 border border-black/5 dark:border-white/10 shadow-xl backdrop-blur-xl transition-all active:scale-90 group overflow-hidden"
          title={isDarkMode ? "Hellmodus aktivieren" : "Dunkelmodus aktivieren"}
        >
          <div className="relative w-5 h-5">
            <Sun className={`w-5 h-5 text-amber-500 absolute inset-0 transition-all duration-500 transform ${isDarkMode ? 'rotate-90 scale-0 opacity-0' : 'rotate-0 scale-100 opacity-100'}`} />
            <Moon className={`w-5 h-5 text-teal-400 absolute inset-0 transition-all duration-500 transform ${isDarkMode ? 'rotate-0 scale-100 opacity-100' : '-rotate-90 scale-0 opacity-0'}`} />
          </div>
          {/* Inner Glow */}
          <div className={`absolute inset-0 rounded-2xl transition-opacity duration-500 blur-md -z-10 ${isDarkMode ? 'bg-teal-400/10 opacity-100' : 'bg-amber-400/10 opacity-0 group-hover:opacity-100'}`} />
        </button>
      </div>

      {/* Purchase Success Toast */}
      {purchaseSuccess && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[110] w-full max-w-md px-4 animate-in slide-in-from-bottom-8 duration-500">
          <div className="bg-emerald-600 text-white rounded-3xl p-6 shadow-2xl flex items-center gap-6">
            <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center shrink-0">
              <CheckCircle className="w-6 h-6" />
            </div>
            <div className="flex-1 min-w-0">
              <h4 className="text-sm font-black uppercase tracking-wider mb-1">Kauf erfolgreich!</h4>
              <p className="text-xs font-medium opacity-90">Dein Plan <span className="font-black">{purchaseSuccess.planName}</span> wurde aktiviert. <span className="font-black">+{purchaseSuccess.amount} Credits</span> hinzugefügt.</p>
            </div>
            <button onClick={() => setPurchaseSuccess(null)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>
      )}

      {/* Credit Warning Toast */}
      {showLowCreditToast && user && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[100] w-full max-w-md px-4 animate-in slide-in-from-bottom-8 duration-500">
          <div className="bg-white dark:bg-slate-900 border-2 border-amber-500 rounded-3xl p-6 shadow-[0_20px_50px_rgba(245,158,11,0.3)] flex items-center gap-6">
            <div className="w-12 h-12 bg-amber-500/10 rounded-2xl flex items-center justify-center shrink-0">
              <AlertCircle className="w-6 h-6 text-amber-500" />
            </div>
            <div className="flex-1 min-w-0">
              <h4 className="text-sm font-black text-slate-900 dark:text-white uppercase tracking-wider mb-1">Guthaben fast leer!</h4>
              <p className="text-xs font-medium text-slate-500 dark:text-slate-400">Du hast nur noch <span className="text-amber-500 font-black">{user.credits} Credits</span>. Jetzt aufladen?</p>
            </div>
            <div className="flex flex-col gap-2">
              <button 
                onClick={() => { setShowLowCreditToast(false); handleNavigate('pricing'); }}
                className="px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white text-[10px] font-black uppercase rounded-xl flex items-center gap-2 shadow-lg shadow-teal-600/20 active:scale-95 transition-all"
              >
                <ShoppingCart className="w-3 h-3" /> Aufladen
              </button>
              <button onClick={() => setShowLowCreditToast(false)} className="text-[9px] font-black uppercase text-slate-400 hover:text-slate-600 text-center">Später</button>
            </div>
          </div>
        </div>
      )}

      {currentView === 'home' && (
        <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden">
          <div 
            className={`absolute inset-0 bg-cover bg-center bg-fixed transform scale-110 blur-[12px] opacity-[0.15] transition-all duration-500 ${isDarkMode ? 'brightness-[1.8] contrast-[1.5]' : 'brightness-[0.9]'}`}
            style={{ backgroundImage: `url(${BACKGROUND_IMAGE})` }}
          />
          <div className={`absolute inset-0 transition-colors duration-500 ${isDarkMode ? 'bg-gradient-to-br from-[#020617] via-[#020617]/90 to-teal-900/25' : 'bg-gradient-to-br from-teal-50/80 via-white/50 to-teal-100/60'}`} />
        </div>
      )}

      <Navbar 
        user={user} 
        onNavigate={handleNavigate} 
        onLoginClick={() => setIsAuthOpen(true)} 
      />

      <main className="relative z-10">
        {currentView === 'home' && (
          <div className="animate-in fade-in duration-700">
            <Hero onStartCreating={() => handleNavigate('studio')} onViewPricing={() => handleNavigate('pricing')} />
            <HowItWorks onStartTool={(tool) => {
              handleNavigate('studio');
              handleSelectStudioMode(tool as StudioView);
            }} />
            <Reviews />
            <Pricing onPurchase={handlePurchase} />
          </div>
        )}

        {currentView === 'studio' && (
          <div className="pt-32 pb-20">
            {studioView === 'selection' ? (
              <>
                <BackButton toHome={true} />
                <StudioSelection user={user} onSelectMode={handleSelectStudioMode} />
              </>
            ) : (
              <>
                <BackButton toHome={false} />
                <div className="px-4">
                  {studioView === 'generate' && <StudioGenerate useCredits={useCredits} user={user} onGoToPricing={() => handleNavigate('pricing')} />}
                  {studioView === 'remake' && <StudioRemake useCredits={useCredits} user={user} />}
                  {studioView === 'channel' && <StudioChannelAnalyze useCredits={useCredits} user={user} />}
                  {studioView === 'analyze' && <StudioAnalyze useCredits={useCredits} user={user} />}
                </div>
              </>
            )}
          </div>
        )}

        {currentView === 'pricing' && <div className="pt-20"><BackButton /><Pricing onPurchase={handlePurchase} /></div>}
        {currentView === 'reviews' && <div className="pt-20"><BackButton /><Reviews /></div>}
        {currentView === 'examples' && <div className="pt-20"><BackButton /><Examples onNavigateToStudio={() => handleNavigate('studio')} /></div>}
      </main>

      <AuthModal isOpen={isAuthOpen} onClose={() => setIsAuthOpen(false)} onLogin={handleLogin} />
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { X, Mail, Lock, AlertCircle, LogIn, UserPlus, Loader2, CheckCircle2, ChevronRight, Info, ShieldCheck } from 'lucide-react';

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  onLogin: (email: string) => void;
}

type GoogleLoginStep = 'initial' | 'connecting' | 'select_account' | 'permissions' | 'finalizing' | 'success';

export const AuthModal: React.FC<AuthModalProps> = ({ isOpen, onClose, onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Google Login Simulation States
  const [googleStep, setGoogleStep] = useState<GoogleLoginStep>('initial');
  const [selectedGoogleAccount, setSelectedGoogleAccount] = useState<any>(null);

  const validateEmail = (email: string) => {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email.toLowerCase());
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (!validateEmail(email)) {
      setError('Bitte gib eine gültige E-Mail-Adresse ein.');
      return;
    }

    if (password.length < 6) {
      setError('Das Passwort muss mindestens 6 Zeichen lang sein.');
      return;
    }

    onLogin(email);
  };

  const handleGoogleSimulation = () => {
    setGoogleStep('connecting');
    setTimeout(() => {
      setGoogleStep('select_account');
    }, 1000);
  };

  const handleAccountSelect = (account: any) => {
    setSelectedGoogleAccount(account);
    setGoogleStep('permissions');
  };

  const grantPermissions = () => {
    setGoogleStep('finalizing');
    setTimeout(() => {
      setGoogleStep('success');
      setTimeout(() => {
        onLogin(selectedGoogleAccount.email);
        setGoogleStep('initial');
      }, 1200);
    }, 1500);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div 
        className="absolute inset-0 bg-slate-950/80 backdrop-blur-md animate-in fade-in duration-300" 
        onClick={onClose}
      ></div>

      <div className="relative w-full max-w-md bg-white dark:bg-slate-900 border border-black/5 dark:border-white/10 rounded-[2.5rem] p-10 shadow-2xl animate-in zoom-in-95 duration-200 overflow-hidden">
        <button 
          onClick={onClose} 
          className="absolute top-6 right-6 text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors z-10"
        >
          <X className="w-6 h-6" />
        </button>

        {googleStep === 'initial' ? (
          <div className="animate-in fade-in slide-in-from-bottom-2">
            <div className="text-center mb-8">
              <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-teal-600/10 text-teal-600 mb-6 border border-teal-600/20">
                {isLogin ? <LogIn className="w-8 h-8" /> : <UserPlus className="w-8 h-8" />}
              </div>
              <h2 className="text-3xl font-black mb-2 text-slate-900 dark:text-white tracking-tight">
                {isLogin ? 'Willkommen zurück' : 'Konto erstellen'}
              </h2>
              <p className="text-slate-500 dark:text-slate-400 font-medium">
                Melde dich bei **ThumbCraft AI** an.
              </p>
            </div>

            {/* Google Login Button */}
            <button 
              onClick={handleGoogleSimulation}
              className="w-full flex items-center justify-center gap-3 py-4 px-4 bg-white dark:bg-white/5 border border-black/10 dark:border-white/10 text-slate-900 dark:text-white rounded-2xl font-bold mb-6 hover:bg-slate-50 dark:hover:bg-white/10 transition-all active:scale-[0.98] shadow-sm"
            >
              <svg className="w-5 h-5" viewBox="0 0 24 24">
                <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
                <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
                <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z"/>
                <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
              </svg>
              Weiter mit Google
            </button>

            <div className="relative mb-6">
              <div className="absolute inset-0 flex items-center">
                <div className="w-full border-t border-black/5 dark:border-white/5"></div>
              </div>
              <div className="relative flex justify-center text-[10px] font-black uppercase tracking-widest">
                <span className="px-3 bg-white dark:bg-slate-900 text-slate-400">E-Mail & Passwort</span>
              </div>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="relative">
                <Mail className={`absolute left-4 top-4 w-5 h-5 ${error && !validateEmail(email) ? 'text-red-500' : 'text-slate-400'}`} />
                <input 
                  type="text" 
                  placeholder="E-Mail Adresse" 
                  value={email}
                  onChange={(e) => {
                    setEmail(e.target.value);
                    if (error) setError(null);
                  }}
                  className={`w-full bg-slate-50 dark:bg-slate-800/50 border rounded-2xl py-4 pl-12 pr-4 text-slate-900 dark:text-white focus:outline-none transition-all ${
                    error && !validateEmail(email) ? 'border-red-500 ring-2 ring-red-500/20' : 'border-black/5 dark:border-white/10 focus:ring-2 focus:ring-teal-500'
                  }`}
                />
              </div>

              <div className="relative">
                <Lock className={`absolute left-4 top-4 w-5 h-5 ${error && password.length < 6 ? 'text-red-500' : 'text-slate-400'}`} />
                <input 
                  type="password" 
                  placeholder="Passwort" 
                  value={password}
                  onChange={(e) => {
                    setPassword(e.target.value);
                    if (error) setError(null);
                  }}
                  className={`w-full bg-slate-50 dark:bg-slate-800/50 border rounded-2xl py-4 pl-12 pr-4 text-slate-900 dark:text-white focus:outline-none transition-all ${
                    error && password.length < 6 ? 'border-red-500 ring-2 ring-red-500/20' : 'border-black/5 dark:border-white/10 focus:ring-2 focus:ring-teal-500'
                  }`}
                />
              </div>

              {error && (
                <div className="flex items-center gap-1.5 text-red-500 text-xs font-bold animate-in fade-in slide-in-from-top-1 duration-200 mb-4">
                  <AlertCircle className="w-3.5 h-3.5" />
                  {error}
                </div>
              )}

