          <div className={`absolute inset-0 transition-colors duration-500 ${isDarkMode ? 'bg-gradient-to-br from-[#020617] via-[#020617]/90 to-teal-900/25' : 'bg-gradient-to-br from-teal-50/80 via-white/50 to-teal-100/60'}`} />
