            const isLocked = !hasPlan;

            return (
              <button
                key={mode.id}
                onClick={() => onSelectMode(mode.id)}
                className={`group relative flex flex-col p-8 bg-white dark:bg-slate-900 border border-black/5 dark:border-white/5 rounded-[2.5rem] text-left transition-all hover:-translate-y-2 active:scale-[0.98] overflow-hidden h-full ${
                  isLocked ? 'grayscale opacity-70' : ''
                }`}
              >
                <div className="absolute top-4 right-4 z-20 flex flex-col items-end gap-2">
                  {!hasPlan && (
                    <div className="p-2 bg-slate-900 text-white rounded-xl flex items-center gap-1.5 text-[10px] font-black uppercase">
                      <Lock className="w-3 h-3" /> Upgrade
                    </div>
                  )}
                  <div className={`p-2 rounded-xl flex items-center gap-1.5 text-[10px] font-black uppercase ${!hasCredits && hasPlan ? 'bg-red-500/10 text-red-500' : 'bg-amber-500/10 text-amber-600 dark:text-amber-400'}`}>
                    <Coins className="w-3 h-3" /> {mode.cost}
                  </div>
                </div>

                <div className="relative z-10 flex flex-col h-full">
                  <div className={`w-14 h-14 rounded-2xl ${mode.lightColor} ${mode.textColor} flex items-center justify-center mb-6`}>
                    {mode.icon}
                  </div>

                  <h3 className="text-xl font-black mb-3">
                    {mode.title}
                  </h3>

                  <p className="text-sm text-slate-500 dark:text-slate-400 font-medium leading-relaxed mb-8">
                    {mode.description}
                  </p>

                  <div className="mt-auto flex items-center gap-2 font-black text-[10px] uppercase group-hover:text-blue-600 transition-colors">
                    {isLocked ? 'Upgrade nötig' : 'Tool starten'}
                    <ChevronRight className="w-3 h-3 group-hover:translate-x-1 transition-transform" />
                  </div>
                </div>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Copy, Upload, Sparkles, Loader2, Download, Trash2, ArrowRight, Coins, Lightbulb, AlertCircle, Image as ImageIcon, Lock, Wand2 } from 'lucide-react';
import { remakeThumbnail } from '../services/geminiService';
import { User } from '../types';

interface StudioRemakeProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
  isCloneMode?: boolean;
}

export const StudioRemake: React.FC<StudioRemakeProps> = ({ useCredits, user, isCloneMode = false }) => {
  const [sourceImage, setSourceImage] = useState<string | null>(null);
  const [adjustment, setAdjustment] = useState('');
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [result, setResult] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const isStarter = user?.plan === 'Starter';
  const toolCost = isCloneMode ? 30 : 20;

  useEffect(() => {
    let interval: any;
    if (loading) {
      setProgress(0);
      const steps = [
        { threshold: 25, text: isCloneMode ? "Stil-Fingerabdruck wird erstellt..." : "Stil-Elemente werden extrahiert..." },
        { threshold: 50, text: isCloneMode ? "Prompt wird an Stil angepasst..." : "Komposition wird gematcht..." },
        { threshold: 80, text: "Anpassungen werden gerendert..." },
        { threshold: 95, text: "Finalisierung..." }
      ];

      interval = setInterval(() => {
        setProgress(prev => {
          const next = prev + Math.random() * 6;
          const currentStep = steps.find(s => next <= s.threshold) || steps[steps.length - 1];
          setStatusText(currentStep.text);
          return next >= 98 ? 98 : next;
        });
      }, 500);
    } else {
      setProgress(0);
      setStatusText('');
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, isCloneMode]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setError(null);
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError("Bitte lade nur Bilddateien hoch.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => setSourceImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleRemake = async () => {
    if (!sourceImage) {
      setError("Bitte lade zuerst ein Referenzbild hoch.");
      return;
    }

    if (!user || user.credits < toolCost) {
      alert(`Du benötigst ${toolCost} Credits für dieses Tool.`);
      return;
    }

    setLoading(true);
    setResult(null);
    try {
      const res = await remakeThumbnail(sourceImage, adjustment);
      useCredits(toolCost);
      setResult(res);
      setProgress(100);
    } catch (err) {
      setError("Der Vorgang ist fehlgeschlagen. Bitte versuche es erneut.");
    } finally {
      setTimeout(() => setLoading(false), 500);
    }
  };

  return (
    <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="grid lg:grid-cols-2 gap-12">
        <div className="space-y-8">

          {/* Starter Plan Info */}
          {isStarter && (
            <div className={`p-6 border rounded-[2rem] flex items-center justify-between gap-6 animate-in slide-in-from-top-4 duration-500 ${isCloneMode ? 'bg-teal-600/5 border-teal-600/20' : 'bg-indigo-600/5 border-indigo-600/20'}`}>
              <div className="flex items-center gap-4">
                <div className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 ${isCloneMode ? 'bg-teal-600/10 text-teal-600' : 'bg-indigo-600/10 text-indigo-600'}`}>
                  <Lock className="w-5 h-5" />
                </div>
                <div>
                  <h4 className={`text-sm font-black uppercase tracking-widest mb-1 leading-none ${isCloneMode ? 'text-teal-600' : 'text-indigo-600'}`}>Starter Plan</h4>
                  <p className={`text-[10px] font-bold opacity-80 uppercase tracking-wider ${isCloneMode ? 'text-teal-500' : 'text-indigo-500'}`}>Ergebnisse enthalten ein Wasserzeichen</p>
                </div>
              </div>
            </div>
          )}

          <div className="p-10 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-2xl font-black flex items-center gap-3">
                {isCloneMode ? (
                    <Sparkles className="w-7 h-7 text-teal-500" />
                ) : (
                    <Copy className="w-7 h-7 text-indigo-500" />
                )}
                {isCloneMode ? 'Clone Style' : 'Thumbnail Remake'}
              </h2>
              <div className="flex items-center gap-1.5 text-[10px] font-black uppercase text-amber-500 tracking-widest bg-amber-500/10 px-3 py-1 rounded-full">
                <Coins className="w-3.5 h-3.5" />
                {toolCost} Credits
              </div>
            </div>

            <div className="space-y-8">
              {/* Reference Upload */}
              <div>
                <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-3">Referenz-Thumbnail</label>
                <div className={`relative h-56 border-2 border-dashed rounded-[2rem] flex flex-col items-center justify-center group overflow-hidden transition-all ${
                  sourceImage 
                    ? (isCloneMode ? 'border-teal-500/50' : 'border-indigo-500/50') 
                    : 'border-black/10 dark:border-white/10 hover:border-indigo-500/30'
                }`}>
                  {sourceImage ? (
                    <>
                      <img src={sourceImage} className="w-full h-full object-cover opacity-60" />
                      <div className="absolute inset-0 flex items-center justify-center gap-3">
                         <button onClick={() => setSourceImage(null)} className="p-3 bg-red-500 text-white rounded-2xl shadow-xl hover:scale-110 transition-transform">
                           <Trash2 className="w-5 h-5" />
                         </button>
                         <div className={`px-4 py-2 text-white text-[10px] font-black uppercase rounded-xl ${isCloneMode ? 'bg-teal-600' : 'bg-indigo-600'}`}>Stil geladen</div>
                      </div>
                    </>
                  ) : (
                    <>
                      <div className="w-16 h-16 bg-slate-100 dark:bg-slate-800 rounded-3xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                        <Upload className={`w-8 h-8 text-slate-400 ${isCloneMode ? 'group-hover:text-teal-500' : 'group-hover:text-indigo-500'}`} />
                      </div>
                      <span className="text-xs font-black uppercase tracking-widest text-slate-400">Bild hier ablegen</span>
                      <input type="file" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                    </>
                  )}
                </div>
              </div>

              {/* Adjustment Prompt */}
              <div>
                <div className="flex items-center justify-between mb-3">
                  <label className="text-xs font-black uppercase tracking-widest text-slate-500">
                      {isCloneMode ? 'Neues Motiv beschreiben' : 'Was soll geändert werden?'}
                  </label>
                  <div className={`flex items-center gap-1.5 text-[10px] font-bold px-2 py-1 rounded-md ${isCloneMode ? 'text-teal-500 bg-teal-500/5' : 'text-indigo-500 bg-indigo-500/5'}`}>
                    <Sparkles className="w-3 h-3" /> Smart Adjustment
                  </div>
                </div>
                <textarea 
                  value={adjustment}
                  onChange={(e) => setAdjustment(e.target.value)}
                  placeholder={isCloneMode ? "z.B. Ein glücklicher Kater, der Pizza isst (im Stil des Referenzbildes)" : "z.B. 'Ändere das Gesicht zu einem lachenden Gamer'..."}
                  className={`w-full h-32 bg-slate-50 dark:bg-slate-800/50 border border-black/5 dark:border-white/5 rounded-2xl p-4 focus:ring-4 outline-none transition-all resize-none font-medium ${isCloneMode ? 'focus:ring-teal-500/10' : 'focus:ring-indigo-500/10'}`}
                />
              </div>

              {error && (
                <div className="flex items-center gap-2 p-4 bg-red-500/10 text-red-500 rounded-2xl text-sm font-bold">
                   <AlertCircle className="w-5 h-5" />
                   {error}
                </div>
              )}

              {loading && (
                <div className="space-y-3 animate-in fade-in slide-in-from-top-2">
                  <div className="flex justify-between items-end">
                    <span className={`text-xs font-black uppercase tracking-widest ${isCloneMode ? 'text-teal-500' : 'text-indigo-500'}`}>{statusText}</span>
                    <span className="text-xs font-black text-slate-400">{Math.round(progress)}%</span>
                  </div>
                  <div className="h-3 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden p-0.5 border border-black/5">
                    <div 
                      className={`h-full rounded-full transition-all duration-500 ease-out shadow-lg ${isCloneMode ? 'bg-gradient-to-r from-teal-600 to-cyan-600 shadow-teal-600/40' : 'bg-gradient-to-r from-indigo-600 to-blue-600 shadow-indigo-600/40'}`}
                      style={{ width: `${progress}%` }}
                    ></div>
                  </div>
                </div>
              )}

              <button 
                onClick={handleRemake}
                disabled={loading || !sourceImage}
                className={`w-full py-5 rounded-2xl font-black text-lg flex items-center justify-center gap-3 shadow-xl transition-all active:scale-95 disabled:opacity-50 text-white ${
                    isCloneMode ? 'bg-teal-600 hover:bg-teal-700 shadow-teal-600/20' : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-600/20'
                }`}
              >
                {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : (isCloneMode ? <Wand2 className="w-6 h-6" /> : <Sparkles className="w-6 h-6" />)}
                {isCloneMode ? 'Style klonen' : 'Remake starten'}
              </button>
            </div>
          </div>
        </div>

        <div className="flex flex-col justify-center">
          {result ? (
            <div className="space-y-6 animate-in zoom-in-95 duration-500">
              <div className="aspect-video rounded-[3rem] overflow-hidden shadow-2xl border-4 border-white dark:border-slate-800 group relative">
                <img src={result} className="w-full h-full object-cover" alt="Ergebnis" />
                <div className={`absolute top-4 left-4 px-4 py-2 text-white text-[10px] font-black uppercase rounded-xl shadow-lg ${isCloneMode ? 'bg-teal-600' : 'bg-indigo-600'}`}>
                    {isCloneMode ? 'Style Match' : 'New Remake'}
                </div>
                {isStarter && (
                  <div className="absolute bottom-4 right-4 bg-black/50 backdrop-blur-md px-4 py-2 rounded-xl border border-white/20 text-white/50 text-[10px] font-black uppercase tracking-widest pointer-events-none select-none">
                    Made with Thumbify AI
                  </div>
                )}
              </div>
              <div className="flex gap-4">
                <button 
                  onClick={() => {
                    const link = document.createElement('a');
                    link.href = result;
                    link.download = 'thumbcraft-result.png';
                    link.click();
                  }}
                  className="flex-1 py-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl font-black flex items-center justify-center gap-3 shadow-xl transition-all active:scale-95"
                >
                  <Download className="w-6 h-6" /> 4K Download
                </button>
                <button 
                  onClick={() => setResult(null)}
                  className="px-8 py-5 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-2xl font-black hover:bg-slate-200 transition-all"
                >
                  Neu
                </button>
              </div>
            </div>
          ) : (
            <div className="aspect-video rounded-[3rem] bg-slate-100 dark:bg-slate-900/50 border-2 border-dashed border-black/10 dark:border-white/5 flex flex-col items-center justify-center text-center p-12">
              <div className={`w-24 h-24 rounded-[2.5rem] flex items-center justify-center mb-8 ${isCloneMode ? 'bg-teal-500/10' : 'bg-indigo-500/10'}`}>
                <ImageIcon className={`w-12 h-12 ${isCloneMode ? 'text-teal-500' : 'text-indigo-500'}`} />
              </div>
              <h3 className="text-2xl font-black text-slate-900 dark:text-white mb-4">
                  {isCloneMode ? 'Bereit zum Klonen' : 'Bereit für dein Remake'}
              </h3>
              <p className="text-slate-500 dark:text-slate-400 font-medium max-w-sm leading-relaxed">
                {isCloneMode 
                    ? 'Lade einen visuellen Stil hoch und beschreibe dein neues Motiv.' 
                    : 'Lade ein Referenzbild hoch und beschreibe deine Änderungen.'}
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User } from './types';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { HomeCategories } from './components/HomeCategories';
import { Pricing } from './components/Pricing';
import { Reviews } from './components/Reviews';
import { AuthModal } from './components/AuthModal';
import { Examples } from './components/Examples';
import { StudioSelection } from './components/StudioSelection';
import { StudioGenerate } from './components/StudioGenerate';
import { StudioChannelAnalyze } from './components/StudioChannelAnalyze';
import { StudioAnalyze } from './components/StudioAnalyze';
import { StudioRemake } from './components/StudioRemake';
import { ArrowLeft, CheckCircle, X, AlertCircle, ShoppingCart } from 'lucide-react';
import { BACKGROUND_IMAGE, PricingPlan } from './constants';

type MainView = 'home' | 'pricing' | 'reviews' | 'examples' | 'studio';
type StudioView = 'suite-selection' | 'generate' | 'channel' | 'analyze' | 'remake' | 'clone';

const ExtremeGlow = () => (
  <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden select-none">
    <div className="absolute top-[-25%] left-[-15%] w-[110%] h-[110%] bg-teal-500/30 dark:bg-teal-500/40 blur-[250px] rounded-full animate-mesh opacity-80"></div>
    <div className="absolute bottom-[-25%] right-[-15%] w-[120%] h-[120%] bg-emerald-600/25 dark:bg-emerald-600/35 blur-[320px] rounded-full animate-mesh opacity-80" style={{ animationDelay: '-8s' }}></div>
  </div>
);

function App() {
  const [user, setUser] = React.useState<User | null>(null);
  const [currentView, setCurrentView] = React.useState<MainView>('home');
  const [studioView, setStudioView] = React.useState<StudioView>('suite-selection');
  const [isAuthOpen, setIsAuthOpen] = React.useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [purchaseSuccess, setPurchaseSuccess] = useState<{ planName: string, amount: number } | null>(null);

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'light') setIsDarkMode(false);
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const handleLogin = (email: string) => {
    setUser({ 
      id: '1', 
      email: email, 
      name: email.split('@')[0], 
      credits: 30, 
      isLoggedIn: true,
      plan: 'Starter'
    });
    setIsAuthOpen(false);
    setCurrentView('studio');
    setStudioView('suite-selection');
  };

  const useCredits = (amount: number): boolean => {
    if (!user || user.credits < amount) {
      setCurrentView('pricing');
      return false;
    }
    setUser({ ...user, credits: user.credits - amount });
    return true;
  };

  const handlePurchase = (plan: PricingPlan) => {
    if (!user) {
      setIsAuthOpen(true);
      return;
    }
    setUser({ ...user, credits: user.credits + plan.credits, plan: plan.name as any });
    setPurchaseSuccess({ planName: plan.name, amount: plan.credits });
    setTimeout(() => setPurchaseSuccess(null), 5000);
    setCurrentView('studio');
  };

  const handleNavigate = (view: MainView) => {
    if (view === 'studio' && !user) {
      setIsAuthOpen(true);
      return;
    }
    setCurrentView(view);
    if (view === 'studio') setStudioView('suite-selection');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSelectCategory = (category: 'suite' | 'channel') => {
    if (!user) {
      setIsAuthOpen(true);
      return;
    }
    setCurrentView('studio');
    setStudioView(category === 'suite' ? 'suite-selection' : 'channel');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSelectStudioTool = (tool: StudioView) => {
    setStudioView(tool);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const BackButton = ({ onClick, label = "Zurück" }: { onClick: () => void, label?: string }) => (
    <button 
      onClick={onClick}
      className="fixed top-24 left-4 lg:left-8 z-40 flex items-center gap-2 px-5 py-2.5 bg-white/80 dark:bg-slate-800/80 hover:bg-white dark:hover:bg-slate-800 border border-black/5 dark:border-white/10 rounded-full text-xs font-black uppercase tracking-widest transition-all group shadow-xl backdrop-blur-md text-slate-900 dark:text-slate-100"
    >
      <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
      {label}
    </button>
  );

  return (
    <div className={`min-h-screen transition-colors duration-500 selection:bg-teal-500 selection:text-white ${isDarkMode ? 'bg-[#020617] text-slate-100' : 'bg-slate-50 text-slate-900'} relative`}>

      <ExtremeGlow />
      <div className="mesh-gradient opacity-90"></div>

      <Navbar 
        user={user} 
        onNavigate={handleNavigate} 
        onLoginClick={() => setIsAuthOpen(true)} 
        isDarkMode={isDarkMode}
        toggleTheme={toggleTheme}
      />

      <main className="relative z-10">
        {currentView === 'home' && (
          <div className="animate-in fade-in duration-700">
            <Hero onStartCreating={() => handleSelectCategory('suite')} onViewPricing={() => handleNavigate('pricing')} />
            <HomeCategories onSelectCategory={handleSelectCategory} />
            <Reviews />
            <Pricing onPurchase={handlePurchase} />
          </div>
        )}

        {currentView === 'studio' && (
          <div className="pt-32 pb-20 min-h-screen">
            {studioView === 'suite-selection' && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                <BackButton onClick={() => setCurrentView('home')} label="Abbrechen" />
                <StudioSelection user={user} onSelectMode={(mode) => handleSelectStudioTool(mode as StudioView)} />
              </div>
            )}

            {studioView === 'generate' && (
              <div className="animate-in fade-in slide-in-from-right-4">
                <BackButton onClick={() => setStudioView('suite-selection')} label="Suite Übersicht" />
                <StudioGenerate useCredits={useCredits} user={user} onGoToPricing={() => handleNavigate('pricing')} />
              </div>
            )}

            {studioView === 'remake' && (
              <div className="animate-in fade-in slide-in-from-right-4">
                <BackButton onClick={() => setStudioView('suite-selection')} label="Suite Übersicht" />
                <StudioRemake useCredits={useCredits} user={user} />
              </div>
            )}

            {studioView === 'clone' && (
              <div className="animate-in fade-in slide-in-from-right-4">
                <BackButton onClick={() => setStudioView('suite-selection')} label="Suite Übersicht" />
                <StudioRemake useCredits={useCredits} user={user} isCloneMode={true} />
              </div>
            )}

            {studioView === 'analyze' && (
              <div className="animate-in fade-in slide-in-from-right-4">
                <BackButton onClick={() => setStudioView('suite-selection')} label="Suite Übersicht" />
                <StudioAnalyze useCredits={useCredits} user={user} />
              </div>
            )}

            {studioView === 'channel' && (
              <div className="animate-in fade-in slide-in-from-right-4">
                <BackButton onClick={() => setCurrentView('home')} label="Startseite" />
                <StudioChannelAnalyze useCredits={useCredits} user={user} />
              </div>
            )}
          </div>
        )}

        {currentView === 'pricing' && <div className="pt-24 min-h-screen"><BackButton onClick={() => handleNavigate('home')} /><Pricing onPurchase={handlePurchase} /></div>}
        {currentView === 'reviews' && <div className="pt-24 min-h-screen"><BackButton onClick={() => handleNavigate('home')} /><Reviews /></div>}
        {currentView === 'examples' && <div className="pt-24 min-h-screen"><BackButton onClick={() => handleNavigate('home')} /><Examples onNavigateToStudio={() => handleSelectCategory('suite')} /></div>}
      </main>

      <AuthModal isOpen={isAuthOpen} onClose={() => setIsAuthOpen(false)} onLogin={handleLogin} />

      {purchaseSuccess && (
        <div className="fixed bottom-8 right-8 z-[110] animate-in slide-in-from-right-8 duration-500">
          <div className="bg-emerald-600 text-white rounded-3xl p-6 shadow-2xl flex items-center gap-4">
            <CheckCircle className="w-8 h-8" />
            <div>
              <p className="font-black uppercase text-xs tracking-widest">Kauf erfolgreich</p>
              <p className="text-sm font-medium">+{purchaseSuccess.amount} Credits hinzugefügt.</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

import React from 'react';
import { Wand2, ChevronRight, Copy, Lock, Coins, Target, Sparkles, LayoutGrid } from 'lucide-react';
import { User } from '../types';

interface StudioSelectionProps {
  user: User | null;
  onSelectMode: (mode: string) => void;
}

export const StudioSelection: React.FC<StudioSelectionProps> = ({ user, onSelectMode }) => {
  const currentPlan = user?.plan || 'Starter';
  const userCredits = user?.credits || 0;

  const checkPlanPermission = (planRequired: string) => {
    if (planRequired === 'Starter') return true;
    if (planRequired === 'Creator Pro') return currentPlan === 'Creator Pro' || currentPlan === 'Production';
    return currentPlan === 'Production';
  };

  const suiteModes = [
    {
