import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const analyzePromptIntent = async (prompt: string) => {
  const ai = getAI();

  const analysisPrompt = `Analysiere den folgenden YouTube-Thumbnail-Prompt: "${prompt}"
Bestimme, ob der Nutzer expliziten Text im Bild wünscht.
Extrahiere den gewünschten Text und erstelle eine optimierte visuelle Beschreibung für eine Bild-KI.

Antworte STRENG im JSON-Format auf Deutsch:
{
  "wantsText": boolean,
  "extractedText": "der genaue Text oder null",
  "visualPrompt": "optimierte Beschreibung des Motivs ohne Text-Anweisungen"
}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: analysisPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            wantsText: { type: Type.BOOLEAN },
            extractedText: { type: Type.STRING, nullable: true },
            visualPrompt: { type: Type.STRING }
          },
          required: ["wantsText", "visualPrompt"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Intent-Analyse fehlgeschlagen", e);
    return null;
  }
};

export const remakeThumbnail = async (sourceBase64: string, adjustmentPrompt: string) => {
  const ai = getAI();

  const analysisPrompt = `Analysiere dieses Thumbnail im Detail auf Deutsch:
1. Was ist das Hauptmotiv?
2. Wie ist die Komposition?
3. Was sind die dominanten Farben?
4. Welche Typografie wird verwendet?

Erstelle basierend auf dieser Analyse und der Nutzeranpassung "${adjustmentPrompt}" eine hochpräzise Beschreibung für ein Remake, das den Stil beibehaltet. Antworte auf Deutsch.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: sourceBase64.split(',')[1], mimeType: 'image/png' } },
        { text: analysisPrompt }
      ]
    }
  });

  return generateThumbnail(response.text || adjustmentPrompt, 'Remake', sourceBase64);
};

export const generateThumbnail = async (prompt: string, style: string, base64Image?: string) => {
  const ai = getAI();
  const intent = await analyzePromptIntent(prompt);

  let textInstruction = "";
  let finalVisualPrompt = prompt;

  if (intent) {
    finalVisualPrompt = intent.visualPrompt;
    if (intent.wantsText) {
      textInstruction = `Nutze fette, moderne Typografie für: "${intent.extractedText}". Der Text muss das zentrale, klickstarke Element sein.`;
    } else {
      textInstruction = `STRIKTE ANWEISUNG: KEIN TEXT im Bild. Keine Buchstaben, keine Zahlen.`;
    }
  }

  const fullPrompt = `AUFGABE: Erstelle ein YouTube-Thumbnail. STIL: ${style}. MOTIV: ${finalVisualPrompt}. VORGABEN: Dramatische Beleuchtung, hoher Kontrast, klickstarke Farben. TEXT: ${textInstruction}. QUALITÄT: 4K, Ultra-Detail.`;

  const contents: any = {
    parts: [{ text: fullPrompt }]
  };

  if (base64Image) {
    contents.parts.push({
      inlineData: { data: base64Image.split(',')[1], mimeType: 'image/png' }
    });
  }

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents,
    config: { imageConfig: { aspectRatio: "16:9" } }
  });

  const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  if (imagePart?.inlineData) {
    return `data:image/png;base64,${imagePart.inlineData.data}`;
  }
  throw new Error("Generierung fehlgeschlagen.");
};

export const analyzeThumbnailImage = async (base64Image: string) => {
  const ai = getAI();
  const prompt = `Analysiere dieses YouTube-Thumbnail auf Deutsch. Bewerte das CTR-Potenzial (0-10) und gib Verbesserungsvorschläge. Antworte STRENG im JSON Format auf Deutsch.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Image.split(',')[1], mimeType: 'image/png' } },
        { text: prompt }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          score: { type: Type.NUMBER },
          feedback: { type: Type.STRING },
          suggestions: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["score", "feedback", "suggestions"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const analyzeYoutubeChannel = async (channelUrl: string) => {
  const ai = getAI();
  const prompt = `Führe ein YouTube Thumbnail Audit auf Deutsch für ${channelUrl} durch. Analysiere Stil, Stärken, Schwächen und erstelle einen Aktionsplan. Antworte STRENG im JSON Format auf Deutsch.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          channelName: { type: Type.STRING },
          identitySummary: { type: Type.STRING },
          strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
          weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
          actionPlan: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["channelName", "identitySummary", "strengths", "weaknesses", "actionPlan"]
      }
    }
  });

  const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
  const result = JSON.parse(response.text || '{}');

  return {
    ...result,
    sources: groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || chunk.web?.uri,
      url: chunk.web?.uri
    })).filter((s: any) => s.url) || []
  };
};

