import React, { useState, useEffect } from 'react';
import { Wand2, Upload, Sparkles, Loader2, Download, Trash2, Image as ImageIcon, Coins, Lightbulb, Plus, AlertCircle, ShoppingCart, Lock, Monitor, Smartphone, Square, AlertTriangle, ChevronRight } from 'lucide-react';
import { generateThumbnail } from '../services/geminiService';
import { ThumbnailStyle, User } from '../types';

interface StudioGenerateProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
  onGoToPricing?: () => void;
}

const STYLE_SUGGESTIONS: Record<ThumbnailStyle, string[]> = {
  [ThumbnailStyle.CLEAN]: ["Professionelle Beleuchtung", "Weicher Hintergrund", "Hoher Kontrast", "Zentriertes Motiv", "Pastellfarben", "Minimalistisches Setup"],
  [ThumbnailStyle.BEAST]: ["Schockierter Gesichtsausdruck", "Intensive Emotionen", "Leuchtende Neonfarben", "Fette Umrandung", "Überrascht in Kamera blickend", "Action-Pose"],
  [ThumbnailStyle.MINIMAL]: ["Viel Negativraum", "Einzelnes Objekt im Fokus", "Flaches Design", "Elegante Ästhetik", "Monochromer Look", "Sanfter Schatten"],
  [ThumbnailStyle.GAMING]: ["RGB-Beleuchtung", "Partikeleffekte", "Dynamischer Blickwinkel", "Cyberpunk Vibe", "Gaming-Setup im Hintergrund", "Explosive Farben"]
};

const ASPECT_RATIOS = [
  { id: '16:9', label: 'Standard (16:9)', icon: Monitor, desc: 'YouTube Video' },
  { id: '9:16', label: 'Shorts (9:16)', icon: Smartphone, desc: 'Reels / TikTok' },
  { id: '1:1', label: 'Quadrat (1:1)', icon: Square, desc: 'Instagram / Post' },
];

export const StudioGenerate: React.FC<StudioGenerateProps> = ({ useCredits, user, onGoToPricing }) => {
  const [prompt, setPrompt] = useState('');
  const [style, setStyle] = useState<ThumbnailStyle>(ThumbnailStyle.CLEAN);
  const [aspectRatio, setAspectRatio] = useState('16:9');
  const [image, setImage] = useState<string | null>(null);
  const [promptError, setPromptError] = useState<string | null>(null);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [result, setResult] = useState<string | null>(null);

  const isLowCredits = user && user.credits < 10;
  const isStarter = user?.plan === 'Starter';

  useEffect(() => {
    let interval: any;
    if (loading) {
      setProgress(0);
      const steps = [
        { threshold: 20, text: "KI initialisiert..." },
        { threshold: 45, text: "Motive werden komponiert..." },
        { threshold: 75, text: "Beleuchtung wird verfeinert..." },
        { threshold: 95, text: "Details werden gerendert..." }
      ];

      interval = setInterval(() => {
        setProgress(prev => {
          const next = prev + Math.random() * 8;
          const currentStep = steps.find(s => next <= s.threshold) || steps[steps.length - 1];
          setStatusText(currentStep.text);
          return next >= 98 ? 98 : next;
        });
      }, 400);
    } else {
      setProgress(0);
      setStatusText('');
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setUploadError(null);

    if (file) {
      const allowedTypes = ['image/png', 'image/jpeg', 'image/jpg'];
      if (!allowedTypes.includes(file.type)) {
        setUploadError("Ungültiges Format. Bitte lade nur PNG oder JPG Dateien hoch.");
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => setImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    setPromptError(null);

    if (!prompt.trim()) {
      setPromptError("Bitte beschreibe zuerst deine Vision für das Thumbnail, bevor du die Generierung startest.");
      return;
    }

    if (!user || user.credits < 10) {
      // Statt alert navigieren wir direkt oder zeigen die UI-Warnung (die unten gerendert wird)
      if (onGoToPricing) onGoToPricing();
      return;
    }

    setLoading(true);
    try {
      const res = await generateThumbnail(prompt, style, aspectRatio, image || undefined);
      useCredits(10);
      setResult(res);
      setProgress(100);
      setStatusText("Fertig!");
    } catch (err) {
      alert("Fehler bei der Generierung.");
    } finally {
      setTimeout(() => setLoading(false), 500);
    }
  };

  const addSuggestion = (suggestion: string) => {
    setPromptError(null);
    setPrompt(prev => {
      const trimmed = prev.trim();
      if (!trimmed) return suggestion;
      if (trimmed.endsWith(',')) return `${trimmed} ${suggestion}`;
      return `${trimmed}, ${suggestion}`;
    });
  };

  return (
    <div className="max-w-6xl mx-auto grid lg:grid-cols-2 gap-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="space-y-8">

        {isStarter && (
          <div className="p-6 bg-blue-600/5 border border-blue-600/20 rounded-[2rem] flex items-center justify-between gap-6 animate-in slide-in-from-top-4 duration-500">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 bg-blue-600/10 rounded-full flex items-center justify-center shrink-0">
                <Lock className="w-5 h-5 text-blue-600" />
              </div>
              <div>
                <h4 className="text-sm font-black text-blue-600 dark:text-blue-400 uppercase tracking-widest mb-1 leading-none">Starter Plan aktiv</h4>
                <p className="text-[10px] text-blue-500 font-bold opacity-80 uppercase tracking-wider">Bilder enthalten ein Wasserzeichen</p>
              </div>
            </div>
            <button 
              onClick={onGoToPricing}
              className="px-6 py-2.5 bg-blue-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-blue-600/20 active:scale-95 transition-all"
            >
              Pro holen
            </button>
          </div>
        )}

        {/* Low Credits Warning Card */}
        {isLowCredits && (
          <div className="p-6 bg-amber-500/10 border border-amber-500/20 rounded-[2rem] flex flex-col sm:flex-row items-center justify-between gap-6 animate-in slide-in-from-top-4 duration-500">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-amber-500/20 rounded-2xl flex items-center justify-center shrink-0">
                <AlertTriangle className="w-6 h-6 text-amber-600" />
              </div>
              <div>
                <h4 className="text-sm font-black text-amber-700 dark:text-amber-400 uppercase tracking-widest mb-1">Guthaben fast leer</h4>
                <p className="text-xs text-amber-600/80 font-medium">Du hast weniger als 10 Credits. Lade dein Konto auf, um fortzufahren.</p>
              </div>
            </div>
            <button 
              onClick={onGoToPricing}
              className="w-full sm:w-auto px-6 py-3 bg-amber-500 hover:bg-amber-600 text-white rounded-xl text-xs font-black uppercase flex items-center justify-center gap-2 shadow-lg shadow-amber-500/20 transition-all active:scale-95"
            >
              Credits aufladen <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        )}

        <div className="p-8 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-black/5 dark:border-white/5 shadow-2xl">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-2xl font-black flex items-center gap-3">
              <Sparkles className="w-6 h-6 text-blue-500" />
              Konfiguration
            </h2>
            <div className={`flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full border ${
              isLowCredits ? 'bg-red-500/10 text-red-500 border-red-500/10' : 'bg-amber-500/10 text-amber-500 border-amber-500/10'
            }`}>
              <Coins className="w-3.5 h-3.5" />
              10 Credits
            </div>
          </div>

          <div className="space-y-6">
            <div>
              <div className="flex items-center justify-between mb-3">
                <label className="text-xs font-black uppercase tracking-widest text-slate-500">Vision beschreiben</label>
                <div className="flex items-center gap-1.5 text-[10px] font-bold text-blue-500 bg-blue-500/5 px-2 py-1 rounded-md">
                   <Lightbulb className="w-3 h-3" /> Prompt Helper
                </div>
              </div>

              <div className="relative">
                <textarea 
                  value={prompt}
                  onChange={(e) => {
                    setPrompt(e.target.value);
                    if (promptError) setPromptError(null);
                  }}
                  placeholder="z.B. Ein schockierter Mann hält ein goldenes iPhone in der Hand..."
                  className={`w-full h-32 bg-slate-50 dark:bg-slate-800/50 border rounded-2xl p-4 focus:ring-2 outline-none transition-all resize-none mb-2 ${
                    promptError ? 'border-red-500 ring-2 ring-red-500/10' : 'border-black/5 dark:border-white/5 focus:ring-blue-500'
                  }`}
                />
                {promptError && (
                  <div className="flex items-center gap-1.5 text-red-500 text-[11px] font-bold animate-in fade-in slide-in-from-top-1 duration-200 mb-4">
                    <AlertCircle className="w-3.5 h-3.5" />
                    {promptError}
                  </div>
                )}
              </div>

              <div className="space-y-2">
                <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Vorschläge für {style}</span>
                <div className="flex flex-wrap gap-2">
                  {STYLE_SUGGESTIONS[style].map((suggestion, i) => (
                    <button
                      key={i}
                      onClick={() => addSuggestion(suggestion)}
                      className="group flex items-center gap-1.5 px-3 py-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-blue-500 hover:text-white dark:hover:bg-blue-600 rounded-full text-[11px] font-bold transition-all border border-transparent"
                    >
                      <Plus className="w-3 h-3 opacity-50 group-hover:opacity-100" />
                      {suggestion}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            <div>
              <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-3">Format / Größe</label>
              <div className="grid grid-cols-3 gap-2">
                {ASPECT_RATIOS.map((ratio) => {
                  const Icon = ratio.icon;
                  return (
                    <button
                      key={ratio.id}
                      onClick={() => setAspectRatio(ratio.id)}
                      className={`flex flex-col items-center justify-center p-3 rounded-2xl border transition-all ${
                        aspectRatio === ratio.id 
                          ? 'bg-blue-600 border-blue-600 text-white shadow-lg' 
                          : 'bg-slate-50 dark:bg-slate-800/50 border-transparent text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'
                      }`}
                    >
                      <Icon className="w-5 h-5 mb-1.5" />
                      <span className="text-[10px] font-black uppercase tracking-wider">{ratio.id}</span>
                      <span className="text-[8px] font-bold opacity-60">{ratio.desc}</span>
                    </button>
                  );
                })}
              </div>
            </div>

            <div>
              <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-3">Stil auswählen</label>
              <div className="grid grid-cols-2 gap-3">
                {Object.values(ThumbnailStyle).map((s) => (
                  <button
                    key={s}
                    onClick={() => setStyle(s)}
                    className={`py-3 px-4 rounded-xl font-bold text-sm border transition-all ${
                      style === s 
                        ? 'bg-blue-600 border-blue-600 text-white shadow-lg' 
                        : 'bg-slate-50 dark:bg-slate-800/50 border-transparent text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'
                    }`}
                  >
                    {s}
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-3">Referenzbild (Optional)</label>
              <div className={`relative h-32 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center group overflow-hidden transition-colors ${
                uploadError ? 'border-red-500 bg-red-500/5' : 'border-black/10 dark:border-white/10'
              }`}>
                {image ? (
                  <>
                    <img src={image} className="w-full h-full object-cover opacity-50" />
                    <button onClick={() => { setImage(null); setUploadError(null); }} className="absolute p-2 bg-red-500 text-white rounded-lg shadow-xl hover:scale-110 transition-transform">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </>
                ) : (
                  <>
                    <Upload className={`w-8 h-8 mb-2 group-hover:text-blue-500 transition-colors ${uploadError ? 'text-red-400' : 'text-slate-300'}`} />
                    <span className={`text-[10px] font-black uppercase tracking-widest ${uploadError ? 'text-red-500' : 'text-slate-400'}`}>
                      Bild hochladen
                    </span>
                    <input type="file" accept="image/png, image/jpeg, image/jpg" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                  </>
                )}
              </div>
            </div>

            {loading && (
              <div className="space-y-3 animate-in fade-in slide-in-from-top-2 duration-300">
                <div className="flex justify-between items-end">
                  <span className="text-xs font-black uppercase tracking-widest text-blue-500">{statusText}</span>
                  <span className="text-xs font-black text-slate-400">{Math.round(progress)}%</span>
                </div>
                <div className="h-3 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden border border-black/5 dark:border-white/5">
                  <div 
                    className="h-full bg-blue-600 transition-all duration-500 ease-out shadow-[0_0_20px_rgba(37,99,235,0.4)]"
                    style={{ width: `${progress}%` }}
                  ></div>
                </div>
              </div>
            )}

            <button 
              onClick={handleGenerate}
              disabled={loading || !!uploadError}
              className={`w-full py-5 rounded-2xl font-black text-lg flex items-center justify-center gap-3 shadow-xl transition-all active:scale-95 disabled:opacity-50 ${
                isLowCredits 
                  ? 'bg-slate-300 dark:bg-slate-700 text-slate-500 cursor-not-allowed' 
                  : 'bg-blue-600 hover:bg-blue-700 shadow-blue-600/20 text-white'
              }`}
            >
              {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Wand2 className="w-6 h-6" />}
              {isLowCredits ? 'Nicht genügend Credits' : 'Thumbnail generieren'}
            </button>
          </div>
        </div>
      </div>

      <div className="flex flex-col justify-center">
        {result ? (
          <div className="space-y-6 animate-in zoom-in-95 duration-500">
            <div className={`rounded-[2.5rem] overflow-hidden shadow-2xl border-4 border-white dark:border-slate-800 relative mx-auto bg-slate-200 dark:bg-slate-800 ${
              aspectRatio === '16:9' ? 'aspect-video w-full' : 
              aspectRatio === '9:16' ? 'aspect-[9/16] h-[600px]' : 'aspect-square w-full max-w-[450px]'
            }`}>
              <img src={result} className="w-full h-full object-cover" alt="Generiertes Thumbnail" />
              {isStarter && (
                <div className="absolute bottom-4 right-4 bg-black/50 backdrop-blur-md px-4 py-2 rounded-xl border border-white/20 text-white/50 text-[10px] font-black uppercase tracking-widest pointer-events-none select-none">
                  Made with Thumbify AI
                </div>
              )}
            </div>
            <div className="flex gap-4">
              <button 
                onClick={() => {
                  const link = document.createElement('a');
                  link.href = result;
                  link.download = `thumbnail_${aspectRatio.replace(':', 'x')}.png`;
                  link.click();
                }}
                className="flex-1 py-4 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-black flex items-center justify-center gap-2"
              >
                <Download className="w-5 h-5" /> In 4K speichern
              </button>
              <button onClick={() => setResult(null)} className="px-6 py-4 bg-slate-100 dark:bg-slate-800 rounded-xl font-black text-slate-500">Neu</button>
            </div>
          </div>
        ) : (
          <div className="aspect-video rounded-[3rem] bg-slate-100 dark:bg-slate-900/50 border-2 border-dashed border-black/5 dark:border-white/5 flex flex-col items-center justify-center text-center p-12">
            <div className="w-20 h-20 bg-blue-500/10 rounded-3xl flex items-center justify-center mb-6">
              <ImageIcon className="w-10 h-10 text-blue-500" />
            </div>
            <h3 className="text-xl font-black mb-2">Vorschau</h3>
            <p className="text-slate-400 text-sm max-w-xs font-medium">Dein KI-generiertes Meisterwerk wird hier angezeigt.</p>
          </div>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { Wand2, ChevronRight, Copy, Lock, Coins, Target, Sparkles, LayoutGrid, AlertCircle } from 'lucide-react';
import { User } from '../types';

interface StudioSelectionProps {
  user: User | null;
  onSelectMode: (mode: string) => void;
  onGoToPricing?: () => void;
}

export const StudioSelection: React.FC<StudioSelectionProps> = ({ user, onSelectMode, onGoToPricing }) => {
  const currentPlan = user?.plan || 'Starter';
  const userCredits = user?.credits || 0;

  const checkPlanPermission = (planRequired: string) => {
    if (planRequired === 'Starter') return true;
    if (planRequired === 'Creator Pro') return currentPlan === 'Creator Pro' || currentPlan === 'Production';
    return currentPlan === 'Production';
  };

  const suiteModes = [
    {
      id: 'generate',
      title: 'Thumbnail generieren',
      description: 'Erstelle hochkonvertierende Designs von Grund auf mit präzisen KI-Text-Prompts.',
      icon: <Wand2 className="w-8 h-8" />,
      lightColor: 'bg-teal-500/10',
      textColor: 'text-teal-600',
      cost: 10,
      planRequired: 'Starter'
    },
    {
      id: 'remake',
      title: 'Thumbnail überarbeiten',
      description: 'Passe ein bestehendes Layout an und tausche Inhalte bei gleichbleibender visueller Struktur.',
      icon: <Copy className="w-8 h-8" />,
      lightColor: 'bg-indigo-500/10',
      textColor: 'text-indigo-600',
      cost: 20,
      planRequired: 'Starter'
    },
    {
      id: 'clone',
      title: 'Stil klonen',
      description: 'Extrahiere die visuelle Identität einer Referenz und wende sie auf dein neues Motiv an.',
      icon: <Sparkles className="w-8 h-8" />,
      lightColor: 'bg-blue-500/10',
      textColor: 'text-blue-600',
      cost: 30,
      planRequired: 'Starter'
    },
    {
      id: 'analyze',
      title: 'Performance analysieren',
      description: 'Erhalte datengestützte Insights und CTR-Vorhersagen für deinen finalen Thumbnail-Entwurf.',
      icon: <Target className="w-8 h-8" />,
      lightColor: 'bg-emerald-500/10',
      textColor: 'text-emerald-600',
      cost: 50,
      planRequired: 'Creator Pro'
    }
  ];

  const handleToolClick = (mode: any) => {
    const hasPlan = checkPlanPermission(mode.planRequired);
    const hasCredits = userCredits >= mode.cost;

    if (!hasPlan || !hasCredits) {
      if (onGoToPricing) onGoToPricing();
      return;
    }

    onSelectMode(mode.id);
  };

  return (
    <div className="px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto">
        <div className="text-center mb-16">
          <div className="w-20 h-20 rounded-3xl bg-teal-600/10 flex items-center justify-center mx-auto mb-8 text-teal-600">
            <LayoutGrid className="w-10 h-10" />
          </div>
          <h1 className="text-5xl md:text-7xl font-black tracking-tight mb-6">
            Thumbnail-<span className="gradient-text">Suite</span>
          </h1>
          <p className="text-xl text-slate-500 dark:text-slate-400 font-medium max-w-2xl mx-auto">
            Vier spezialisierte Tools für deine YouTube-Dominanz. Wähle dein Werkzeug.
          </p>
        </div>

        <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-8">
          {suiteModes.map((mode) => {
            const hasPlan = checkPlanPermission(mode.planRequired);
            const hasCredits = userCredits >= mode.cost;
            const isLocked = !hasPlan || !hasCredits;

            return (
              <button
                key={mode.id}
                onClick={() => handleToolClick(mode)}
                className={`group relative flex flex-col p-10 bg-white/70 dark:bg-slate-900/40 backdrop-blur-xl border border-black/5 dark:border-white/10 rounded-[3rem] text-left transition-all hover:-translate-y-3 hover:shadow-2xl active:scale-[0.98] overflow-hidden h-full ${
                  isLocked ? 'grayscale-[0.8] opacity-80' : ''
                }`}
              >
                <div className="absolute top-6 right-6 z-20 flex flex-col items-end gap-2">
                  {!hasPlan && (
                    <div className="p-2 bg-slate-900 text-white rounded-xl flex items-center gap-1.5 text-[10px] font-black uppercase shadow-lg">
                      <Lock className="w-3 h-3" /> Upgrade
                    </div>
                  )}
                  {!hasCredits && hasPlan && (
                    <div className="p-2 bg-red-600 text-white rounded-xl flex items-center gap-1.5 text-[10px] font-black uppercase shadow-lg">
                      <AlertCircle className="w-3 h-3" /> Credits nötig
                    </div>
                  )}
                  <div className={`p-2 rounded-xl flex items-center gap-1.5 text-[10px] font-black uppercase border ${
                    !hasCredits ? 'bg-red-500/10 text-red-500 border-red-500/20' : 'bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/10'
                  }`}>
                    <Coins className="w-3 h-3" /> {mode.cost}
                  </div>
                </div>

                <div className="relative z-10 flex flex-col h-full">
                  <div className={`w-16 h-16 rounded-2xl ${mode.lightColor} ${mode.textColor} flex items-center justify-center mb-8 shadow-inner transition-transform group-hover:scale-110`}>
                    {mode.icon}
                  </div>

                  <h3 className="text-2xl font-black mb-4">
                    {mode.title}
                  </h3>

                  <p className="text-base text-slate-500 dark:text-slate-400 font-medium leading-relaxed mb-10 flex-1">
                    {mode.description}
                  </p>

                  <div className={`inline-flex items-center gap-2 font-black text-xs uppercase tracking-widest transition-all ${
                    isLocked ? 'text-slate-400' : 'group-hover:text-teal-600'
                  }`}>
                    {isLocked ? (
                      <span className="flex items-center gap-2">Aufstocken zum Freischalten <ChevronRight className="w-4 h-4" /></span>
                    ) : (
                      <span className="flex items-center gap-2">Tool starten <ChevronRight className="w-4 h-4 group-hover:translate-x-2 transition-transform" /></span>
                    )}
                  </div>
                </div>

                {/* Visual Lock Overlay for better UX */}
                {isLocked && (
                  <div className="absolute inset-0 bg-slate-100/10 dark:bg-slate-900/10 pointer-events-none transition-colors group-hover:bg-transparent" />
                )}
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User } from './types';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { HomeCategories } from './components/HomeCategories';
import { HowItWorks } from './components/HowItWorks';
import { Pricing } from './components/Pricing';
import { Reviews } from './components/Reviews';
import { AuthModal } from './components/AuthModal';
import { Examples } from './components/Examples';
import { StudioSelection } from './components/StudioSelection';
import { StudioGenerate } from './components/StudioGenerate';
import { StudioChannelAnalyze } from './components/StudioChannelAnalyze';
import { StudioAnalyze } from './components/StudioAnalyze';
import { StudioRemake } from './components/StudioRemake';
import { ArrowLeft, CheckCircle, X, AlertCircle, ShoppingCart, LayoutGrid, Youtube, ChevronRight } from 'lucide-react';
import { BACKGROUND_IMAGE, PricingPlan } from './constants';

type MainView = 'home' | 'pricing' | 'reviews' | 'examples' | 'studio';
type StudioView = 'suite-selection' | 'generate' | 'channel' | 'analyze' | 'remake' | 'clone';

const ExtremeGlow = () => (
  <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden select-none">
    <div className="absolute top-[-25%] left-[-15%] w-[110%] h-[110%] bg-teal-500/30 dark:bg-teal-500/40 blur-[250px] rounded-full animate-mesh opacity-80"></div>
    <div className="absolute bottom-[-25%] right-[-15%] w-[120%] h-[120%] bg-emerald-600/25 dark:bg-emerald-600/35 blur-[320px] rounded-full animate-mesh opacity-80" style={{ animationDelay: '-8s' }}></div>
  </div>
);

function App() {
  const [user, setUser] = React.useState<User | null>(null);
  const [currentView, setCurrentView] = React.useState<MainView>('home');
  const [studioView, setStudioView] = React.useState<StudioView>('suite-selection');
  const [isAuthOpen, setIsAuthOpen] = React.useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [purchaseSuccess, setPurchaseSuccess] = useState<{ planName: string, amount: number } | null>(null);

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'light') setIsDarkMode(false);
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const handleLogin = (email: string) => {
    setUser({ 
      id: '1', 
      email: email, 
      name: email.split('@')[0], 
      credits: 30, 
      isLoggedIn: true,
      plan: 'Starter'
    });
    setIsAuthOpen(false);
    setCurrentView('studio');
    setStudioView('suite-selection');
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView('home');
    setStudioView('suite-selection');
  };

  const useCredits = (amount: number): boolean => {
    if (!user || user.credits < amount) {
      setCurrentView('pricing');
      return false;
    }
    setUser({ ...user, credits: user.credits - amount });
    return true;
  };

  const handlePurchase = (plan: PricingPlan) => {
    if (!user) {
      setIsAuthOpen(true);
      return;
    }
    setUser({ ...user, credits: user.credits + plan.credits, plan: plan.name as any });
    setPurchaseSuccess({ planName: plan.name, amount: plan.credits });
    setTimeout(() => setPurchaseSuccess(null), 5000);
    setCurrentView('studio');
  };

  const handleNavigate = (view: MainView) => {
    if (view === 'studio' && !user) {
      setIsAuthOpen(true);
      return;
    }
    setCurrentView(view);
    if (view === 'studio') setStudioView('suite-selection');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSelectCategory = (category: 'suite' | 'channel') => {
    if (!user) {
      setIsAuthOpen(true);
      return;
    }
    setCurrentView('studio');
    setStudioView(category === 'suite' ? 'suite-selection' : 'channel');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSelectStudioTool = (tool: StudioView) => {
    setStudioView(tool);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const BackButton = ({ onClick, label = "Zurück" }: { onClick: () => void, label?: string }) => (
    <button 
      onClick={onClick}
      className="fixed top-36 left-4 lg:left-8 z-40 flex items-center gap-2 px-5 py-2.5 bg-white/80 dark:bg-slate-800/80 hover:bg-white dark:hover:bg-slate-800 border border-black/5 dark:border-white/10 rounded-full text-xs font-black uppercase tracking-widest transition-all group shadow-xl backdrop-blur-md text-slate-900 dark:text-slate-100"
    >
      <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
      {label}
    </button>
  );

  const WorkspaceSwitcher = () => {
    const isChannel = studioView === 'channel';
    return (
      <div className="fixed top-24 left-1/2 -translate-x-1/2 z-50 px-2 py-2 bg-white/40 dark:bg-slate-900/40 backdrop-blur-2xl border border-black/5 dark:border-white/10 rounded-2xl flex items-center gap-1 shadow-2xl">
        <button
          onClick={() => setStudioView('suite-selection')}
          className={`px-5 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all flex items-center gap-2 ${
            !isChannel 
              ? 'bg-teal-600 text-white shadow-lg shadow-teal-600/20' 
              : 'text-slate-500 dark:text-slate-400 hover:text-teal-600 dark:hover:text-teal-400'
          }`}
        >
          <LayoutGrid className="w-4 h-4" />
          Thumbnail-Suite
        </button>
        <button
          onClick={() => setStudioView('channel')}
          className={`px-5 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all flex items-center gap-2 ${
            isChannel 
              ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' 
              : 'text-slate-500 dark:text-slate-400 hover:text-blue-600 dark:hover:text-blue-400'
          }`}
        >
          <Youtube className="w-4 h-4" />
          Kanal-Analyse
        </button>
      </div>
    );
  };

  return (
    <div className={`min-h-screen transition-colors duration-500 selection:bg-teal-500 selection:text-white ${isDarkMode ? 'bg-[#020617] text-slate-100' : 'bg-slate-50 text-slate-900'} relative`}>

      <ExtremeGlow />
      <div className="mesh-gradient opacity-90"></div>

      <Navbar 
        user={user} 
        onNavigate={handleNavigate} 
        onLoginClick={() => setIsAuthOpen(true)} 
        onLogout={handleLogout}
        isDarkMode={isDarkMode}
        toggleTheme={toggleTheme}
      />

      <main className="relative z-10">
        {currentView === 'home' && (
          <div className="animate-in fade-in duration-700">
            <Hero onStartCreating={() => handleSelectCategory('suite')} onViewPricing={() => handleNavigate('pricing')} />
            <HomeCategories onSelectCategory={handleSelectCategory} />
            <HowItWorks />
            <Reviews />
            <Pricing onPurchase={handlePurchase} />
          </div>
        )}

        {currentView === 'studio' && (
          <div className="pt-48 pb-20 min-h-screen">
            <WorkspaceSwitcher />

            {studioView === 'suite-selection' && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                <BackButton onClick={() => setCurrentView('home')} label="Abbrechen" />
                <StudioSelection 
                  user={user} 
                  onSelectMode={(mode) => handleSelectStudioTool(mode as StudioView)} 
                  onGoToPricing={() => handleNavigate('pricing')}
                />
              </div>
            )}

            {studioView === 'generate' && (
              <div className="animate-in fade-in slide-in-from-right-4">
                <BackButton onClick={() => setStudioView('suite-selection')} label="Suite Übersicht" />
                <StudioGenerate useCredits={useCredits} user={user} onGoToPricing={() => handleNavigate('pricing')} />
              </div>
            )}

            {studioView === 'remake' && (
              <div className="animate-in fade-in slide-in-from-right-4">
                <BackButton onClick={() => setStudioView('suite-selection')} label="Suite Übersicht" />
                <StudioRemake useCredits={useCredits} user={user} />
              </div>
            )}

            {studioView === 'clone' && (
              <div className="animate-in fade-in slide-in-from-right-4">
                <BackButton onClick={() => setStudioView('suite-selection')} label="Suite Übersicht" />
                <StudioRemake useCredits={useCredits} user={user} isCloneMode={true} />
              </div>
            )}

            {studioView === 'analyze' && (
              <div className="animate-in fade-in slide-in-from-right-4">
                <BackButton onClick={() => setStudioView('suite-selection')} label="Suite Übersicht" />
                <StudioAnalyze useCredits={useCredits} user={user} />
              </div>
            )}

            {studioView === 'channel' && (
              <div className="animate-in fade-in slide-in-from-right-4">
                <BackButton onClick={() => setCurrentView('home')} label="Startseite" />
                <StudioChannelAnalyze useCredits={useCredits} user={user} />
              </div>
            )}
          </div>
        )}

        {currentView === 'pricing' && <div className="pt-24 min-h-screen"><BackButton onClick={() => handleNavigate('home')} /><Pricing onPurchase={handlePurchase} /></div>}
        {currentView === 'reviews' && <div className="pt-24 min-h-screen"><BackButton onClick={() => handleNavigate('home')} /><Reviews /></div>}
        {currentView === 'examples' && <div className="pt-24 min-h-screen"><BackButton onClick={() => handleNavigate('home')} /><Examples onNavigateToStudio={() => handleSelectCategory('suite')} /></div>}
      </main>

      <AuthModal isOpen={isAuthOpen} onClose={() => setIsAuthOpen(false)} onLogin={handleLogin} />

      {purchaseSuccess && (
        <div className="fixed bottom-8 right-8 z-[110] animate-in slide-in-from-right-8 duration-500">
          <div className="bg-emerald-600 text-white rounded-3xl p-6 shadow-2xl flex items-center gap-4">
            <CheckCircle className="w-8 h-8" />
            <div>
              <p className="font-black uppercase text-xs tracking-widest">Kauf erfolgreich</p>
              <p className="text-sm font-medium">+{purchaseSuccess.amount} Credits hinzugefügt.</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

