import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const analyzePromptIntent = async (prompt: string) => {
  const ai = getAI();

  const analysisPrompt = `Analysiere den folgenden YouTube-Thumbnail-Prompt: "${prompt}"
Bestimme, ob der Nutzer expliziten Text im Bild wünscht.
Extrahiere den gewünschten Text und erstelle eine optimierte visuelle Beschreibung für eine Bild-KI.

Antworte STRENG im JSON-Format auf Deutsch:
{
  "wantsText": boolean,
  "extractedText": "der genaue Text oder null",
  "visualPrompt": "optimierte Beschreibung des Motivs ohne Text-Anweisungen"
}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: analysisPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            wantsText: { type: Type.BOOLEAN },
            extractedText: { type: Type.STRING, nullable: true },
            visualPrompt: { type: Type.STRING }
          },
          required: ["wantsText", "visualPrompt"]
        }
      }
    });

    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Intent-Analyse fehlgeschlagen", e);
    return null;
  }
};

/**
 * Klont den Stil eines Bildes und wendet ihn auf ein neues Motiv an.
 */
export const cloneStyle = async (sourceBase64: string, newMotifPrompt: string) => {
  const ai = getAI();

  // 1. Stil-Analyse der Referenz
  const styleAnalysisPrompt = `Analysiere den visuellen STIL dieses Thumbnails auf Deutsch. 
Extrahiere:
1. Farbschema (dominante Farben, Kontraste)
2. Beleuchtung (dramatisch, weich, Studio)
3. Kompositions-Regeln (Zentriert, Drittel-Regel, Tiefenschärfe)
4. Grafische Elemente (Umrandungen, Effekte, Typografie-Vibe)

Erstelle daraus eine kompakte "Stil-Anweisung" für eine Bild-KI, die diesen Stil beschreibt, ohne das ursprüngliche Motiv zu erwähnen.`;

  try {
    const analysisResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: sourceBase64.split(',')[1], mimeType: 'image/png' } },
          { text: styleAnalysisPrompt }
        ]
      }
    });

    const styleInstructions = analysisResponse.text || "Moderner YouTube-Stil";

    // 2. Generierung mit kombiniertem Prompt (Stil + neues Motiv)
    // Wir übergeben das Bild NICHT an generateThumbnail, da wir ein NEUES Motiv wollen, aber im GLEICHEN STIL.
    return generateThumbnail(newMotifPrompt, `Klon-Stil (${styleInstructions})`, "16:9");
  } catch (e) {
    console.error("Style Cloning fehlgeschlagen", e);
    throw e;
  }
};

/**
 * Überarbeitet ein bestehendes Thumbnail (Image-to-Image).
 */
export const remakeThumbnail = async (sourceBase64: string, adjustmentPrompt: string) => {
  const ai = getAI();

  const analysisPrompt = `Analysiere dieses Thumbnail im Detail auf Deutsch:
1. Was ist das Hauptmotiv?
2. Wie ist die Komposition?
3. Was sind die dominanten Farben?
4. Welche Typografie wird verwendet?

Erstelle basierend auf dieser Analyse und der Nutzeranpassung "${adjustmentPrompt}" eine hochpräzise Beschreibung für ein Remake, das den Stil beibehaltet. Antworte auf Deutsch.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: sourceBase64.split(',')[1], mimeType: 'image/png' } },
          { text: analysisPrompt }
        ]
      }
    });

    // Hier übergeben wir das sourceBase64, da es eine direkte Überarbeitung (Remake) ist
    return generateThumbnail(response.text || adjustmentPrompt, 'Remake', "16:9", sourceBase64);
  } catch (e) {
    console.error("Remake fehlgeschlagen", e);
    throw e;
  }
};

export const generateThumbnail = async (prompt: string, style: string, aspectRatio: string = "16:9", base64Image?: string) => {
  const ai = getAI();

  // Intent-Analyse nur für rohe Nutzer-Prompts (nicht für bereits KI-optimierte Remake-Beschreibungen)
  let textInstruction = "";
  let finalVisualPrompt = prompt;

  if (!style.includes("Remake") && !style.includes("Klon-Stil")) {
    const intent = await analyzePromptIntent(prompt);
    if (intent) {
      finalVisualPrompt = intent.visualPrompt;
      if (intent.wantsText) {
        textInstruction = `Nutze fette, moderne Typografie für: "${intent.extractedText}". Der Text muss das zentrale, klickstarke Element sein.`;
      } else {
        textInstruction = `STRIKTE ANWEISUNG: KEIN TEXT im Bild. Keine Buchstaben, keine Zahlen.`;
      }
    }
  }

  const fullPrompt = `AUFGABE: Erstelle ein YouTube-Thumbnail. STIL: ${style}. MOTIV: ${finalVisualPrompt}. VORGABEN: Dramatische Beleuchtung, hoher Kontrast, klickstarke Farben. TEXT: ${textInstruction}. QUALITÄT: 4K, Ultra-Detail.`;

  const contents: any = {
    parts: [{ text: fullPrompt }]
  };

  if (base64Image) {
    const base64Data = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;
    contents.parts.push({
      inlineData: { data: base64Data, mimeType: 'image/png' }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents,
      config: { imageConfig: { aspectRatio: aspectRatio as any } }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return `data:image/png;base64,${imagePart.inlineData.data}`;
    }
    throw new Error("Kein Bildteil in der Antwort gefunden.");
  } catch (e) {
    console.error("Bilderzeugung fehlgeschlagen", e);
    throw e;
  }
};

export const analyzeThumbnailImage = async (base64Image: string) => {
  const ai = getAI();
  const prompt = `Analysiere dieses YouTube-Thumbnail auf Deutsch. Bewerte das CTR-Potenzial (0-10) und gib Verbesserungsvorschläge. Antworte STRENG im JSON Format auf Deutsch.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Image.split(',')[1], mimeType: 'image/png' } },
        { text: prompt }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          score: { type: Type.NUMBER },
          feedback: { type: Type.STRING },
          suggestions: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["score", "feedback", "suggestions"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const analyzeYoutubeChannel = async (channelUrl: string) => {
  const ai = getAI();
  const prompt = `Führe ein YouTube Thumbnail Audit auf Deutsch für ${channelUrl} durch. Analysiere Stil, Stärken, Schwächen und erstelle einen Aktionsplan. Antworte STRENG im JSON Format auf Deutsch.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          channelName: { type: Type.STRING },
          identitySummary: { type: Type.STRING },
          strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
          weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
          actionPlan: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["channelName", "identitySummary", "strengths", "weaknesses", "actionPlan"]
      }
    }
  });

  const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
  const result = JSON.parse(response.text || '{}');

  return {
    ...result,
    sources: groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || chunk.web?.uri,
      url: chunk.web?.uri
    })).filter((s: any) => s.url) || []
  };
};

import React, { useState, useEffect } from 'react';
import { Copy, Upload, Sparkles, Loader2, Download, Trash2, ArrowRight, Coins, Lightbulb, AlertCircle, Image as ImageIcon, Lock, Wand2 } from 'lucide-react';
import { remakeThumbnail, cloneStyle } from '../services/geminiService';
import { User } from '../types';

interface StudioRemakeProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
  isCloneMode?: boolean;
}

export const StudioRemake: React.FC<StudioRemakeProps> = ({ useCredits, user, isCloneMode = false }) => {
  const [sourceImage, setSourceImage] = useState<string | null>(null);
  const [adjustment, setAdjustment] = useState('');
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [result, setResult] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const isStarter = user?.plan === 'Starter';
  const toolCost = isCloneMode ? 30 : 20;

  useEffect(() => {
    let interval: any;
    if (loading) {
      setProgress(0);
      const steps = [
        { threshold: 25, text: isCloneMode ? "Stil-Fingerabdruck wird erstellt..." : "Stil-Elemente werden extrahiert..." },
        { threshold: 50, text: isCloneMode ? "Prompt wird an Stil angepasst..." : "Komposition wird gematcht..." },
        { threshold: 80, text: "Anpassungen werden gerendert..." },
        { threshold: 95, text: "Finalisierung..." }
      ];

      interval = setInterval(() => {
        setProgress(prev => {
          const next = prev + Math.random() * 6;
          const currentStep = steps.find(s => next <= s.threshold) || steps[steps.length - 1];
          setStatusText(currentStep.text);
          return next >= 98 ? 98 : next;
        });
      }, 500);
    } else {
      setProgress(0);
      setStatusText('');
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, isCloneMode]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setError(null);
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError("Bitte lade nur Bilddateien hoch.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => setSourceImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleRemake = async () => {
    if (!sourceImage) {
      setError("Bitte lade zuerst ein Referenzbild hoch.");
      return;
    }

    if (!user || user.credits < toolCost) {
      alert(`Du benötigst ${toolCost} Credits für dieses Tool.`);
      return;
    }

    setLoading(true);
    setResult(null);
    setError(null);
    try {
      let res;
      if (isCloneMode) {
        // Klont nur den Stil für ein komplett neues Motiv
        res = await cloneStyle(sourceImage, adjustment || "Ein interessantes YouTube-Motiv");
      } else {
        // Überarbeitet das bestehende Bild (Image-to-Image)
        res = await remakeThumbnail(sourceImage, adjustment);
      }

      useCredits(toolCost);
      setResult(res);
      setProgress(100);
    } catch (err: any) {
      console.error(err);
      setError("Der Vorgang ist fehlgeschlagen. " + (err.message || "Bitte versuche es erneut."));
    } finally {
      setTimeout(() => setLoading(false), 500);
    }
  };

  return (
    <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="grid lg:grid-cols-2 gap-12">
        <div className="space-y-8">

          {/* Starter Plan Info */}
          {isStarter && (
