import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Extrahiert den MIME-Typ aus einem Base64-String oder setzt einen Standardwert.
 */
const getMimeType = (base64: string): string => {
  const match = base64.match(/^data:([^;]+);base64,/);
  return match ? match[1] : 'image/png';
};

/**
 * Bereinigt Base64-Daten für die API (entfernt den Data-URL-Header).
 */
const cleanBase64 = (base64: string): string => {
  return base64.includes(',') ? base64.split(',')[1] : base64;
};

/**
 * Analysiert den Nutzerwunsch (Text vs. Bildinhalt).
 */
const analyzePromptIntent = async (prompt: string) => {
  const ai = getAI();

  const analysisPrompt = `Analysiere diesen YouTube-Thumbnail-Prompt: "${prompt}". 
  Bestimme, ob Text im Bild sein soll. Extrahiere den Text und erstelle eine visuelle Beschreibung.
  Antworte STRENG als JSON: { "wantsText": boolean, "extractedText": string|null, "visualPrompt": string }`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: analysisPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            wantsText: { type: Type.BOOLEAN },
            extractedText: { type: Type.STRING, nullable: true },
            visualPrompt: { type: Type.STRING }
          },
          required: ["wantsText", "visualPrompt"]
        }
      }
    });
    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Intent-Analyse fehlgeschlagen:", e);
    return null;
  }
};

/**
 * Klont den Stil eines Bildes und wendet ihn auf ein neues Motiv an.
 */
export const cloneStyle = async (sourceBase64: string, newMotifPrompt: string) => {
  const ai = getAI();

  const styleAnalysisPrompt = `Analyze the visual STYLE of this thumbnail image. 
  Describe the following for an image-to-image AI: color palette, lighting style, composition rules, and specific graphic treatments.
  Provide a concise style instruction in English that replicates this specific aesthetic.`;

  try {
    const analysisResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: cleanBase64(sourceBase64), mimeType: getMimeType(sourceBase64) } },
          { text: styleAnalysisPrompt }
        ]
      }
    });

    const styleInstructions = analysisResponse.text || "Modern vibrant high-contrast YouTube thumbnail style";

    // Generierung eines NEUEN Bildes basierend auf der extrahierten Stil-Beschreibung
    // Hier nutzen wir Text-to-Image mit dem analysierten Stil
    return generateThumbnail(newMotifPrompt, `Style Reference: ${styleInstructions}`, "16:9");
  } catch (e) {
    console.error("Style Cloning fehlgeschlagen:", e);
    throw new Error("Stil-Analyse des Referenzbildes fehlgeschlagen. Bitte versuche ein anderes Bild.");
  }
};

/**
 * Überarbeitet ein bestehendes Thumbnail (Image-to-Image / Inpainting-like).
 */
export const remakeThumbnail = async (sourceBase64: string, adjustmentPrompt: string) => {
  const ai = getAI();

  const analysisPrompt = `Look at this thumbnail and the user's request: "${adjustmentPrompt}".
  Describe the necessary visual changes in English to modify the original image while keeping the overall layout and character.
  Focus on specific elements to add, change, or remove.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: cleanBase64(sourceBase64), mimeType: getMimeType(sourceBase64) } },
          { text: analysisPrompt }
        ]
      }
    });

    // Hier nutzen wir Image-to-Image (Image + Text Prompt)
    return generateThumbnail(response.text || adjustmentPrompt, 'Remake Mode', "16:9", sourceBase64);
  } catch (e) {
    console.error("Remake fehlgeschlagen:", e);
    throw new Error("Analyse des Thumbnails fehlgeschlagen.");
  }
};

/**
 * Kern-Funktion zur Bilderzeugung (Unterstützt Text-to-Image und Image-to-Image).
 */
export const generateThumbnail = async (prompt: string, style: string, aspectRatio: string = "16:9", base64Image?: string) => {
  const ai = getAI();

  let textInstruction = "";
  let finalVisualPrompt = prompt;

  // Nur bei reiner Text-Generierung (kein Image-to-Image) den Intent prüfen
  if (!base64Image && !style.includes("Remake") && !style.includes("Style Reference")) {
    const intent = await analyzePromptIntent(prompt);
    if (intent) {
      finalVisualPrompt = intent.visualPrompt;
      textInstruction = intent.wantsText 
        ? `Incorporate this bold text: "${intent.extractedText}". The text should be eye-catching and readable.` 
        : "Do not include any text or letters in the image.";
    }
  }

  const fullPrompt = `Task: Create a professional YouTube thumbnail. 
  Style Description: ${style}. 
  Visual Subject: ${finalVisualPrompt}. 
  Technical requirements: High contrast, cinematic lighting, vibrant saturation, 4K quality, sharp details. 
  ${textInstruction}`;

  const parts: any[] = [{ text: fullPrompt }];

  // Wenn ein Basisbild vorhanden ist, fügen wir es als Referenz für Image-to-Image hinzu
  if (base64Image) {
    parts.unshift({
      inlineData: { 
        data: cleanBase64(base64Image), 
        mimeType: getMimeType(base64Image) 
      }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts },
      config: { 
        imageConfig: { 
          aspectRatio: aspectRatio as any
        } 
      }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      const mimeType = imagePart.inlineData.mimeType || 'image/png';
      return `data:${mimeType};base64,${imagePart.inlineData.data}`;
    }

    throw new Error("Die KI hat kein Bild generiert. Dies kann an Sicherheitsfiltern liegen.");
  } catch (e: any) {
    console.error("Gemini API Error:", e);
    throw new Error(e.message || "Bilderzeugung fehlgeschlagen.");
  }
};

export const analyzeThumbnailImage = async (base64Image: string) => {
  const ai = getAI();
  const prompt = `Analysiere dieses YouTube-Thumbnail auf Deutsch. Bewerte das CTR-Potenzial (0-10) und gib Verbesserungsvorschläge. Antworte STRENG im JSON Format.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: cleanBase64(base64Image), mimeType: getMimeType(base64Image) } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER },
            feedback: { type: Type.STRING },
            suggestions: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["score", "feedback", "suggestions"]
        }
      }
    });
    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Analyse fehlgeschlagen:", e);
    throw e;
  }
};

export const analyzeYoutubeChannel = async (channelUrl: string) => {
  const ai = getAI();
  const prompt = `Führe ein YouTube Thumbnail Audit für ${channelUrl} durch. Analysiere Stil, Stärken, Schwächen. Antworte als JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            channelName: { type: Type.STRING },
            identitySummary: { type: Type.STRING },
            strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
            actionPlan: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["channelName", "identitySummary", "strengths", "weaknesses", "actionPlan"]
        }
      }
    });

    const result = JSON.parse(response.text || '{}');
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    return {
      ...result,
      sources: groundingChunks?.map((chunk: any) => ({
        title: chunk.web?.title || chunk.web?.uri,
        url: chunk.web?.uri
      })).filter((s: any) => s.url) || []
    };
  } catch (e) {
    console.error("Channel Analyse fehlgeschlagen:", e);
    throw e;
  }
};

import React, { useState, useEffect } from 'react';
import { Copy, Upload, Sparkles, Loader2, Download, Trash2, ArrowRight, Coins, Lightbulb, AlertCircle, Image as ImageIcon, Lock, Wand2, RefreshCcw } from 'lucide-react';
import { remakeThumbnail, cloneStyle } from '../services/geminiService';
import { User } from '../types';

interface StudioRemakeProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
  isCloneMode?: boolean;
}

export const StudioRemake: React.FC<StudioRemakeProps> = ({ useCredits, user, isCloneMode = false }) => {
  const [sourceImage, setSourceImage] = useState<string | null>(null);
  const [adjustment, setAdjustment] = useState('');
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [result, setResult] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const isStarter = user?.plan === 'Starter';
  const toolCost = isCloneMode ? 30 : 20;

  useEffect(() => {
    let interval: any;
    if (loading) {
      setProgress(0);
      const steps = [
        { threshold: 25, text: isCloneMode ? "Stil-Fingerabdruck wird erstellt..." : "Bildinhalte werden analysiert..." },
        { threshold: 50, text: isCloneMode ? "Ästhetik wird auf Motiv übertragen..." : "Änderungen werden komponiert..." },
        { threshold: 80, text: "KI-Rendering läuft..." },
        { threshold: 95, text: "Finalisierung..." }
      ];

      interval = setInterval(() => {
        setProgress(prev => {
          const next = prev + (Math.random() * 4);
          const currentStep = steps.find(s => next <= s.threshold) || steps[steps.length - 1];
          setStatusText(currentStep.text);
          return next >= 98 ? 98 : next;
        });
      }, 600);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, isCloneMode]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setError(null);
    setResult(null);
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError("Bitte lade nur Bilddateien (JPG, PNG) hoch.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => setSourceImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleProcess = async () => {
    if (!sourceImage) {
      setError("Bitte lade zuerst ein Referenzbild hoch.");
      return;
    }

    if (!user || user.credits < toolCost) {
      setError(`Du benötigst mindestens ${toolCost} Credits für diese Funktion.`);
      return;
    }

    setLoading(true);
    setResult(null);
    setError(null);
    setProgress(5);

    try {
      let res;
      if (isCloneMode) {
        // Stil klonen: Nutzt das Bild zur Analyse und generiert ein neues Motiv
        res = await cloneStyle(sourceImage, adjustment || "A stunning YouTube thumbnail motif");
      } else {
        // Remake: Nutzt das Bild als Basis und modifiziert es
        res = await remakeThumbnail(sourceImage, adjustment || "Professional enhancement of the scene");
      }

      useCredits(toolCost);
      setResult(res);
      setProgress(100);
      setStatusText("Fertig!");
    } catch (err: any) {
      console.error("Studio Process Error:", err);
      setError(err.message || "Die Generierung ist fehlgeschlagen. Bitte versuche es mit einem anderen Bild oder Prompt.");
    } finally {
      setLoading(false);
    }
  };

  const resetTool = () => {
    setResult(null);
    setError(null);
    setProgress(0);
    setAdjustment('');
  };

  return (
    <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="grid lg:grid-cols-2 gap-12">
        <div className="space-y-8">

          {/* Header Card */}
          <div className={`p-6 border rounded-[2rem] flex items-center justify-between gap-6 ${isCloneMode ? 'bg-teal-600/5 border-teal-600/20' : 'bg-indigo-600/5 border-indigo-600/20'}`}>
            <div className="flex items-center gap-4">
              <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 ${isCloneMode ? 'bg-teal-600/10 text-teal-600' : 'bg-indigo-600/10 text-indigo-600'}`}>
                {isCloneMode ? <Sparkles className="w-6 h-6" /> : <Copy className="w-6 h-6" />}
              </div>
              <div>
                <h4 className="text-sm font-black uppercase tracking-widest mb-1 leading-none">
                  {isCloneMode ? 'Stil klonen' : 'Thumbnail Remake'}
                </h4>
                <p className="text-[10px] font-bold opacity-60 uppercase tracking-wider">
                  {isCloneMode ? 'Anderes Motiv, gleicher Look' : 'Bestehendes Bild modifizieren'}
                </p>
              </div>
            </div>
            <div className="flex items-center gap-1.5 text-xs font-black text-amber-500 bg-amber-500/10 px-4 py-2 rounded-2xl border border-amber-500/10">
              <Coins className="w-4 h-4" /> {toolCost}
            </div>
          </div>

          <div className="p-10 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl">
            <div className="space-y-8">
              {/* Upload area */}
              <div>
                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-3">Referenzbild hochladen</label>
                <div className={`relative h-64 border-2 border-dashed rounded-[2rem] flex flex-col items-center justify-center group overflow-hidden transition-all ${
                  sourceImage ? 'border-teal-500/40 bg-teal-500/5' : 'border-black/10 dark:border-white/10 hover:border-teal-500/30'
                }`}>
                  {sourceImage ? (
                    <>
                      <img src={sourceImage} className="w-full h-full object-cover opacity-80" alt="Upload" />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-3">
                         <button onClick={() => setSourceImage(null)} className="p-4 bg-red-500 text-white rounded-2xl shadow-xl hover:scale-110 transition-transform">
                           <Trash2 className="w-6 h-6" />
