};

import React, { useState, useEffect } from 'react';
import { User } from './types';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { HomeCategories } from './components/HomeCategories';
import { HowItWorks } from './components/HowItWorks';
import { Pricing } from './components/Pricing';
import { Reviews } from './components/Reviews';
import { AuthModal } from './components/AuthModal';
import { Examples } from './components/Examples';
import { StudioSelection } from './components/StudioSelection';
import { StudioGenerate } from './components/StudioGenerate';
import { StudioChannelAnalyze } from './components/StudioChannelAnalyze';
import { StudioAnalyze } from './components/StudioAnalyze';
import { StudioRemake } from './components/StudioRemake';
import { Snowfall } from './components/Snowfall';
import { BackgroundWaves } from './components/BackgroundWaves';
import { ArrowLeft, CheckCircle, X, AlertCircle, ShoppingCart, LayoutGrid, Youtube, ChevronRight } from 'lucide-react';
import { BACKGROUND_IMAGE, PricingPlan } from './constants';

type MainView = 'home' | 'pricing' | 'reviews' | 'examples' | 'studio';
type StudioView = 'suite-selection' | 'generate' | 'channel' | 'analyze' | 'remake' | 'clone';

const ExtremeGlow = () => (
  <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden select-none">
    <div className="absolute top-[-25%] left-[-15%] w-[110%] h-[110%] bg-blue-500/5 dark:bg-slate-800/10 blur-[250px] rounded-full animate-mesh opacity-60"></div>
    <div className="absolute bottom-[-25%] right-[-15%] w-[120%] h-[120%] bg-indigo-600/5 dark:bg-indigo-900/10 blur-[320px] rounded-full animate-mesh opacity-60" style={{ animationDelay: '-8s' }}></div>
  </div>
);

function App() {
  const [user, setUser] = React.useState<User | null>(null);
  const [currentView, setCurrentView] = React.useState<MainView>('home');
  const [studioView, setStudioView] = React.useState<StudioView>('suite-selection');
  const [isAuthOpen, setIsAuthOpen] = React.useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [purchaseSuccess, setPurchaseSuccess] = useState<{ planName: string, amount: number } | null>(null);

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'light') setIsDarkMode(false);
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const handleLogin = (email: string) => {
    setUser({ 
      id: '1', 
      email: email, 
      name: email.split('@')[0], 
      credits: 30, 
      isLoggedIn: true,
      plan: 'Starter'
    });
    setIsAuthOpen(false);
    setCurrentView('studio');
    setStudioView('suite-selection');
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView('home');
    setStudioView('suite-selection');
  };

  const useCredits = (amount: number): boolean => {
    if (!user || user.credits < amount) {
      setCurrentView('pricing');
      return false;
    }
    setUser({ ...user, credits: user.credits - amount });
    return true;
  };

  const handlePurchase = (plan: PricingPlan) => {
    if (!user) {
      setIsAuthOpen(true);
      return;
    }
    setUser({ ...user, credits: user.credits + plan.credits, plan: plan.name as any });
    setPurchaseSuccess({ planName: plan.name, amount: plan.credits });
    setTimeout(() => setPurchaseSuccess(null), 5000);
    setCurrentView('studio');
  };

  const handleNavigate = (view: MainView) => {
    if (view === currentView) {
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }

    if (view === 'studio' && !user) {
      setIsAuthOpen(true);
      return;
    }
    setCurrentView(view);
    if (view === 'studio') setStudioView('suite-selection');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSelectCategory = (category: 'suite' | 'channel') => {
    if (!user) {
      setIsAuthOpen(true);
      return;
    }
    setCurrentView('studio');
    setStudioView(category === 'suite' ? 'suite-selection' : 'channel');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSelectStudioTool = (tool: StudioView) => {
    setStudioView(tool);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const BackButton = ({ onClick, label = "Zurück" }: { onClick: () => void, label?: string }) => (
    <button 
      onClick={onClick}
      className="fixed top-36 left-4 lg:left-8 z-40 flex items-center gap-2 px-5 py-2.5 bg-white/80 dark:bg-slate-800/80 hover:bg-white dark:hover:bg-slate-800 border border-black/5 dark:border-white/10 rounded-full text-xs font-black uppercase tracking-widest transition-all group shadow-xl backdrop-blur-md text-slate-900 dark:text-slate-100"
    >
      <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
      {label}
    </button>
  );

  const WorkspaceSwitcher = () => {
    const isChannel = studioView === 'channel';
    return (
      <div className="fixed top-24 left-1/2 -translate-x-1/2 z-50 px-2 py-2 bg-white/40 dark:bg-slate-900/40 backdrop-blur-2xl border border-black/5 dark:border-white/10 rounded-2xl flex items-center gap-1 shadow-2xl">
        <button
          onClick={() => setStudioView('suite-selection')}
          className={`px-5 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all flex items-center gap-2 ${
            !isChannel 
              ? 'bg-orange-600 text-white shadow-lg shadow-orange-600/20' 
              : 'text-slate-500 dark:text-slate-400 hover:text-orange-600 dark:hover:text-orange-400'
          }`}
        >
          <LayoutGrid className="w-4 h-4" />
          Thumbnail-Suite
        </button>
        <button
          onClick={() => setStudioView('channel')}
          className={`px-5 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all flex items-center gap-2 ${
            isChannel 
              ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/20' 
              : 'text-slate-500 dark:text-slate-400 hover:text-blue-600 dark:hover:text-blue-400'
          }`}
        >
          <Youtube className="w-4 h-4" />
          Kanal-Analyse
        </button>
      </div>
    );
  };

  return (
    <div className={`min-h-screen transition-colors duration-500 selection:bg-orange-500 selection:text-white ${isDarkMode ? 'bg-[#020617] text-slate-100' : 'bg-slate-50 text-slate-900'} relative`}>

      <Snowfall />
      <BackgroundWaves />
      <ExtremeGlow />
      <div className="mesh-gradient opacity-90"></div>

      <Navbar 
        user={user} 
        onNavigate={handleNavigate} 
        onLoginClick={() => setIsAuthOpen(true)} 
        onLogout={handleLogout}
        isDarkMode={isDarkMode}
        toggleTheme={toggleTheme}
      />

      <main className="relative z-10">
        {currentView === 'home' && (
          <div className="animate-in fade-in duration-700">
            <Hero onStartCreating={() => handleSelectCategory('suite')} onViewPricing={() => handleNavigate('pricing')} />
            <HowItWorks onExplore={() => handleNavigate('studio')} />
            <HomeCategories onSelectCategory={handleSelectCategory} />
            <Reviews />
            <Pricing onPurchase={handlePurchase} />
          </div>
        )}

        {currentView === 'studio' && (
          <div className="pt-48 pb-20 min-h-screen">
            <WorkspaceSwitcher />

            {studioView === 'suite-selection' && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                <BackButton onClick={() => setCurrentView('home')} label="Abbrechen" />
                <StudioSelection 
                  user={user} 
                  onSelectMode={(mode) => handleSelectStudioTool(mode as StudioView)} 
                  onGoToPricing={() => handleNavigate('pricing')}
                />
              </div>
            )}

            {studioView === 'generate' && (
              <div className="animate-in fade-in slide-in-from-right-4">
                <BackButton onClick={() => setStudioView('suite-selection')} label="Suite Übersicht" />
                <StudioGenerate useCredits={useCredits} user={user} onGoToPricing={() => handleNavigate('pricing')} />
              </div>
            )}

            {studioView === 'remake' && (
              <div className="animate-in fade-in slide-in-from-right-4">
                <BackButton onClick={() => setStudioView('suite-selection')} label="Suite Übersicht" />
                <StudioRemake useCredits={useCredits} user={user} />
              </div>
            )}

            {studioView === 'clone' && (
              <div className="animate-in fade-in slide-in-from-right-4">
                <BackButton onClick={() => setStudioView('suite-selection')} label="Suite Übersicht" />
                <StudioRemake useCredits={useCredits} user={user} isCloneMode={true} />
              </div>
            )}

            {studioView === 'analyze' && (
              <div className="animate-in fade-in slide-in-from-right-4">
                <BackButton onClick={() => setStudioView('suite-selection')} label="Suite Übersicht" />
                <StudioAnalyze useCredits={useCredits} user={user} />
              </div>
            )}

            {studioView === 'channel' && (
              <div className="animate-in fade-in slide-in-from-right-4">
                <BackButton onClick={() => setCurrentView('home')} label="Startseite" />
                <StudioChannelAnalyze useCredits={useCredits} user={user} />
              </div>
            )}
          </div>
        )}

        {currentView === 'pricing' && <div className="pt-24 min-h-screen"><BackButton onClick={() => handleNavigate('home')} /><Pricing onPurchase={handlePurchase} /></div>}
        {currentView === 'reviews' && <div className="pt-24 min-h-screen"><BackButton onClick={() => handleNavigate('home')} /><Reviews /></div>}
        {currentView === 'examples' && <div className="pt-24 min-h-screen"><BackButton onClick={() => handleNavigate('home')} /><Examples onNavigateToStudio={() => handleSelectCategory('suite')} /></div>}
      </main>

      <AuthModal isOpen={isAuthOpen} onClose={() => setIsAuthOpen(false)} onLogin={handleLogin} />

      {purchaseSuccess && (
        <div className="fixed bottom-8 right-8 z-[110] animate-in slide-in-from-right-8 duration-500">
          <div className="bg-emerald-600 text-white rounded-3xl p-6 shadow-2xl flex items-center gap-4">
            <CheckCircle className="w-8 h-8" />
            <div>
              <p className="font-black uppercase text-xs tracking-widest">Kauf erfolgreich</p>
              <p className="text-sm font-medium">+{purchaseSuccess.amount} Credits hinzugefügt.</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

