import React, { useState, useRef, useEffect } from 'react';

export const ComparisonSlider: React.FC = () => {
  const [position, setPosition] = useState(50);
  const containerRef = useRef<HTMLDivElement>(null);

  const handleMove = (clientX: number) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
    setPosition((x / rect.width) * 100);
  };

  const onMouseMove = (e: React.MouseEvent) => handleMove(e.clientX);
  const onTouchMove = (e: React.TouchEvent) => handleMove(e.touches[0].clientX);

  return (
    <div 
      ref={containerRef}
      className="relative w-full aspect-video rounded-[2.5rem] overflow-hidden cursor-ew-resize shadow-2xl border-4 border-white dark:border-slate-800 select-none group"
      onMouseMove={onMouseMove}
      onTouchMove={onTouchMove}
    >
      {/* After Image (Optimized) */}
      <div className="absolute inset-0">
        <img 
          src="https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&q=80&w=1200" 
          className="w-full h-full object-cover grayscale-0 saturate-[1.4] contrast-[1.1]"
          alt="After KI Optimization"
        />
        <div className="absolute top-6 right-6 px-4 py-2 bg-blue-600 text-white text-[10px] font-black uppercase rounded-full shadow-lg">
          Optimiert mit KI
        </div>
      </div>

      {/* Before Image (Raw) */}
      <div 
        className="absolute inset-0" 
        style={{ width: `${position}%`, overflow: 'hidden' }}
      >
        <img 
          src="https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&q=80&w=1200" 
          className="w-full h-full object-cover grayscale saturate-[0.5] brightness-75"
          style={{ width: `${100 / (position / 100)}%` }}
          alt="Before Optimization"
        />
        <div className="absolute top-6 left-6 px-4 py-2 bg-white/20 backdrop-blur-md text-white text-[10px] font-black uppercase rounded-full border border-white/20">
          Rohaufnahme
        </div>
      </div>

      {/* Slider Divider */}
      <div 
        className="absolute inset-y-0 w-1 bg-white shadow-[0_0_15px_rgba(255,255,255,0.5)] z-20"
        style={{ left: `${position}%` }}
      >
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-10 h-10 bg-white rounded-full shadow-xl flex items-center justify-center group-hover:scale-110 transition-transform">
          <div className="flex gap-1">
            <div className="w-1 h-3 bg-slate-300 rounded-full"></div>
            <div className="w-1 h-3 bg-slate-300 rounded-full"></div>
          </div>
        </div>
      </div>
    </div>
  );
};

