import React, { useState, useEffect } from 'react';
import { Copy, Upload, Sparkles, Loader2, Download, Trash2, ArrowRight, Coins, Lightbulb, AlertCircle, Image as ImageIcon, Lock, Wand2, RefreshCcw } from 'lucide-react';
import { remakeThumbnail, cloneStyle } from '../services/geminiService';
import { User } from '../types';

interface StudioRemakeProps {
useCredits: (amount: number) => boolean;
user: User | null;
isCloneMode?: boolean;
}

export const StudioRemake: React.FC<StudioRemakeProps> = ({ useCredits, user, isCloneMode = false }) => {
const [sourceImage, setSourceImage] = useState<string | null>(null);
const [adjustment, setAdjustment] = useState('');
const [loading, setLoading] = useState(false);
const [progress, setProgress] = useState(0);
const [statusText, setStatusText] = useState('');
const [result, setResult] = useState<string | null>(null);
const [error, setError] = useState<string | null>(null);

const isStarter = user?.plan === 'Starter';
const toolCost = isCloneMode ? 30 : 20;

useEffect(() => {
  let interval: any;
  if (loading) {
    setProgress(0);
    const steps = [
      { threshold: 25, text: isCloneMode ? "Stil-Fingerabdruck wird erstellt..." : "Bildinhalte werden analysiert..." },
      { threshold: 50, text: isCloneMode ? "Ästhetik wird auf Motiv übertragen..." : "Änderungen werden komponiert..." },
      { threshold: 80, text: "KI-Rendering läuft..." },
      { threshold: 95, text: "Finalisierung..." }
    ];

    interval = setInterval(() => {
      setProgress(prev => {
        const next = prev + (Math.random() * 4);
        const currentStep = steps.find(s => next <= s.threshold) || steps[steps.length - 1];
        setStatusText(currentStep.text);
        return next >= 98 ? 98 : next;
      });
    }, 600);
  } else {
    clearInterval(interval);
  }
  return () => clearInterval(interval);
}, [loading, isCloneMode]);

const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
  const file = e.target.files?.[0];
  setError(null);
  setResult(null);
  if (file) {
    if (!file.type.startsWith('image/')) {
      setError("Bitte lade nur Bilddateien (JPG, PNG) hoch.");
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => setSourceImage(reader.result as string);
    reader.readAsDataURL(file);
  }
};

const handleProcess = async () => {
  if (!sourceImage) {
    setError("Bitte lade zuerst ein Referenzbild hoch.");
    return;
  }

  if (!user || user.credits < toolCost) {
    setError(`Du benötigst mindestens ${toolCost} Credits für diese Funktion.`);
    return;
  }

  setLoading(true);
  setResult(null);
  setError(null);
  setProgress(5);

  try {
    let res;
    if (isCloneMode) {
      // Stil klonen: Nutzt das Bild zur Analyse und generiert ein neues Motiv
      res = await cloneStyle(sourceImage, adjustment || "A stunning YouTube thumbnail motif");
    } else {
      // Remake: Nutzt das Bild als Basis und modifiziert es
      res = await remakeThumbnail(sourceImage, adjustment || "Professional enhancement of the scene");
    }

    useCredits(toolCost);
    setResult(res);
    setProgress(100);
    setStatusText("Fertig!");
  } catch (err: any) {
    console.error("Studio Process Error:", err);
    setError(err.message || "Die Generierung ist fehlgeschlagen. Bitte versuche es mit einem anderen Bild oder Prompt.");
  } finally {
    setLoading(false);
  }
};

const resetTool = () => {
  setResult(null);
  setError(null);
  setProgress(0);
  setAdjustment('');
};

return (
  <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-700">
    <div className="grid lg:grid-cols-2 gap-12">
      <div className="space-y-8">

        {/* Header Card */}
        <div className={`p-6 border rounded-[2rem] flex items-center justify-between gap-6 ${isCloneMode ? 'bg-teal-600/5 border-teal-600/20' : 'bg-indigo-600/5 border-indigo-600/20'}`}>
          <div className="flex items-center gap-4">
            <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 ${isCloneMode ? 'bg-teal-600/10 text-teal-600' : 'bg-indigo-600/10 text-indigo-600'}`}>
              {isCloneMode ? <Sparkles className="w-6 h-6" /> : <Copy className="w-6 h-6" />}
            </div>
            <div>
              <h4 className="text-sm font-black uppercase tracking-widest mb-1 leading-none">
                {isCloneMode ? 'Stil klonen' : 'Thumbnail Remake'}
              </h4>
              <p className="text-[10px] font-bold opacity-60 uppercase tracking-wider">
                {isCloneMode ? 'Anderes Motiv, gleicher Look' : 'Bestehendes Bild modifizieren'}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-1.5 text-xs font-black text-amber-500 bg-amber-500/10 px-4 py-2 rounded-2xl border border-amber-500/10">
            <Coins className="w-4 h-4" /> {toolCost}
          </div>
        </div>

        <div className="p-10 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl">
          <div className="space-y-8">
            {/* Upload area */}
            <div>
              <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-3">Referenzbild hochladen</label>
              <div className={`relative h-64 border-2 border-dashed rounded-[2rem] flex flex-col items-center justify-center group overflow-hidden transition-all ${
                sourceImage ? 'border-teal-500/40 bg-teal-500/5' : 'border-black/10 dark:border-white/10 hover:border-teal-500/30'
              }`}>
                {sourceImage ? (
                  <>
                    <img src={sourceImage} className="w-full h-full object-cover opacity-80" alt="Upload" />
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-3">
                       <button onClick={() => setSourceImage(null)} className="p-4 bg-red-500 text-white rounded-2xl shadow-xl hover:scale-110 transition-transform">
                         <Trash2 className="w-4 h-4" />
                       </button>
                    </div>
                  </>
                ) : (
                  <>
                    <Upload className="w-12 h-12 text-slate-300 mb-4 group-hover:scale-110 transition-transform" />
                    <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Bild wählen oder hierher ziehen</span>
                    <input type="file" accept="image/*" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
                  </>
                )}
              </div>
            </div>

            {/* Input Area */}
            <div>
              <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-3">
                {isCloneMode ? 'Was soll im neuen Bild zu sehen sein?' : 'Was soll am Bild geändert werden?'}
              </label>
              <textarea 
                value={adjustment}
                onChange={(e) => setAdjustment(e.target.value)}
                placeholder={isCloneMode ? "z.B. Ein glücklicher Gamer, der einen Award hält..." : "z.B. Ersetze das Auto durch ein rotes Motorrad..."}
                className="w-full h-32 bg-slate-50 dark:bg-slate-800/50 border border-black/5 dark:border-white/5 rounded-2xl p-5 focus:ring-4 focus:ring-teal-500/10 outline-none transition-all resize-none font-medium text-sm text-slate-900 dark:text-white"
              />
            </div>

            {error && (
              <div className="p-4 bg-red-500/10 border border-red-500/20 text-red-600 dark:text-red-400 rounded-2xl text-xs font-bold flex items-center gap-3 animate-in fade-in zoom-in-95">
                 <AlertCircle className="w-5 h-5 shrink-0" />
                 {error}
              </div>
            )}

            {loading && (
              <div className="space-y-3">
                <div className="flex justify-between items-end">
                  <span className="text-[10px] font-black uppercase tracking-widest text-teal-500 animate-pulse">{statusText}</span>
                  <span className="text-[10px] font-black text-slate-400">{Math.round(progress)}%</span>
                </div>
                <div className="h-2 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-teal-600 transition-all duration-300 ease-out shadow-[0_0_15px_rgba(20,184,166,0.4)]"
                    style={{ width: `${progress}%` }}
                  ></div>
                </div>
              </div>
            )}

            <button 
              onClick={handleProcess}
              disabled={loading || !sourceImage}
              className={`w-full py-5 rounded-2xl font-black text-lg flex items-center justify-center gap-3 shadow-xl transition-all active:scale-95 disabled:opacity-40 disabled:grayscale ${
                isCloneMode ? 'bg-teal-600 hover:bg-teal-700 shadow-teal-600/20' : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-600/20'
              } text-white`}
            >
              {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : (isCloneMode ? <Sparkles className="w-6 h-6" /> : <Copy className="w-6 h-6" />)}
              {isCloneMode ? 'Stil jetzt klonen' : 'Remake starten'}
            </button>
          </div>
        </div>
      </div>

      {/* Results Area */}
      <div className="flex flex-col justify-center">
        {result ? (
          <div className="space-y-6 animate-in zoom-in-95 duration-500">
            <div className="aspect-video rounded-[3rem] overflow-hidden shadow-2xl border-4 border-white dark:border-slate-800 relative group bg-slate-100 dark:bg-slate-800">
              <img src={result} className="w-full h-full object-cover" alt="Generiertes Ergebnis" />
              <div className="absolute top-4 left-4 px-4 py-2 bg-black/60 backdrop-blur-md text-white text-[10px] font-black uppercase rounded-xl border border-white/10">
                  Ergebnis bereit
              </div>
              {isStarter && (
                <div className="absolute bottom-4 right-4 bg-black/50 backdrop-blur-md px-4 py-2 rounded-xl border border-white/20 text-white/50 text-[10px] font-black uppercase tracking-widest pointer-events-none select-none">
                  Made with Thumbify AI
                </div>
              )}
            </div>
            <div className="flex gap-4">
              <button 
                onClick={() => {
                  const link = document.createElement('a');
                  link.href = result;
                  link.download = `thumbcraft_${isCloneMode ? 'style_clone' : 'remake'}_${Date.now()}.png`;
                  link.click();
                }}
                className="flex-1 py-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl font-black flex items-center justify-center gap-3 shadow-xl transition-all active:scale-95"
              >
                <Download className="w-6 h-6" /> Download 4K
