  const getInitials = (name: string) => name.charAt(0).toUpperCase();

  return (
    <nav className="fixed top-0 left-0 right-0 z-[60] glass border-b border-black/5 dark:border-white/5">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-24">

          <div 
            className="flex items-center gap-3 cursor-pointer group" 
            onClick={() => onNavigate('home')}
          >
            <div className="bg-orange-600 p-2 rounded-xl shadow-lg shadow-orange-600/20 group-hover:scale-110 transition-transform">
              <Zap className="w-5 h-5 text-white fill-white" />
            </div>
            <span className="text-2xl font-black tracking-tight hidden sm:block text-slate-900 dark:text-white">ThumbCraft <span className="text-orange-600">AI</span></span>
          </div>

          <div className="hidden lg:flex items-center gap-1 bg-white/50 dark:bg-white/5 border border-black/5 p-1.5 rounded-2xl absolute left-1/2 -translate-x-1/2 shadow-sm">
            <NavLink onClick={() => onNavigate('pricing')}>Preise</NavLink>
            <NavLink onClick={() => onNavigate('examples')} icon={Sparkles}>Beispiele</NavLink>
            <NavLink onClick={() => onNavigate('reviews')} icon={Star}>Bewertungen</NavLink>
            <NavLink onClick={() => onNavigate('studio')} icon={LayoutGrid}>Studio</NavLink>

            <button 
              onClick={() => onNavigate('home')}
              className="mx-2 px-6 py-2 bg-orange-600 hover:bg-orange-700 text-white rounded-xl font-black text-sm transition-all flex items-center gap-2 shadow-xl shadow-orange-600/20 active:scale-95"
            >
              <Home className="w-4 h-4" />
              Startseite
            </button>
          </div>

          <div className="flex items-center gap-2 md:gap-4">
            <button
              onClick={toggleTheme}
              className="p-2.5 rounded-xl bg-slate-100 dark:bg-slate-800 border border-black/5 dark:border-white/5 transition-all active:scale-90 group"
              title={isDarkMode ? "Hellmodus aktivieren" : "Dunkelmodus aktivieren"}
            >
              {isDarkMode ? (
                <Sun className="w-5 h-5 text-amber-500 animate-in zoom-in-50 duration-300" />
              ) : (
                <Moon className="w-5 h-5 text-orange-600 animate-in zoom-in-50 duration-300" />
              )}
            </button>

            <div className="hidden lg:flex items-center gap-4">
              {user && (
                <div className="flex items-center gap-3">
                  <button 
                    onClick={() => onNavigate('pricing')}
                    className={`flex items-center gap-2 px-4 py-2 border rounded-2xl font-black text-sm shadow-sm transition-all ${
                      isLowCredits 
                        ? 'bg-amber-500 text-white border-amber-600 shadow-lg shadow-amber-500/20' 
                        : 'bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/20'
                    }`}
                  >
                    {isLowCredits ? <AlertTriangle className="w-4 h-4" /> : <Coins className="w-4 h-4" />}
                    {user.credits} Credits
                  </button>

                  {/* Profile Menu Dropdown */}
                  <div className="relative" ref={profileRef}>
                    <button 
                      onClick={() => setIsProfileOpen(!isProfileOpen)}
                      className="w-10 h-10 rounded-full bg-gradient-to-br from-orange-500 to-blue-600 flex items-center justify-center text-white font-black text-sm shadow-lg hover:scale-105 active:scale-95 transition-all border-2 border-white dark:border-slate-800"
                    >
                      {getInitials(user.name)}
                    </button>

                    {isProfileOpen && (
                      <div className="absolute right-0 mt-4 w-72 bg-white dark:bg-slate-900 rounded-[2rem] border border-black/5 dark:border-white/10 shadow-2xl animate-in fade-in zoom-in-95 duration-200 p-2">
                        <div className="p-4 border-b border-black/5 dark:border-white/5">
                          <div className="flex items-center gap-3 mb-3">
                            <div className="w-12 h-12 rounded-2xl bg-orange-600 flex items-center justify-center text-white font-black text-lg">
                              {getInitials(user.name)}
                            </div>
                            <div className="flex-1 min-w-0">
                              <p className="text-sm font-black text-slate-900 dark:text-white truncate leading-none mb-1">{user.name}</p>
                              <p className="text-[10px] text-slate-500 dark:text-slate-400 truncate">{user.email}</p>
                            </div>
                          </div>
                          <div className="flex items-center justify-between bg-slate-50 dark:bg-slate-800/50 p-3 rounded-xl">
                            <div className="flex items-center gap-2 text-[10px] font-black text-slate-500 uppercase tracking-widest">
                              <Shield className="w-3.5 h-3.5 text-orange-600" />
                              Plan: {user.plan}
                            </div>
                            <button 
                              onClick={() => { onNavigate('pricing'); setIsProfileOpen(false); }}
                              className="text-[10px] font-black text-orange-600 uppercase tracking-widest hover:underline"
                            >
                              Upgrade
                            </button>
                          </div>
                        </div>

                        <div className="p-2 space-y-1">
                          <button 
                            className="w-full flex items-center gap-3 px-4 py-3 text-sm font-bold text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl transition-colors"
                            onClick={() => setIsProfileOpen(false)}
                          >
                            <UserIcon className="w-4 h-4" /> Mein Profil
                          </button>
                          <button 
                            className="w-full flex items-center gap-3 px-4 py-3 text-sm font-bold text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800 rounded-xl transition-colors"
                            onClick={() => setIsProfileOpen(false)}
                          >
                            <Settings className="w-4 h-4" /> Einstellungen
                          </button>
                          <div className="h-px bg-black/5 dark:border-white/5 my-1" />
                          <button 
                            onClick={() => { onLogout(); setIsProfileOpen(false); }}
                            className="w-full flex items-center gap-3 px-4 py-3 text-sm font-bold text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 rounded-xl transition-colors"
                          >
                            <LogOut className="w-4 h-4" /> Abmelden
                          </button>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              )}
              {!user && (
                <button 
                  onClick={onLoginClick}
                  className="px-8 py-3 bg-orange-600 text-white hover:bg-orange-700 rounded-2xl font-black transition-all active:scale-95 shadow-xl shadow-orange-600/20"
                >
                  Anmelden
                </button>
              )}
            </div>

            <div className="lg:hidden flex items-center gap-2">
               {user && (
                <button 
                  onClick={() => onNavigate('pricing')}
                  className="p-2.5 bg-amber-500/10 text-amber-600 rounded-xl"
                >
                  <Coins className="w-5 h-5" />
                </button>
              )}
              <button 
                onClick={() => setIsOpen(!isOpen)} 
                className="p-2 text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-colors"
              >
                {isOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
              </button>
            </div>
          </div>
        </div>
      </div>

      {isOpen && (
        <div className="lg:hidden glass border-t border-black/5 p-4 space-y-6 animate-in slide-in-from-top-4 duration-300 max-h-[90vh] overflow-y-auto pb-10">
          {user && (
            <div className="flex items-center gap-4 p-4 bg-slate-50 dark:bg-slate-800/50 rounded-3xl border border-black/5">
              <div className="w-12 h-12 rounded-2xl bg-orange-600 flex items-center justify-center text-white font-black text-xl">
                {getInitials(user.name)}
              </div>
              <div className="flex-1">
                <p className="text-sm font-black text-slate-900 dark:text-white leading-none mb-1">{user.name}</p>
                <div className={`flex items-center gap-1.5 text-[10px] font-black uppercase ${isLowCredits ? 'text-amber-500' : 'text-orange-600'}`}>
                  <Coins className="w-3 h-3" /> {user.credits} Credits verfügbar
                </div>
              </div>
              <button className="p-2 text-slate-400">
                <Settings className="w-5 h-5" />
              </button>
            </div>
          )}

          <div className="space-y-3">
            <p className="px-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Navigation</p>
            <div className="grid grid-cols-2 gap-2">
              <button 
                onClick={() => handleMobileNav('home')} 
                className="flex flex-col items-center justify-center gap-2 py-6 bg-orange-600 text-white rounded-[2rem] font-black shadow-lg shadow-orange-600/20 active:scale-95 transition-all"
              >
                <Home className="w-6 h-6" /> <span className="text-xs">Startseite</span>
              </button>
              <button 
                onClick={() => handleMobileNav('pricing')} 
                className="flex flex-col items-center justify-center gap-2 py-6 bg-white dark:bg-slate-800 border border-black/5 rounded-[2rem] font-black active:scale-95 transition-all shadow-sm"
              >
                <CreditCard className="w-6 h-6 text-orange-500" /> <span className="text-xs">Preise</span>
              </button>
              <button 
                onClick={() => handleMobileNav('examples')} 
                className="flex flex-col items-center justify-center gap-2 py-6 bg-white dark:bg-slate-800 border border-black/5 rounded-[2rem] font-black active:scale-95 transition-all shadow-sm"
              >
                <Sparkles className="w-6 h-6 text-blue-500" /> <span className="text-xs">Beispiele</span>
              </button>
              <button 
