import React from 'react';
import { Wand2, ChevronRight, Lock, Coins, Target, Sparkles, LayoutGrid, AlertCircle } from 'lucide-react';
import { User } from '../types';

interface StudioSelectionProps {
  user: User | null;
  onSelectMode: (mode: string) => void;
  onGoToPricing?: () => void;
}

export const StudioSelection: React.FC<StudioSelectionProps> = ({ user, onSelectMode, onGoToPricing }) => {
  const currentPlan = user?.plan || 'Starter';
  const userCredits = user?.credits || 0;

  const checkPlanPermission = (planRequired: string) => {
    if (planRequired === 'Starter') return true;
    if (planRequired === 'Creator Pro') return currentPlan === 'Creator Pro' || currentPlan === 'Production';
    return currentPlan === 'Production';
  };

  const suiteModes = [
    {
      id: 'generate',
      title: 'Thumbnail generieren',
      description: 'Erstelle hochkonvertierende Designs von Grund auf mit präzisen KI-Text-Prompts.',
      icon: <Wand2 className="w-8 h-8" />,
      lightColor: 'bg-teal-500/10',
      textColor: 'text-teal-600',
      cost: 10,
      planRequired: 'Starter'
    },
    {
      id: 'clone',
      title: 'Stil klonen',
      description: 'Extrahiere die visuelle Identität einer Referenz und wende sie auf dein neues Motiv an.',
      icon: <Sparkles className="w-8 h-8" />,
      lightColor: 'bg-blue-500/10',
      textColor: 'text-blue-600',
      cost: 30,
      planRequired: 'Starter'
    },
    {
      id: 'analyze',
      title: 'Performance analysieren',
      description: 'Erhalte datengestützte Insights und CTR-Vorhersagen für deinen finalen Thumbnail-Entwurf.',
      icon: <Target className="w-8 h-8" />,
      lightColor: 'bg-emerald-500/10',
      textColor: 'text-emerald-600',
      cost: 50,
      planRequired: 'Creator Pro'
    }
  ];

  const handleToolClick = (mode: any) => {
    const hasPlan = checkPlanPermission(mode.planRequired);
    const hasCredits = userCredits >= mode.cost;

    if (!hasPlan || !hasCredits) {
      if (onGoToPricing) onGoToPricing();
      return;
    }

    onSelectMode(mode.id);
  };

  return (
    <div className="px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto">
        <div className="text-center mb-16">
          <div className="w-20 h-20 rounded-3xl bg-teal-600/10 flex items-center justify-center mx-auto mb-8 text-teal-600">
            <div className="relative">
              <div className="absolute inset-0 bg-teal-400 blur-xl opacity-20 animate-pulse"></div>
              <LayoutGrid className="w-10 h-10 relative" />
            </div>
          </div>
          <h1 className="text-5xl md:text-7xl font-black tracking-tight mb-6">
            Thumbnail-<span className="gradient-text">Suite</span>
          </h1>
          <p className="text-xl text-slate-500 dark:text-slate-400 font-medium max-w-2xl mx-auto">
            Drei spezialisierte Tools für deine YouTube-Dominanz. Wähle dein Werkzeug.
          </p>
        </div>

        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-8">
          {suiteModes.map((mode) => {
            const hasPlan = checkPlanPermission(mode.planRequired);
            const hasCredits = userCredits >= mode.cost;
            const isLocked = !hasPlan || !hasCredits;

            return (
              <button
                key={mode.id}
                onClick={() => handleToolClick(mode)}
                className={`group relative flex flex-col p-10 bg-white/70 dark:bg-slate-900/40 backdrop-blur-xl border border-black/5 dark:border-white/10 rounded-[3rem] text-left transition-all hover:-translate-y-3 hover:shadow-2xl active:scale-[0.98] overflow-hidden h-full ${
                  isLocked ? 'grayscale-[0.8] opacity-80' : ''
                }`}
              >
                <div className="absolute top-6 right-6 z-20 flex flex-col items-end gap-2">
                  {!hasPlan && (
                    <div className="p-2 bg-slate-900 text-white rounded-xl flex items-center gap-1.5 text-[10px] font-black uppercase shadow-lg">
                      <Lock className="w-3 h-3" /> Upgrade
                    </div>
                  )}
                  {!hasCredits && hasPlan && (
                    <div className="p-2 bg-red-600 text-white rounded-xl flex items-center gap-1.5 text-[10px] font-black uppercase shadow-lg">
                      <AlertCircle className="w-3 h-3" /> Credits nötig
                    </div>
                  )}
                  <div className={`p-2 rounded-xl flex items-center gap-1.5 text-[10px] font-black uppercase border ${
                    !hasCredits ? 'bg-red-500/10 text-red-500 border-red-500/20' : 'bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/10'
                  }`}>
                    <Coins className="w-3.5 h-3.5" /> {mode.cost}
                  </div>
                </div>

                <div className="relative z-10 flex flex-col h-full">
                  <div className={`w-16 h-16 rounded-2xl ${mode.lightColor} ${mode.textColor} flex items-center justify-center mb-8 shadow-inner transition-transform group-hover:scale-110`}>
                    {mode.icon}
                  </div>

                  <h3 className="text-2xl font-black mb-4">
                    {mode.title}
                  </h3>

                  <p className="text-base text-slate-500 dark:text-slate-400 font-medium leading-relaxed mb-10 flex-1">
                    {mode.description}
                  </p>

                  <div className={`inline-flex items-center gap-2 font-black text-xs uppercase tracking-widest transition-all ${
                    isLocked ? 'text-slate-400' : 'group-hover:text-teal-600'
                  }`}>
                    {isLocked ? (
                      <span className="flex items-center gap-2">Aufstocken zum Freischalten <ChevronRight className="w-4 h-4" /></span>
                    ) : (
                      <span className="flex items-center gap-2">Tool starten <ChevronRight className="w-4 h-4 group-hover:translate-x-2 transition-transform" /></span>
                    )}
                  </div>
                </div>

                {isLocked && (
                  <div className="absolute inset-0 bg-slate-100/10 dark:bg-slate-900/10 pointer-events-none transition-colors group-hover:bg-transparent" />
                )}
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

