                      <div className="absolute right-0 mt-4 w-72 bg-white dark:bg-slate-900 rounded-[2rem] border border-black/5 dark:border-white/10 shadow-2xl animate-in fade-in zoom-in-95 duration-200 p-2">
                        <div className="p-4 border-b border-black/5 dark:border-white/5">
                          <div className="flex items-center gap-3 mb-3">
