              >
                <Star className="w-6 h-6 text-yellow-500" /> <span className="text-xs">Bewertungen</span>
              </button>
            </div>
          </div>

          <div className="space-y-3">
             <div className="flex justify-between items-center px-4">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">AI Creator Studio</p>
                <button onClick={() => handleMobileNav('studio')} className="text-[10px] font-black text-orange-600 uppercase tracking-widest flex items-center gap-1">
                  Alle Tools <ChevronRight className="w-3 h-3" />
                </button>
             </div>

             <div className="grid grid-cols-1 gap-2">
               {[
                 { id: 'studio', icon: Wand2, label: 'Thumbnail Generator', desc: 'Von Text zu Bild', color: 'text-blue-500', bg: 'bg-blue-500/10' },
                 { id: 'studio', icon: Sparkles, label: 'Stil klonen', desc: 'Designs adaptieren', color: 'text-indigo-500', bg: 'bg-indigo-500/10' },
                 { id: 'studio', icon: LineChart, label: 'CTR Analyse', desc: 'Datengestütztes Feedback', color: 'text-emerald-500', bg: 'bg-emerald-500/10' },
                 { id: 'studio', icon: Youtube, label: 'Kanal Strategie', desc: 'YouTube Audit', color: 'text-red-500', bg: 'bg-red-500/10' }
               ].map((tool, i) => (
                 <button 
                    key={i}
                    onClick={() => handleMobileNav(tool.id as any)} 
                    className="flex items-center justify-between w-full px-5 py-4 bg-white dark:bg-slate-800/50 border border-black/5 dark:border-white/5 rounded-2xl active:scale-[0.98] transition-all shadow-sm"
                 >
                   <div className="flex items-center gap-4">
                     <div className={`p-2.5 rounded-xl ${tool.bg} ${tool.color}`}>
                       <tool.icon className="w-5 h-5" />
                     </div>
                     <div className="text-left">
                        <p className="text-sm font-black text-slate-800 dark:text-slate-100">{tool.label}</p>
                        <p className="text-[10px] font-bold text-slate-400">{tool.desc}</p>
                     </div>
                   </div>
                   <ChevronRight className="w-4 h-4 text-slate-300" />
                 </button>
               ))}
             </div>
          </div>

          {!user ? (
            <button 
              onClick={() => { onLoginClick(); setIsOpen(false); }} 
              className="block w-full bg-orange-600 text-white text-center py-5 rounded-[2rem] font-black shadow-xl shadow-orange-600/20 mt-4 active:scale-95 transition-all"
            >
              Kostenlos anmelden
            </button>
          ) : (
            <button 
              onClick={() => { onLogout(); setIsOpen(false); }}
              className="flex items-center justify-center gap-2 w-full py-4 text-red-500 font-black text-sm mt-4"
            >
              <LogOut className="w-4 h-4" /> Abmelden
            </button>
          )}
        </div>
      )}
    </nav>
  );
};

