            Willkommen, <span className="gradient-text">{user?.name}</span>!
          </h1>
          <p className="text-slate-500 dark:text-slate-400 font-medium">Was möchtest du heute für deinen Kanal erreichen?</p>
        </div>
        <div className="flex gap-4">
           <div className="p-4 bg-white dark:bg-slate-900 border border-black/5 dark:border-white/5 rounded-3xl flex items-center gap-4 shadow-sm">
              <div className="p-2 bg-orange-600/10 text-orange-600 rounded-xl">
                 <TrendingUp className="w-5 h-5" />
