import React, { useState, useEffect } from 'react';
import { Youtube, Search, Loader2, Sparkles, CheckCircle, AlertTriangle, Coins, RefreshCcw, FileText, Database, ExternalLink, ShieldCheck, Zap } from 'lucide-react';
import { analyzeYoutubeChannel } from '../services/geminiService';
import { User } from '../types';

interface StudioChannelAnalyzeProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
}

export const StudioChannelAnalyze: React.FC<StudioChannelAnalyzeProps> = ({ useCredits, user }) => {
  const [url, setUrl] = useState('');
  const [urlError, setUrlError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [result, setResult] = useState<any | null>(null);

  useEffect(() => {
    let interval: any;
    if (loading) {
      setProgress(0);
      const steps = [
        { threshold: 15, text: "Google Grounding wird vorbereitet..." },
        { threshold: 40, text: "Echtzeit-Kanalscan läuft..." },
        { threshold: 65, text: "Wettbewerber-Benchmark..." },
        { threshold: 85, text: "Visual-Data-Processing..." },
        { threshold: 98, text: "Insights werden kuratiert..." }
      ];

      interval = setInterval(() => {
        setProgress(prev => {
          const next = prev + Math.random() * 5;
          const currentStep = steps.find(s => next <= s.threshold) || steps[steps.length - 1];
          setStatusText(currentStep.text);
          return next >= 98 ? 98 : next;
        });
      }, 500);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const handleAnalyze = async () => {
    if (!url.trim()) {
      setUrlError("Bitte gib eine Kanal-URL an.");
      return;
    }

    if (!user || user.credits < 100) {
      alert("Du benötigst 100 Credits für ein Deep-Audit.");
      return;
    }

    setLoading(true);
    setResult(null);
    try {
      const res = await analyzeYoutubeChannel(url);
      useCredits(100);
      setResult(res);
      setProgress(100);
    } catch (err) {
      alert("Analyse fehlgeschlagen.");
    } finally {
      setTimeout(() => setLoading(false), 500);
    }
  };

  return (
    <div className="max-w-5xl mx-auto space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700 pb-20">
      <div className="p-10 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-red-600/5 blur-[100px] rounded-full pointer-events-none" />

        <div className="flex justify-between items-center mb-10">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-red-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-red-600/20">
              <Youtube className="w-7 h-7" />
            </div>
            <div>
              <h2 className="text-3xl font-black tracking-tight">Kanal Deep-Audit</h2>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Powered by Google Search & Gemini 2.5</p>
            </div>
          </div>
          <div className="flex items-center gap-1.5 text-xs font-black text-amber-500 bg-amber-500/10 px-4 py-2 rounded-2xl border border-amber-500/10">
            <Coins className="w-4 h-4" /> 100 Credits
          </div>
        </div>

        <div className="space-y-8">
          <div className="space-y-2">
            <div className="relative">
              <Search className="absolute left-6 top-1/2 -translate-y-1/2 w-6 h-6 text-slate-400" />
              <input 
                type="text"
                value={url}
                onChange={(e) => { setUrl(e.target.value); setUrlError(null); }}
                placeholder="youtube.com/@dein_kanal oder Handle..."
                className="w-full pl-16 pr-6 py-6 bg-slate-50 dark:bg-slate-800/50 border border-black/5 dark:border-white/10 rounded-[2rem] text-lg font-bold focus:ring-4 focus:ring-red-600/10 outline-none transition-all"
              />
            </div>
            {urlError && <p className="text-red-500 text-xs font-bold px-6">{urlError}</p>}
          </div>

          {loading && (
            <div className="space-y-4 animate-in fade-in slide-in-from-top-2">
              <div className="flex justify-between text-xs font-black uppercase tracking-widest">
                <span className="text-red-600 animate-pulse flex items-center gap-2">
                  <Database className="w-3.5 h-3.5" /> {statusText}
                </span>
                <span className="text-slate-400">{Math.round(progress)}%</span>
              </div>
              <div className="h-3 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden p-0.5 border border-black/5 dark:border-white/5">
                <div className="h-full bg-gradient-to-r from-red-600 to-orange-500 rounded-full transition-all duration-700 shadow-[0_0_15px_rgba(220,38,38,0.3)]" style={{ width: `${progress}%` }} />
              </div>
            </div>
          )}

          <div className="flex gap-4">
             <button 
                onClick={handleAnalyze}
                disabled={loading || !url}
                className="flex-1 py-5 bg-slate-900 dark:bg-slate-100 text-white dark:text-slate-900 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 shadow-2xl transition-all active:scale-95 disabled:opacity-40"
              >
                {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6" />}
                Audit jetzt starten
              </button>
              {result && (
                <button onClick={() => { setUrl(''); setResult(null); }} className="px-6 py-5 bg-slate-100 dark:bg-slate-800 rounded-[2rem] text-slate-400"><RefreshCcw className="w-6 h-6" /></button>
              )}
          </div>
        </div>
      </div>

      {result && (
        <div className="animate-in slide-in-from-bottom-8 duration-700 space-y-10">
          <div className="grid md:grid-cols-3 gap-8">
            <div className="md:col-span-2 space-y-8">
               <div className="p-10 bg-gradient-to-br from-slate-900 to-slate-800 rounded-[3rem] text-white shadow-2xl relative overflow-hidden">
