                    <ul className="space-y-4">
                      {result.strengths.map((s: string, i: number) => (
                        <li key={i} className="text-sm font-bold text-slate-600 dark:text-slate-400 leading-snug flex items-start gap-3">
                          <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full mt-1.5 shrink-0" /> {s}
