              {recentActivity.map((activity, i) => (
                <div key={i} className="flex items-center justify-between group cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800/50 p-3 -mx-3 rounded-2xl transition-colors">
                   <div className="flex items-center gap-4">
                      <div className="w-10 h-10 rounded-xl bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-slate-400 group-hover:text-orange-600 transition-colors">
                         <Zap className="w-5 h-5" />
                      </div>
                      <div>
                         <p className="text-sm font-black text-slate-800 dark:text-slate-200">{activity.title}</p>
                         <p className="text-[10px] text-slate-400 font-bold">{activity.date}</p>
                      </div>
                   </div>
                   <div className="text-[9px] font-black text-slate-400 border border-slate-200 dark:border-slate-700 px-2 py-1 rounded-lg">
                      -{activity.cost}
