import React, { useState, useEffect } from 'react';
import { LineChart, Upload, Loader2, Target, CheckCircle, AlertTriangle, Coins, RefreshCcw } from 'lucide-react';
import { analyzeThumbnailImage } from '../services/geminiService';
import { User } from '../types';
import { Tooltip } from './Tooltip';

interface StudioAnalyzeProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
}

export const StudioAnalyze: React.FC<StudioAnalyzeProps> = ({ useCredits, user }) => {
  const [image, setImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [analysis, setAnalysis] = useState<{score: number, feedback: string, suggestions: string[]} | null>(null);

  useEffect(() => {
    let interval: any;
    if (loading) {
      setProgress(0);
      const steps = [
        { threshold: 30, text: "Visuelle Analyse..." },
        { threshold: 60, text: "Farbkontraste prüfen..." },
        { threshold: 85, text: "CTR-Modell berechnen..." },
        { threshold: 95, text: "Feedback generieren..." }
      ];

      interval = setInterval(() => {
        setProgress(prev => {
          const next = prev + Math.random() * 15;
          const currentStep = steps.find(s => next <= s.threshold) || steps[steps.length - 1];
          setStatusText(currentStep.text);
          return next >= 98 ? 98 : next;
        });
      }, 300);
    } else {
      setProgress(0);
      setStatusText('');
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
        setAnalysis(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!image) return;

    if (!user || user.credits < 50) {
      alert("Du benötigst mindestens 50 Credits für eine Thumbnail-Analyse.");
      return;
    }

    setLoading(true);
    try {
      const res = await analyzeThumbnailImage(image);
      useCredits(50);
      setAnalysis(res);
      setProgress(100);
    } catch (err) {
      alert("Analyse fehlgeschlagen.");
    } finally {
      setTimeout(() => setLoading(false), 400);
    }
  };

  const handleReset = () => {
    setImage(null);
    setAnalysis(null);
    setProgress(0);
  };

  return (
    <div className="max-w-5xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="grid md:grid-cols-2 gap-12">
        <div className="space-y-8">
          <div className="p-10 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-2xl font-black flex items-center gap-3">
                <Target className="w-7 h-7 text-emerald-500" />
                Thumbnail-Analyse
              </h2>
              <div className="flex items-center gap-1.5 text-[10px] font-black uppercase text-amber-500 tracking-widest bg-amber-500/10 px-3 py-1 rounded-full">
                <Coins className="w-3.5 h-3.5" />
                50 Credits
              </div>
            </div>
            <Tooltip text="Lade dein Design hoch, um es gegen Millionen von Klick-Daten zu prüfen.">
              <div className="relative aspect-video rounded-3xl border-2 border-dashed border-black/10 dark:border-white/10 flex flex-col items-center justify-center overflow-hidden group">
                {image ? (
                  <img src={image} className="w-full h-full object-cover" />
                ) : (
                  <>
                    <Upload className="w-10 h-10 text-slate-300 mb-4 group-hover:text-emerald-500 transition-colors" />
                    <p className="text-sm font-bold text-slate-400">Bild zum Analysieren ablegen</p>
                  </>
                )}
                <input type="file" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
              </div>
            </Tooltip>

            {loading && (
              <div className="mt-8 space-y-3 animate-in fade-in slide-in-from-top-2 duration-300">
                <div className="flex justify-between items-end">
                  <span className="text-xs font-black uppercase tracking-widest text-emerald-500">{statusText}</span>
                  <span className="text-xs font-black text-slate-400">{Math.round(progress)}%</span>
                </div>
                <div className="h-3 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden border border-black/5 dark:border-white/5">
                  <div 
                    className="h-full bg-emerald-600 transition-all duration-300 ease-out shadow-[0_0_25px_rgba(16,185,129,0.4)]"
                    style={{ width: `${progress}%` }}
                  ></div>
                </div>
              </div>
            )}

            <button 
              onClick={handleAnalyze}
              disabled={loading || !image}
              className="w-full mt-8 py-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl font-black text-lg flex items-center justify-center gap-3 shadow-xl transition-all active:scale-95 disabled:opacity-50"
            >
              {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <LineChart className="w-6 h-6" />}
              CTR Score vorhersagen
            </button>
          </div>
        </div>

        <div className="flex flex-col justify-center">
          {analysis ? (
            <div className="space-y-8 animate-in slide-in-from-right-8 duration-500">
              <div className="p-10 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-500/10 blur-[60px] rounded-full" />
                <div className="relative z-10 flex items-center justify-between mb-8">
                  <Tooltip text="Ein Score über 7.0 deutet auf ein starkes Design hin.">
                    <div>
                      <h3 className="text-xs font-black uppercase tracking-widest text-slate-500 mb-1">Vorhergesagter Score</h3>
                      <p className="text-5xl font-black text-slate-900 dark:text-white">{analysis.score}<span className="text-2xl text-slate-400">/10</span></p>
                    </div>
                  </Tooltip>
                  <div className={`px-4 py-2 rounded-xl text-xs font-black uppercase ${analysis.score > 7 ? 'bg-emerald-500/10 text-emerald-500' : 'bg-amber-500/10 text-amber-500'}`}>
                    {analysis.score > 7 ? 'Hohes Potenzial' : 'Optimierung nötig'}
                  </div>
                </div>
                <p className="text-slate-600 dark:text-slate-400 font-medium leading-relaxed mb-10">{analysis.feedback}</p>
                <div className="space-y-4 mb-10">
                  {analysis.suggestions.map((s, i) => (
                    <div key={i} className="flex items-start gap-4 p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl border border-black/5">
                      {analysis.score > 7 ? <CheckCircle className="w-5 h-5 text-emerald-500 shrink-0 mt-0.5" /> : <AlertTriangle className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />}
                      <span className="text-sm font-bold text-slate-700 dark:text-slate-300">{s}</span>
                    </div>
                  ))}
                </div>
                <button 
                  onClick={handleReset}
                  className="w-full py-4 bg-slate-100 dark:bg-white/5 hover:bg-slate-200 dark:hover:bg-white/10 rounded-2xl font-black text-slate-500 flex items-center justify-center gap-2 transition-all active:scale-95"
                >
                  <RefreshCcw className="w-4 h-4" /> Neue Analyse starten
                </button>
              </div>
            </div>
          ) : (
            <div className="text-center p-12 opacity-50">
              <div className="w-20 h-20 bg-slate-200 dark:bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-6">
                <LineChart className="w-10 h-10 text-slate-400" />
              </div>
              <h3 className="text-xl font-bold mb-2">Ergebnisse</h3>
              <p className="text-sm font-medium">Lade ein Bild hoch, um detaillierte Insights und CTR-Verbesserungen zu erhalten.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

