import React, { useState, useEffect } from 'react';
import { X, ChevronRight, Wand2, Target, LayoutGrid, CheckCircle2, Youtube } from 'lucide-react';

interface TourStep {
  targetId: string;
  title: string;
  description: string;
  icon: any;
  position: 'right' | 'top' | 'center';
}

const TOUR_STEPS: TourStep[] = [
  {
    targetId: 'tour-sidebar-dashboard',
    title: 'Dein Kontrollzentrum',
    description: 'Hier findest du eine Übersicht deiner Projekte und Credits sowie wichtige Performance-Metriken.',
    icon: LayoutGrid,
    position: 'right'
  },
  {
    targetId: 'tour-sidebar-generate',
    title: 'Thumbnail Generator',
    description: 'Der Kern von ThumbCraft. Beschreibe deine Vision und lass die KI hochauflösende Designs erstellen.',
    icon: Wand2,
    position: 'right'
  },
  {
    targetId: 'tour-sidebar-analyze',
    title: 'CTR Analyse',
    description: 'Lade deine Designs hoch und lass sie von unserer KI auf Klick-Psychologie und Farbkontraste prüfen.',
    icon: Target,
    position: 'right'
  },
  {
    targetId: 'tour-sidebar-channel',
    title: 'Kanal Deep-Audit',
    description: 'Analysiere deinen gesamten YouTube-Kanal für eine langfristige Wachstumsstrategie.',
    icon: Youtube,
    position: 'right'
  }
];

interface StudioTourProps {
  onComplete: () => void;
}

export const StudioTour: React.FC<StudioTourProps> = ({ onComplete }) => {
  const [currentStep, setCurrentStep] = useState(0);
  const [highlightRect, setHighlightRect] = useState<DOMRect | null>(null);

  useEffect(() => {
    const updateHighlight = () => {
      const step = TOUR_STEPS[currentStep];
      const desktopTarget = document.getElementById(step.targetId);
      const mobileTarget = document.getElementById(step.targetId.replace('sidebar', 'mobile'));

      const target = window.innerWidth >= 1024 ? desktopTarget : mobileTarget;

      if (target) {
        setHighlightRect(target.getBoundingClientRect());
      } else {
        setHighlightRect(null);
      }
    };

    updateHighlight();
    window.addEventListener('resize', updateHighlight);
    return () => window.removeEventListener('resize', updateHighlight);
  }, [currentStep]);

  const handleNext = () => {
    if (currentStep < TOUR_STEPS.length - 1) {
      setCurrentStep(prev => prev + 1);
    } else {
      onComplete();
    }
  };

  const stepData = TOUR_STEPS[currentStep];
  const Icon = stepData.icon;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center pointer-events-none">
      {/* Dimmed Background Overlay with Hole (Spotlight) */}
      <div className="absolute inset-0 bg-slate-950/70 backdrop-blur-sm pointer-events-auto" onClick={onComplete}>
        {highlightRect && (
          <div 
            className="absolute bg-white transition-all duration-500 rounded-2xl"
            style={{
              top: highlightRect.top - 8,
              left: highlightRect.left - 8,
              width: highlightRect.width + 16,
              height: highlightRect.height + 16,
              boxShadow: '0 0 0 9999px rgba(2, 6, 23, 0.7)',
              mixBlendMode: 'hard-light'
            }}
          />
        )}
      </div>

      {/* Tooltip Card */}
      <div 
        className={`absolute pointer-events-auto w-full max-w-[320px] bg-white dark:bg-slate-900 border border-black/5 dark:border-white/10 rounded-[2.5rem] p-8 shadow-2xl animate-in zoom-in-95 duration-300 transition-all ${
          window.innerWidth >= 1024 
            ? 'left-[300px]' 
            : 'bottom-[120px] left-1/2 -translate-x-1/2'
        }`}
        style={window.innerWidth >= 1024 && highlightRect ? { top: highlightRect.top } : {}}
      >
        <div className="flex items-center gap-4 mb-6">
          <div className="w-12 h-12 bg-orange-600/10 text-orange-600 rounded-2xl flex items-center justify-center shrink-0">
            <Icon className="w-6 h-6" />
          </div>
          <div>
            <h4 className="text-lg font-black tracking-tight leading-none mb-1">{stepData.title}</h4>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
              Schritt {currentStep + 1} von {TOUR_STEPS.length}
            </p>
          </div>
        </div>

        <p className="text-sm font-medium text-slate-500 dark:text-slate-400 leading-relaxed mb-8">
          {stepData.description}
        </p>

        <div className="flex items-center justify-between gap-4">
          <button 
            onClick={onComplete}
            className="text-[10px] font-black uppercase tracking-widest text-slate-400 hover:text-red-500 transition-colors"
          >
            Überspringen
          </button>

