import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Extrahiert den MIME-Typ aus einem Base64-String oder setzt einen Standardwert.
 */
const getMimeType = (base64: string): string => {
  const match = base64.match(/^data:([^;]+);base64,/);
  return match ? match[1] : 'image/png';
};

/**
 * Bereinigt Base64-Daten für die API (entfernt den Data-URL-Header).
 */
const cleanBase64 = (base64: string): string => {
  return base64.includes(',') ? base64.split(',')[1] : base64;
};

/**
 * Analysiert den Nutzerwunsch (Text vs. Bildinhalt) mit Fokus auf Präzision und Layout.
 */
const analyzePromptIntent = async (prompt: string) => {
  const ai = getAI();

  const analysisPrompt = `Analysiere diesen YouTube-Thumbnail-Prompt: "${prompt}". 
  Deine Aufgabe ist es, den Intent präzise zu strukturieren. 
  Achte besonders auf:
  1. Text-Inhalt: Was soll genau im Bild stehen?
  2. Text-Positionierung: WO soll der Text stehen (oben, unten, links, rechts, mitte)?
  3. Visuelle Details: Was ist das Hauptmotiv?

  Antworte STRENG als JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: analysisPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            wantsText: { type: Type.BOOLEAN },
            extractedText: { type: Type.STRING, nullable: true },
            textPosition: { 
              type: Type.STRING, 
              description: "Genaue Positionierungsanweisung (z.B. 'at the bottom center', 'top right corner', 'centered large').",
              nullable: true 
            },
            visualPrompt: { type: Type.STRING, description: "Die bereinigte visuelle Beschreibung ohne Textanweisungen." }
          },
          required: ["wantsText", "visualPrompt"]
        }
      }
    });
    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Intent-Analyse fehlgeschlagen:", e);
    return null;
  }
};

/**
 * Klont den Stil eines Bildes und wendet ihn auf ein neues Motiv an.
 */
export const cloneStyle = async (sourceBase64: string, newMotifPrompt: string) => {
  const ai = getAI();

  const styleAnalysisPrompt = `Analyze the visual STYLE of this thumbnail image in great detail. 
  Describe the artistic style, color palette, lighting (rim lighting, studio glow), composition, and graphic elements.
  Provide a concise style instruction in English for an image generation model to replicate this EXACT aesthetic.`;

  try {
    const analysisResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: cleanBase64(sourceBase64), mimeType: getMimeType(sourceBase64) } },
          { text: styleAnalysisPrompt }
        ]
      }
    });

    const styleInstructions = analysisResponse.text || "Modern vibrant high-contrast YouTube thumbnail style";

    return generateThumbnail(newMotifPrompt, `CLONE_STYLE: ${styleInstructions}`, "16:9", sourceBase64);
  } catch (e) {
    console.error("Style Cloning fehlgeschlagen:", e);
    throw new Error("Stil-Analyse des Referenzbildes fehlgeschlagen.");
  }
};

/**
 * Überarbeitet ein bestehendes Thumbnail (Image-to-Image / Inpainting-like).
 */
export const remakeThumbnail = async (sourceBase64: string, adjustmentPrompt: string) => {
  const ai = getAI();

  const analysisPrompt = `Look at this thumbnail and the user's request: "${adjustmentPrompt}".
  Describe the necessary visual changes in English. 
  Be EXTREMELY PRECISE about spatial locations (top/bottom/left/right). 
  If the user wants something at the bottom, ensure the description explicitly states the bottom area.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: cleanBase64(sourceBase64), mimeType: getMimeType(sourceBase64) } },
          { text: analysisPrompt }
        ]
      }
    });

    return generateThumbnail(response.text || adjustmentPrompt, 'REMAKE_MODE', "16:9", sourceBase64);
  } catch (e) {
    console.error("Remake fehlgeschlagen:", e);
    throw new Error("Analyse des Thumbnails fehlgeschlagen.");
  }
};

/**
 * Kern-Funktion zur Bilderzeugung (Unterstützt Text-to-Image und Image-to-Image).
 * Optimiert für Layout-Präzision.
 */
export const generateThumbnail = async (prompt: string, style: string, aspectRatio: string = "16:9", base64Image?: string) => {
  const ai = getAI();

  let textInstruction = "";
  let finalVisualPrompt = prompt;

  const isSpecialMode = style.includes("REMAKE_MODE") || style.includes("CLONE_STYLE");

  if (!base64Image && !isSpecialMode) {
    const intent = await analyzePromptIntent(prompt);
    if (intent) {
      finalVisualPrompt = intent.visualPrompt;
      if (intent.wantsText && intent.extractedText) {
        const position = intent.textPosition || "prominently visible";
        textInstruction = `STRICT LAYOUT RULE: Place the bold, highly readable text "${intent.extractedText}" EXACTLY ${position}. Do NOT place it anywhere else. The text must be sharp and professional.`;
      } else {
        textInstruction = "STRICT RULE: NO TEXT, no letters, no characters in the image.";
      }
    }
  }

  let fullPrompt = "";
  if (style.includes("CLONE_STYLE")) {
    const cleanedStyle = style.replace("CLONE_STYLE:", "").trim();
    fullPrompt = `CRITICAL: USE THE ATTACHED IMAGE AS A STYLE REFERENCE ONLY. 
    REPLICATE THE LIGHTING AND AESTHETIC.
    SUBJECT: ${finalVisualPrompt}.
    LAYOUT: Respect the spatial descriptions provided. If a specific position is mentioned, adhere to it strictly.
    ${textInstruction}
    Aesthetic to clone: ${cleanedStyle}`;
  } else if (style.includes("REMAKE_MODE")) {
    fullPrompt = `CRITICAL MODIFICATION: Change the attached image based on this instruction: ${finalVisualPrompt}.
    STRICT SPATIAL ACCURACY: Adhere perfectly to positioning (top, bottom, etc.). 
    Maintain layout consistency except where modification is requested.
    ${textInstruction}`;
  } else {
    fullPrompt = `CRITICAL: Create a professional YouTube thumbnail.
    STYLE: ${style}. 
    SUBJECT: ${finalVisualPrompt}. 
    SPATIAL PRECISION: If the user specified a location (e.g., bottom, top), follow it EXACTLY. 
    TECHNICAL: 4K, high contrast, viral aesthetic.
    ${textInstruction}`;
  }

  const parts: any[] = [{ text: fullPrompt }];

  if (base64Image) {
    parts.unshift({
      inlineData: { 
        data: cleanBase64(base64Image), 
        mimeType: getMimeType(base64Image) 
      }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts },
      config: { 
        imageConfig: { 
          aspectRatio: aspectRatio as any
        } 
      }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      const mimeType = imagePart.inlineData.mimeType || 'image/png';
      return `data:${mimeType};base64,${imagePart.inlineData.data}`;
    }

    throw new Error("Die KI hat kein Bild generiert. Dies kann an Sicherheitsfiltern liegen.");
  } catch (e: any) {
