import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Extrahiert den MIME-Typ aus einem Base64-String oder setzt einen Standardwert.
 */
const getMimeType = (base64: string): string => {
  const match = base64.match(/^data:([^;]+);base64,/);
  return match ? match[1] : 'image/png';
};

/**
 * Bereinigt Base64-Daten für die API (entfernt den Data-URL-Header).
 */
const cleanBase64 = (base64: string): string => {
  return base64.includes(',') ? base64.split(',')[1] : base64;
};

/**
 * Analysiert den Nutzerwunsch mit Fokus auf "1:1 Präzision".
 * Extrahiert Layout-Anweisungen, Text und visuelle Details getrennt.
 */
const analyzePromptIntent = async (prompt: string) => {
  const ai = getAI();

  const analysisPrompt = `Du bist ein Expert für Layout-Analyse. Analysiere diesen Nutzer-Prompt für ein YouTube-Thumbnail: "${prompt}".
  Extrahiere den Intent mit EXTREMER PRÄZISION. 

  Regeln für die Extraktion:
  1. Wenn der Nutzer eine Position nennt (z.B. "unten", "rechts oben", "zentriert"), muss dies 1:1 in 'textPosition' übernommen werden.
  2. Trenne den Textinhalt (was geschrieben steht) vom visuellen Inhalt (was man sieht).
  3. Identifiziere explizite Layout-Verbote (z.B. "kein Gesicht", "kein Text").

  Antworte STRENG als JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: analysisPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            wantsText: { type: Type.BOOLEAN },
            extractedText: { type: Type.STRING, nullable: true },
            textPosition: { 
              type: Type.STRING, 
              description: "Die vom Nutzer gewünschte Position (z.B. 'at the very bottom', 'left side', 'top center'). Default: 'center'.",
              nullable: true 
            },
            visualPrompt: { 
              type: Type.STRING, 
              description: "Der rein bildliche Teil der Beschreibung (ohne Layout-Anweisungen)." 
            },
            layoutConstraints: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "Spezielle Layout-Regeln wie 'No faces', 'High contrast bottom area', etc."
            }
          },
          required: ["wantsText", "visualPrompt", "layoutConstraints"]
        }
      }
    });
    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Intent-Analyse fehlgeschlagen:", e);
    return null;
  }
};

/**
 * Klont den Stil eines Bildes und wendet ihn auf ein neues Motiv an.
 */
export const cloneStyle = async (sourceBase64: string, newMotifPrompt: string) => {
  const ai = getAI();

  const styleAnalysisPrompt = `Analyze the visual STYLE of this thumbnail. 
  Describe colors, lighting, composition and professional polish. 
  Ignore the actual content (persons/objects), only focus on the AESTHETIC DNA.`;

  try {
    const analysisResponse = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: cleanBase64(sourceBase64), mimeType: getMimeType(sourceBase64) } },
          { text: styleAnalysisPrompt }
        ]
      }
    });

    const styleInstructions = analysisResponse.text || "Professional high-contrast vibrant YouTube aesthetic";

    return generateThumbnail(newMotifPrompt, `CLONE_STYLE: ${styleInstructions}`, "16:9", sourceBase64);
