/**
 * Überarbeitet ein bestehendes Thumbnail mit 1:1 räumlicher Korrektheit.
 */
export const remakeThumbnail = async (sourceBase64: string, adjustmentPrompt: string) => {
  const ai = getAI();

  const analysisPrompt = `Look at the image and this specific request: "${adjustmentPrompt}".
  Create a technical modification instruction. If the user mentions a location (top, bottom, etc.), you MUST emphasize it in the result. 
  Example: If they want text at the bottom, your instruction must say: 'Add the text exactly at the bottom border'.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: cleanBase64(sourceBase64), mimeType: getMimeType(sourceBase64) } },
          { text: analysisPrompt }
        ]
      }
    });

    return generateThumbnail(response.text || adjustmentPrompt, 'REMAKE_MODE', "16:9", sourceBase64);
  } catch (e) {
    console.error("Remake fehlgeschlagen:", e);
    throw new Error("Remake-Analyse fehlgeschlagen.");
  }
};

/**
 * Kern-Funktion zur Bilderzeugung.
 * Hier wird sichergestellt, dass Layout-Anweisungen (Positionierung) höchste Priorität haben.
 */
export const generateThumbnail = async (prompt: string, style: string, aspectRatio: string = "16:9", base64Image?: string) => {
  const ai = getAI();

  let layoutRule = "";
  let finalVisualPrompt = prompt;

  // Intent-Analyse für präzises Layout (nur wenn kein Remake/Clone direkt vorliegt oder als Ergänzung)
  const intent = await analyzePromptIntent(prompt);
  if (intent) {
    finalVisualPrompt = intent.visualPrompt;
    if (intent.wantsText && intent.extractedText) {
      const position = intent.textPosition || "centered";
      layoutRule = `\n[STRICT LAYOUT RULE]: Overlay the text "${intent.extractedText}" EXACTLY ${position}. DO NOT place it anywhere else. The text must be huge, bold, and highly legible.`;
    } else if (!intent.wantsText) {
      layoutRule = `\n[STRICT RULE]: ABSOLUTELY NO TEXT or letters allowed in the image.`;
    }

    if (intent.layoutConstraints.length > 0) {
      layoutRule += `\n[ADDITIONAL CONSTRAINTS]: ${intent.layoutConstraints.join(', ')}.`;
    }
  }

  let fullPrompt = "";
  if (style.includes("CLONE_STYLE")) {
    const aesthetic = style.replace("CLONE_STYLE:", "").trim();
    fullPrompt = `STYLE REFERENCE: Use the attached image's aesthetic (lighting, color grading).
    NEW CONTENT: ${finalVisualPrompt}
    LAYOUT INSTRUCTION: ${layoutRule}
    AESTHETIC TO REPLICATE: ${aesthetic}`;
  } else if (style.includes("REMAKE_MODE")) {
    fullPrompt = `IMAGE MODIFICATION: Use the attached image as BASE.
    ACTION: ${finalVisualPrompt}
    PRECISION RULE: Adhere 1:1 to spatial instructions. ${layoutRule}`;
  } else {
    fullPrompt = `PRO YOUTUBE THUMBNAIL GENERATION.
    PRIMARY SUBJECT: ${finalVisualPrompt}
    ARTISTIC STYLE: ${style}
    TECHNICAL: 4K, HDR, vibrant colors, viral clickbait aesthetic.
    LAYOUT PRECISION: ${layoutRule}`;
  }

  const parts: any[] = [{ text: fullPrompt }];

  if (base64Image) {
    parts.unshift({
      inlineData: { 
        data: cleanBase64(base64Image), 
        mimeType: getMimeType(base64Image) 
      }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts },
      config: { 
        imageConfig: { 
          aspectRatio: aspectRatio as any
        } 
      }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      const mimeType = imagePart.inlineData.mimeType || 'image/png';
      return `data:${mimeType};base64,${imagePart.inlineData.data}`;
    }

    throw new Error("KI-Sicherheitsfilter hat die Generierung blockiert oder kein Bild geliefert.");
  } catch (e: any) {
    console.error("Generation Error:", e);
    throw new Error(e.message || "Fehler bei der Bilderzeugung.");
  }
};

