            </div>
          )}

          <div className="flex gap-4">
             <button 
                onClick={handleAnalyze}
                disabled={loading || !url || isLowCredits}
                className={`flex-1 py-5 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 shadow-2xl transition-all active:scale-95 disabled:opacity-40 ${
                  isLowCredits 
                    ? 'bg-slate-300 dark:bg-slate-700 text-slate-500 cursor-not-allowed' 
                    : 'bg-slate-900 dark:bg-slate-100 text-white dark:text-slate-900'
                }`}
              >
                {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : (isLowCredits ? <Lock className="w-6 h-6" /> : <Sparkles className="w-6 h-6" />)}
