                        </li>
                      ))}
                    </ul>
                  </div>
               </div>
            </div>

            <div className="space-y-8">
               <div className="p-8 bg-blue-600/5 border border-blue-600/10 rounded-[3rem] shadow-sm h-full">
                  <div className="flex items-center gap-2 mb-6">
                    <div className="w-8 h-8 bg-blue-600 text-white rounded-lg flex items-center justify-center">
                       <Database className="w-4 h-4" />
                    </div>
                    <div>
                       <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-600 leading-none mb-1">Live Research</h4>
                       <p className="text-[8px] font-bold text-blue-500/60 uppercase">Echtzeit-Datenquellen</p>
                    </div>
                  </div>

                  <div className="space-y-3">
                    {result.sources && result.sources.length > 0 ? result.sources.map((s: any, i: number) => (
                      <a 
                        key={i} 
                        href={s.url} 
                        target="_blank" 
                        className="block p-4 bg-white dark:bg-slate-800 rounded-2xl border border-black/5 hover:border-blue-500/50 transition-all group"
                      >
                        <p className="text-[10px] font-black text-slate-800 dark:text-white truncate mb-1 flex items-center justify-between">
                          {s.title} <ExternalLink className="w-3 h-3 text-slate-300 group-hover:text-blue-500 transition-colors" />
                        </p>
                        <p className="text-[8px] text-slate-400 truncate">{s.url}</p>
                      </a>
                    )) : (
                      <p className="text-[10px] font-bold text-slate-400 italic">Keine externen Referenzen gefunden.</p>
                    )}
                  </div>

                  <div className="mt-8 p-4 bg-white dark:bg-slate-800 rounded-2xl border border-blue-600/20 flex items-center gap-3">
                     <ShieldCheck className="w-5 h-5 text-blue-600" />
                     <p className="text-[9px] font-bold text-slate-500">Diese Analyse basiert auf verifizierten Kanal-Daten von YouTube.</p>
                  </div>
               </div>
            </div>
          </div>

          <div className="p-10 bg-white dark:bg-slate-900 rounded-[4rem] border border-black/5 shadow-2xl relative overflow-hidden">
             <div className="absolute top-0 right-0 p-12 opacity-[0.03] rotate-12"><Sparkles className="w-64 h-64" /></div>
             <h4 className="text-2xl font-black mb-10 flex items-center gap-4">
                <div className="w-12 h-12 bg-orange-600 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-orange-600/20">
                  <Zap className="w-6 h-6 fill-current" />
                </div>
                Dein 3-Stufen Aktionsplan
             </h4>
             <div className="grid md:grid-cols-3 gap-8">
                {result.actionPlan.map((step: string, i: number) => (
                  <div key={i} className="relative p-8 bg-slate-50 dark:bg-slate-800/50 rounded-[2.5rem] border border-black/5 group hover:bg-white dark:hover:bg-slate-800 transition-all">
                    <span className="text-5xl font-black text-orange-600/10 absolute top-4 right-8 group-hover:text-orange-600/20 transition-colors">{i+1}</span>
                    <p className="font-black text-slate-800 dark:text-slate-200 relative z-10 leading-snug">{step}</p>
                  </div>
                ))}
             </div>
             <div className="mt-12 flex justify-center">
                <button className="px-10 py-4 bg-orange-600 text-white rounded-2xl font-black uppercase tracking-widest text-sm shadow-xl shadow-orange-600/20 hover:scale-105 active:scale-95 transition-all flex items-center gap-3">
                   <FileText className="w-5 h-5" /> Strategie als PDF (Pro)
                </button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

