                  <div className="flex items-center gap-2 text-white">
                    <Sparkles className="w-4 h-4 text-orange-500 fill-current" />
                    <span className="text-[10px] font-black uppercase tracking-widest">KI-Generiertes Resultat</span>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Progress Indicators */}
          <div className="flex justify-center gap-2 mt-8">
            {showcaseItems.map((_, i) => (
              <button 
                key={i}
                onClick={() => {
                  setCurrentIndex(i);
                  setDisplayedPrompt('');
                  setIsTyping(true);
                }}
                className={`h-1.5 rounded-full transition-all duration-500 ${currentIndex === i ? 'w-8 bg-orange-600' : 'w-2 bg-slate-200 dark:bg-slate-800'}`}
              />
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

