                  </select>
                </div>
              </div>

              <div>
                <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-3">Referenzbild (Optional)</label>
                <Tooltip text="Lade ein Bild hoch, damit die KI Gesichter oder Objekte als Basis nutzt.">
                  <div className={`relative h-32 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center group overflow-hidden transition-colors ${
                    uploadError ? 'border-red-500 bg-red-500/5' : 'border-black/10 dark:border-white/10'
                  }`}>
                    {image ? (
                      <>
                        <img src={image} className="w-full h-full object-cover opacity-50" />
                        <button onClick={() => { setImage(null); setUploadError(null); }} className="absolute p-2 bg-red-500 text-white rounded-lg shadow-xl hover:scale-110 transition-transform">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </>
                    ) : (
                      <>
                        <Upload className={`w-8 h-8 mb-2 group-hover:text-blue-500 transition-colors ${uploadError ? 'text-red-400' : 'text-slate-300'}`} />
                        <span className={`text-[10px] font-black uppercase tracking-widest ${uploadError ? 'text-red-500' : 'text-slate-400'}`}>
                          Bild hochladen
                        </span>
                        <input type="file" accept="image/png, image/jpeg, image/jpg" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
