import React from 'react';
import { Wand2, ChevronRight, Coins, Target, Sparkles, TrendingUp, Zap, Lightbulb, Youtube, Lock, Star } from 'lucide-react';
import { User } from '../types';

interface StudioSelectionProps {
  user: User | null;
  onSelectMode: (mode: string) => void;
  onGoToPricing?: () => void;
}

export const StudioSelection: React.FC<StudioSelectionProps> = ({ user, onSelectMode, onGoToPricing }) => {
  const currentPlan = user?.plan || 'Starter';
  const userCredits = user?.credits || 0;

  const checkPlanPermission = (planRequired: string) => {
    if (planRequired === 'Starter') return true;
    if (planRequired === 'Creator Pro') return currentPlan === 'Creator Pro' || currentPlan === 'Production';
    return currentPlan === 'Production';
  };

  const suiteModes = [
    {
      id: 'generate',
      title: 'Thumbnail Generator',
      description: 'Beschreibe dein Bild und die KI erstellt es sofort. Perfekt für neue Video-Ideen.',
      icon: <Wand2 className="w-8 h-8" />,
      color: 'from-orange-500 to-amber-500',
      shadow: 'shadow-orange-500/20',
      cost: 10,
      planRequired: 'Starter',
      badge: 'Bestseller'
    },
    {
      id: 'clone',
      title: 'Stil kopieren',
      description: 'Nimm ein Bild als Vorlage und die KI übernimmt den Look für dein eigenes Vorschaubild.',
      icon: <Sparkles className="w-8 h-8" />,
      color: 'from-blue-500 to-indigo-500',
      shadow: 'shadow-blue-500/20',
      cost: 30,
      planRequired: 'Starter',
      badge: 'Beliebt'
    },
    {
      id: 'analyze',
      title: 'Klick-Test',
      description: 'Lass die KI prüfen, ob dein Bild gut ankommt. Erhalte Tipps für mehr Klicks.',
      icon: <Target className="w-8 h-8" />,
      color: 'from-emerald-500 to-teal-500',
      shadow: 'shadow-emerald-500/20',
      cost: 50,
      planRequired: 'Creator Pro',
      badge: 'Pro-Feature'
    },
    {
      id: 'channel',
      title: 'Kanal-Check',
      description: 'Die KI analysiert deinen ganzen Kanal und gibt dir einen Plan für besseres Design.',
      icon: <Youtube className="w-8 h-8" />,
      color: 'from-red-600 to-rose-600',
      shadow: 'shadow-red-600/20',
      cost: 100,
      planRequired: 'Production',
      badge: 'Premium'
    }
  ];

  return (
    <div className="space-y-12 pb-20 max-w-7xl mx-auto">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-8">
        <div>
          <div className="flex items-center gap-2 mb-3">
            <Star className="w-4 h-4 text-amber-500 fill-amber-500" />
            <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Dein Studio Dashboard</span>
          </div>
          <h1 className="text-4xl md:text-6xl font-black tracking-tighter mb-4">
            Hallo, <span className="gradient-text">{user?.name}</span>
          </h1>
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-1.5 px-3 py-1 bg-slate-100 dark:bg-slate-800 rounded-lg text-[10px] font-black text-slate-500 uppercase">
              Paket: <span className="text-orange-600">{user?.plan}</span>
            </div>
            <div className="flex items-center gap-1.5 px-3 py-1 bg-slate-100 dark:bg-slate-800 rounded-lg text-[10px] font-black text-slate-500 uppercase">
              Guthaben: <span className="text-emerald-600">{user?.credits}</span>
            </div>
          </div>
        </div>

        <div className="flex gap-4">
           <div className="p-6 bg-white dark:bg-slate-900/60 backdrop-blur-md border border-black/5 dark:border-white/5 rounded-[2.5rem] flex items-center gap-4 shadow-sm">
              <div className="w-12 h-12 bg-emerald-600/10 text-emerald-600 rounded-2xl flex items-center justify-center">
                 <TrendingUp className="w-6 h-6" />
              </div>
              <div>
                 <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Ø Mehr Klicks</p>
                 <p className="text-2xl font-black text-slate-900 dark:text-white">+4.2%</p>
              </div>
           </div>
        </div>
      </div>

      <div className="grid md:grid-cols-2 gap-8">
        {suiteModes.map((mode) => {
          const hasPlanPermission = checkPlanPermission(mode.planRequired);
          const hasCredits = userCredits >= mode.cost;
          const isLocked = !hasPlanPermission || !hasCredits;

          return (
            <button
              key={mode.id}
              onClick={() => {
                if (!hasPlanPermission || !hasCredits) {
                  onGoToPricing?.();
                } else {
                  onSelectMode(mode.id);
                }
              }}
              className={`group relative flex flex-col p-10 bg-white/70 dark:bg-slate-900/40 backdrop-blur-xl border border-black/5 dark:border-white/10 rounded-[4rem] text-left transition-all hover:-translate-y-4 hover:shadow-2xl active:scale-[0.98] overflow-hidden ${
                isLocked ? 'opacity-80 saturate-[0.5]' : ''
              }`}
            >
              <div className={`absolute top-0 right-0 w-64 h-64 bg-gradient-to-br ${mode.color} opacity-[0.03] group-hover:opacity-[0.08] blur-3xl rounded-full transition-opacity`} />

              <div className="absolute top-8 right-8 flex flex-col items-end gap-2">
                <div className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest flex items-center gap-1.5 border transition-colors ${
                  !hasCredits ? 'bg-red-500/10 text-red-500 border-red-500/20' : 'bg-amber-500/10 text-amber-500 border-amber-500/10'
                }`}>
                   <Coins className="w-3 h-3" /> {mode.cost} Guthaben
                </div>
                {!hasPlanPermission && (
                   <div className="px-3 py-1 bg-orange-500/10 text-orange-600 border border-orange-500/10 rounded-full text-[9px] font-black uppercase tracking-widest">
                     {mode.planRequired} Abo nötig
                   </div>
                )}
              </div>

              <div className="relative z-10">
                <div className={`w-20 h-20 rounded-[2rem] bg-gradient-to-br ${mode.color} text-white flex items-center justify-center mb-8 shadow-2xl ${mode.shadow} group-hover:scale-110 transition-transform duration-500 ${isLocked ? 'grayscale' : ''}`}>
                  {mode.icon}
                </div>

                <div className="inline-block px-3 py-1 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-400 text-[9px] font-black uppercase tracking-[0.2em] mb-4">
                  {mode.badge}
                </div>

                <h3 className="text-3xl font-black mb-4 text-slate-900 dark:text-white group-hover:text-orange-600 transition-colors">
                  {mode.title}
                </h3>
                <p className="text-slate-500 dark:text-slate-400 font-medium leading-relaxed mb-10 min-h-[4.5rem]">
                  {mode.description}
                </p>

                <div className={`inline-flex items-center gap-3 font-black text-xs uppercase tracking-[0.2em] transition-all ${
                  isLocked ? 'text-orange-600' : 'text-slate-900 dark:text-white group-hover:gap-5'
                }`}>
                   {isLocked ? (
                     <span className="flex items-center gap-2">
                       <Zap className="w-4 h-4 fill-current" /> Guthaben aufladen
                     </span>
                   ) : 'Werkzeug starten'} <ChevronRight className="w-5 h-5" />
                </div>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
};

