const ASPECT_RATIOS = [
  { id: '16:9', label: 'Standard (16:9)', icon: Monitor, desc: 'YouTube Video' },
  { id: '9:16', label: 'Shorts (9:16)', icon: Smartphone, desc: 'Reels / TikTok' },
  { id: '1:1', label: 'Quadrat (1:1)', icon: Square, desc: 'Instagram / Post' },
];

const QUALITY_OPTIONS = [
  { id: 'standard', label: 'Standard', cost: 10, icon: Monitor, desc: '1K Auflösung - Schnell & Effizient' },
  { id: 'high', label: 'Hoch', cost: 25, icon: Zap, desc: '2K Auflösung - Mehr Textur & Details' },
  { id: 'max', label: 'Maximal', cost: 50, icon: Star, desc: '4K Ultra HD - Maximale Schärfe für Profis' },
];

interface GeneratedResult {
  id: string;
  url: string;
  prompt: string;
  isSaved?: boolean;
}

export const StudioGenerate: React.FC<StudioGenerateProps> = ({ useCredits, user, onGoToPricing, onSaveDesign }) => {
  const [isBulkMode, setIsBulkMode] = useState(false);
  const [prompt, setPrompt] = useState('');
  const [bulkPrompts, setBulkPrompts] = useState('');
  const [style, setStyle] = useState<ThumbnailStyle>(ThumbnailStyle.CLEAN);
  const [aspectRatio, setAspectRatio] = useState('16:9');
  const [quality, setQuality] = useState(QUALITY_OPTIONS[0]);
  const [image, setImage] = useState<string | null>(null);
  const [promptError, setPromptError] = useState<string | null>(null);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [results, setResults] = useState<GeneratedResult[]>([]);
  const [justAdded, setJustAdded] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isStarter = user?.plan === 'Starter';
  const isLowCredits = user && user.credits < quality.cost;

  useEffect(() => {
    let interval: any;
    if (loading) {
      if (!isBulkMode) {
        setProgress(0);
        const steps = [
          { threshold: 20, text: "KI initialisiert..." },
          { threshold: 45, text: "Motive werden komponiert..." },
          { threshold: 75, text: "Beleuchtung wird verfeinert..." },
          { threshold: 95, text: "Details werden gerendert..." }
        ];

        interval = setInterval(() => {
          setProgress(prev => {
            const next = prev + Math.random() * 8;
            const currentStep = steps.find(s => next <= s.threshold) || steps[steps.length - 1];
            setStatusText(currentStep.text);
            return next >= 98 ? 98 : next;
          });
        }, 400);
      }
    } else {
      setProgress(0);
      setStatusText('');
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, isBulkMode]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setUploadError(null);

    if (file) {
      const allowedTypes = ['image/png', 'image/jpeg', 'image/jpg'];
      if (!allowedTypes.includes(file.type)) {
        setUploadError("Ungültiges Format. Bitte lade nur PNG oder JPG Dateien hoch.");
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => setImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handlePromptListUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const text = event.target?.result as string;
        setBulkPrompts(text);
      };
      reader.readAsText(file);
    }
  };

  const handleGenerate = async () => {
    setPromptError(null);
    const activePrompts = isBulkMode 
      ? bulkPrompts.split('\n').map(p => p.trim()).filter(p => p.length > 0)
      : [prompt.trim()].filter(p => p.length > 0);

    if (activePrompts.length === 0) {
      setPromptError("Bitte gib mindestens eine Vision an.");
      return;
    }

    const totalCost = activePrompts.length * quality.cost;
    if (!user || user.credits < totalCost) {
      if (onGoToPricing) onGoToPricing();
      return;
    }

    setLoading(true);
    setResults([]);
    try {
      const qualityPrefix = quality.id === 'max' ? "ULTRA HIGH RESOLUTION 4K, EXTREME DETAIL. " : quality.id === 'high' ? "HIGH RESOLUTION 2K, SHARP DETAILS. " : "";

      const newResults: GeneratedResult[] = [];

      for (let i = 0; i < activePrompts.length; i++) {
        const currentPrompt = activePrompts[i];
        if (isBulkMode) {
          setStatusText(`Generiere ${i + 1} von ${activePrompts.length}...`);
          setProgress(((i) / activePrompts.length) * 100);
        }

        const res = await generateThumbnail(qualityPrefix + currentPrompt, style, aspectRatio, image || undefined);
        useCredits(quality.cost);
        newResults.push({
          id: Math.random().toString(36).substr(2, 9),
          url: res,
          prompt: currentPrompt
        });

        if (isBulkMode) {
          setProgress(((i + 1) / activePrompts.length) * 100);
          setResults([...newResults]);
        } else {
          setResults(newResults);
        }
      }

      setProgress(100);
      setStatusText("Alle Generierungen abgeschlossen!");
    } catch (err) {
      alert("Fehler bei der Generierung.");
    } finally {
      setTimeout(() => setLoading(false), 500);
    }
  };

  const handleSave = (res: GeneratedResult) => {
    if (onSaveDesign) {
      onSaveDesign({
        id: res.id,
        imageUrl: res.url,
        prompt: res.prompt,
        createdAt: new Date().toISOString(),
        style: style,
        aspectRatio: aspectRatio
      });
      setResults(prev => prev.map(r => r.id === res.id ? { ...r, isSaved: true } : r));
    }
  };

  const addSuggestion = (suggestion: string) => {
    setPromptError(null);
    setJustAdded(true);
    setTimeout(() => setJustAdded(false), 500);

    if (isBulkMode) {
      setBulkPrompts(prev => prev ? `${prev}\n${suggestion}` : suggestion);
    } else {
      setPrompt(prev => {
        const trimmed = prev.trim();
        if (!trimmed) return suggestion;
        if (trimmed.endsWith(',') || trimmed.endsWith('.')) return `${trimmed} ${suggestion}`;
        return `${trimmed}, ${suggestion}`;
      });
    }
  };

  const removeResult = (id: string) => {
    setResults(prev => prev.filter(r => r.id !== id));
  };

  const downloadAll = () => {
    results.forEach((res, index) => {
      const link = document.createElement('a');
      link.href = res.url;
      link.download = `thumbnail_${index + 1}_${aspectRatio.replace(':', 'x')}.png`;
      link.click();
    });
  };

  return (
    <div className="max-w-7xl mx-auto space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">

      {/* Bulk Mode Toggle */}
      <div className="flex justify-center">
        <div className="bg-white dark:bg-slate-900 p-1.5 rounded-2xl border border-black/5 dark:border-white/10 shadow-lg flex gap-1">
          <button 
            onClick={() => setIsBulkMode(false)}
            className={`px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all flex items-center gap-2 ${!isBulkMode ? 'bg-orange-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
          >
            <Monitor className="w-3.5 h-3.5" /> Einzeln
          </button>
          <button 
            onClick={() => setIsBulkMode(true)}
            className={`px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all flex items-center gap-2 ${isBulkMode ? 'bg-orange-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
          >
            <Layers className="w-3.5 h-3.5" /> Bulk ({isBulkMode ? bulkPrompts.split('\n').filter(p => p.trim()).length : 0})
          </button>
        </div>
      </div>

      <div className="grid lg:grid-cols-2 gap-12">
        <div className="space-y-8">

          {isStarter && (
            <div className="p-6 bg-blue-600/5 border border-blue-600/20 rounded-[2rem] flex items-center justify-between gap-6 animate-in slide-in-from-top-4 duration-500">
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 bg-blue-600/10 rounded-full flex items-center justify-center shrink-0">
                  <Lock className="w-5 h-5 text-blue-600" />
                </div>
                <div>
                  <h4 className="text-sm font-black text-blue-600 dark:text-blue-400 uppercase tracking-widest mb-1 leading-none">Starter Plan aktiv</h4>
                  <p className="text-[10px] text-blue-500 font-bold opacity-80 uppercase tracking-wider">Bilder enthalten ein Wasserzeichen</p>
                </div>
              </div>
              <button 
                onClick={onGoToPricing}
                className="px-6 py-2.5 bg-blue-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-blue-600/20 active:scale-95 transition-all"
              >
                Pro holen
              </button>
            </div>
          )}

          <div className="p-8 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-black/5 dark:border-white/5 shadow-2xl">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-black flex items-center gap-3">
                <Sparkles className="w-6 h-6 text-blue-500" />
                {isBulkMode ? 'Bulk Konfiguration' : 'Konfiguration'}
              </h2>
              <div className={`flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full border ${
                isLowCredits ? 'bg-red-500/10 text-red-500 border-red-500/10' : 'bg-amber-500/10 text-amber-500 border-amber-500/10'
              }`}>
                <Coins className="w-3.5 h-3.5" />
                {isBulkMode ? `${quality.cost} Cr. pro Bild` : `${quality.cost} Credits`}
              </div>
            </div>

            <div className="space-y-6">
              <div>
                <div className="flex items-center justify-between mb-3">
                  <label className="text-xs font-black uppercase tracking-widest text-slate-500">
                    {isBulkMode ? 'Prompt Liste (Eine Vision pro Zeile)' : 'Vision beschreiben'}
                  </label>
                  <div className="flex gap-2">
                    {isBulkMode && (
                      <button 
                        onClick={() => fileInputRef.current?.click()}
                        className="flex items-center gap-1.5 text-[10px] font-bold text-orange-600 bg-orange-600/5 px-2 py-1 rounded-md hover:bg-orange-600/10 transition-colors"
                      >
                        <FileText className="w-3 h-3" /> Liste hochladen (.txt)
                        <input type="file" ref={fileInputRef} onChange={handlePromptListUpload} accept=".txt" className="hidden" />
                      </button>
                    )}
                    <button 
                      onClick={() => isBulkMode ? setBulkPrompts('') : setPrompt('')}
                      className="flex items-center gap-1.5 text-[10px] font-bold text-slate-400 hover:text-red-500 transition-colors"
                    >
                      <RotateCcw className="w-3 h-3" /> Leeren
                    </button>
                  </div>
                </div>

                <div className="relative">
                  <Tooltip text={isBulkMode ? "Jede Zeile erzeugt ein eigenes Thumbnail." : "Präzise Beschreibungen liefern bessere Details."}>
                    <textarea 
                      value={isBulkMode ? bulkPrompts : prompt}
                      onChange={(e) => {
                        if (isBulkMode) setBulkPrompts(e.target.value);
                        else setPrompt(e.target.value);
                        if (promptError) setPromptError(null);
                      }}
                      placeholder={isBulkMode ? "Gamer am PC\nSchockierter Mann mit Award\nMinimalistische Tech-Vorschau" : "z.B. Ein schockierter Mann hält ein goldenes iPhone in der Hand..."}
                      className={`w-full h-32 bg-slate-50 dark:bg-slate-800/50 border rounded-2xl p-4 focus:ring-2 outline-none transition-all resize-none mb-2 ${
                        promptError ? 'border-red-500 ring-2 ring-red-500/10' : 
                        justAdded ? 'border-blue-500 ring-4 ring-blue-500/10 scale-[1.01]' :
                        'border-black/5 dark:border-white/5 focus:ring-blue-500'
                      }`}
                    />
                  </Tooltip>
                  {promptError && (
                    <div className="flex items-center gap-1.5 text-red-500 text-[11px] font-bold animate-in fade-in slide-in-from-top-1 duration-200 mb-4">
                      <AlertCircle className="w-3.5 h-3.5" />
                      {promptError}
                    </div>
                  )}
                </div>

                <div className="space-y-3">
                  <div className="flex items-center justify-between">
                    <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Inspiration für {style}</span>
                    <span className="text-[9px] font-bold text-slate-300 italic">Klicke zum Hinzufügen</span>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {STYLE_SUGGESTIONS[style].map((suggestion, i) => (
                      <button
                        key={i}
                        onClick={() => addSuggestion(suggestion)}
                        className="group flex items-center gap-1.5 px-3 py-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-blue-600 hover:text-white dark:hover:bg-blue-600 rounded-xl text-[10px] font-black uppercase tracking-wider transition-all border border-black/5 dark:border-white/5 active:scale-95"
                      >
                        <Plus className="w-3 h-3 text-blue-500 group-hover:text-white transition-colors" />
                        {suggestion}
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-3">Format</label>
                  <div className="flex gap-2">
                    {ASPECT_RATIOS.map((ratio) => {
                      const Icon = ratio.icon;
                      return (
                        <Tooltip key={ratio.id} text={ratio.desc}>
                          <button
                            onClick={() => setAspectRatio(ratio.id)}
                            className={`flex-1 flex flex-col items-center justify-center p-3 rounded-2xl border transition-all ${
                              aspectRatio === ratio.id 
                                ? 'bg-blue-600 border-blue-600 text-white shadow-lg' 
                                : 'bg-slate-50 dark:bg-slate-800/50 border-transparent text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'
                            }`}
                          >
                            <Icon className="w-5 h-5 mb-1.5" />
                            <span className="text-[10px] font-black uppercase tracking-wider">{ratio.id}</span>
                          </button>
                        </Tooltip>
                      );
                    })}
                  </div>
                </div>
                <div>
                  <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-3">Stil</label>
                  <select 
                    value={style}
                    onChange={(e) => setStyle(e.target.value as ThumbnailStyle)}
                    className="w-full bg-slate-50 dark:bg-slate-800/50 border border-black/5 dark:border-white/5 rounded-2xl p-3 font-bold text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all"
                  >
                    {Object.values(ThumbnailStyle).map((s) => (
                      <option key={s} value={s}>{s}</option>
                    ))}
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-3">Qualität & Auflösung</label>
                <div className="grid grid-cols-3 gap-2">
                  {QUALITY_OPTIONS.map((opt) => {
                    const Icon = opt.icon;
                    return (
                      <Tooltip key={opt.id} text={opt.desc}>
                        <button
                          onClick={() => setQuality(opt)}
                          className={`w-full flex flex-col items-center justify-center p-3 rounded-2xl border transition-all ${
                            quality.id === opt.id 
                              ? 'bg-blue-600 border-blue-600 text-white shadow-lg scale-105' 
                              : 'bg-slate-50 dark:bg-slate-800/50 border-transparent text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'
                          }`}
                        >
                          <Icon className="w-5 h-5 mb-1.5" />
