import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Extrahiert den MIME-Typ aus einem Base64-String oder setzt einen Standardwert.
 */
const getMimeType = (base64: string): string => {
  const match = base64.match(/^data:([^;]+);base64,/);
  return match ? match[1] : 'image/png';
};

/**
 * Bereinigt Base64-Daten für die API (entfernt den Data-URL-Header).
 */
const cleanBase64 = (base64: string): string => {
  return base64.includes(',') ? base64.split(',')[1] : base64;
};

/**
 * Analysiert den Nutzerwunsch mit Fokus auf STRIKTE ADHÄRENZ.
 */
const analyzePromptIntent = async (prompt: string) => {
  const ai = getAI();

  const analysisPrompt = `Du bist ein Expert für präzise Prompt-Analyse. Analysiere: "${prompt}".
  Extrahiere NUR das, was explizit genannt wurde.

  WICHTIGSTE REGEL: Füge KEINE eigenen Ideen, Stile oder Objekte hinzu, die nicht im Text stehen. 
  Wenn der Nutzer "Hund" sagt, beschreibe nur einen Hund, keine Umgebung, außer sie wird genannt.

  Antworte STRENG als JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: analysisPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            wantsText: { type: Type.BOOLEAN },
            extractedText: { type: Type.STRING, nullable: true },
            textPosition: { type: Type.STRING, nullable: true },
            visualPrompt: { 
              type: Type.STRING, 
              description: "Die wörtliche visuelle Beschreibung basierend auf dem Nutzerinput." 
            },
            layoutConstraints: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["wantsText", "visualPrompt", "layoutConstraints"]
        }
      }
    });
    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Intent-Analyse fehlgeschlagen:", e);
    return null;
  }
};

/**
 * Kern-Funktion zur Bilderzeugung mit Fokus auf wörtliche Umsetzung.
 */
export const generateThumbnail = async (prompt: string, style: string, aspectRatio: string = "16:9", base64Image?: string) => {
  const ai = getAI();

  let layoutRule = "";
  let finalVisualPrompt = prompt;

  const intent = await analyzePromptIntent(prompt);
  if (intent) {
    finalVisualPrompt = intent.visualPrompt;
    if (intent.wantsText && intent.extractedText) {
      const position = intent.textPosition || "centered";
      layoutRule = `\n[LAYOUT]: Place text "${intent.extractedText}" ${position}.`;
    } else if (!intent.wantsText) {
      layoutRule = `\n[RULE]: NO TEXT.`;
    }
