    <div className="max-w-7xl mx-auto space-y-12 animate-in fade-in slide-up duration-700">

      {/* Mode Switcher */}
      <div className="flex justify-center">
        <div className="bg-white dark:bg-slate-900 p-1.5 rounded-2xl border border-black/5 dark:border-white/10 shadow-lg flex gap-1">
          <button 
            onClick={() => setIsBulkMode(false)}
            className={`px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all flex items-center gap-2 ${!isBulkMode ? 'bg-orange-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
          >
            <Monitor className="w-3.5 h-3.5" /> Einzeln
          </button>
          <button 
            onClick={() => setIsBulkMode(true)}
            className={`px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all flex items-center gap-2 ${isBulkMode ? 'bg-orange-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
          >
            <Sparkles className="w-3.5 h-3.5" /> Bulk
          </button>
        </div>
      </div>

      <div className="grid lg:grid-cols-2 gap-12">
        <div className="space-y-8">
          <div className="p-8 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-black/5 dark:border-white/5 shadow-2xl">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-black flex items-center gap-3">
                <Wand2 className="w-6 h-6 text-orange-500" />
                Konfiguration
              </h2>
              <div className="flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full bg-amber-500/10 text-amber-500 border border-amber-500/10">
                <Coins className="w-3.5 h-3.5" />
                {quality.cost} Credits
              </div>
            </div>

            <div className="space-y-6">
              <div>
                <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-3">Vision beschreiben (Strikte Umsetzung)</label>
                <textarea 
                  value={isBulkMode ? bulkPrompts : prompt}
                  onChange={(e) => isBulkMode ? setBulkPrompts(e.target.value) : setPrompt(e.target.value)}
                  placeholder={isBulkMode ? "Prompt 1\nPrompt 2..." : "Beschreibe genau, was im Bild sein soll. Die KI fügt nichts Eigenes hinzu."}
                  className="w-full h-32 bg-slate-50 dark:bg-slate-800/50 border border-black/5 dark:border-white/5 rounded-2xl p-4 focus:ring-2 focus:ring-orange-500 outline-none transition-all resize-none mb-2"
                />
                {promptError && <p className="text-red-500 text-[10px] font-bold">{promptError}</p>}
                <div className="flex flex-wrap gap-2 mt-2">
                  {STYLE_SUGGESTIONS[style].map((s, i) => (
                    <button key={i} onClick={() => setPrompt(prev => prev + " " + s)} className="px-3 py-1 bg-slate-100 dark:bg-slate-800 rounded-lg text-[10px] font-bold text-slate-500 hover:bg-orange-500 hover:text-white transition-all">+ {s}</button>
                  ))}
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-3">Format</label>
                  <select value={aspectRatio} onChange={(e) => setAspectRatio(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800/50 border border-black/5 rounded-xl p-3 text-sm font-bold outline-none">
                    {ASPECT_RATIOS.map(r => <option key={r.id} value={r.id}>{r.label}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-3">Stil</label>
                  <select value={style} onChange={(e) => setStyle(e.target.value as ThumbnailStyle)} className="w-full bg-slate-50 dark:bg-slate-800/50 border border-black/5 rounded-xl p-3 text-sm font-bold outline-none">
                    {Object.values(ThumbnailStyle).map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-3">Qualität</label>
                <div className="grid grid-cols-3 gap-2">
                  {QUALITY_OPTIONS.map(opt => (
                    <button key={opt.id} onClick={() => setQuality(opt)} className={`p-3 rounded-xl border transition-all flex flex-col items-center ${quality.id === opt.id ? 'bg-orange-600 border-orange-600 text-white shadow-lg' : 'bg-slate-50 dark:bg-slate-800 border-transparent text-slate-500'}`}>
                      <opt.icon className="w-4 h-4 mb-1" />
                      <span className="text-[10px] font-black uppercase">{opt.label}</span>
                    </button>
                  ))}
                </div>
              </div>

              {loading && (
                <div className="space-y-2 animate-in fade-in slide-up">
                  <div className="flex justify-between text-[10px] font-black uppercase text-orange-500">
                    <span>{statusText}</span>
                    <span>{Math.round(progress)}%</span>
                  </div>
                  <div className="h-2 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                    <div className="h-full bg-orange-600 transition-all duration-300 shadow-[0_0_10px_rgba(249,115,22,0.4)]" style={{ width: `${progress}%` }} />
                  </div>
                </div>
              )}

              <button 
                onClick={handleGenerate}
                disabled={loading || isLowCredits(quality.cost)}
                className="w-full py-5 bg-orange-600 hover:bg-orange-700 text-white rounded-2xl font-black text-lg shadow-xl shadow-orange-600/20 flex items-center justify-center gap-3 disabled:opacity-50 transition-all active:scale-95"
              >
                {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Wand2 className="w-6 h-6" />}
                {isLowCredits(quality.cost) ? 'Nicht genügend Credits' : 'Jetzt generieren'}
              </button>
            </div>
          </div>
        </div>

        {/* Results with Refinement Column */}
        <div className="flex flex-col space-y-6 max-h-[1000px] overflow-y-auto no-scrollbar pr-2">
          {results.length > 0 ? (
            results.map((res) => (
              <div key={res.id} className="bg-white dark:bg-slate-900 rounded-[2.5rem] border border-black/5 dark:border-white/5 p-6 shadow-xl animate-in zoom-in-95 duration-500">
                <div className="grid md:grid-cols-5 gap-6">
                  {/* Image Part */}
                  <div className="md:col-span-3">
                    <div className="relative aspect-video rounded-2xl overflow-hidden bg-slate-100 dark:bg-slate-800 group shadow-inner">
                      <img src={res.url} className="w-full h-full object-cover" alt={res.prompt} />
                      {res.isRefining && (
                        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center">
                          <Loader2 className="w-10 h-10 text-white animate-spin" />
                        </div>
                      )}
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2">
                        <button onClick={() => handleSave(res)} className={`p-3 rounded-xl shadow-xl transition-transform hover:scale-110 ${res.isSaved ? 'bg-rose-500 text-white' : 'bg-white text-rose-500'}`} title="Speichern"><Heart className={`w-5 h-5 ${res.isSaved ? 'fill-current' : ''}`} /></button>
                        <button onClick={() => { const a = document.createElement('a'); a.href = res.url; a.download = 'thumbnail.png'; a.click(); }} className="p-3 bg-white text-slate-900 rounded-xl hover:scale-110 transition-all shadow-xl"><Download className="w-5 h-5" /></button>
                        <button onClick={() => removeResult(res.id)} className="p-3 bg-red-500 text-white rounded-xl hover:scale-110 transition-all shadow-xl"><Trash2 className="w-5 h-5" /></button>
                      </div>
                    </div>
                  </div>

                  {/* Refinement Column */}
                  <div className="md:col-span-2 flex flex-col">
                    <div className="flex items-center gap-2 mb-3">
                      <MessageSquare className="w-4 h-4 text-orange-600" />
                      <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400">Verbesserungsvorschlag</h4>
                    </div>

                    <div className="flex-1 flex flex-col gap-3">
                      <div className="relative flex-1">
                        <textarea 
                          value={res.refinementText}
                          onChange={(e) => setResults(prev => prev.map(r => r.id === res.id ? { ...r, refinementText: e.target.value } : r))}
                          placeholder="z.B. Hintergrund dunkler machen oder Textfarbe ändern..."
                          className="w-full h-full min-h-[100px] bg-slate-50 dark:bg-slate-800/50 border border-black/5 dark:border-white/5 rounded-2xl p-4 text-xs font-medium focus:ring-2 focus:ring-orange-500 outline-none transition-all resize-none"
                        />
                      </div>

                      <button 
                        onClick={() => handleRefine(res.id)}
                        disabled={res.isRefining || !res.refinementText?.trim() || isLowCredits(5)}
                        className="w-full py-3 bg-orange-600 text-white rounded-xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-2 shadow-lg shadow-orange-600/10 active:scale-95 disabled:opacity-50 transition-all"
                      >
                        {res.isRefining ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-3 h-3" />}
                        Senden (5 Cr.)
                      </button>
                    </div>

                    <div className="mt-4 pt-4 border-t border-black/5 dark:border-white/5 flex items-center gap-2 opacity-50">
                       <Sparkles className="w-3 h-3" />
                       <span className="text-[8px] font-black uppercase tracking-widest">Präzise Korrektur</span>
                    </div>
                  </div>
                </div>

                <div className="mt-4 p-3 bg-slate-50 dark:bg-slate-800/30 rounded-xl">
                  <p className="text-[10px] font-bold text-slate-400 truncate" title={res.prompt}>Prompt: {res.prompt}</p>
                </div>
              </div>
            ))
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center text-center p-12 bg-slate-100 dark:bg-slate-900/50 rounded-[4rem] border-2 border-dashed border-black/5">
              <ImageIcon className="w-16 h-16 text-slate-300 mb-6" />
              <h3 className="text-xl font-black mb-2">Bereit für Ergebnisse</h3>
              <p className="text-slate-400 text-sm max-w-xs font-medium">Nach der Generierung kannst du hier spezifische Korrekturen für 5 Credits pro Bild vornehmen.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

