            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const getMimeType = (base64: string): string => {
  const match = base64.match(/^data:([^;]+);base64,/);
  return match ? match[1] : 'image/png';
};

const cleanBase64 = (base64: string): string => {
  return base64.includes(',') ? base64.split(',')[1] : base64;
};

/**
 * Analysiert den Nutzerwunsch mit Fokus auf STRIKTE ADHÄRENZ.
 */
const analyzePromptIntent = async (prompt: string) => {
  const ai = getAI();

  const analysisPrompt = `Du bist ein Expert für präzise Prompt-Analyse. Analysiere den Nutzer-Prompt: "${prompt}".
  Extrahiere NUR die explizit genannten visuellen Elemente.

  WICHTIGSTE REGEL: Füge KEINE eigenen Ideen, Verzierungen, Hintergründe oder Objekte hinzu, die nicht im Text stehen. 
  Das Ziel ist 100%ige Genauigkeit zum Text. Ignoriere implizite YouTube-Klischees.

  Antworte STRENG als JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: analysisPrompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            visualPrompt: { 
              type: Type.STRING, 
              description: "Die wörtliche visuelle Beschreibung basierend auf dem Nutzerinput." 
            },
            layoutConstraints: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["visualPrompt", "layoutConstraints"]
        }
      }
    });
    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Intent-Analyse fehlgeschlagen:", e);
    return null;
  }
};

/**
 * Kern-Funktion zur Bilderzeugung mit Fokus auf wörtliche Umsetzung.
 */
export const generateThumbnail = async (prompt: string, style: string, aspectRatio: string = "16:9", base64Image?: string) => {
  const ai = getAI();

  const intent = await analyzePromptIntent(prompt);
  const finalVisualPrompt = intent ? intent.visualPrompt : prompt;

  let fullPrompt = `LITERAL GENERATION TASK. 
  Follow the user prompt exactly: "${finalVisualPrompt}". 
  STYLE: ${style}. 
  CRITICAL: DO NOT add extra objects, text, or complex backgrounds unless explicitly mentioned. 
  Accuracy is the absolute priority. Output ONLY what was requested.`;

  const parts: any[] = [{ text: fullPrompt }];

  if (base64Image) {
    parts.unshift({
      inlineData: { 
        data: cleanBase64(base64Image), 
        mimeType: getMimeType(base64Image) 
      }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts },
      config: { 
        imageConfig: { 
          aspectRatio: aspectRatio as any
        } 
      }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return `data:${imagePart.inlineData.mimeType || 'image/png'};base64,${imagePart.inlineData.data}`;
    }

    throw new Error("Kein Bild geliefert.");
  } catch (e: any) {
    throw new Error(e.message || "Fehler bei der Bilderzeugung.");
  }
};

/**
 * Überarbeitet ein bestehendes Thumbnail für 5 Credits (Refinement).
 */
export const remakeThumbnail = async (sourceBase64: string, adjustmentPrompt: string) => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { data: cleanBase64(sourceBase64), mimeType: getMimeType(sourceBase64) } },
          { text: `Based on the user suggestion "${adjustmentPrompt}", create a STICKT MODIFICATION command. Focus ONLY on the requested change. Preserve everything else 1:1.` }
        ]
      }
    });
    return generateThumbnail(response.text || adjustmentPrompt, 'REFINEMENT_MODE', "16:9", sourceBase64);
  } catch (e) {
    throw new Error("Refinement fehlgeschlagen.");
  }
};

export const cloneStyle = async (sourceBase64: string, newMotifPrompt: string) => {
  const ai = getAI();
  const analysisResponse = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: cleanBase64(sourceBase64), mimeType: getMimeType(sourceBase64) } },
        { text: "Describe the AESTHETIC DNA of this image: colors, lighting, composition only." }
      ]
    }
  });
  const styleInstructions = analysisResponse.text || "Professional YouTube aesthetic";
  return generateThumbnail(newMotifPrompt, `STYLE: ${styleInstructions}`, "16:9", sourceBase64);
};

export const analyzeThumbnailImage = async (base64Image: string) => {
