import React, { useState, useEffect, useRef } from 'react';
import { Wand2, Sparkles, Loader2, Download, Trash2, Image as ImageIcon, Coins, Monitor, Smartphone, Square, Heart, Send, Zap, MessageSquare, ArrowRight } from 'lucide-react';
import { generateThumbnail, remakeThumbnail } from '../services/geminiService';
import { ThumbnailStyle, User, Design } from '../types';

interface StudioGenerateProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
  onGoToPricing?: () => void;
  onSaveDesign?: (design: Design) => void;
}

const STYLE_SUGGESTIONS: Record<ThumbnailStyle, string[]> = {
  [ThumbnailStyle.CLEAN]: ["Produktfoto", "Studio-Hintergrund", "Minimalistisch"],
  [ThumbnailStyle.BEAST]: ["Auffällige Mimik", "Hoher Kontrast", "Vibrant"],
  [ThumbnailStyle.MINIMAL]: ["Viel Leerraum", "Pastell", "Einfach"],
  [ThumbnailStyle.GAMING]: ["Neon", "Action", "RGB"]
};

const ASPECT_RATIOS = [
  { id: '16:9', label: '16:9', icon: Monitor },
  { id: '9:16', label: '9:16', icon: Smartphone },
  { id: '1:1', label: '1:1', icon: Square },
];

const QUALITY_OPTIONS = [
  { id: 'standard', label: 'Standard', cost: 10, icon: Zap },
  { id: 'max', label: 'Max (4K)', cost: 50, icon: Sparkles },
];

interface GeneratedResult {
  id: string;
  url: string;
  prompt: string;
  isSaved?: boolean;
  isRefining?: boolean;
  refinementText?: string;
}

export const StudioGenerate: React.FC<StudioGenerateProps> = ({ useCredits, user, onGoToPricing, onSaveDesign }) => {
  const [prompt, setPrompt] = useState('');
  const [style, setStyle] = useState<ThumbnailStyle>(ThumbnailStyle.CLEAN);
  const [aspectRatio, setAspectRatio] = useState('16:9');
  const [quality, setQuality] = useState(QUALITY_OPTIONS[0]);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [results, setResults] = useState<GeneratedResult[]>([]);

  const isLowCredits = (cost: number) => !user || user.credits < cost;

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setProgress(prev => (prev >= 98 ? 98 : prev + Math.random() * 5));
        setStatusText("KI generiert...");
      }, 400);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    if (isLowCredits(quality.cost)) {
      onGoToPricing?.();
      return;
    }

    setLoading(true);
    setProgress(5);
    try {
      const res = await generateThumbnail(prompt, style, aspectRatio);
      useCredits(quality.cost);
      setResults(prev => [{
        id: Math.random().toString(36).substr(2, 9),
        url: res,
        prompt: prompt,
        refinementText: ''
      }, ...prev]);
      setPrompt('');
      setProgress(100);
    } catch (err) {
      alert("Fehler bei der Generierung.");
    } finally {
      setLoading(false);
    }
  };

  const handleRefine = async (resultId: string) => {
    const result = results.find(r => r.id === resultId);
    if (!result || !result.refinementText?.trim()) return;

    const cost = 5;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }

    setResults(prev => prev.map(r => r.id === resultId ? { ...r, isRefining: true } : r));

    try {
      const refinedUrl = await remakeThumbnail(result.url, result.refinementText);
      useCredits(cost);
      setResults(prev => prev.map(r => r.id === resultId ? { 
        ...r, 
        url: refinedUrl, 
        isRefining: false, 
        refinementText: '',
        prompt: `${r.prompt} (+ ${result.refinementText})`
      } : r));
    } catch (err) {
      alert("Refinement fehlgeschlagen.");
      setResults(prev => prev.map(r => r.id === resultId ? { ...r, isRefining: false } : r));
    }
  };

  const handleSave = (res: GeneratedResult) => {
    onSaveDesign?.({
      id: res.id,
      imageUrl: res.url,
      prompt: res.prompt,
      createdAt: new Date().toISOString(),
      style: style,
      aspectRatio: aspectRatio
    });
    setResults(prev => prev.map(r => r.id === res.id ? { ...r, isSaved: true } : r));
  };

  return (
    <div className="max-w-7xl mx-auto grid lg:grid-cols-2 gap-12 animate-in fade-in slide-up duration-700">

      {/* Left: Configuration */}
      <div className="space-y-6">
        <div className="p-8 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-black/5 dark:border-white/5 shadow-2xl sticky top-28">
          <div className="flex justify-between items-center mb-8">
            <h2 className="text-2xl font-black flex items-center gap-3">
              <Wand2 className="w-6 h-6 text-orange-500" /> Labor
            </h2>
            <div className="flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full bg-amber-500/10 text-amber-500 border border-amber-500/10">
              <Coins className="w-3.5 h-3.5" /> {quality.cost} Credits
            </div>
          </div>

          <div className="space-y-6">
            <div>
              <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-3">Vision beschreiben</label>
              <textarea 
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="Was soll im Bild sein? Die KI fügt nichts Eigenes hinzu."
