                    <div className="h-full bg-orange-600 transition-all duration-300 shadow-[0_0_10px_rgba(249,115,22,0.4)]" style={{ width: `${progress}%` }} />
                  </div>
                </div>
              ) : (
                <button 
                  onClick={handleGenerate}
                  disabled={!prompt.trim() || isLowCredits(10)}
                  className="w-full py-5 bg-orange-600 hover:bg-orange-700 text-white rounded-[2rem] font-black text-lg shadow-2xl shadow-orange-600/20 flex items-center justify-center gap-3 transition-all active:scale-95 disabled:opacity-50"
                >
                  <Zap className="w-6 h-6 fill-current" /> Thumbnail generieren
                </button>
              )}
            </div>

            <div className="p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl border border-black/5 flex items-start gap-3">
               <Info className="w-4 h-4 text-orange-500 shrink-0 mt-0.5" />
               <p className="text-[10px] text-slate-500 leading-relaxed font-bold">Die KI optimiert deine Idee automatisch für maximale Klicks. Ergebnisse erscheinen sofort rechts.</p>
            </div>
          </div>
        </div>
      </div>

      {/* Results Feed */}
      <div className="flex-1 space-y-10">
        {results.length > 0 ? (
          results.map((res) => (
            <div key={res.id} className="bg-white dark:bg-slate-900 rounded-[3.5rem] border border-black/5 dark:border-white/5 p-8 shadow-2xl animate-in zoom-in-95 duration-500 relative group/card">
              <div className="flex flex-col md:flex-row gap-10">

